local function ApplyCustomProps(Object, Props: { [string]: any }?)
	
end

function Creator.AddSignal(Signal: RBXScriptSignal, Function)
	Creator.Signals[#Creator.Signals+1] = Signal:Connect(Function)
end

function Creator.Disconnect()
	for Idx = #Creator.Signals, 1, -1 do
		local Connection = table.remove(Creator.Signals, Idx)
		
		if Connection then
			Connection:Disconnect()
		end
	end
end

function Creator.New(Name, Properties: { [string]: any }?, Children: { [number]: Instance }?): Instance
	local Object = Instance.new(Name)

	-- Default properties
	for Name, Value in next, Creator.DefaultProperties[Name] or {} do
		Object[Name] = Value
	end

	-- Properties
	for Name, Value in next, Properties or {} do
		if Name ~= "ThemeTag" then
			Object[Name] = Value
		end
	end

	-- Children
	for _, Child in next, Children or {} do
		Child.Parent = Object
	end

	ApplyCustomProps(Object, Properties)

	return Object
end
--[[
function Creator.SpringMotor(Initial: any, Instance: Object, Prop: string, IgnoreDialogCheck: boolean?, ResetOnThemeChange: boolean?)
	IgnoreDialogCheck = IgnoreDialogCheck or false
	ResetOnThemeChange = ResetOnThemeChange or false
	local Motor = Flipper.SingleMotor.new(Initial)
	Motor:onStep(function(value)
		Instance[Prop] = value
	end)

	if ResetOnThemeChange then
		Creator.TransparencyMotors[#Creator.TransparencyMotors + 1] = Motor
	end

	local function SetValue(Value, Ignore: boolean?)
		Ignore = Ignore or false
		if not IgnoreDialogCheck then
			if not Ignore then
				if Prop == "BackgroundTransparency" and require(Root).DialogOpen then
					return
				end
			end
		end
		Motor:setGoal(Flipper.Spring.new(Value, { frequency = 8 }))
	end

	return Motor, SetValue
end]]

return Creator
end)()
__mods.Utils = (function()
 local function map(value, inMin, inMax, outMin, outMax)
    return (value - inMin) * (outMax - outMin) / (inMax - inMin) + outMin
end

local function viewportPointToWorld(location, distance)
    local unitRay = workspace.CurrentCamera:ScreenPointToRay(location.X, location.Y)
    return unitRay.Origin + unitRay.Direction * distance
end

local function getOffset()
    local viewportSizeY = workspace.CurrentCamera.ViewportSize.Y
    return map(viewportSizeY, 0, 2560, 8, 56)
end

return {viewportPointToWorld, getOffset}
end)()
__mods.CreateAcrylic = (function()
 local Creator = __mods.Creator
local isStudio = game:GetService("RunService"):IsStudio()

local function createAcrylic()


	local flag = false
	if getgenv then
		if getgenv().NoAnticheat == nil or getgenv().NoAnticheat == true then
			flag = true
		end
		if getgenv().SecureMode then
			flag = false
		end
	end
	if game:GetService("RunService"):IsStudio() then
		flag = true
	end
	if not flag then return end
	
	local Part = Creator.New("Part", {
		Name = "Body",
		Color = Color3.new(0, 0, 0),
		Material = Enum.Material.Glass,
		Size = Vector3.new(1.04, 1.12, 0),
		Anchored = true,
		CanCollide = false,
		Locked = true,
		CastShadow = false,
		Transparency = 0.98,
	}, {
		Creator.New("SpecialMesh", {
			MeshType = Enum.MeshType.Brick,
			Offset = Vector3.new(0, 0, -0.000001),
		})
	})

	return Part
end

return createAcrylic
end)()
__mods.AcrylicBlur = (function()
 local Creator = __mods.Creator
local createAcrylic = __mods.CreateAcrylic
local viewportPointToWorld, getOffset = unpack(__mods.Utils)

local BlurFolder = game:GetService("Workspace").CurrentCamera:FindFirstChild("Starlight Blur Elements") and game:GetService("Workspace").CurrentCamera["Starlight Blur Elements"] or Instance.new("Folder", game:GetService("Workspace").CurrentCamera)
BlurFolder.Name = "Starlight Blur Elements"

-- (LxYHook) a glass part follows the Visible of its own frame only; the frames of a closed colour picker or dropdown
-- (and of the pages that are not open) stay Visible inside a hidden parent, so their glass kept showing. Every
-- 0.25 s the shown parts are checked against the whole parent chain of their frame.
local blurStates = setmetatable({}, { __mode = "k" })
local function chainVisible(inst)
	local a = inst
	while a ~= nil do
		if a:IsA("GuiObject") then
			if not a.Visible then return false end
		elseif a:IsA("LayerCollector") then
			return a.Enabled
		end
		a = a.Parent
	end
	return false
end
task.spawn(function()
	local idle = 0
	while BlurFolder.Parent ~= nil and idle < 40 do
		if next(blurStates) == nil then idle += 1 else idle = 0 end
		for st in pairs(blurStates) do
			local comp = st.comp
			if comp ~= nil and st.shown then
				local v = chainVisible(comp)
				if v ~= st.vis then
					st.vis = v
					st.apply()
				end
			end
		end
		task.wait(0.25)
	end
end)

local function createAcrylicBlur(distance)
	

	local flag = false
	if getgenv then
		if getgenv().NoAnticheat == nil or getgenv().NoAnticheat == true then
			flag = true
		end
		if getgenv().SecureMode then
			flag = false
		end
	end
	if game:GetService("RunService"):IsStudio() then
			flag = true
	end
	if not flag then return end
	local cleanups = {}
	-- (LxYHook) the camera connections of a shown part (it follows the camera only while it is shown)
	local following = {}

	distance = distance or 0.001
	local positions = {
		topLeft = Vector2.new(),
		topRight = Vector2.new(),
		bottomRight = Vector2.new(),
	}
	local model = createAcrylic()
	local mesh = model:FindFirstChildWhichIsA("SpecialMesh")

	model.Parent = BlurFolder

	local follow
	local function updatePositions(size, position)
		positions.topLeft = position
		positions.topRight = position + Vector2.new(size.X, 0)
		positions.bottomRight = position + size
	end

	local function render()
		local camera = game:GetService("Workspace").CurrentCamera
		local cameraTransform = if camera then camera.CFrame else CFrame.identity

		local topLeft = positions.topLeft
		local topRight = positions.topRight
		local bottomRight = positions.bottomRight

		local topLeft3D = viewportPointToWorld(topLeft, distance)
		local topRight3D = viewportPointToWorld(topRight, distance)
		local bottomRight3D = viewportPointToWorld(bottomRight, distance)

		local width = (topRight3D - topLeft3D).Magnitude
		local height = (topRight3D - bottomRight3D).Magnitude

		model.CFrame =
			CFrame.fromMatrix((topLeft3D + bottomRight3D) / 2, cameraTransform.XVector, cameraTransform.YVector, cameraTransform.ZVector)

		if mesh then
			mesh.Scale = Vector3.new(width, height, 0)
		end
	end

	-- (LxYHook) the glass is a 3D part, so the GUI does not clip it: the controls of the pages that are not open sit
	-- outside the window (Starlight parks them there with Visible still true) and their glass showed over the game.
	-- A part is shown only while its frame is on and fully inside the main window.
	local state = { shown = false, inside = true, vis = true, window = nil, comp = nil }

	local function apply()
		local on = state.shown and state.inside and state.vis
		pcall(function() model.Transparency = on and 0.98 or 1 end)
		follow(on)
	end

	local function onChange(rbx)
		local offset = getOffset()
		local size = rbx.AbsoluteSize - Vector2.new(offset, offset)
		local position = rbx.AbsolutePosition + Vector2.new(offset / 2, offset / 2)

		updatePositions(size, position)
		local win = state.window
		if win == nil or win.Parent == nil then
			win = nil
			local a = rbx
			while a ~= nil do
				if a.Name == "MainWindow" then win = a break end
				a = a.Parent
			end
			state.window = win
		end
		if win ~= nil then
			local p, sz = win.AbsolutePosition, win.AbsoluteSize
			local inside = position.X >= p.X - 2 and position.Y >= p.Y - 2
				and position.X + size.X <= p.X + sz.X + 2 and position.Y + size.Y <= p.Y + sz.Y + 2
			if inside ~= state.inside then
				state.inside = inside
				apply()
			end
		end
		if #following > 0 then
			task.spawn(render)
		end
	end

	-- (LxYHook) was renderOnChange: every part re-rendered on every camera move, shown or not (a closed dropdown's
	-- or colour picker's too), which with one part per popup was a lot of work every frame
	function follow(on)
		if on == (#following > 0) then
			return
		end
		if on then
			local camera = game:GetService("Workspace").CurrentCamera
			if not camera then
				return
			end
			following[1] = camera:GetPropertyChangedSignal("CFrame"):Connect(render)
			following[2] = camera:GetPropertyChangedSignal("ViewportSize"):Connect(render)
			following[3] = camera:GetPropertyChangedSignal("FieldOfView"):Connect(render)
			task.spawn(render)
		else
			for _, connection in following do
				connection:Disconnect()
			end
			table.clear(following)
		end
	end

	blurStates[state] = true
	state.apply = apply
	model.Destroying:Connect(function()
		blurStates[state] = nil
		follow(false)
		for _, item in cleanups do
			pcall(function()
				item:Disconnect()
			end)
		end
	end)

	follow(true)

	return onChange, model, follow, state, apply
end

return function(distance)
	local Blur = {}
	local onChange, model, follow, state, apply = createAcrylicBlur(distance)

	local comp = Creator.New("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
	})
	local y = Creator.New("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(0, 0),
	})
	if state ~= nil then state.comp = comp end

	-- (LxYHook) no glass part: nothing to follow
	if onChange ~= nil then
	Creator.AddSignal(comp:GetPropertyChangedSignal("AbsolutePosition"), function()
		pcall(onChange, comp)
	end)

	Creator.AddSignal(comp:GetPropertyChangedSignal("AbsoluteSize"), function()
		pcall(onChange, comp)
	end)
	end

	Blur.AddParent = function(Parent)
		if model == nil then return end
		-- (LxYHook) a part starts out shown; a frame that is hidden from the start (a closed colour picker) never
		-- fires Visible, so its glass stayed on for good
		Blur.SetVisibility(Parent.Visible)
		Creator.AddSignal(Parent:GetPropertyChangedSignal("Visible"), function()
			Blur.SetVisibility(Parent.Visible)
		end)

		Creator.AddSignal(Parent.AncestryChanged, function(_, newParent)
			if not newParent then
				Blur.SetVisibility(false)
			end
		end)
 
		pcall(function()
			model.Color = Parent.BackgroundColor3
			Creator.AddSignal(Parent:GetPropertyChangedSignal("BackgroundColor3"), function()
				model.Color = Parent.BackgroundColor3
			end)
		end)
	end


	Blur.SetVisibility = function(Value)
		if model == nil then return end
		state.shown = Value == true
		apply()
	end

	Blur.Frame = comp
	Blur.Model = model

	return Blur
end
end)()
