    } end)()

    -- labels built from a template ("Enable " .. title .. " ESP", P .. " Chams" ...): the captured part is
    -- translated too. Only tried when there is no exact entry.
    L.patterns = {
        { "^Enable (.+) ESP$", "啟用%1透視" },
        { "^Enable (.+)$", "啟用%1" },
        { "^(.+) Allowed Hitboxes$", "%1可瞄準部位" },
        { "^(.+) Chams Material$", "%1上色材質" },
        { "^(.+) Chams$", "%1上色" },
        { "^Strip (.+) Textures$", "%1去掉貼圖" },
        { "^(.+) Highlight$", "%1高亮" },
        { "^(.+) Wireframe$", "%1線框" },
        { "^(.+) Mode$", "%1模式" },
        { "^(.+) Enabled$", "%1 啟用" },
        { "^Current Autoload Theme:? ?(.*)$", "目前自動載入的主題:%1" },
    }

    -- strings that have no translation, collected while Chinese is on (for adding them to L.zh later)
    local missing, missingList, missingQueued = {}, {}, false
    local function noteMissing(s)
        if missing[s] or #missingList >= 3000 or #s > 400 then return end
        missing[s] = true
        missingList[#missingList + 1] = s
        if missingQueued then return end
        missingQueued = true
        task.delay(3, function()
            missingQueued = false
            local wrf = K.fn("writefile")
            if wrf then pcall(wrf, MISSING_FILE, table.concat(missingList, "\n")) end
        end)
    end

    local zh = L.zh
    local function T(s)
        if L.lang ~= "zh" or type(s) ~= "string" or s == "" then return s end
        local r = zh[s]
        if r ~= nil then return r end
        -- already Chinese (translated once before), or nothing to translate
        if s:find("[\128-\255]") or not s:find("%a") then return s end
        local lead, core, trail = s:match("^(%s*)(.-)(%s*)$")
        if core ~= s and core ~= "" then
            r = zh[core]
            if r ~= nil then return lead .. r .. trail end
        end
        for _, p in ipairs(L.patterns) do
            local caps = table.pack(s:match(p[1]))
            if caps[1] ~= nil then
                return (p[2]:gsub("%%(%d)", function(i) return T(caps[tonumber(i)] or "") end))
            end
        end
        noteMissing(s)
        return s
    end
    L.T = T
    K.T = T
    -- T for a template: K.TF("Round %s", n) -> "第 3 回合"
    function K.TF(fmt, ...)
        return string.format(T(fmt), ...)
    end

    -- a spec table as the page builders pass it, with its texts translated. A copy: the builder's own table is
    -- never changed. Dropdown values stay as they are; what is shown comes from Labels.
    local TEXT_KEYS = { "Label", "Title", "Description", "Tooltip", "Placeholder", "PlaceholderText", "PinHint",
        "ActionText", "Content", "Subtitle", "Text", "Header", "Hint", "EmptyText" }
    function L.spec(o)
        if L.lang ~= "zh" then return o end
        if type(o) == "string" then return T(o) end
        if type(o) ~= "table" or getmetatable(o) ~= nil then return o end
        local c = table.clone(o)
        for _, k in ipairs(TEXT_KEYS) do
            local v = c[k]
            if type(v) == "string" then c[k] = T(v) end
        end
        if type(o.Label) == "string" then c._enLabel = o.Label end
        local opts, old = c.Options, c.Labels
        if type(opts) == "table" or type(old) == "table" then
            local labels, changed = {}, false
            if type(old) == "table" then
                for k, v in pairs(old) do
                    labels[k] = v
                    if type(v) == "string" then
                        local t = T(v)
                        if t ~= v then labels[k] = t; changed = true end
                    end
                end
            end
            if type(opts) == "table" then
                for _, opt in ipairs(opts) do
                    if type(opt) == "string" and labels[opt] == nil then
                        local t = T(opt)
                        if t ~= opt then labels[opt] = t; changed = true end
                    end
                end
            end
            if changed then c.Labels = labels end
        end
        return c
    end

    -- which argument of a menu method is its spec (or its text)
    local SPEC_ARG = {
        AddTab = 1, AddSection = 1, AddMultiSection = 1, AddToggle = 1, AddSlider = 1, AddRangeSlider = 1,
        AddButton = 1, AddLabel = 1, AddDivider = 1, AddTextBox = 1, AddDropdown = 1, AddMultiDropdown = 1,
        AddList = 1, AddMultiList = 1, AddKeybind = 1, AddColor = 1, AddColorPicker = 1, AddSkinChanger = 1,
        AddIconStrip = 1, AddOrdered = 1, AddGroup = 1, Grid = 1, Dialog = 1, AddPage = 1,
        SetLabel = 1, SetTooltip = 1, _make = 2,
    }
    local done = setmetatable({}, { __mode = "k" })
    local labelDone = setmetatable({}, { __mode = "k" })
    local function classOf(o)
        local mt = getmetatable(o)
        if type(mt) == "table" then
            local idx = rawget(mt, "__index")
            if type(idx) == "table" then return idx end
        end
        return nil
    end
    local wrapObj
    -- a label's Set(text) shows text: translate it (only label classes get this)
    local function patchLabelSet(o)
        if type(o) ~= "table" then return end
        local cls = classOf(o)
        if cls == nil or labelDone[cls] then return end
        labelDone[cls] = true
        local orig = cls.Set
        if type(orig) ~= "function" then return end
        pcall(rawset, cls, "Set", function(self, v, ...)
            if L.lang == "zh" and type(v) == "string" then v = T(v) end
            return orig(self, v, ...)
        end)
    end
    local function patchClass(cls)
        if done[cls] then return end
        done[cls] = true
        for name, at in pairs(SPEC_ARG) do
            local orig = cls[name]
            if type(orig) == "function" then
                pcall(rawset, cls, name, function(self, ...)
                    if L.lang ~= "zh" then return orig(self, ...) end
                    local args = table.pack(...)
                    local kind = args[1]
                    args[at] = L.spec(args[at])
                    -- Dialog(o, builder) / AddPage(o, builder): the builder gets new menu objects
                    if name == "Dialog" or name == "AddPage" then
                        for i = 1, args.n do
                            local f = args[i]
                            if type(f) == "function" then
                                args[i] = function(a, ...)
                                    wrapObj(a)
                                    return f(a, ...)
                                end
                            end
                        end
                    end
                    local res = table.pack(orig(self, table.unpack(args, 1, args.n)))
                    for i = 1, res.n do wrapObj(res[i]) end
                    if name == "AddLabel" or (name == "_make" and kind == "Label") then patchLabelSet(res[1]) end
                    return table.unpack(res, 1, res.n)
                end)
            end
        end
    end
    function wrapObj(o)
        if type(o) ~= "table" then return end
        local cls = classOf(o)
        if cls ~= nil then patchClass(cls) end
        -- objects with their own methods (dialogs) are patched as they are
        if rawget(o, "AddPage") ~= nil or rawget(o, "AddSection") ~= nil then patchClass(o) end
    end
    -- called with every menu right after it is made; does nothing while the language is English
    function L.attach(menu)
        if L.lang ~= "zh" then return end
        local ok, err = pcall(wrapObj, menu)
        if not ok and K.Log then K.Log("ui", "menu language: could not attach: " .. tostring(err)) end
    end
    -- notification parts ({ {Text=..}, .. } or a string)
    function L.parts(p)
        if L.lang ~= "zh" then return p end
        if type(p) == "string" then return T(p) end
        if type(p) ~= "table" then return p end
        local out = {}
        for i, part in ipairs(p) do
            if type(part) == "table" and type(part.Text) == "string" and not part.Accent then
                local c = table.clone(part)
                c.Text = T(part.Text)
                out[i] = c
            else
                out[i] = part
            end
        end
        return out
    end

    local function readLang()
        local g
        pcall(function() g = getgenv().LxYLang end)
        if g == "zh" or g == "en" then return g end
        local isf, rf = K.fn("isfile"), K.fn("readfile")
        if isf and rf then
            local ok, v = pcall(function() return isf(LANG_FILE) and rf(LANG_FILE) or nil end)
            if ok and type(v) == "string" then
                v = v:gsub("%s", "")
                if v == "zh" or v == "en" then return v end
            end
        end
        return "en"
    end
    L.lang = readLang()
    L.Choices = { "English", "繁體中文" }
    function L.Choice() return L.lang == "zh" and "繁體中文" or "English" end
    -- switch language: saved, and the menu is rebuilt in the new language (like switching UI Style)
    function L.Set(lang)
        if lang == "繁體中文" then lang = "zh" elseif lang == "English" then lang = "en" end
        if (lang ~= "zh" and lang ~= "en") or lang == L.lang then return end
        L.lang = lang
        pcall(function() getgenv().LxYLang = lang end)
        local wrf = K.fn("writefile")
        if wrf then pcall(wrf, LANG_FILE, lang) end
        if K.Log then K.Log("ui", "menu language: " .. lang) end
        if K.RebuildMenu and K.UIMode then task.defer(K.RebuildMenu, K.UIMode()) end
    end
end

K.Mark("pcall wrapper + diagnostics")
--==========================================================================
--  pcall wrapper: an error swallowed by a pcall is still recorded (once per distinct message, with a repeat
--  counter and where the failing function was defined). The diagnostics block below writes them to
--  session_<UserId>_<time>_pcall.log. It is installed on the global pcall instead of a local, because the main
--  chunk is close to Luau's limit of 200 locals, and the original is put back on unload. Behaviour of pcall is
--  unchanged (same return values, yields still work).
--  Since the script no longer calls getfenv (see K.fn), an executor that runs it in an optimised environment
--  binds this script's own `pcall` calls when the script is loaded, before this wrapper exists: there the log
--  only gets what reaches the global pcall afterwards. That is the price of keeping Luau's fast paths on.
--==========================================================================
do
    local env = getgenv()
    local oldPcall = env.__KiciaOrigPcall or pcall
    env.__KiciaOrigPcall = oldPcall
    local S = { total = 0, keys = {}, nkeys = 0, new = {}, lines = 0, dropped = 0, busy = false }
    K.Swallowed = S
    local function describe(f)
        if type(f) ~= "function" then return "?" end
        local ok, src, line = oldPcall(debug.info, f, "sl")
        if ok then return tostring(src) .. ":" .. tostring(line) end
        return "?"
    end
    local function report(f, err)
        if S.busy then return end
        S.total += 1
        local key = type(err) == "string" and err or tostring(err)
        local e = S.keys[key]
        if e then e.n += 1 return end
        if S.nkeys >= 600 then S.dropped += 1 return end
        S.busy = true
        e = { n = 1, where = describe(f), msg = string.sub(key, 1, 300) }
        S.keys[key] = e
        S.nkeys += 1
        S.new[#S.new + 1] = e
        S.busy = false
    end
    local function finish(f, ok, ...)
        if not ok then report(f, (...)) end
        return ok, ...
    end
    local function wrapped(f, ...)
        return finish(f, oldPcall(f, ...))
    end
    env.pcall = wrapped
    K.onUnload(function()
        if env.pcall == wrapped then env.pcall = oldPcall end
    end)
end

--==========================================================================
--  Diagnostics log (survives crashes)
--  Every session writes kiciarebuild/logs/session_<UserId>_<time>.log as it goes (appended line by line, so the
--  last lines are on disk even when the client dies). A heartbeat line every 15 s records fps, Roblox memory,
--  Lua heap, instance count, ping and which match of the current chain this is. A small state file tells the next
--  start how the previous session ended: if it did not end cleanly (not unloaded, not a normal leave, or a
--  teleport that never arrived) a report with its last lines is added to kiciarebuild/logs/crash_reports.log.
--  K.Log(level, message) is available to the rest of the script.
--==========================================================================
do
    local wrf, apf, rdf = K.fn("writefile"), K.fn("appendfile"), K.fn("readfile")
    local isf, isd, mkf = K.fn("isfile"), K.fn("isfolder"), K.fn("makefolder")
    local lsf, dlf = K.fn("listfiles"), K.fn("delfile")
    local dir = "kiciarebuild/logs"
    if mkf then
        for _, p in ipairs({ "kiciarebuild", dir }) do
            pcall(function() if not (isd and isd(p)) then mkf(p) end end)
        end
    end

    local uid = tostring(player.UserId)
    local t0 = tick()
    local path = string.format("%s/session_%s_%s.log", dir, uid, os.date("%Y%m%d_%H%M%S"))
    local statePath = string.format("%s/state_%s.json", dir, uid)
    local reportPath = dir .. "/crash_reports.log"
    local lineCount, maxLines = 0, 4000
    local canWrite = (apf ~= nil) or (wrf ~= nil and rdf ~= nil and isf ~= nil)

    local function append(file, text)
        if apf then
            pcall(apf, file, text)
        elseif canWrite then
            -- no appendfile in this executor: rewrite the file (the line cap keeps it small)
            local old = ""
            pcall(function() if isf(file) then old = rdf(file) end end)
            pcall(wrf, file, old .. text)
        end
    end

    -- Breadcrumbs: the last actions before the end. A process killed from outside (anti-cheat, crash) leaves no
    -- message, so the newest crumbs are kept in the state file (saved every 3 s) and printed in the crash report.
    local crumbs = {}
    function K.Crumb(text)
        crumbs[#crumbs + 1] = os.date("%H:%M:%S ") .. string.sub(tostring(text), 1, 160)
        if #crumbs > 16 then table.remove(crumbs, 1) end
    end

    function K.Log(level, msg)
        if level ~= "beat" then K.Crumb(tostring(level) .. ": " .. tostring(msg)) end
        if lineCount >= maxLines or not canWrite then return end
        lineCount += 1
        append(path, string.format("[%s +%6.1fs %-5s] %s\n", os.date("%H:%M:%S"), tick() - t0, tostring(level), tostring(msg)))
    end
    K.LogPath = path
    local swPath = string.gsub(path, "%.log$", "_pcall.log")

    -- clock = os.clock() is the process's own timer: it keeps counting across a server switch inside the same
    -- Roblox process and starts over in a new process, which is how a switch is told from a restart after a crash
    local state = { state = "running", path = path, started = os.time(), beat = os.time(), matches = 1, last = "",
        clock = os.clock(), tpAt = 0, peakMem = 0, maxStall = 0, stallAt = 0, kick = "", disc = "", crumbs = crumbs,
        swallowed = 0 }
    local function saveState()
        state.clock = os.clock()
        state.swallowed = K.Swallowed and K.Swallowed.total or 0
        if wrf then pcall(wrf, statePath, HttpService:JSONEncode(state)) end
    end

    -- best guess at why the previous session vanished, from what was recorded before it did
    local function guessCause(prev, gap)
        if prev.kick ~= nil and prev.kick ~= "" then
            return "Roblox showed an error prompt first (kick / anti-cheat / lost connection): " .. tostring(prev.kick)
        end
        if prev.disc ~= nil and prev.disc ~= "" then
            return "the connection to the server was closed first: " .. tostring(prev.disc)
        end
        if (tonumber(prev.peakMem) or 0) >= 3000 then
            return string.format("Roblox memory was very high (peak %.0f MB): most likely ran out of memory", tonumber(prev.peakMem))
        end
        if (tonumber(prev.maxStall) or 0) >= 3 then
            return string.format("the game froze for %.1f s shortly before the end (hang, then killed or crashed)", tonumber(prev.maxStall))
        end
        return "no warning of any kind (no kick prompt, no disconnect, no memory or freeze signs): the process was "
            .. "terminated from outside - anti-cheat termination, a client crash, or the window / task was closed"
    end

    -- how did the previous session of this account end?
    local prev
    if rdf and isf then
        local ok, data = pcall(function()
            if isf(statePath) then return HttpService:JSONDecode(rdf(statePath)) end
            return nil
        end)
        if ok and type(data) == "table" then prev = data end
    end
    local prevNote = "none"
    if prev then
        local gap = os.time() - (tonumber(prev.beat) or 0)
        -- same process = a real server switch; a smaller clock means Roblox was restarted since
        local sameProcess = tonumber(prev.clock) ~= nil and os.clock() >= tonumber(prev.clock) - 1
        if prev.state == "teleport" and gap < 300 and sameProcess then
            state.matches = (tonumber(prev.matches) or 1) + 1
            prevNote = string.format("server switch, %d s after the teleport started", os.time() - (tonumber(prev.tpAt) or os.time()))
        elseif prev.state == "clean" or prev.state == "left" then
            prevNote = "previous session ended normally (" .. tostring(prev.state) .. ")"
        elseif prev.path ~= path then
            prevNote = "PREVIOUS SESSION DID NOT END CLEANLY"
            local tail = ""
            pcall(function()
                if isf(prev.path) then
                    local rows = {}
                    for row in string.gmatch(rdf(prev.path), "[^\n]+") do rows[#rows + 1] = row end
                    tail = table.concat(rows, "\n", math.max(1, #rows - 14), #rows)
                end
            end)
            local lastActions = ""
            if type(prev.crumbs) == "table" then
                lastActions = "    " .. table.concat(prev.crumbs, "\n    ")
            end
            append(reportPath, string.format(
                "=== %s  a session ended without a clean exit (client crash, killed process, or the window was closed)\n"
                    .. "  likely cause     : %s\n"
                    .. "  state at the end : %s\n  session log      : %s\n  last sign of life: %s (%d s before this start)\n"
                    .. "  matches in chain : %s\n  last stats       : %s\n  peak memory      : %.0f MB | longest freeze in the last minute: %.1f s\n"
                    .. "  errors swallowed by pcall: %s (see the _pcall.log next to the session log)\n"
                    .. "  last actions before the end (newest last):\n%s\n  last log lines:\n%s\n\n",
                os.date("%Y-%m-%d %H:%M:%S"), guessCause(prev, gap), tostring(prev.state), tostring(prev.path),
                os.date("%H:%M:%S", tonumber(prev.beat) or 0), gap, tostring(prev.matches), tostring(prev.last),
                tonumber(prev.peakMem) or 0, tonumber(prev.maxStall) or 0, tostring(prev.swallowed), lastActions, tail))
            prevNote = "PREVIOUS SESSION DID NOT END CLEANLY - likely cause: " .. guessCause(prev, gap)
            KQ("[Kicia Rebuild] the previous session did not end cleanly - see " .. reportPath)
        end
    end
    saveState()

    local executor = "?"
    pcall(function() executor = tostring((identifyexecutor or getexecutorname or function() return "?" end)()) end)
    local rbxVersion = "?"
    pcall(function() rbxVersion = version() end)
    K.Log("info", string.format("start build=%s account=%s place=%s job=%s private=%s match=%d executor=%s roblox=%s",
        tostring(K.Build), uid, tostring(game.PlaceId), tostring(game.JobId), tostring(game.PrivateServerId ~= ""),
        state.matches, executor, rbxVersion))
    K.Log("info", "previous: " .. prevNote .. (prev and prev.last ~= "" and (" | last stats: " .. tostring(prev.last)) or ""))
    KQ("[Kicia Rebuild] diagnostics log: " .. path)

    -- keep only the newest 40 session logs (and their _pcall.log files) of this account
    if lsf and dlf then
        pcall(function()
            local mine = {}
            for _, f in ipairs(lsf(dir)) do
                local name = tostring(f)
                if string.find(name, "session_" .. uid .. "_", 1, true) then mine[#mine + 1] = name end
            end
            table.sort(mine)
            for i = 1, #mine - 80 do pcall(dlf, mine[i]) end
        end)
    end

    local conns = {}
    local function hook(signal, fn)
        local ok, c = pcall(function() return signal:Connect(fn) end)
        if ok and c then conns[#conns + 1] = c end
    end

    -- teleports and how the session ends
    local statsLine
    hook(player.OnTeleport, function(st, placeId)
        -- stats at the moment of every teleport stage, so a crash during a server switch can be compared with
        -- the heartbeat lines before it
        K.Log("tp", string.format("%s place=%s | %s", tostring(st), tostring(placeId), statsLine and statsLine() or ""))
        if st == Enum.TeleportState.Started then
            state.state, state.beat, state.tpAt = "teleport", os.time(), os.time()
            saveState()
        elseif st == Enum.TeleportState.Failed then
            state.state, state.beat = "running", os.time()
            saveState()
        end
    end)
    hook(Players.PlayerRemoving, function(p)
        if p == player and state.state ~= "teleport" then
            K.Log("info", "local player is leaving")
            state.state, state.beat = "left", os.time()
            saveState()
        end
    end)
    pcall(function()
        game:BindToClose(function()
            if state.state ~= "teleport" then
                K.Log("info", "BindToClose")
                state.state, state.beat = "left", os.time()
                saveState()
            end
        end)
    end)

    -- Roblox's own error prompts (kicks, lost connection, ...) and script errors
    local GuiService = game:GetService("GuiService")
    hook(GuiService.ErrorMessageChanged, function()
        local ok, msg = pcall(function() return GuiService:GetErrorMessage() end)
        if ok and msg and msg ~= "" then
            local okType, errType = pcall(function() return tostring(GuiService:GetErrorType()) end)
            K.Log("gui", "error prompt: " .. tostring(msg) .. (okType and (" (" .. errType .. ")") or ""))
            state.kick, state.beat = string.sub(tostring(msg), 1, 200), os.time()
            saveState()
        end
    end)
    -- the connection to the server going away without a prompt (the prompt usually follows a moment later)
    pcall(function()
        hook(game:GetService("NetworkClient").ChildRemoved, function(child)
            K.Log("net", "NetworkClient child removed: " .. tostring(child))
            state.disc, state.beat = "NetworkClient child removed (" .. tostring(child) .. ")", os.time()
            saveState()
        end)
    end)
    pcall(function()
        local UIS = game:GetService("UserInputService")
        hook(UIS.WindowFocused, function() K.Crumb("window focused") end)
        hook(UIS.WindowFocusReleased, function() K.Crumb("window lost focus") end)
    end)

    -- Low-load mode. With several clients open (5 on one RTX 4060 in the 2026-11-14 18:2x logs) every one fell to
    -- fps 4-17 with frames of 1-2.4 s and the one that was slowest (fps=4) crashed natively (access violation in
    -- RobloxPlayerBeta, after an 11 s freeze). A client that nobody is looking at has no need to draw the 3D world,
    -- so while low-load is on: 3D rendering is switched off, the graphics quality drops to 1 and the fps cap is 60
    -- (rendering off would otherwise spin the loop at 300+ fps). Everything is put back when low-load ends, or when
    -- the script unloads. Server-side logic, physics, animation and the ragebot do not depend on drawing and keep
    -- running (the effect of render-off on the ragebot is not measured yet - hence the "keep 3D" mode).
    -- K.PerfMode is set from Settings > General > Startup > Low-Load Mode and kept per account, in the file
    -- <K.AccountDir>/perf_mode.txt (the old shared file KICIA_PERF_MODE is no longer read):
    --   "auto"   low-load only while the Roblox window is not the active window
    --   "keep3d" same, but 3D rendering stays on (only quality and fps cap drop)
    --   "always" low-load even while the window is active (a single client that is only watched)
    --   "off"    never touch rendering (default)
    K.PerfModes = { auto = "Auto (window inactive)", keep3d = "Auto, keep 3D on", always = "Always", off = "Off" }
    K.PerfOrder = { "Auto (window inactive)", "Auto, keep 3D on", "Always", "Off" }
    function K.SetPerfMode(label)
        for key, text in pairs(K.PerfModes) do
            if text == label then
                K.PerfMode = key
                local wrf = K.fn and K.fn("writefile")
                if wrf then pcall(wrf, K.AccountDir .. "/perf_mode.txt", key) end
                return
            end
        end
    end
    pcall(function()
        if K.PerfMode == nil then
            K.PerfMode = "off" -- default: off (the user turns it on in Settings > General > Startup > Low-Load Mode)
            local perfFile = K.AccountDir .. "/perf_mode.txt"
            if isfile(perfFile) then
                local t = string.gsub(readfile(perfFile), "%s+", "")
                if K.PerfModes[t] ~= nil then K.PerfMode = t end
            end
        end
        local RS = game:GetService("RunService")
        local LOW_CAP = 60
        local cur, saved = "normal", nil -- "normal" | "low" | "low-keep3d"
        local function active()
            local ok, a = pcall(isrbxactive)
            if ok and type(a) == "boolean" then return a end
            return true -- cannot tell: behave as if watched, never starve a client by mistake
        end
        local function want()
            local m = K.PerfMode
            if m == "off" then return "normal" end
            if m == "always" or not active() then return "low" end
            return "normal"
        end
        local function setState(target)
            if target == "low" and K.PerfMode == "keep3d" then target = "low-keep3d" end
            if target == cur then return end
            if cur ~= "normal" then
                local s = saved or {}
                pcall(function() RS:Set3dRenderingEnabled(true) end)
                if s.quality ~= nil then pcall(function() settings().Rendering.QualityLevel = s.quality end) end
                -- getfpscap() gives 0 when it cannot be read; setfpscap(0) means the 2000 maximum, i.e. uncapped
                pcall(setfpscap, (type(s.cap) == "number" and s.cap > 0) and s.cap or 0)
                K.Log("perf", string.format("low-load off (cap back to %s)", tostring(s.cap)))
                saved, cur = nil, "normal"
            end
            if target ~= "normal" then
                saved = {}
                pcall(function() saved.cap = getfpscap() end)
                pcall(function() saved.quality = settings().Rendering.QualityLevel end)
                local r1 = target == "low-keep3d" or pcall(function() RS:Set3dRenderingEnabled(false) end)
                local r2 = pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
                local r3 = pcall(setfpscap, LOW_CAP)
                cur = target
                K.Log("perf", string.format("low-load on [%s] (3d off=%s, quality=%s, cap=%s; was cap=%s quality=%s)",
                    tostring(K.PerfMode), tostring(r1), tostring(r2), tostring(r3), tostring(saved.cap), tostring(saved.quality)))
            end
        end
        task.spawn(function()
            while not K.destroyed do
                setState(want())
                task.wait(1)
            end
        end)
        K.onUnload(function() setState("normal") end)
    end)

    local seen, logged = {}, 0
    local function noteError(kind, message)
        message = tostring(message)
        local key = string.sub(message, 1, 120)
        seen[key] = (seen[key] or 0) + 1
        if seen[key] <= 3 and logged < 300 then
            logged += 1
            K.Log(kind, string.sub(message, 1, 400))
        end
    end
    hook(game:GetService("LogService").MessageOut, function(message, messageType)
        if messageType == Enum.MessageType.MessageError then
            noteError("error", message)
        elseif messageType == Enum.MessageType.MessageWarning and string.find(message, "[Kicia", 1, true) then
            noteError("warn", message)
        end
    end)
    hook(game:GetService("ScriptContext").Error, function(message, trace)
        noteError("lua", tostring(message) .. " | " .. string.gsub(tostring(trace), "\n", " / "))
    end)

    -- heartbeat
    local frames, elapsed, worstDt, stallLines = 0, 0, 0, 0
    -- the menu notes its last step here (page build, window shown / hidden) so a stall line says what the menu
    -- was doing just before the game froze
    function K.UIMark(name)
        K.UILast, K.UILastAt = name, os.clock()
    end
    hook(RunService.Heartbeat, LPH_NO_VIRTUALIZE(function(dt)
        frames += 1
        elapsed += dt
        if dt > worstDt then worstDt = dt end
        -- a frame that took long: the game froze for that time (logged, and kept for the crash report)
        if dt > 0.75 then
            if dt > state.maxStall then state.maxStall, state.stallAt = dt, os.time() end
            if stallLines < 100 then
                stallLines += 1
                local lastUI = ""
                if K.UILast ~= nil then
                    lastUI = string.format(" | last menu step: %s, %.1f s before the frame ended", K.UILast, os.clock() - K.UILastAt)
                end
                K.Log("stall", string.format("frame took %.2f s | %s%s", dt, statsLine and statsLine() or "", lastUI))
            end
        end
    end))
    local Stats = game:GetService("Stats")
    function statsLine()
        local fps = elapsed > 0 and frames / elapsed or 0
        local mem, inst, ping = -1, -1, -1
        pcall(function() mem = Stats:GetTotalMemoryUsageMb() end)
        pcall(function() inst = Stats.InstanceCount end)
        pcall(function() ping = Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
        local luaMb = collectgarbage("count") / 1024
        if mem > state.peakMem then state.peakMem = mem end
        return string.format("fps=%.0f mem=%.0fMB lua=%.0fMB inst=%d ping=%.0fms worst-frame=%.2fs match=%d conns=%d pcall-errors=%d",
            fps, mem, luaMb, inst, ping, worstDt, state.matches, #K.connections, K.Swallowed and K.Swallowed.total or 0)
    end
    -- errors swallowed by pcall (K.Swallowed, filled by the pcall wrapper at the top of the script): new messages go
    -- to the _pcall.log file, and every 30 s a summary of the most frequent ones
    local function flushSwallowed(mode)
        local S = K.Swallowed
        if not S then return end
        if #S.new > 0 then
            local rows = {}
            for i, e in ipairs(S.new) do
                rows[#rows + 1] = string.format("[%s] %s  | pcall'd function defined at %s", os.date("%H:%M:%S"), e.msg, e.where)
                if i <= 3 then K.Crumb("pcall: " .. e.msg) end
            end
            S.new = {}
            if S.lines < 1500 then
                S.lines += #rows
                append(swPath, table.concat(rows, "\n") .. "\n")
            end
        end
        local function summary(limit)
            local list = {}
            for _, e in pairs(S.keys) do list[#list + 1] = e end
            table.sort(list, function(a, b) return a.n > b.n end)
            local out = {}
            for i = 1, math.min(limit, #list) do
                out[i] = string.format("  x%d  %s  | %s", list[i].n, list[i].msg, list[i].where)
            end
            return table.concat(out, "\n")
        end
        if mode == "final" then
            append(swPath, string.format("--- final: %d errors swallowed, %d distinct (%d more distinct ones not tracked). Most frequent:\n%s\n",
                S.total, S.nkeys, S.dropped, summary(25)))
        elseif mode == "summary" and S.total ~= S.lastSummaryTotal then
            S.lastSummaryTotal = S.total
            K.Log("pcall", string.format("swallowed so far: %d (%d distinct) | most frequent: %s", S.total, S.nkeys,
                string.gsub(summary(3), "\n", " ;")))
        end
    end

    task.spawn(function()
        local tick3 = 0
        while not K.destroyed do
            task.wait(3)
            tick3 += 1
            state.beat = os.time()
            if tick3 % 5 == 0 then
                state.last = statsLine()
                frames, elapsed, worstDt = 0, 0, 0
                K.Log("beat", state.last)
            end
            flushSwallowed(tick3 % 10 == 0 and "summary" or nil)
            if tick3 % 10 == 0 then
                state.maxStall = 0 -- the longest freeze counts for the last 30-60 s only
            end
            saveState()
        end
    end)

    K.onUnload(function()
        flushSwallowed("final")
        for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
        K.Log("info", "unload (clean)")
        state.state, state.beat = "clean", os.time()
        saveState()
    end)
end

K.Mark("signal/trove")
--==========================================================================
--  Signal / Trove (Kicia's own small versions)
--==========================================================================
local Signal = {}
Signal.__index = Signal
function Signal.new() return setmetatable({ _handlers = {} }, Signal) end
function Signal:Connect(fn)
    local h = { fn = fn, connected = true }
    table.insert(self._handlers, h)
    local sig = self
    return {
        Connected = true,
        Disconnect = function(c)
            if not h.connected then return end
            h.connected = false
            c.Connected = false
            local i = table.find(sig._handlers, h)
            if i then table.remove(sig._handlers, i) end
        end,
    }
end
function Signal:Once(fn)
    local c
    c = self:Connect(function(...) c:Disconnect() fn(...) end)
    return c
end
function Signal:Fire(...)
    local list = table.clone(self._handlers)
    for _, h in ipairs(list) do
        if h.connected then task.spawn(h.fn, ...) end
    end
end
function Signal:FireSync(...)
    for _, h in ipairs(table.clone(self._handlers)) do
        if h.connected then h.fn(...) end
    end
end
function Signal:Destroy() table.clear(self._handlers) end
K.Signal = Signal

local Trove = {}
Trove.__index = Trove
function Trove.new(name) return setmetatable({ _name = name, _items = {} }, Trove) end
local function cleanItem(o)
    local t = typeof(o)
    if t == "RBXScriptConnection" then o:Disconnect()
    elseif t == "Instance" then pcall(function() o:Destroy() end)
    elseif t == "thread" then pcall(task.cancel, o)
    elseif type(o) == "function" then pcall(o)
    elseif type(o) == "table" then
        --  some objects (Kicia's signal connections) error on unknown fields
        local function member(k)
            local ok, v = pcall(function() return o[k] end)
            return ok and type(v) == "function" and v or nil
        end
        local cancel, getStatus = member("cancel"), member("getStatus")
        if cancel and getStatus then pcall(cancel, o) return end
        local destroy = member("Destroy")
        if destroy then pcall(destroy, o) return end
        local disconnect = member("Disconnect")
        if disconnect then pcall(disconnect, o) end
    end
end
function Trove:Add(o) table.insert(self._items, o) return o end
function Trove:Connect(sig, fn) return self:Add(sig:Connect(fn)) end
function Trove:Extend() return self:Add(Trove.new(self._name)) end
function Trove:Remove(o, keep)
    local i = table.find(self._items, o)
    if i then
        table.remove(self._items, i)
        if not keep then cleanItem(o) end
    end
end
--  Promise held until it settles; cancelled if the trove is cleaned first.
function Trove:AddPromise(promise)
    if tostring(promise:getStatus()) == "Started" then
        self:Add(promise)
        promise:finally(function()
            if not self._cleaning then self:Remove(promise, true) end
        end)
    end
    return promise
end
--  Sub-trove that cleans itself up when `instance` is destroyed.
function Trove:AttachExtend(instance)
    local sub = self:Extend()
    sub:Connect(instance.Destroying, function() self:Remove(sub) end)
    return sub
end
