--==========================================================================
--  Rivals anti-cheat bypass (replaces Kicia's b7)
--
--  LocalScript3 runs a plaintext check function every Heartbeat that probes
--  for environment tampering (hook detection on 29 C-function bait pairs,
--  trap-table metamethod sentinels, metatable lock strings, newproxy
--  identity, EncodingService).  When a check fails it calls a Luraph-VM
--  reporter closure (u53) that fires the AnalyticsPipeline remote with the
--  detection code.  The 40-byte challenge-response lives in separate VM
--  code and is not touched.
--
--  Strategy: GC-scan for the check function, replace the reporter upvalue
--  with a no-op.  The check still runs (normal control flow for the VM)
--  but detection codes never reach the server.
--==========================================================================
do
    local getgc_        = K.fn("getgc")
    local isexec_       = K.fn("isexecutorclosure") or function() return false end
    local iscc_         = K.fn("iscclosure")
    -- getgc(true) also yields C closures; debug.getupvalue throws "Lua function expected" on them
    local rawgetup_     = debug.getupvalue
    local function getupvalue_(f, i)
        local ok, n, v = pcall(rawgetup_, f, i)
        if ok then return n, v end
        return nil
    end
    local setupvalue_   = debug.setupvalue

    local function findAndSilence()
        if not getgc_ then return false end

        local acRemote
        pcall(function()
            local r = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
            if r then
                local ap = r:FindFirstChild("AnalyticsPipeline")
                if ap then acRemote = ap:FindFirstChild("RemoteEvent") end
            end
        end)

        for _, obj in next, getgc_(true) do
            if type(obj) ~= "function" or isexec_(obj) then continue end
            if iscc_ and iscc_(obj) then continue end

            local lockedIdx, baitIdx, remoteIdx
            local nups = 0

            for i = 1, 50 do
                local name, val = getupvalue_(obj, i)
                if name == nil then break end
                nups = nups + 1

                if val == "The metatable is locked" then
                    lockedIdx = i
                end

                if acRemote and val == acRemote then
                    remoteIdx = i
                end

                if type(val) == "table" and not baitIdx then
                    local n, ok = 0, true
                    for _, entry in next, val do
                        n = n + 1
                        if n > 30 or type(entry) ~= "table" then ok = false; break end
                    end
                    if ok and n == 29 then baitIdx = i end
                end
            end

            if lockedIdx and baitIdx and nups >= 20 then
                -- found the plaintext check function
                -- reporter (u53) is the function upvalue immediately before the bait table (u54)
                for i = baitIdx - 1, 1, -1 do
                    local _, val = getupvalue_(obj, i)
                    if type(val) == "function" then
                        setupvalue_(obj, i, function() end)
                        K.Crumb("AC bypass: reporter silenced (up " .. i .. ")")
                        return true
                    end
                end
                -- fallback: scan all function upvalues after the bait table that are
                -- NOT in the 15-fn call list (u58) and silence each one that has ≤ 2
                -- upvalues itself (the reporter has 2: VM table + tbl#20)
                for i = 1, nups do
                    local _, val = getupvalue_(obj, i)
                    if type(val) == "function" and i ~= baitIdx then
                        local inner = 0
                        pcall(function()
                            for j = 1, 5 do
                                if getupvalue_(val, j) == nil then break end
                                inner = inner + 1
                            end
                        end)
                        if inner == 2 then
                            local _, sub1 = pcall(getupvalue_, val, 1)
                            local _, sub2 = pcall(getupvalue_, val, 2)
                            if type(sub1) == "table" and type(sub2) == "table" then
                                setupvalue_(obj, i, function() end)
                                K.Crumb("AC bypass: reporter silenced [fallback] (up " .. i .. ")")
                                return true
                            end
                        end
                    end
                end
                K.Crumb("AC bypass: check fn found but reporter not identified")
                return false
            end
        end
        return false
    end

    if not findAndSilence() then
        task.delay(3, function()
            if not findAndSilence() then
                K.Crumb("AC bypass: check function not found")
            end
        end)
    end
end

