K.Mark("rivals helper")
--==========================================================================
--  Rivals Helper: ELO leaderboard, FPS / ping / server HUD, watchlist join alerts (+ optional Discord webhook)
--  and streak-hunter alerts. Ported from v4pl/RivalsHelper (obfuscated.lua, restored with a decompiler).
--  Everything is driven by Config.RivalsHelper: a 0.25 s controller starts and stops the pieces, and
--  K.onUnload removes all of them. The menu page is tbl17.hRH (Automation > Rivals Helper).
--==========================================================================
do -- hRHrun
local function fn35()
    tbl17.aE()
    local config = tbl17.bG()
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local HttpService = game:GetService("HttpService")
    local localPlayer = Players.LocalPlayer
    local alive = true

    local function get(key)
        local ok, v = pcall(function() return config.Data.RivalsHelper[key] end)
        if ok then return v end
        return nil
    end

    local function parseList(text)
        local set = {}
        if type(text) == "string" then
            for raw in string.gmatch(text, "[^,;\n]+") do
                local item = string.lower((string.gsub(raw, "^%s+", ""):gsub("%s+$", "")))
                if item ~= "" then set[item] = true end
            end
        end
        return set
    end

    local function new(class, props)
        local inst = Instance.new(class)
        for k, v in pairs(props) do inst[k] = v end
        return inst
    end

    local function headshot(userId)
        return "https://www.roblox.com/headshot-thumbnail/image?userId=" .. tostring(userId) .. "&width=100&height=100&format=png"
    end

    --------------------------------------------------------------- popups
    local popupGui
    local slots = {}
    local function popup(text, color, soundId, duration, imageUrl)
        if not alive then return end
        if popupGui == nil or popupGui.Parent == nil then
            popupGui = new("ScreenGui", {Name = HttpService:GenerateGUID(false), ResetOnSpawn = false, DisplayOrder = 30, Parent = K.hudParent()})
        end
        local slot = 1
        while slots[slot] do slot = slot + 1 end
        slots[slot] = true
        local y = 12 + (slot - 1) * 78
        local frame = new("Frame", {
            Size = UDim2.new(0, 360, 0, 70), Position = UDim2.new(0.5, -180, 0, y - 90),
            BackgroundColor3 = color, BackgroundTransparency = 0.15, BorderSizePixel = 0, Parent = popupGui,
        })
        new("UICorner", {CornerRadius = UDim.new(0, 10), Parent = frame})
        if imageUrl then
            new("ImageLabel", {Size = UDim2.new(0, 50, 0, 50), Position = UDim2.new(0, 10, 0.5, -25), BackgroundTransparency = 1, Image = imageUrl, Parent = frame})
        end
        new("TextLabel", {
            Size = UDim2.new(1, -70, 1, -10), Position = UDim2.new(0, 65, 0, 5), BackgroundTransparency = 1,
            TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.GothamBold, TextScaled = true, Text = text,
            TextXAlignment = Enum.TextXAlignment.Left, Parent = frame,
        })
        local sound = new("Sound", {SoundId = soundId, Volume = 2, Parent = frame})
        pcall(function() sound:Play() end)
        pcall(function() frame:TweenPosition(UDim2.new(0.5, -180, 0, y), Enum.EasingDirection.Out, Enum.EasingStyle.Back, 0.3, true) end)
        task.delay(duration or 3, function()
            pcall(function() frame:TweenPosition(UDim2.new(0.5, -180, 0, y - 90), Enum.EasingDirection.In, Enum.EasingStyle.Back, 0.3, true) end)
            task.wait(0.4)
            frame:Destroy()
            slots[slot] = nil
        end)
    end

    --------------------------------------------------------------- webhook
    local function sendWebhook(player, priority)
        local url = get("WebhookUrl")
        if type(url) ~= "string" or url == "" then return end
        task.spawn(function()
            pcall(function()
                local body = HttpService:JSONEncode({
                    username = "Rivals Assistant",
                    embeds = {{
                        title = priority and "Watchlist player found" or "Player found",
                        description = player.Name .. " has joined your server!",
                        color = priority and 16711680 or 3447003,
                        thumbnail = {url = headshot(player.UserId)},
                        footer = {text = "Rivals Assistant"},
                        timestamp = DateTime.now():ToIsoDate(),
                    }},
                })
                local req = (syn and syn.request) or http_request or request
                if req then
                    req({Url = url, Method = "POST", Headers = {["Content-Type"] = "application/json"}, Body = body})
                else
                    HttpService:PostAsync(url, body, Enum.HttpContentType.ApplicationJson)
                end
            end)
        end)
    end

    --------------------------------------------------------------- stats
    local function pick(parent, names)
        for _, n in ipairs(names) do
            local c = parent:FindFirstChild(n)
            if c then return c end
        end
        return nil
    end
    local function stat(player, childNames, attrNames)
        if player:FindFirstChild("leaderstats") then
            local s = pick(player.leaderstats, childNames)
            if s and s.Value ~= nil then return tonumber(s.Value) or 0 end
        end
        for _, a in ipairs(attrNames) do
            local v = player:GetAttribute(a)
            if v ~= nil then return tonumber(v) or 0 end
        end
        return 0
    end
    local function getElo(p) return stat(p, {"ELO", "Elo", "DisplayELO"}, {"DisplayELO", "ELO", "Elo", "elo", "displayELO"}) end
    local function getLevel(p) return stat(p, {"Level", "level"}, {"Level", "level"}) end
    local function getStreak(p) return stat(p, {"Win Streak", "WinStreak", "StatisticDuelsWinStreak"}, {"StatisticDuelsWinStreak", "Win Streak", "WinStreak", "StatisticDuelsWins"}) end

    local rankColors = {
        Bronze = Color3.fromRGB(205, 127, 50), Silver = Color3.fromRGB(192, 192, 192), Gold = Color3.fromRGB(255, 215, 0),
        Platinum = Color3.fromRGB(175, 238, 238), Diamond = Color3.fromRGB(0, 191, 255), Onyx = Color3.fromRGB(85, 0, 128),
        Nemesis = Color3.fromRGB(255, 69, 0), Archnemesis = Color3.fromRGB(255, 0, 0),
    }
    local function eloToRank(elo)
        if not elo then return "Bronze" end
        elo = tonumber(elo) or 0
        if elo >= 6000 then return "Archnemesis" end
        if elo >= 3600 then return "Nemesis" end
        if elo >= 3000 then return "Onyx" end
        if elo >= 2400 then return "Diamond" end
        if elo >= 1800 then return "Platinum" end
        if elo >= 1200 then return "Gold" end
        if elo >= 600 then return "Silver" end
        return "Bronze"
    end
    local function rankColor(rank)
        local c = rankColors[rank] or Color3.new(1, 1, 1)
        return string.format("rgb(%d,%d,%d)", math.floor(c.R * 255), math.floor(c.G * 255), math.floor(c.B * 255))
    end
    local function truncate(text, maxLen)
        maxLen = maxLen or 12
        if #text <= maxLen then return text end
        return string.sub(text, 1, maxLen - 1) .. "..."
    end

    --------------------------------------------------------------- draggable panels
    -- The panels are built once and then only shown / hidden. They can be dragged while the KH menu is open
    -- (K.MakeHudDraggable); the drop position is saved in Config.RivalsHelper as a percent of the screen.
    local function savedPos(keyX, keyY)
        local px, py = tonumber(get(keyX)), tonumber(get(keyY))
        if px and py and px >= 0 and py >= 0 then return UDim2.fromScale(px / 100, py / 100) end
        return nil
    end
    local function makeDraggable(frame, keyX, keyY)
        local pos = savedPos(keyX, keyY)
        if pos then frame.Position = pos end
        pcall(K.MakeHudDraggable, frame, function(x, y)
            pcall(function()
                config:Set({"RivalsHelper", keyX}, x)
                config:Set({"RivalsHelper", keyY}, y)
            end)
        end)
    end

    --------------------------------------------------------------- leaderboard
    local lb, lbToken = nil, nil
    local LB_DEFAULT = UDim2.new(1, -380, 0, 60)
    local function buildLeaderboard()
        local gui = new("ScreenGui", {
            Name = HttpService:GenerateGUID(false), ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 20,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling, Parent = K.hudParent(),
        })
        local frame = new("Frame", {
            Size = UDim2.new(0, 360, 0, 300), Position = LB_DEFAULT, BackgroundColor3 = Color3.fromRGB(25, 25, 25),
            BackgroundTransparency = 0.15, BorderSizePixel = 0, Parent = gui,
        })
        new("UICorner", {CornerRadius = UDim.new(0, 10), Parent = frame})
        new("UIStroke", {Thickness = 2, Color = Color3.fromRGB(25, 25, 40), Parent = frame})
        local title = new("Frame", {Size = UDim2.new(1, 0, 0, 36), BackgroundColor3 = Color3.fromRGB(35, 35, 35), BorderSizePixel = 0, Parent = frame})
        new("UICorner", {CornerRadius = UDim.new(0, 10), Parent = title})
        new("TextLabel", {
            Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 16,
            TextColor3 = Color3.new(1, 1, 1), Text = K.T("Rivals Leaderboard"), Parent = title,
        })
        local list = new("ScrollingFrame", {
            Size = UDim2.new(1, -10, 1, -46), Position = UDim2.new(0, 5, 0, 40), BackgroundTransparency = 1,
            ScrollBarThickness = 6, CanvasSize = UDim2.new(0, 0, 0, 0), Parent = frame,
        })
        new("UIListLayout", {Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, Parent = list})
        makeDraggable(frame, "LeaderboardX", "LeaderboardY")
        lb = {gui = gui, frame = frame, list = list, pool = {}}
    end
    local function refreshLeaderboard()
        local hide = parseList(get("HidePlayers"))
        local rows = {}
        for _, plr in ipairs(Players:GetPlayers()) do
            local elo, level, streak = getElo(plr), getLevel(plr), getStreak(plr)
            if not hide[string.lower(plr.Name)] and (level ~= 0 or streak ~= 0 or elo ~= 0 or plr.Name == localPlayer.Name) then
                table.insert(rows, {name = plr.Name, streak = streak, level = level, elo = elo, rank = eloToRank(elo)})
            end
        end
        table.sort(rows, function(a, b)
            if a.elo ~= b.elo then return a.elo > b.elo end
            if a.level ~= b.level then return a.level > b.level end
            return a.streak > b.streak
        end)
        for idx, row in ipairs(rows) do
            local label = lb.pool[idx]
            if not label then
                label = new("TextLabel", {
                    Size = UDim2.new(1, -8, 0, 22), Position = UDim2.new(0, 4, 0, (idx - 1) * 26 + 2), BackgroundTransparency = 1,
                    Font = Enum.Font.GothamSemibold, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left,
                    TextColor3 = Color3.fromRGB(230, 230, 230), RichText = true, Parent = lb.list,
                })
                lb.pool[idx] = label
            end
            local pos = "rgb(230,230,230)"
            if idx == 1 then pos = "rgb(255,215,0)" elseif idx == 2 then pos = "rgb(192,192,192)" elseif idx == 3 then pos = "rgb(205,127,50)" end
            label.Text = string.format("<font color='%s'>#%d</font> [Lvl %s] %s | <font color='%s'>WS: %s</font> | <font color='%s'>ELO: %d (%s)</font>",
                pos, idx, tostring(row.level), truncate(row.name, 12),
                row.streak > 0 and "rgb(100,255,100)" or "rgb(255,100,100)", tostring(row.streak),
                rankColor(row.rank), row.elo, row.rank)
        end
        for i = #rows + 1, #lb.pool do
            if lb.pool[i] then
                lb.pool[i]:Destroy()
                lb.pool[i] = nil
            end
        end
        lb.list.CanvasSize = UDim2.new(0, 0, 0, math.max(0, #rows * 26))
    end
    local function startLeaderboard()
        if lbToken then return end
        if not lb then buildLeaderboard() end
        lb.gui.Enabled = true
        local token = {}
        lbToken = token
        task.spawn(function()
            while alive and lbToken == token do
                local ok, err = pcall(refreshLeaderboard)
                if not ok then KQ("[RivalsHelper] leaderboard refresh error: " .. tostring(err)) end
                for _ = 1, 16 do
                    if not alive or lbToken ~= token then break end
                    task.wait(0.25)
                end
            end
        end)
    end
    local function stopLeaderboard()
        lbToken = nil
        if lb then lb.gui.Enabled = false end
    end

    --------------------------------------------------------------- HUD
    local hud, hudConn = nil, nil
    local HUD_DEFAULT = UDim2.new(1, -280, 0, 320)
    -- Server line: only values the client can really read. Checked against the client log on 2026-11-15: workspace.DistributedGameTime
    -- is NOT the server's uptime (it started ~9 s after the client had connected), and Stats.Network.ServerStatsItem.ElapsedTime
    -- matches the moment "Connection accepted" was logged, so the time shown is how long this client has been connected.
    -- The client is never told where the server is, so no region is shown.
    local function serverInfo()
        local t = 0
        local ok, v = pcall(function() return game:GetService("Stats").Network.ServerStatsItem.ElapsedTime:GetValue() end)
        t = math.floor((ok and v) or workspace.DistributedGameTime)
        return string.format("Server: %d/%d players | in %d:%02d", #Players:GetPlayers(), Players.MaxPlayers, math.floor(t / 60), t % 60)
    end
    local function buildHud()
        local gui = new("ScreenGui", {Name = HttpService:GenerateGUID(false), ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 20, Parent = K.hudParent()})
        local frame = new("Frame", {
            Size = UDim2.new(0, 260, 0, 112), Position = HUD_DEFAULT, BackgroundColor3 = Color3.fromRGB(25, 25, 25),
            BackgroundTransparency = 0.15, BorderSizePixel = 0, Parent = gui,
        })
        new("UICorner", {CornerRadius = UDim.new(0, 10), Parent = frame})
        new("UIStroke", {Thickness = 2, Color = Color3.fromRGB(25, 25, 40), Parent = frame})
        local bar = new("Frame", {Size = UDim2.new(1, 0, 0, 28), BackgroundColor3 = Color3.fromRGB(35, 35, 35), BorderSizePixel = 0, Parent = frame})
        new("UICorner", {CornerRadius = UDim.new(0, 10), Parent = bar})
        new("TextLabel", {
            Size = UDim2.new(1, -8, 1, 0), Position = UDim2.new(0, 8, 0, 0), BackgroundTransparency = 1, Font = Enum.Font.GothamBold,
            TextSize = 14, TextColor3 = Color3.fromRGB(255, 255, 255), Text = K.T("Rivals HUD"), TextXAlignment = Enum.TextXAlignment.Left, Parent = bar,
        })
        local function line(y)
            return new("TextLabel", {
                Size = UDim2.new(1, -12, 0, 20), Position = UDim2.new(0, 6, 0, y), BackgroundTransparency = 1,
                TextColor3 = Color3.fromRGB(255, 255, 255), Font = Enum.Font.GothamBold, TextSize = 14,
                TextXAlignment = Enum.TextXAlignment.Left, Parent = frame,
            })
        end
        makeDraggable(frame, "HudX", "HudY")
        hud = {gui = gui, frame = frame, fps = line(34), ping = line(58), server = line(82)}
    end
    local function startHud()
        if hudConn then return end
        if not hud then buildHud() end
        hud.gui.Enabled = true
        hud.server.Text = serverInfo()
        local frames, pingFrames, last = 0, 0, os.clock()
        hudConn = RunService.RenderStepped:Connect(LPH_NO_VIRTUALIZE(function()
            frames = frames + 1
            pingFrames = pingFrames + 1
            local now = os.clock()
            if now - last >= 1 then
                hud.fps.Text = K.T("FPS: ") .. frames
                frames = 0
                last = now
            end
            if frames % 6 == 1 or hud.ping.Text == "" then
                -- both numbers are what Roblox itself reports: Ping = the performance-stats value (GetNetworkPing, in
                -- seconds, x1000), Data = Stats.Network "Data Ping" from the developer console. No guessed conversion.
                local ok, ping = pcall(function() return math.floor(localPlayer:GetNetworkPing() * 1000 + 0.5) end)
                local okD, data = pcall(function() return math.floor(game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue() + 0.5) end)
                hud.ping.Text = K.TF("Ping: %s | Data: %s", (ok and ping) and (ping .. "ms") or "-", (okD and data) and (data .. "ms") or "-")
            end
            if pingFrames >= 60 then
                pingFrames = 0
                hud.server.Text = serverInfo()
            end
        end))
    end
    local function stopHud()
        if hudConn then hudConn:Disconnect() hudConn = nil end
        if hud then hud.gui.Enabled = false end
    end

    -- "Reset Panel Positions" button: forget the saved spots and put both panels back
    K.RivalsHelperResetPositions = function()
        for _, key in ipairs({"LeaderboardX", "LeaderboardY", "HudX", "HudY"}) do
            pcall(function() config:Set({"RivalsHelper", key}, -1) end)
        end
        if lb then lb.frame.Position = LB_DEFAULT end
        if hud then hud.frame.Position = HUD_DEFAULT end
    end

    --------------------------------------------------------------- watchlist + streak alerts
    local alerted, streakSeen = {}, {}
    local watchConn, streakConn, removeConn

    local function checkWatch(plr)
        if not alive or plr == localPlayer or alerted[plr.UserId] then return end
        if parseList(get("WatchList"))[string.lower(plr.Name)] then
            alerted[plr.UserId] = true
            popup("ALERT: " .. plr.Name .. " joined!", Color3.fromRGB(120, 0, 0), "rbxassetid://12222005", 4, headshot(plr.UserId))
            sendWebhook(plr, true)
        end
    end
    local function checkStreak(plr)
        if not alive or streakSeen[plr.UserId] or not plr.Parent then return end
        local streak = getStreak(plr)
        local limit = tonumber(get("StreakThreshold")) or 1000
        if streak >= limit then
            streakSeen[plr.UserId] = true
            popup("STREAKHUNTER: " .. tostring(plr.Name) .. " (" .. tostring(streak) .. " WS)", Color3.fromRGB(255, 128, 0), "rbxassetid://138201977", 5)
        end
    end
    local function startWatch()
        if watchConn then return end
        watchConn = Players.PlayerAdded:Connect(function(plr) task.defer(pcall, checkWatch, plr) end)
        for _, plr in ipairs(Players:GetPlayers()) do pcall(checkWatch, plr) end
    end
    local function stopWatch()
        if watchConn then watchConn:Disconnect() watchConn = nil end
    end
    local function startStreak()
        if streakConn then return end
        streakConn = Players.PlayerAdded:Connect(function(plr) task.defer(pcall, checkStreak, plr) end)
        for _, plr in ipairs(Players:GetPlayers()) do pcall(checkStreak, plr) end
    end
    local function stopStreak()
        if streakConn then streakConn:Disconnect() streakConn = nil end
    end
    removeConn = Players.PlayerRemoving:Connect(function(plr)
        alerted[plr.UserId] = nil
        streakSeen[plr.UserId] = nil
    end)

    --------------------------------------------------------------- controller
    K.onUnload(function()
        alive = false
        stopLeaderboard() stopHud() stopWatch() stopStreak()
        if lb then lb.gui:Destroy() lb = nil end
        if hud then hud.gui:Destroy() hud = nil end
        K.RivalsHelperResetPositions = nil
        if removeConn then removeConn:Disconnect() end
        if popupGui then popupGui:Destroy() end
    end)
    task.spawn(function()
        while alive and not K.destroyed do
            local function apply(on, start, stop)
                if on then pcall(start) else pcall(stop) end
            end
            apply(get("Leaderboard") == true, startLeaderboard, stopLeaderboard)
            apply(get("Hud") == true, startHud, stopHud)
            apply(get("PlayerAlerts") == true, startWatch, stopWatch)
            apply(get("StreakAlerts") == true, startStreak, stopStreak)
            task.wait(0.25)
        end
    end)
    return true
end

tbl17.hRHrun = function()
local c = tbl17.cache.hRHrun

if not c then
c = { c = fn35() }
tbl17.cache.hRHrun = c
end

return c.c
end
end
do -- hRH
local function fn35()
    tbl17.aE()
    tbl17.hRHrun()
    return function(l)
        local I = l:AddSection({Title = "Overlays", Side = "left"})
        I:AddToggle({Label = "Leaderboard (ELO / Level / Win Streak)", Config = {"RivalsHelper", "Leaderboard"}})
        I:AddToggle({Label = "Info HUD (FPS / Ping / Server)", Config = {"RivalsHelper", "Hud"}})
        I:AddTextBox({Label = "Hide From Leaderboard", Placeholder = "name1, name2", Config = {"RivalsHelper", "HidePlayers"}})
        I:AddButton({Label = "Reset Panel Positions", OnClick = function() if K.RivalsHelperResetPositions then K.RivalsHelperResetPositions() end end})
        local A = l:AddSection({Title = "Alerts", Side = "right"})
        A:AddToggle({Label = "Watchlist Join Alerts", Config = {"RivalsHelper", "PlayerAlerts"}})
        A:AddTextBox({Label = "Watchlist", Placeholder = "name1, name2", Config = {"RivalsHelper", "WatchList"}})
        A:AddTextBox({Label = "Discord Webhook URL (optional)", Placeholder = "https://discord.com/api/webhooks/...", Config = {"RivalsHelper", "WebhookUrl"}})
        A:AddToggle({Label = "Streak Hunter Alerts", Config = {"RivalsHelper", "StreakAlerts"}})
        A:AddSlider({Label = "Streak Threshold", Min = 5, Max = 1000, Step = 5, Config = {"RivalsHelper", "StreakThreshold"}})
    end
end

tbl17.hRH = function()
local c = tbl17.cache.hRH

if not c then
c = { c = fn35() }
tbl17.cache.hRH = c
end

return c.c
end
end
--==========================================================================
--  Damage Text: the two hit-effect number styles of Unnamed Enhancements ("phantom forces", "fortnite damage"),
--  restored from its decompiled protos 124/4155/4160/4161/7079/7081/8201 and hooked into Hit Feedback.
--  Driven by Config.PlayerHit.DamageText; PlayerHit._HandleHit calls tbl17.hDT().show(...) on every hit.
--  The Fortnite style's font (Burbank Big Condensed Black) is the OTF that UE embeds as base64.
--==========================================================================
--  Damage Text: the two hit-effect number styles of Unnamed Enhancements ("phantom forces", "fortnite damage"),
--  restored from its decompiled protos 124/4155/4160/4161/7079/7081/8201 and hooked into Hit Feedback.
--  Driven by Config.PlayerHit.DamageText; PlayerHit._HandleHit calls tbl17.hDT().show(...) on every hit.
--  The Fortnite style's font (Burbank Big Condensed Black) is the OTF that UE embeds as base64.
--==========================================================================
do -- hDT
local function fn35()
    tbl17.aE()
    local config = tbl17.bG()
    local RunService = game:GetService("RunService")
    local TweenService = game:GetService("TweenService")
    local HttpService = game:GetService("HttpService")
    local Workspace = game:GetService("Workspace")
    local DT = {}
    local live = {}     -- every popup part still alive, so unload can remove them

    local function cfg(key, default)
        local ok, v = pcall(function() return config.Data.PlayerHit.DamageText[key] end)
        if ok and v ~= nil then return v end
        return default
    end

    local function new(class, props, parent)
        local i = Instance.new(class)
        for k, v in pairs(props) do i[k] = v end
        if parent then i.Parent = parent end
        return i
    end

    local function colorN(n)
        local d = {Color3.fromRGB(255, 102, 102), Color3.fromRGB(255, 150, 0), Color3.fromRGB(255, 255, 0)}
        local c = cfg("Color" .. n, d[n])
        if typeof(c) ~= "Color3" then c = d[n] end
        return c
    end

    local function track(part)
        live[part] = true
        part.Destroying:Connect(function() live[part] = nil end)
        return part
    end

    -- ───────────────────────────────── fonts ─────────────────────────────────
    local BURBANK_B64 = ""
    local zekton = function(weight, style) return Font.new("rbxasset://fonts/families/Zekton.json", weight, style) end
    local burbank

    local function b64decode(s)
        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local map = {}
        for i = 1, 64 do map[alphabet:byte(i)] = i - 1 end
        local out = buffer.create(#s * 3 // 4 + 3)
        local n = 0
        for i = 1, #s, 4 do
            local a, b, c, d = s:byte(i, i + 3)
            local vc, vd = map[c], map[d]
            local v = map[a] * 262144 + map[b] * 4096 + (vc or 0) * 64 + (vd or 0)
            buffer.writeu8(out, n, bit32.rshift(v, 16)) n += 1
            if vc then buffer.writeu8(out, n, bit32.band(bit32.rshift(v, 8), 255)) n += 1 end
            if vd then buffer.writeu8(out, n, bit32.band(v, 255)) n += 1 end
        end
        return buffer.readstring(out, 0, n)
    end

    local function getBurbank()
        if burbank then return burbank end
        local wrf, gca, isf, rdf = K.fn("writefile"), K.fn("getcustomasset") or K.fn("getsynasset"), K.fn("isfile"), K.fn("readfile")
        local ok, f = pcall(function()
            assert(wrf and gca, "executor has no writefile/getcustomasset")
            pcall(function() tbl17.w().ensureStorageDirectories("kiciarebuild/fonts") end)
            local data = b64decode(BURBANK_B64)
            local otf, json = "kiciarebuild/fonts/burbank_black.otf", "kiciarebuild/fonts/burbank_black.json"
            if not (isf and rdf and isf(otf) and #rdf(otf) == #data) then wrf(otf, data) end
            wrf(json, HttpService:JSONEncode({
                name = "burbank black",
                faces = {{name = "Regular", weight = 400, style = "normal", assetId = gca(otf)}},
            }))
            return Font.new(gca(json))
        end)
        if ok and f then burbank = f
        else
            KQ("[DamageText] Burbank font unavailable (" .. tostring(f) .. "), using GothamBlack")
            burbank = Font.fromEnum(Enum.Font.GothamBlack)
        end
        return burbank
    end

    -- ══════════════════════════ style 1: phantom forces ══════════════════════════
    local pfTemplate
    local pfCounter = 0  -- one shared cell: it picks the cycle colour AND is the spiral angle

    local function buildPF()
        if pfTemplate then return pfTemplate end
        local part = new("Part", {
            Name = "DamagePart", Transparency = 1, Anchored = true, CanCollide = false, CanQuery = false,
            CanTouch = false, CastShadow = false, Material = Enum.Material.SmoothPlastic,
            TopSurface = Enum.SurfaceType.Smooth, BottomSurface = Enum.SurfaceType.Smooth,
            Size = Vector3.new(0.2, 0.2, 0.2),
        })
        local bb = new("BillboardGui", {
            Name = "BillboardDamage", ZIndexBehavior = Enum.ZIndexBehavior.Sibling, Active = true,
            ExtentsOffset = Vector3.new(0, 0.5, 0), LightInfluence = 1, AlwaysOnTop = true,
            Size = UDim2.new(0, 500, 0, 500), ClipsDescendants = true,
        }, part)
        local function label(name, color, pos, z)
            local l = new("TextLabel", {
                Name = name, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.new(0, 20, 0, 20),
                BorderColor3 = Color3.fromRGB(0, 0, 0), BackgroundTransparency = 1, Position = pos,
                BorderSizePixel = 0, BackgroundColor3 = Color3.fromRGB(255, 255, 255),
                FontSize = Enum.FontSize.Size28, TextSize = 28, TextColor3 = color, Text = "24",
            }, bb)
            if z then l.ZIndex = z end
            l.FontFace = zekton(Enum.FontWeight.Bold, Enum.FontStyle.Normal)
            return l
        end
        label("TextDamage", Color3.fromRGB(255, 225, 0), UDim2.new(0.5, 0, 0.5, 0), 2)
        local shadow = label("TextDamageShadow", Color3.fromRGB(67, 67, 67), UDim2.new(0.5, 1, 0.5, 1))
        new("UIStroke", {Thickness = 3, Color = Color3.fromRGB(52, 52, 52)}, shadow)
        pfTemplate = part
        return part
    end

    local PF_ORIGINAL = {
        Head = Color3.fromRGB(255, 102, 102),
        UpperTorso = Color3.fromRGB(255, 150, 0),
        LowerTorso = Color3.fromRGB(255, 150, 0),
    }
    local function pfColor(partName)                       -- proto 4160
        if cfg("CycleColors", false) then return colorN(pfCounter % 3 + 1) end
        if cfg("OriginalColors", true) then return PF_ORIGINAL[partName] or Color3.fromRGB(255, 255, 0) end
        if partName == "Head" then return colorN(1) end
        if partName == "UpperTorso" then return colorN(2) end
        return colorN(3)
    end

    local function phantom(pos, partName, text)            -- proto 4161 + 7081
        local part = track(buildPF():Clone())
        part.CFrame = CFrame.new(pos)
        part.Parent = Workspace
        local head = false   -- head hits use the body hit's font (regular, normal size, thin outline); only the colour still depends on the part
        local scale = head and 1.75 or 1
        local bb = part.BillboardDamage
        local main, shadow = bb.TextDamage, bb.TextDamageShadow
        main.Text, shadow.Text = text, text
        main.TextSize, shadow.TextSize = 20 * scale, 20 * scale
        bb.Adornee = part
        bb.Parent = part
        main.TextColor3 = pfColor(partName)
        shadow.UIStroke.Thickness = head and 2 or 0.5
        if head then
            local f = zekton(Enum.FontWeight.Regular, Enum.FontStyle.Italic)
            main.FontFace, shadow.FontFace = f, f
        end
        -- golden-angle spiral: each popup lands 137.5 degrees round from the previous one
        local a = 2.399963229728653 * pfCounter
        pfCounter += 1
        local target = UDim2.new(0.5, 32 * math.cos(a), 0.5, -48 * math.sin(a) - 90)
        main:TweenPosition(target, Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 1, true)
        shadow:TweenPosition(target + UDim2.fromOffset(1, 1), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 1, true)
        task.delay(1, function()
            for i = 1, 10 do
                if not part.Parent then return end
                main.TextTransparency, shadow.TextTransparency = i / 10, i / 10
                task.wait(1 / 60)
            end
            part:Destroy()   -- the original only destroys the billboard and leaves the 0.2-stud part behind
        end)
    end

    -- ══════════════════════════ style 2: fortnite damage ══════════════════════════
    local ftBillboard, ftFrame
    local ftColorIdx = 0
    local active = {}       -- [character] = {damage, thread, part, offset}   (proto 4155's stacking table)
    local POP = TweenInfo.new(1.8, Enum.EasingStyle.Elastic, Enum.EasingDirection.Out, 0, false)

    local function buildFT()
        if ftBillboard then return end
        ftBillboard = new("BillboardGui", {
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling, Active = true, LightInfluence = 1, AlwaysOnTop = true,
            Size = UDim2.new(0, 1000, 0, 1000), ClipsDescendants = true,
        })
        new("UIScale", {}, ftBillboard)
        ftFrame = new("Frame", {
            AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.fromScale(0, 0), AnchorPoint = Vector2.new(0.5, 1),
            BackgroundTransparency = 1, Position = UDim2.new(0.5, 0, 0.5, 0),
        })
        new("TextLabel", {
            AnchorPoint = Vector2.new(0.5, 0.5), AutomaticSize = Enum.AutomaticSize.XY,
            BorderColor3 = Color3.fromRGB(0, 0, 0), BackgroundTransparency = 1, Position = UDim2.new(0.5, 0, 0.5, 0),
            BorderSizePixel = 0, BackgroundColor3 = Color3.fromRGB(255, 255, 255), FontSize = Enum.FontSize.Size60,
            TextStrokeTransparency = 0, TextSize = 40, TextColor3 = Color3.fromRGB(242, 255, 0), Text = "9",
            FontFace = getBurbank(),
        }, ftFrame)
    end

    local function ftPopup(part, damage, offset, key, startScale)      -- proto 7079 + 8201
        local bb = ftBillboard:Clone()
        bb.Parent, bb.Adornee = part, part
        local colorIdx = cfg("CycleColors", false) and ftColorIdx or 0
        local labels, cursor = {}, nil
        for _, ch in ipairs(tostring(damage):split("")) do
            colorIdx = colorIdx % 3 + 1
            local frame = ftFrame:Clone()
            local lbl = frame.TextLabel
            lbl.TextColor3 = colorN(colorIdx)
            lbl.Text = ch
            frame.Parent = bb
            lbl.Rotation = math.random(-2, 2)
            local w = lbl.TextBounds.X
            cursor = cursor and (cursor + w) or -w
            frame.Position = frame.Position + offset + UDim2.fromOffset(cursor, 0)
            table.insert(labels, lbl)
        end
        ftColorIdx = colorIdx
        local ui = bb.UIScale
        ui.Scale = startScale
        TweenService:Create(ui, POP, {Scale = 1}):Play()
        task.wait(0.7 + math.random() * 0.5)
        for i, lbl in ipairs(labels) do               -- left half flies left, right half flies right
            local dir = (i / #labels > 0.5) and 1 or -1
            local p = lbl.Position
            local pos = Vector2.new(p.X.Offset, p.Y.Offset)
            local vel = Vector2.new(dir * 75, 0)
            local t, conn = 0, nil
            conn = RunService.RenderStepped:Connect(function(dt)
                if t > 1 or not lbl.Parent then conn:Disconnect() return end
                vel = Vector2.new(vel.X - vel.X * 0.93 * dt, vel.Y + 130 * dt)   -- drag on x, gravity on y
                pos = pos + vel * dt
                lbl.Position = UDim2.new(0.5, pos.X, 0.5, pos.Y)
                lbl.TextTransparency = t
                lbl.Rotation = dir * 360 * math.exp(t)
                t += dt
            end)
        end
        task.wait(1)
        part:Destroy()
        if active[key] and active[key].part == part then active[key] = nil end
    end

    local function fortnite(char, pos, damage)             -- proto 4155
        buildFT()
        local stack = cfg("Stack", false)
        local prev = active[char]
        local startScale = (stack and prev) and 0.75 or 0   -- a merged popup re-pops from 0.75, a fresh one from 0
        if prev and stack then
            prev.part:Destroy()
            damage += prev.damage
            pcall(task.cancel, prev.thread)
        end
        local part = track(new("Part", {
            CanCollide = false, CanTouch = false, CanQuery = false, Anchored = true, Transparency = 1,
        }, Workspace))
        local offset = stack and prev and prev.offset
        if not offset then
            if stack then
                offset = UDim2.fromOffset(25, -25)
            else
                local x = math.random(-30, 30)
                if x > 0 then x += 30 end
                offset = UDim2.fromOffset(x, math.random(-30, 30))
            end
        end
        part.Position = pos + Vector3.new(0, 1.75, 0)
        local thread = task.spawn(ftPopup, part, damage, offset, char, startScale)
        active[char] = {damage = damage, thread = thread, part = part, offset = offset}
    end


    -- ══════════════════════════ non-text hit effects ══════════════════════════
    -- slashes (proto 4156), explosion (4157), bubble (4158), clone (4159); colours are the same three
    -- Color1/2/3 UE calls hit_effects_col_1..3. Each takes the BasePart that was hit.
    local function heCfg(key, default)
        local ok, v = pcall(function() return config.Data.PlayerHit.HitEffects[key] end)
        if ok and v ~= nil then return v end
        return default
    end

    -- Effects are spawned IN FRONT of the target: moved from the hit part toward the camera by FrontOffset studs
    -- (never past the camera), so they are not buried inside the enemy's body.
    local function frontPos(hitPart)
        local pos = hitPart.Position
        local cam = Workspace.CurrentCamera
        if not cam then return pos end
        local toCam = cam.CFrame.Position - pos
        local mag = toCam.Magnitude
        if mag < 0.01 then return pos end
        return pos + toCam.Unit * math.min(heCfg("FrontOffset", 2.5), mag)
    end

    local slashBB, slashImg
    local function buildSlash()
        if slashBB then return end
        slashBB = new("BillboardGui", {
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling, Active = true, LightInfluence = 1, AlwaysOnTop = true,
            Size = UDim2.new(0, 250, 0, 250), ClipsDescendants = true, Enabled = true,
        })
        new("CanvasGroup", {
            Size = UDim2.new(1, 0, 1, 0), BorderColor3 = Color3.fromRGB(0, 0, 0), BackgroundTransparency = 1,
            BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
            GroupTransparency = 1, BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        }, slashBB)
        slashImg = new("ImageLabel", {
            Size = UDim2.new(0, 30, 0, 30), BorderColor3 = Color3.fromRGB(0, 0, 0), BackgroundTransparency = 1,
            BorderSizePixel = 0, ImageColor3 = Color3.new(1, 1, 1), BackgroundColor3 = Color3.fromRGB(255, 255, 255),
            Image = "rbxassetid://101352470463799", AnchorPoint = Vector2.new(0.5, 0.5),
        })
    end

    local function slashes(hitPart)
        buildSlash()
        local bb = slashBB:Clone()
        local part = track(new("Part", {
            Anchored = true, Transparency = 1, CanCollide = false, CanTouch = false, CanQuery = false,
        }, Workspace))
        part.Position = frontPos(hitPart) + Random.new():NextUnitVector() * 1.5   -- original: hit position + random * 3
        bb.Adornee = part
        bb.Parent = part
        local canvas = bb.CanvasGroup
        local imgs, base = {}, math.random(0, 360)
        for i = 1, 3 do                                   -- three slashes fanned 45 degrees apart
            local img = slashImg:Clone()
            img.Rotation = base + i * 45
            img.Parent = canvas
            img.Position = UDim2.new(0.5, math.random(-5, 5), 0.5, math.random(-5, 5))
            table.insert(imgs, img)
            TweenService:Create(img, TweenInfo.new(1.5), {Rotation = img.Rotation + math.random(-10, 10)}):Play()
        end
        local t = 1
        while t > 0 do                                    -- fade in
            t -= task.wait() * 10
            canvas.GroupTransparency = t
        end
        for i, img in ipairs(imgs) do                     -- slash i tints to colour i
            TweenService:Create(img, TweenInfo.new(0.5), {ImageColor3 = colorN(i)}):Play()
        end
        task.wait(0.5)
        local g = 0
        while g < 1 do                                    -- fade out
            g += task.wait() * 3
            canvas.GroupTransparency = g
        end
        part:Destroy()
    end

    local function explosion(hitPart)
        local e = Instance.new("Explosion", Workspace)
        e.BlastRadius = 0                                 -- visual only
        e.Position = frontPos(hitPart)
    end

    local bubbleTpl
    local function buildBubble()
        if bubbleTpl then return end
        bubbleTpl = Instance.new("Attachment")
        local em = new("ParticleEmitter", {
            Name = "particle_1", LightEmission = 3, Transparency = NumberSequence.new(0),
            Color = ColorSequence.new(Color3.new(1, 1, 1)),
            Size = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 6, 1.2)}),
            Rotation = NumberRange.new(0), RotSpeed = NumberRange.new(0), Enabled = false, Rate = 2,
            Lifetime = NumberRange.new(0.25), Speed = NumberRange.new(0.1), Squash = NumberSequence.new(0),
            ZOffset = 1, Texture = "rbxassetid://2916153928", Orientation = "VelocityPerpendicular",
            Shape = "Box", ShapeInOut = "Outward", ShapeStyle = "Volume",
        }, bubbleTpl)
        local facing = em:Clone()
        facing.Orientation = "FacingCamera"
        facing.Parent = bubbleTpl
    end

    local function bubble(hitPart)
        buildBubble()
        local at = bubbleTpl:Clone()
        at.Parent = hitPart
        at.WorldPosition = frontPos(hitPart)
        local seq = ColorSequence.new({
            ColorSequenceKeypoint.new(0, colorN(1)), ColorSequenceKeypoint.new(0.5, colorN(2)),
            ColorSequenceKeypoint.new(1, colorN(3)),
        })
        for _, em in ipairs(at:GetChildren()) do
            em.Color = seq
            em:Emit(1)
        end
        task.delay(1, function() at:Destroy() end)
    end

    local CLONE_PARTS = {"HumanoidRootPart", "RightHand", "LeftLowerArm", "RightLowerArm", "LeftUpperArm", "RightUpperArm",
        "LowerTorso", "LeftLowerLeg", "LeftUpperLeg", "LeftFoot", "RightFoot", "RightLowerLeg", "RightUpperLeg",
        "UpperTorso", "LeftHand", "Head"}
    local cloneBusy = {}

    local function cloneFx(hitPart)
        local char = hitPart.Parent
        if not char or cloneBusy[char] then return end
        local cam = Workspace.CurrentCamera
        if cam and (hitPart.Position - cam.CFrame.Position).Magnitude > 500 then return end
        cloneBusy[char] = true
        local model = track(Instance.new("Model"))
        model.Parent = char.Parent
        local clones, color = {}, colorN(1)
        local material = Enum.Material[heCfg("CloneMaterial", "ForceField")] or Enum.Material.ForceField
        local kids = char:GetChildren()
        if char.PrimaryPart then
            local i = table.find(kids, char.PrimaryPart)
            if i then table.remove(kids, i) end
        end
        local keepAccessories = not heCfg("CloneRemoveAccessories", false)
        local function ghost(inst, mat)
            inst.Material = mat
            inst.CanCollide, inst.CanQuery, inst.Anchored = false, false, true
            inst.Color = color
            table.insert(clones, inst)
        end
        for _, c in ipairs(kids) do
            if keepAccessories and c.ClassName == "Accessory" then
                local a = c:Clone()
                local h = a:FindFirstChild("Handle")
                if h and h.Transparency ~= 1 then
                    h:ClearAllChildren()
                    a.Parent = model
                    ghost(h, Enum.Material.ForceField)
                end
            elseif table.find(CLONE_PARTS, c.Name) then
                local p = c:Clone()
                p:ClearAllChildren()
                p.Parent = model
                ghost(p, material)
            end
        end
        task.delay(0.15, function() cloneBusy[char] = false end)
        task.wait(1)
        local t = 0
        while t < 1 do
            t += RunService.RenderStepped:Wait() * 2
            for _, p in ipairs(clones) do p.Transparency = t end
        end
        table.clear(clones)
        model:Destroy()
    end

    local function runFx(name, fn, hitPart)
        task.spawn(function()
            local ok, e = pcall(fn, hitPart)
            if not ok then KQ("[HitEffects] " .. name .. ": " .. tostring(e)) end
        end)
    end

    -- hitPart = the BasePart that was hit; force = run all four regardless of the toggles (menu test)
    function DT.effects(char, hitPart, force)
        if typeof(hitPart) ~= "Instance" or not hitPart:IsA("BasePart") then
            local h = typeof(char) == "Instance" and (char:FindFirstChild("UpperTorso") or char:FindFirstChild("Head"))
            if not h then return end
            hitPart = h
        end
        if force or heCfg("Slashes", false) then runFx("slashes", slashes, hitPart) end
        if force or heCfg("Explosion", false) then runFx("explosion", explosion, hitPart) end
        if force or heCfg("Bubble", false) then runFx("bubble", bubble, hitPart) end
        if force or heCfg("Clone", false) then runFx("clone", cloneFx, hitPart) end
    end

    function DT.testFx()
        local lp = game:GetService("Players").LocalPlayer
        local mine = lp.Character and lp.Character:FindFirstChild("Head")
        local best, bd
        for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
            local c = p ~= lp and p.Character
            local h = c and c:FindFirstChild("UpperTorso")
            if h and mine then
                local d = (h.Position - mine.Position).Magnitude
                if not bd or d < bd then best, bd = c, d end
            end
        end
        best = best or lp.Character
        if best then DT.effects(best, best:FindFirstChild("UpperTorso") or best:FindFirstChild("Head"), true) end
    end

    -- ─────────────────────────────── entry point ───────────────────────────────
    -- char = the victim's Character, damage = number, part = "Head" / "Body", hitPart = the BasePart that was hit
    function DT.show(char, damage, part, hitPart, force)
        if force ~= true and cfg("Enabled", false) ~= true then return end
        if typeof(char) ~= "Instance" or type(damage) ~= "number" then return end
        damage = math.floor(damage + 0.5)   -- whole numbers only, no decimal point
        local pos
        if typeof(hitPart) == "Instance" and hitPart:IsA("BasePart") then pos = hitPart.Position end
        if not pos then
            local h = char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart
            pos = h and h.Position
        end
        if not pos then return end
        local isHead = part == "Head"
        local partName = isHead and "Head" or ((typeof(hitPart) == "Instance" and hitPart.Name or "UpperTorso"):gsub("^Hitbox", ""))
        if not isHead and not PF_ORIGINAL[partName] then partName = "UpperTorso" end
        local style = cfg("Style", "Phantom Forces")
        if style == "Fortnite" then
            task.spawn(function() local ok, e = pcall(fortnite, char, pos, damage) if not ok then KQ("[DamageText] " .. tostring(e)) end end)
        else
            local ok, e = pcall(phantom, pos, partName, tostring(damage))
            if not ok then KQ("[DamageText] " .. tostring(e)) end
        end
    end

    -- a test popup on the nearest other player, used by the menu button
    function DT.test()
        local lp = game:GetService("Players").LocalPlayer
        local mine = lp.Character and lp.Character:FindFirstChild("Head")
        local best, bd
        for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
            local c = p ~= lp and p.Character
            local h = c and c:FindFirstChild("Head")
            if h and mine then
                local d = (h.Position - mine.Position).Magnitude
                if not bd or d < bd then best, bd = c, d end
            end
        end
        best = best or lp.Character
        if not best then return end
        local head = best:FindFirstChild("Head")
        local torso = best:FindFirstChild("UpperTorso") or best:FindFirstChild("Torso") or head
        DT.show(best, 100, "Head", head, true)
        task.wait(0.3)
        DT.show(best, 24, "Body", torso, true)
    end

    function DT.clear()
        for p in pairs(live) do pcall(function() p:Destroy() end) end
        table.clear(live)
        table.clear(active)
        table.clear(cloneBusy)
    end
    K.onUnload(DT.clear)
    return DT
end

