-- to exist before we call anything a target
if v102(entity, "RootPart") == nil then
return false
end

local humanoid = v102(entity, "Humanoid")

if humanoid == nil or humanoid.Health <= 0 then
return false
end

-- the death replication sets _is_dead before Health actually reaches 0
if v102(entity, "_destroyed") or v102(entity, "_is_dead") then
return false
end

local data = v102(entity, "Data")

if data ~= nil and v102(data, "IsInvincible") == true then
return false
end

return true
end

