end

local humanoid = v102(entity, "Humanoid")
local head, body = monsterHitboxes(entity, model)

if head == nil then
return nil
end

local noItems = {}
local itemObserver = {
GetItems = function() return noItems end,
GetEquippedItem = function() return nil end,
EquippedItemAsMelee = function() return nil end,
EquippedItemAsGun = function() return nil end,
}

local aliveState = {
Alive = true,
Health = humanoid and humanoid.Health or 100,
MaxHealth = humanoid and humanoid.MaxHealth or 100,
Model = model,
Humanoid = humanoid,
RootPart = rootPart,
HitboxHead = head,
HitboxBody = body,
TargetPartsByName = { HitboxHead = head, HitboxBody = body, HitboxHeadSmall = head, HitboxBodySmall = body },
_lastPosition = nil,
Velocity = Vector3.zero,
}

local fighterState = {
Inner = entity,
-- no Player instance exists for a monster; the HUD only wants a name and attributes
Player = { Name = model.Name, GetAttribute = function() return nil end },
IsEnemy = true,
IsMonster = true,
EnvironmentId = model:GetAttribute("EnvironmentID"),
-- a monster never changes arena, so this signal exists only to be Connect-able
EnvironmentIdChanged = Signal.new(),
ItemObserver = itemObserver,
Character = { State = aliveState },
GetRank = function() return nil end,
GetCameraRotation = function() return Vector2.zero end,
IsCrouching = function() return false end,
IsInvincible = function()
local data = v102(entity, "Data")
return data ~= nil and v102(data, "IsInvincible") == true
end,
}

record = { FighterState = fighterState, AliveState = aliveState, Entity = entity }
monsterRecords[model] = record
return record
end

local function sweepContext(fighters)
local localState = fighters and fighters.LocalState

if localState == nil then
return nil
end

local localAlive = localState.Character.State

if not localAlive.Alive then
return nil
end

-- the controller builds this map in its own _Init, so it can still be absent on the first frames
local modelToEnemy = v102(enemyController, "_model_to_enemy")

if modelToEnemy == nil then
return nil
end

return modelToEnemy, localState.EnvironmentId, localAlive
end

-- EnvironmentID keeps every sweep off the monsters belonging to the other duels running on the same
-- server: BaseTower streams several towers at once and they all sit in the same workspace.
local function inOurArena(entity, environmentId)
if environmentId == nil then
return true
end

return v102(entity, "Model"):GetAttribute("EnvironmentID") == environmentId
end

-- Every monster in the arena, as fighter states, appended to `out`. The aim providers score the
-- whole candidate list themselves (FOV, distance, hitbox visibility), so narrowing it here would
-- just throw away the target they would have picked.
local function appendMonsterStates(fighters, out)
local modelToEnemy, environmentId = sweepContext(fighters)

if modelToEnemy == nil then
return out
end

local n = #out

for _, entity in next, modelToEnemy, nil do
if monsterValid(entity) and inOurArena(entity, environmentId) then
local record = monsterRecord(entity)

if record ~= nil then
n += 1
out[n] = record.FighterState
end
end
end

return out
end

return {
AppendStates = appendMonsterStates,
}
end

