"rbxassetid://17225650859",
"rbxassetid://17225651405",
}
local white = Color3.new(1, 1, 1)
local hud = nil
local iconByItemName = {}

local function create(className, props)
local instance = Instance.new(className)
for k, v in props do
if k ~= "Parent" then
instance[k] = v
end
end
instance.Parent = props.Parent
return instance
end

