create("UICorner", { CornerRadius = UDim.new(0, 6), Parent = root })
local rootStroke = create("UIStroke", { Color = theme.Outline, Parent = root })

local slots = {}
local leftGrid = createGrid(root, false)
slots[1] = createSlot(leftGrid)
slots[2] = createSlot(leftGrid)
local rightGrid = createGrid(root, true)
slots[3] = createSlot(rightGrid)
slots[4] = createSlot(rightGrid)

local center = create("Frame", {
ZIndex = 101,
BackgroundTransparency = 1,
BorderSizePixel = 0,
