Parent = header,
})
local statsRow = create("Frame", { ZIndex = 101, BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 9), LayoutOrder = 2, Parent = header })
create("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 8), Parent = statsRow })
local statLevel = createStat(statsRow, "level")
local statElo = createStat(statsRow, "elo")
local statStreak = createStat(statsRow, "streak")

local divHolder = create("Frame", { ZIndex = 101, BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, -30, 0, 6), LayoutOrder = 2, Parent = center })
local divider = create("Frame", {
