create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 4), Parent = bar })
local barTop = create("Frame", { ZIndex = 101, BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 10), LayoutOrder = 1, Parent = bar })
create("TextLabel", {
