TextColor3 = theme.TextColor,
TextSize = 13,
TextXAlignment = Enum.TextXAlignment.Right,
TextYAlignment = Enum.TextYAlignment.Bottom,
Parent = barTop,
})
local track = create("Frame", { ZIndex = 101, BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 2), LayoutOrder = 2, Parent = bar })
