end
end
end)

-- helpers other styles can use
rage.isDeflecting = rageIsDeflecting
rage.isTranslocated = rageIsTranslocated
rage.setPhysics = rageSetPhysics
rage.setCFrame = rageSetCFrame

return rage
end

