-- Diagnostics: every 5 s one line in the session log (K.Log) saying what the ragebot did with its frames, so
-- "sometimes it does not hit" can be told apart: no target at all, a target but no item to shoot with
-- (swap / reload / nothing equipped), a target and a weapon but the shoot lock held the shot back, or shots
-- actually sent. Hits are counted from the game's own hit confirmation (see ensureHitHook).
local rageDbg = { frames = 0, noTarget = 0, noShot = 0, shots = 0, why = {}, last = os.clock(), lastName = "-", lastDist = -1,
hits = 0, damage = 0, hp = setmetatable({}, { __mode = "k" }),
gameHits = 0, gameHitsTotal = 0, hookAt = 0, hookState = "not installed", wrappers = setmetatable({}, { __mode = "k" }) }

-- Real hit confirmation: the game calls ClientViewModel.PlayHitmarkerSound when the server confirmed a hit on
-- somebody. A counting wrapper around it gives the true hit count (the health-drop estimate below stays as a
-- cross-check). It is re-checked every 5 s because "Disable game hitsound" swaps the method for an empty one
-- and swaps it back, so the wrapper is put (back) on whatever is installed; a wrapper already in place is never
-- wrapped twice, which would double-count.
local function ensureHitHook()
local okCls, cls = pcall(function() return tbl17.aS().ClientViewModel end)
if not okCls or type(cls) ~= "table" then
rageDbg.hookState = "ClientViewModel not found"
return
end
local current = v102(cls, "PlayHitmarkerSound")
if type(current) ~= "function" then
rageDbg.hookState = "PlayHitmarkerSound not found"
return
end
if rageDbg.wrappers[current] then
return
end
local function counted(...)
rageDbg.gameHits += 1
rageDbg.gameHitsTotal += 1
if not rageDbg.argsLogged then
rageDbg.argsLogged = true
local types = {}
for i = 1, select("#", ...) do
local v = select(i, ...)
types[i] = typeof(v) .. ((type(v) == "number" or type(v) == "boolean" or type(v) == "string") and ("=" .. tostring(v)) or "")
end
K.Log("rage", "first game-confirmed hit (PlayHitmarkerSound args: " .. table.concat(types, ", ") .. ")")
end
return current(...)
end
rageDbg.wrappers[counted] = true
v103(cls, "PlayHitmarkerSound", counted)
rageDbg.hookState = "installed"
K.onUnload(function()
if v102(cls, "PlayHitmarkerSound") == counted then
v103(cls, "PlayHitmarkerSound", current)
end
end)
end

local function rageDebug(target, action, fired, clientCFrame, ourRoot)
rageDbg.root = ourRoot
if os.clock() - rageDbg.hookAt >= 5 then
rageDbg.hookAt = os.clock()
local okHook, errHook = pcall(ensureHitHook)
if not okHook then
rageDbg.hookState = "failed: " .. tostring(errHook)
end
end
rageDbg.frames += 1
if target == nil then
rageDbg.noTarget += 1
elseif fired then
rageDbg.shots += 1
else
rageDbg.noShot += 1
local why = action ~= nil and tostring(action.Type) or "no-item"
rageDbg.why[why] = (rageDbg.why[why] or 0) + 1
end
if action ~= nil and action.Item ~= nil then
local okItem, itemName = pcall(function() return tostring(action.Item.__type) .. ":" .. tostring(action.Item.Name) end)
if okItem then
rageDbg.item = itemName
end
end
if target ~= nil then
local ok, name, dist, headGap = pcall(function()
local alive = target.AliveState
-- distance between the target's head hitbox and its own root: ~0 normally, huge while KH's glue has the
-- hitbox parked at its far point (so it shows whether the glue is actually active when shots go out)
local gap = alive.HitboxHead ~= nil and (alive.HitboxHead.Position - alive.RootPart.Position).Magnitude or -1
return target.FighterState.Player.Name, (alive.RootPart.Position - clientCFrame.Position).Magnitude, gap
end)
if ok then
rageDbg.lastName, rageDbg.lastDist, rageDbg.headGap = name, dist, headGap
end
end
-- Hit estimate (cross-check for the game-confirmed count above): a drop of the target's health between two
-- frames is a hit that landed (damage from anyone else would count too, but in a duel that is rare).
if target ~= nil then
local okHp, hp = pcall(function() return target.FighterState.Character.State.Health end)
if okHp and type(hp) == "number" then
local prevHp = rageDbg.hp[target.FighterState]
if prevHp ~= nil and hp < prevHp then
rageDbg.hits += 1
rageDbg.damage += prevHp - hp
end
rageDbg.hp[target.FighterState] = hp
end
end
local now = os.clock()
if now - rageDbg.last >= 5 then
if K.Log and rageDbg.frames > 0 then
local parts = {}
for k, v in rageDbg.why do
parts[#parts + 1] = k .. "=" .. v
end
table.sort(parts)
K.Log("rage", string.format("5s: style=%s item=%s frames=%d no-target=%d target-no-shot=%d [%s] shots=%d | last target %s at %.0f studs, head-to-root gap %.0f | repRoot=%s mode=%s",
tostring(K.RagebotStyle(v115.Data.Ragebot.KnifeMode)), tostring(rageDbg.item), rageDbg.frames, rageDbg.noTarget, rageDbg.noShot,
table.concat(parts, " "), rageDbg.shots, rageDbg.lastName, rageDbg.lastDist, tonumber(rageDbg.headGap) or -1,
tostring(K.RepRootProperty), tostring(v115.Data.Ragebot.Evasion.Mode)))
if rageDbg.shots > 0 or rageDbg.hits > 0 or rageDbg.gameHits > 0 then
-- Read our rep root back: the write goes through sethiddenproperty inside a pcall, so an executor whose
-- sethiddenproperty does nothing for this property would look exactly like success. KH is expected to read
-- back the target's head hitbox, UE's gun path "Terrain", and our own root part means the write had no effect.
local readBack = "n/a"
local getHidden = K.fn("gethiddenproperty")
if getHidden ~= nil and rageDbg.root ~= nil and K.RepRootProperty ~= nil then
local okRead, value = pcall(getHidden, rageDbg.root, K.RepRootProperty)
if okRead then
local okName, name = pcall(function() return typeof(value) == "Instance" and value:GetFullName() or tostring(value) end)
readBack = okName and tostring(name) or tostring(value)
else
readBack = "read failed: " .. tostring(value)
end
end
K.Log("rage", string.format("   hit check: shots=%d game-confirmed hits=%d (total %d, hook %s) | hp-drop estimate: hits=%d damage=%.0f | paced-out=%d | rep root reads back: %s",
rageDbg.shots, rageDbg.gameHits, rageDbg.gameHitsTotal, rageDbg.hookState, rageDbg.hits, rageDbg.damage, K.RagePaced or 0, string.sub(readBack, -90)))
K.RagePaced = 0
end
end
rageDbg.frames, rageDbg.noTarget, rageDbg.noShot, rageDbg.shots = 0, 0, 0, 0
rageDbg.hits, rageDbg.damage, rageDbg.gameHits = 0, 0, 0
table.clear(rageDbg.why)
rageDbg.last = now
end
end

-- Round Start Delay debug log: kiciarebuild/logs/round_delay.log, one line per change of the round status, per
-- arming and per change of the gate, so a round that does not delay can be read back afterwards
local function roundDelayLog(message)
pcall(function()
if appendfile ~= nil then
appendfile("kiciarebuild/logs/round_delay.log", string.format("%s %.1f %s\n", os.date("%H:%M:%S"), os.clock(), message))
end
end)
end

index2.Update = function(arg, arg2)
-- publish the round status (same source as UE's ueRoundActive) for the Careful style's Round Start Delay
do
-- The round status is DuelController.CurrentObject.Data.Status, cycling RoundStarted -> RoundFinished ->
-- RoundStarting (about 5 s of countdown) -> RoundStarted (read in game). The fighters registry's
-- LocalState that was read here before is nil in this game, so the status never came through.
local status
local okStatus = pcall(function()
local duelController = tbl17.ragebotDuelController
if duelController == nil then
duelController = K.Controller("DuelController")
tbl17.ragebotDuelController = duelController
end
local currentDuel = duelController.CurrentObject
local duelData = type(currentDuel) == "table" and currentDuel.Data or nil
status = type(duelData) == "table" and duelData.Status or nil
end)
tbl17.ragebotRoundActive = status == "RoundStarted" and true or nil
local statusText = not okStatus and "error" or (status == nil and "no-duel" or tostring(status))
if tbl17.ragebotLoggedStatus ~= statusText then
roundDelayLog(string.format("status %s -> %s (StartDelay=%s, style=%s, ragebotKeyOn=%s)", tostring(tbl17.ragebotLoggedStatus), statusText, tostring(v115.Data.Ragebot.StartDelay), tostring(v115.Data.Ragebot.KnifeMode), tostring(tbl17.ragebotKeyOn)))
tbl17.ragebotLoggedStatus = statusText
end
end
-- Round Start Delay (Ragebot.StartDelay, every style): arm a random 1-6 s hold the moment the round goes
-- active. This is tracked here because Update runs every frame, which _Plan does not (it is only reached
-- once the round is on), and a switch from "no match / not started" to RoundStarted counts as a new round.
-- Only the very first frame after the script starts never arms it (the script was enabled mid-round).
do
local roundNow = tbl17.ragebotRoundActive
if roundNow == true and tbl17.ragebotRoundWas ~= true and tbl17.ragebotUpdateSeen == true
and v115.Data.Ragebot.StartDelay == true then
local delaySeconds = 1 + math.random() * 5
tbl17.ragebotStartDelayUntil = os.clock() + delaySeconds
roundDelayLog(string.format("ARMED %.2f s", delaySeconds))
end
tbl17.ragebotRoundWas = roundNow
tbl17.ragebotUpdateSeen = true
end
-- Underground on: the ragebot stays off in every style (the underground write owns the server CFrame).
if K.UndergroundActive() then
arg:_Reset()
return
end
-- Careful style is the LY hub's ragebot (module LYC) on its own Heartbeat: KH's planner lets go once and
-- then stays out of it. LY never touches the assembly history flags, so they go back to the off values.
if K.RagebotStyle(v115.Data.Ragebot.KnifeMode) == "Careful" then
if arg._enabled and arg._historyStyle ~= "Careful" then
arg:_ApplyHistoryFlags(true)
end
if not arg._lyCareful then
arg._lyCareful = true
arg:_Reset()
end
-- a failure in the card must never take the ragebot down with it
pcall(carefulTargetHud, arg)
return
end
arg._lyCareful = false
local innerContext = arg._innerContext
if innerContext == nil then
arg:_Reset()
return
end
local fighterState = innerContext.FighterState
if fighterState.EnvironmentId == nil or not arg._enabled then
arg:_Reset()
return
end
if arg._historyStyle ~= K.RagebotStyle(v115.Data.Ragebot.KnifeMode) then
arg:_ApplyHistoryFlags(true)
end
local state = fighterState.Character.State
if not state.Alive then
arg:_Reset()
return
end
-- Round Start Delay, entry timer (what the first FW UE did): the first frame in a match that gets past the
-- "no match / not enabled / dead" resets above arms a random 1-6 s hold of its own, whatever the round
-- status says. The round-started timer in the top of Update still arms again when the round really starts,
-- and the later of the two is kept. _Reset clears the flag, so a new match arms again.
if arg._entryDelayArmed ~= true then
arg._entryDelayArmed = true
if v115.Data.Ragebot.StartDelay == true then
local entrySeconds = 1 + math.random() * 5
local entryUntil = os.clock() + entrySeconds
if entryUntil > (tbl17.ragebotStartDelayUntil or 0) then
tbl17.ragebotStartDelayUntil = entryUntil
end
roundDelayLog(string.format("ENTRY ARMED %.2f s (first frame in a match, status=%s)", entrySeconds, tostring(tbl17.ragebotLoggedStatus)))
end
end
local characterController = innerContext.CharacterController
local clientCFrame = characterController:GetClientCFrame()
-- FW UE style: never attacks. Sits in the void for FW_VOID_SECONDS, then under the InstakillOOB
-- (Translocate, point computed in the Translocate compute) for FW_TRANSLOCATE_SECONDS, then straight
-- back to the void. Both times are fixed (no menu), the same for every enemy: there is no UE / KH
-- detection any more.
local mode = v115.Data.Ragebot.Evasion.Mode
local fwue = K.RagebotStyle(v115.Data.Ragebot.KnifeMode) == "FWUE"
local fwVoid = false
-- set below from the melee scan: an enemy is holding a knife / melee weapon this frame
local fwHasKnife = false
if fwue then
local FW_VOID_SECONDS = 4
local FW_TRANSLOCATE_SECONDS = 0.85
local now3 = os.clock()
local function fwNotify(parts)
pcall(function()
tbl17.aB().get():Notify(parts, { Color = v115.Data.HackerDetector.Color, Lifetime = 4 })
end)
end
-- Knife holders (checked every frame): an enemy knife that is ready can stab the moment he gets to us, and
-- a heavy stab does 150, so while one is ready the void time is extended (at most FW_KNIFE_WAIT_MAX s) until
-- every knife has been used. The window opens only once each knife's swing is over (FW_KNIFE_SWING after the
-- stab) and the heavy cooldown is still running, and it closes early, back to the void, when a cooldown is
-- about to end. Read the way Careful's heavyPhase does it: FighterController fighter.EquippedItem keeps
-- _attack_cooldown (tick() time the cooldown ends) and _last_attack_animation_name up to date for other
-- players; the start of a stab is taken when _attack_cooldown is seen to change.
-- a heavy stab does its damage up to 0.625 s after its packet (measured, kh.lua:30329), so the window stays shut
-- that long after the stab
local FW_KNIFE_SWING = 0.625
local FW_KNIFE_WAIT_MAX = 3
local FW_KNIFE_CLOSE_MARGIN = 0
local FW_KNIFE_MIN_WINDOW = 0
local FW_KNIFE_COOLDOWN_FACTOR = 0.8
-- Weapon check (optional, "FW Weapon Check"): the same idea for every other weapon an enemy holds. With it on, the
-- hide window opens ONLY while it is open: every enemy's held weapon must still have at least FW_TRANSLOCATE_SECONDS
-- of shot / swing cooldown left (fast weapons: a nearly empty magazine instead), and nobody may be reloading. There
-- is no FW_KNIFE_WAIT_MAX cap then: the void goes on until the window opens. Once in the hide, the full
-- FW_TRANSLOCATE_SECONDS are spent, except that an enemy starting to reload sends us back to the void.
-- A slow weapon opens the window only with this much cooldown left: the FW_TRANSLOCATE_SECONDS of the hide.
local FW_GUN_ENTRY_WINDOW = 0.85
-- Weapons with a shot cooldown up to this many seconds are fast: they are judged by their magazine, not their cooldown.
local FW_GUN_FAST_COOLDOWN = 0.3
-- A fast weapon counts as nearly empty at or below this share of its magazine.
local FW_GUN_LOW_AMMO = 0.4
local fwWeaponCheck = v115.Data.Ragebot.FWWeaponCheck == true
local knifeSeen = arg._fwKnifeSeen
if knifeSeen == nil then
knifeSeen = setmetatable({}, { __mode = "k" })
arg._fwKnifeSeen = knifeSeen
end
local hasKnife, knifeCanOpen, knifeRemaining = false, true, math.huge
local gunBlocked, gunRemaining, gunReloading = false, math.huge, false
pcall(function()
local fighterController = K.Controller("FighterController")
local clock = tick()
for enemyPlayer, enemyState in arg._targetSelection._fighters.EnemyByPlayer, nil, nil do
local enemyAlive = enemyState.Character.State
if enemyAlive ~= nil and enemyAlive.Alive then
local fighter = fighterController:GetFighter(enemyPlayer)
local item = fighter ~= nil and fighter.EquippedItem or nil
-- every melee weapon (knife, chainsaw, katana, maul, ...) follows the knife rule below; for a knife the swing
-- must be a heavy attack, for the others any attack counts, and a held chainsaw (_attack_cooldown = infinity) is
-- not in a cooldown at all
if item ~= nil and item.Info ~= nil and item.Info.Class == "Melee" then
hasKnife = true
local info = item.Info
local heavyCooldown = info.HeavyAttackCooldown or info.AttackCooldown
local key, ends = item._last_attack_animation_name, item._attack_cooldown
local isHeavy = item.Name ~= "Knife" or (type(key) == "string" and key:match("^HeavyAttack%d") ~= nil)
if type(heavyCooldown) == "number" and isHeavy and type(ends) == "number" and ends > clock and ends < math.huge then
local seen = knifeSeen[item]
if seen == nil then
seen = { ends = ends, started = ends - heavyCooldown }
knifeSeen[item] = seen
elseif seen.ends ~= ends then
seen.ends, seen.started = ends, clock
end
-- every knife is treated as one that stabs again FW_KNIFE_COOLDOWN_FACTOR of its heavy cooldown after the last
-- stab (1.25 s by default is the base). Using that for all knives only closes the window a little early on the
-- others.
local remaining = seen.started + heavyCooldown * FW_KNIFE_COOLDOWN_FACTOR - clock
if clock - seen.started < FW_KNIFE_SWING or remaining <= FW_KNIFE_MIN_WINDOW then
knifeCanOpen = false
end
knifeRemaining = math.min(knifeRemaining, remaining)
else
knifeCanOpen = false
end
end
if fwWeaponCheck and item ~= nil and not (item.Info ~= nil and (item.Info.Class == "Utility" or item.Info.Class == "Melee")) then
-- utility items (grenades, tripmines, ...) are not checked: their cooldown lives in _use_cooldown; melee weapons
-- follow the knife rule above
local info = item.Info
local shootCd = info ~= nil and info.ShootCooldown or nil
local remaining
local reloadEnds = item._reload_cooldown
if type(reloadEnds) == "number" and reloadEnds > clock then
-- reloading: the window cannot open now, and an open one is closed (see the hide check below)
gunReloading = true
remaining = 0
elseif type(shootCd) == "number" and shootCd <= FW_GUN_FAST_COOLDOWN then
-- Fast weapon (cooldown <= FW_GUN_FAST_COOLDOWN, e.g. Uzi, Assault Rifle, Handgun): its cooldown is over before
-- we could use it, so go by the magazine instead. The window only counts as safe while the magazine is nearly
-- empty (FW_GUN_LOW_AMMO of its size, at least 1 round): it cannot keep shooting for long.
local okAmmo, ammo = pcall(function() return item:Get("Ammo") end)
local maxAmmo = info.MaxAmmo
if okAmmo and type(ammo) == "number" and type(maxAmmo) == "number" and maxAmmo > 0 and ammo <= math.max(1, math.floor(maxAmmo * FW_GUN_LOW_AMMO)) then
remaining = math.huge
else
remaining = 0
end
else
-- Slow weapon (long cooldown): _shoot_cooldown / _attack_cooldown are tick() times the weapon is busy until.
local busyUntil = 0
for _, key in { "_shoot_cooldown", "_attack_cooldown" } do
local value = item[key]
if type(value) == "number" and value > busyUntil then
busyUntil = value
end
end
remaining = busyUntil - clock
end
if remaining < FW_GUN_ENTRY_WINDOW then
gunBlocked = true
end
gunRemaining = math.min(gunRemaining, remaining)
end
end
end
end)
if arg._fwPhase == nil then
arg._fwPhase = "void"
arg._fwVoidStart = now3
arg._fwUntil = now3 + FW_VOID_SECONDS
elseif now3 >= arg._fwUntil then
if arg._fwPhase == "void" then
local knifeWait = hasKnife and not knifeCanOpen
if gunBlocked or (knifeWait and now3 - arg._fwVoidStart < FW_VOID_SECONDS + FW_KNIFE_WAIT_MAX) then
-- an enemy weapon is ready (or mid-swing): stay in the void a little longer. A knife or other melee weapon that
-- cannot open the window is waited for at most FW_KNIFE_WAIT_MAX s, then the window opens anyway; a blocking gun
-- (weapon check on) is waited for until the window opens, however long that takes.
if not arg._fwKnifeWaitNotified then
arg._fwKnifeWaitNotified = true
fwNotify({ { Text = (knifeWait and not gunBlocked) and "Knife ready" or "Weapon ready", Accent = true }, { Text = " - waiting for the cooldown in the void" } })
end
else
arg._fwKnifeWaitNotified = false
arg._fwPhase = "hide"
arg._fwUntil = now3 + FW_TRANSLOCATE_SECONDS
end
else
arg._fwPhase = "void"
arg._fwVoidStart = now3
arg._fwUntil = now3 + FW_VOID_SECONDS
end
elseif arg._fwPhase == "hide" and ((hasKnife and knifeRemaining < FW_KNIFE_CLOSE_MARGIN) or (fwWeaponCheck and gunReloading)) then
-- a knife is about to come off cooldown, or an enemy started reloading: leave
arg._fwPhase = "void"
arg._fwVoidStart = now3
arg._fwUntil = now3 + FW_VOID_SECONDS
end
-- Round Start Delay (the global switch): for a random 1-6 s from the start of the round stay in the void, no
-- window; the delay is the first void stretch, the cycle goes on from there
if v115.Data.Ragebot.StartDelay == true and now3 < (tbl17.ragebotStartDelayUntil or 0) then
arg._fwPhase = "void"
arg._fwVoidStart = now3
arg._fwUntil = tbl17.ragebotStartDelayUntil
end
fwVoid = arg._fwPhase == "void"
fwHasKnife = hasKnife
-- Debug: every health drop in FW UE prints one line to the F9 console ("[FW hit]") with the recent phase
-- changes, what the knife / weapon check saw this frame and each enemy's held weapon (seconds left on its
-- shot / swing / reload cooldown), so a hit can be traced to the phase and weapon that caused it.
if arg._fwPhaseSeen ~= arg._fwPhase then
arg._fwPhaseSeen = arg._fwPhase
local hist = arg._fwHist
if hist == nil then
hist = {}
arg._fwHist = hist
end
table.insert(hist, { phase = arg._fwPhase, at = now3 })
if #hist > 4 then
table.remove(hist, 1)
end
end
local fwHealth = state.Health
local fwLastHealth = arg._fwLastHealth
arg._fwLastHealth = fwHealth
if type(fwHealth) == "number" and type(fwLastHealth) == "number" and fwHealth < fwLastHealth then
pcall(function()
local phases = {}
for _, h in ipairs(arg._fwHist or {}) do
table.insert(phases, string.format("%s %.2fs ago", h.phase, now3 - h.at))
end
local enemies = {}
local fighterController = K.Controller("FighterController")
local clock = tick()
for enemyPlayer, enemyState in arg._targetSelection._fighters.EnemyByPlayer, nil, nil do
local alive = enemyState.Character.State
if alive ~= nil and alive.Alive then
local fighter = fighterController:GetFighter(enemyPlayer)
local item = fighter ~= nil and fighter.EquippedItem or nil
if item ~= nil then
local function left(key)
local value = item[key]
return type(value) == "number" and math.max(value - clock, 0) or 0
end
table.insert(enemies, string.format("%s:%s shoot %.2f attack %.2f reload %.2f", enemyPlayer.Name, tostring(item.Name), left("_shoot_cooldown"), left("_attack_cooldown"), left("_reload_cooldown")))
end
end
end
KQ(string.format("[FW hit] -%.0f hp (%.0f left) | now %s | phases: %s | knife: has=%s canOpen=%s remaining=%.2f | weapon check=%s blocked=%s remaining=%.2f reloading=%s | enemies: %s",
fwLastHealth - fwHealth, fwHealth, tostring(arg._fwPhase), table.concat(phases, ", "), tostring(hasKnife), tostring(knifeCanOpen), knifeRemaining,
tostring(fwWeaponCheck), tostring(gunBlocked), gunRemaining, tostring(gunReloading), table.concat(enemies, " ; ")))
end)
end
mode = "Translocate"
else
arg._fwPhase = nil
end
local v130 = v128.getAction(innerContext)

if fwue or (mode == "Translocate" and not isUE() and not ueS.IsK8x() and arg._reloadGun == nil and (v130 == nil or v130.Type ~= "Reload")) then
arg:_ApplyForcedCrouch(v86[153])
targetHud.Hide()
-- FW UE void phase: UE's void (random direction at 2147483647 studs, kept above the map), the furthest
-- point any style here uses; the immune ring (1.3e8 - 1.07e9) is the fallback. Otherwise Translocate.
-- An enemy holds a knife / melee weapon: never go to the void. A stab comes from behind, so stand with the back
-- flat against a vertical killing OOB wall (outside the map) instead of upright under the slab: nothing can get
-- behind us without standing inside the wall. A fixed facing (away from the wall), no random yaw; only a slide
-- along the wall. This replaces the void phase for as long as a knife is held (also during the Round Start
-- Delay). With no usable wall the old void / hide cycle is kept.
local knifeWall = (fwue and fwHasKnife) and v125.wallStand() or nil
if fwue and ((fwVoid and knifeWall == nil) or not arg._targetSelection:HasTargets()) then
characterController:SetServerCFrame(ueS.Void() or v127.getImmune())
else
local translocateCFrame, jitterRadius = v125.compute(clientCFrame, arg._targetSelection:HasTargets())
if knifeWall ~= nil then
translocateCFrame, jitterRadius = knifeWall, nil
end
if fwue and translocateCFrame ~= nil and jitterRadius ~= nil then
-- FW UE: a new random spot in the safe disc and a new random yaw every frame (upright, so the head hitbox
-- stays 1.75 above the root and the height never changes). A knife backstab crits when the attacker's
-- view matches the victim's facing, which this keeps from lining up.
if jitterRadius > 0 then
-- fast + wide: each frame lands on the far side of the disc from the last one (+-60 deg), at 60-100% of the
-- radius, so the step per frame is close to the whole diameter; the yaw below stays fully random
local jitterAngle = (arg._fwLastAngle or 0) + math.pi + (math.random() * 2 - 1) * (math.pi / 3)
arg._fwLastAngle = jitterAngle
local jitterDistance = jitterRadius * (0.6 + 0.4 * math.random())
translocateCFrame = translocateCFrame + Vector3.new(math.cos(jitterAngle) * jitterDistance, 0, math.sin(jitterAngle) * jitterDistance)
end
translocateCFrame = translocateCFrame * CFrame.Angles(0, math.random() * 6.283185307179586, 0)
end
characterController:SetServerCFrame(translocateCFrame)
end
return
end

local target = arg._targetSelection:GetTarget(state.Health)

if target ~= nil then
arg._lastTargetWorld = target.AliveState.RootPart.Position
else
arg._lastTargetWorld = nil
end

-- Target HUD: a failure in the card must never take the ragebot down with it
pcall(targetHud.Update, target)

local v131 = arg:_Plan(arg2, v130, target, state.RootPart, clientCFrame, mode)
arg:_ApplyPlan(v131, target, innerContext)
local reloadGun = arg._reloadGun

if reloadGun ~= nil and arg._reloadReadyAt == nil and arg._pendingDepletionAmmo == nil and not reloadGun:IsReloading() then
arg._reloadReadyAt = os.clock() + v122.getEstimatedReplicationDelay()
end

arg:_ApplyForcedCrouch(v131.ShouldForceCrouch == true)
local v132 = innerContext.ItemBehaviors:EquippedItemAsGun()
local ammo = v132 ~= nil and v132:GetAmmo() or 0
local shotRequestCount = v132 ~= nil and v132.ShotRequestCount or 0
local weaponAction = v131.WeaponAction
pcall(rageDebug, target, v130, weaponAction ~= nil, clientCFrame, state.RootPart)

if weaponAction ~= nil then
tbl17.ragebotLastFire = os.clock()
weaponAction()

if v132 ~= nil and (v132 ~= nil and v132.ShotRequestCount - shotRequestCount or 0) > 0 and v132:GetExpectedAmmoAfterPendingShots() <= 0 then
if isUE() or ueS.IsK8x() then
-- not "isUE() and x or y": with Never Void on, ueVoidPlan's CFrame is nil and that idiom would fall through
innerContext.CharacterController:SetServerCFrame(ueVoidPlan(arg, v132, state.RootPart).CFrame)
else
innerContext.CharacterController:SetServerCFrame(v127.getImmune())
end
local now2 = os.clock()
arg._reloadGun = v132
arg._reloadReadyAt = now2 + v122.getEstimatedReplicationDelay()
arg._pendingDepletionAmmo = ammo
arg._reloadAcknowledgementDeadline = now2 + v122.getEstimatedRemoteDelay() + v122.getEstimatedReplicationDelay()
end
end
end

-- UE will not act outside a round: 4320 pc81 skips target selection entirely when
-- duel_cache.current.Data.Status ~= 'RoundStarted', and 4312 pc244 voids on the same test.
local function ueRoundActive(arg)
local fighters = arg._fighters
if fighters == nil then
return true
end
local localState = fighters.LocalState
if localState == nil then
return true
end
local ok, status = pcall(localState.GetRoundStatus, localState)
if not ok then
return true
end
return status == "RoundStarted"
end

-- Round Start Delay (Ragebot.StartDelay, all styles): for a random 1-6 s from the start of the round, hide
-- instead of attacking. The time is armed in Update (tbl17.ragebotStartDelayUntil).
local function ragebotStartDelayActive(arg)
local active = v115.Data.Ragebot.StartDelay == true and os.clock() < (tbl17.ragebotStartDelayUntil or 0)
if active ~= tbl17.ragebotGateWas then
tbl17.ragebotGateWas = active
roundDelayLog("_Plan gate active=" .. tostring(active))
end
return active
end
-- Detect Knife (Ragebot.DetectKnife): never stand next to a target whose Knife can stab. The knife is
-- dangerous unless its attack cooldown is running (FighterController fighter.EquippedItem keeps
-- _attack_cooldown = tick() time the cooldown ends, as FW UE reads it) and the swing that started it is over
-- (a stab does its damage up to 0.625 s after its packet, kh.lua:30329). While it is dangerous the plan is the
-- evasion plan, so we are far away and the stab has nobody to hit. KNIFE_WAIT_MAX = how long we wait for the
-- window before attacking anyway (math.huge = never; the round can then stall against a knife that never swings).
local KNIFE_SWING = 0.625
local KNIFE_LEAD = 0.15
local KNIFE_WAIT_MAX = math.huge
local knifeSeen = setmetatable({}, { __mode = "k" })
local knifeWaitSince = nil
local function targetKnifeDangerous(target)
	if v115.Data.Ragebot.DetectKnife == false then
		knifeWaitSince = nil
		return false
	end
	local ok, danger = pcall(function()
		local player = target.FighterState ~= nil and target.FighterState.Player or nil
		if player == nil then
			return false
		end
		local fighter = K.Controller("FighterController"):GetFighter(player)
		local item = fighter ~= nil and fighter.EquippedItem or nil
		if item == nil or item.Name ~= "Knife" then
			return false
		end
		local clock = tick()
		local ends = item._attack_cooldown
		if type(ends) ~= "number" or ends == math.huge or ends <= clock + KNIFE_LEAD then
			return true
		end
		local rec = knifeSeen[item]
		if rec == nil or rec.ends ~= ends then
			rec = { ends = ends, at = clock }
			knifeSeen[item] = rec
		end
		return clock - rec.at < KNIFE_SWING
	end)
	danger = ok and danger == true
	if danger then
		knifeWaitSince = knifeWaitSince or os.clock()
		if os.clock() - knifeWaitSince > KNIFE_WAIT_MAX then
			return false
		end
	else
		knifeWaitSince = nil
	end
	return danger
end

-- k8x: when to hide in the void (straight up) instead of sitting under the target.
local K8X_FAR = 14000000
-- the map's position, taken from its killing OOB parts (tag "OutOfBoundsPart", KillDelay == 0, else any OOB part): the average of their centres. Cached for a second.
local k8xMapCache, k8xMapAt = nil, -math.huge
local function k8xMapPosition()
	local now2 = os.clock()
	if now2 - k8xMapAt < 1 then
		return k8xMapCache
	end
	k8xMapAt = now2
	local ok, pos = pcall(function()
		local sum, n, sumAll, nAll = Vector3.zero, 0, Vector3.zero, 0
		for _, part in CollectionService:GetTagged("OutOfBoundsPart") do
			if part:IsA("BasePart") then
				sumAll += part.Position
				nAll += 1
				if part:GetAttribute("KillDelay") == 0 then
					sum += part.Position
					n += 1
				end
			end
		end
		if n > 0 then
			return sum / n
		end
		if nAll > 0 then
			return sumAll / nAll
		end
		return nil
	end)
	k8xMapCache = ok and pos or nil
	return k8xMapCache
end
-- Status line: "k8x | <what it is doing>". The text only changes at most every 0.6 s (the state flips every
-- frame, which made the line unreadable).
local k8xStatusText, k8xStatusAt = nil, -math.huge
local function k8xSetStatus(action)
	local text = "k8x | " .. action
	local now2 = os.clock()
	if k8xStatusText == nil or (text ~= k8xStatusText and now2 - k8xStatusAt >= 0.6) then
		k8xStatusText = text
		k8xStatusAt = now2
	end
	ueS.SetStatus(k8xStatusText)
end
local function k8xShouldVoid(arg, action, target, ownRoot)
	-- no target
	if target == nil then
		return true, "no target"
	end
	-- reloading / swapping
	if arg._reloadGun ~= nil or (action ~= nil and (action.Type == "Reload" or action.Type == "Swap")) then
		return true, "reload / swap"
	end
	local item = action ~= nil and action.Item or nil
	if item ~= nil and item.__type == "Gun" then
		local okR, reloading = pcall(item.IsReloading, item)
		if okR and reloading then
			return true, "reloading"
		end
		-- out of bullets
		local okA, ammo = pcall(item.GetExpectedAmmoAfterPendingShots, item)
		if okA and type(ammo) == "number" and ammo <= 0 then
