--  Lithium logo: written to disk once per load and turned into an asset id
--  for the menu rail and the watermark.
do
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local map = {}
    for i = 1, 64 do map[alphabet:byte(i)] = i - 1 end
    local function decode(s)
        local out = buffer.create(#s * 3 // 4 + 3)
        local n = 0
        for i = 1, #s, 4 do
            local a, b, c, d = s:byte(i, i + 3)
            local vc, vd = map[c], map[d]
            local v = map[a] * 262144 + map[b] * 4096 + (vc or 0) * 64 + (vd or 0)
            buffer.writeu8(out, n, bit32.rshift(v, 16))
            n += 1
            if vc then buffer.writeu8(out, n, bit32.band(bit32.rshift(v, 8), 255)) n += 1 end
            if vd then buffer.writeu8(out, n, bit32.band(v, 255)) n += 1 end
        end
        return buffer.readstring(out, 0, n)
    end
    local logoData = decode(LITHIUM_LOGO_B64)
    local logoYData = decode(LY_LOGO_Y_B64)
    -- Called at startup and again by every place that shows the logo, so a failed first try is retried on use.
    -- The logo is two images: the base (L, hat, snowflake, dots: fixed colours) and the Y, drawn white so it can be
    -- tinted with the menu's Accent colour (see K.AddLogoY).
    function K.LoadLogo()
    if K.LithiumLogo ~= nil and K.LithiumLogoY ~= nil then return K.LithiumLogo end
    local wrf, gca = K.fn("writefile"), K.fn("getcustomasset") or K.fn("getsynasset")
    if wrf and gca then
        -- The old version rewrote one shared file on every load. With several clients open at once another one can
        -- hold that file, the write fails, and the logo came out blank. Now: keep an intact existing file as it is,
        -- only write when it is missing or the wrong size, and fall back to a per-session file name if writing fails.
        local isf, rdf = K.fn("isfile"), K.fn("readfile")
        local function tryPath(path, data)
            local function intact()
                if not (isf and rdf) then return false end
                local ok, good = pcall(function() return isf(path) and #rdf(path) == #data end)
                return ok and good == true
            end
            if not intact() then
                if not pcall(wrf, path, data) then return nil end
            end
            for attempt = 1, 3 do
                local ok2, id = pcall(gca, path)
                if ok2 and type(id) == "string" and id ~= "" then return id end
                pcall(task.wait, 0.05 * attempt)
            end
            return nil
        end
        if K.LithiumLogo == nil then
            K.LithiumLogo = tryPath("kiciarebuild/ly_logo.png", logoData)
                or tryPath(string.format("kiciarebuild/ly_logo_%d.png", math.random(100000, 999999)), logoData)
        end
        if K.LithiumLogoY == nil then
            K.LithiumLogoY = tryPath("kiciarebuild/ly_logo_y.png", logoYData)
                or tryPath(string.format("kiciarebuild/ly_logo_y_%d.png", math.random(100000, 999999)), logoYData)
        end
    end
    return K.LithiumLogo
    end
    -- Puts the Y layer over a logo ImageLabel. paint(o) is the caller's way of binding the accent colour to o.
    function K.AddLogoY(label, paint)
        if typeof(label) ~= "Instance" then return nil end
        if K.LithiumLogoY == nil then K.LoadLogo() end
        if K.LithiumLogoY == nil then return nil end
        local o = Instance.new("ImageLabel")
        o.Name = "LogoY"
        o.BackgroundTransparency = 1
        o.BorderSizePixel = 0
        o.Size = UDim2.fromScale(1, 1)
        o.Image = K.LithiumLogoY
        o.ImageColor3 = Color3.new(1, 1, 1)
        pcall(function() o.ScaleType = label.ScaleType o.ZIndex = label.ZIndex + 1 end)
        o.Parent = label
        if paint then pcall(paint, o) end
        return o
    end
    K.LoadLogo()
end

K.Mark("ui form")
--==========================================================================
--  UI form: "Classic" (default, the script's own menu) or "Starlight". Chosen at startup from getgenv().LxYUI or
--  the file kiciarebuild/ui_style.txt, switched live from Settings > General > UI Style.
--  (ui_style.txt replaces the old ui_mode.txt, so a Classic choice saved before Starlight became the default is ignored.)
--==========================================================================
do
    -- one file per account (like the rest of its settings, in K.AccountDir), so each account keeps its own menu form
    local MODE_FILE = K.AccountDir .. "/ui_style.txt"
    local function valid(m) return m == "Classic" or m == "Starlight" or m == "Lite" or m == "Setsuna" or m == "Setsuna Drop" or m == "Matcha" or m == "KH V2" end
    function K.UIMode()
        local m = getgenv().LxYUI
        if valid(m) then return m end
        local rdf, isf = K.fn("readfile"), K.fn("isfile")
        if rdf and isf then
            local ok, text = pcall(function() if isf(MODE_FILE) then return rdf(MODE_FILE) end end)
            if ok and type(text) == "string" then
                text = string.gsub(text, "%s+", "")
                if valid(text) then return text end
            end
        end
        return "Classic"
    end
    function K.SetUIMode(m)
        if not valid(m) then return end
        getgenv().LxYUI = m
        local wrf = K.fn("writefile")
        if wrf then pcall(wrf, MODE_FILE, m) end
    end
    function K.SwitchUI(m)
        if not valid(m) then return end
        K.SetUIMode(m)
        K.Log("ui", "switching the menu to " .. m)
        if K.RebuildMenu then task.defer(K.RebuildMenu, m) end
    end
end

K.Mark("starlight backend")
--==========================================================================
--  Starlight UI backend (second form of the menu)
--  The page builders talk to a Menu object (AddTab / Grid / AddSection / AddToggle ...). K.StarUI.Menu implements
--  that same surface on top of the Starlight Interface Suite (Nebula Softworks), so every page builds unchanged
--  and the form is chosen when the menu is built (Settings > General > UI Style).
--  Starlight is downloaded when this form is chosen. If it cannot be loaded or built, the classic menu is built.
--  Notes on what Starlight does not have, and what is done instead:
--    * Starlight elements have no silent set and no hide: programmatic writes are fenced with a time window,
--      and elements are hidden through their Instance.
--    * Dropdown groups (AddGroup with Source/Option) show and hide their members.
--    * Keybinds: the key is picked with Starlight's bind box, the mode with a small dropdown row. The key press
--      itself is handled by the keybind controller of the script, as in the classic menu.
--    * Gradient colours are edited as one colour; the skin changer, viewport, icon strip and gear widgets have
--      no Starlight equivalent (the skin changer page shows a button back to the classic menu).
--==========================================================================
K.LoadAltUI = function() -- Starlight / Lite / Setsuna / Matcha / KH V2 forms: defined when one of them is first chosen
    if K.AltUILoaded then return end
    K.AltUILoaded = true
    local StarUI = {}
    K.StarUI = StarUI

    local lib, libSource, libErr
    local nextId = 0

    local function log(msg)
        if K.Log then pcall(K.Log, "ui", msg) end
    end

    local function uid(prefix)
        nextId = nextId + 1
        return prefix .. nextId
    end

    local function notify(text)
        pcall(function() tbl17.aB().get():Notify(text) end)
    end

    local function clone(t)
        local out = {}
        if type(t) == "table" then
            for k, v in pairs(t) do out[k] = v end
        end
        return out
    end

    local function iconOf(v)
        if v == nil then return "" end
        if type(v) == "number" then return tostring(v) end
        local id = string.match(tostring(v), "(%d+)$")
        return id or ""
    end

    -- names of the form Add / Set / Is / Get / ... are methods; everything else (fields) is looked up as nil
    local FIELD_NAMES = { Label = true, Icon = true, Description = true, Title = true, Keybind = true, Visible = true,
        Dragging = true, Directory = true, Value = true, Text = true, Kind = true }
    local function isMethodName(k)
        return type(k) == "string" and string.match(k, "^%u") ~= nil and not FIELD_NAMES[k]
    end

    local function fireSignal(sig)
        local fs = getgenv().firesignal
        if type(fs) == "function" then
            local ok = pcall(fs, sig)
            if ok then return true end
        end
        local gc = getgenv().getconnections
        if type(gc) == "function" then
            local ok = pcall(function()
                for _, c in ipairs(gc(sig)) do
                    if c.Fire then c:Fire() elseif c.Function then c.Function() end
                end
            end)
            return ok
        end
        return false
    end

    --------------------------------------------------------------------------------------------------- loading
    local SOURCES = {
        "https://raw.nebulasoftworks.xyz/starlight",
        "https://raw.githubusercontent.com/Nebula-Softworks/Starlight-Interface-Suite/master/Source.lua",
    }

    -- Starlight gives every element a tooltip with its own RenderStepped connection and an AbsolutePosition
    -- listener; with ~600 controls that is ~600 callbacks a frame, and dragging or scrolling the window runs every
    -- listener. The patch moves the tooltips onto one shared RenderStepped loop that only runs the hovered ones, and
    -- lets the AbsolutePosition listener return at once when its element is not hovered. If the source changed and a
    -- piece is not found, that piece is left as it was.
    local TIP_STEP = [[
local __LxYTipActive, __LxYTipConn = {}, nil
local function __LxYTipStep(inst, fn)
	inst.MouseEnter:Connect(function()
		__LxYTipActive[fn] = true
		if __LxYTipConn == nil then
			__LxYTipConn = game:GetService("RunService").RenderStepped:Connect(function(dt)
				if next(__LxYTipActive) == nil then __LxYTipConn:Disconnect() __LxYTipConn = nil return end
				for f in pairs(__LxYTipActive) do task.spawn(f, dt) end
			end)
		end
	end)
	inst.MouseLeave:Connect(function() __LxYTipActive[fn] = nil end)
	inst.Destroying:Connect(function() __LxYTipActive[fn] = nil end)
end
-- a RenderStepped callback that only runs while frame is shown (a colour picker's drag loop: its popup)
local function __LxYOpenStep(frame, fn)
	local conn
	local function sync()
		if frame.Visible and conn == nil then
			conn = game:GetService("RunService").RenderStepped:Connect(fn)
		elseif not frame.Visible and conn ~= nil then
			conn:Disconnect()
			conn = nil
		end
	end
	frame:GetPropertyChangedSignal("Visible"):Connect(sync)
	frame.Destroying:Connect(function() if conn ~= nil then conn:Disconnect() conn = nil end end)
	sync()
end
]]
    -- Starlight's Hide / Unhide fade every descendant of what they are given (a GUID attribute and two or three tweens
    -- each). For the main window (its minimize button, the mobile button, the menu key) that was thousands of
    -- instances, and fading it left pages built during a fade see-through, so the window is shown and hidden at once,
    -- with no animation. Dialogs and notifications keep Starlight's own fade. Starlight also sets Minimized when a
    -- notification fades out, which the menu would read as the window closing, so after those Minimized is put back
    -- to what the window shows. Starlight.__LxYSetWindowShown(show) is what the menu key calls.
    local FAST_HIDE = [[
local __LxYSlowHide, __LxYSlowUnhide
local function __LxYIsWindow(i) return i.Name == "MainWindow" or (i.Name == "Drag" and i.Parent == Starlight.Instance) end
local function Hide(Interface, ...)
	if __LxYIsWindow(Interface) then
		Interface.Visible = false
		Starlight.Minimized = true
		return
	end
	__LxYSlowHide(Interface, ...)
	pcall(function() Starlight.Minimized = not Starlight.Instance.MainWindow.Visible end)
end
local function Unhide(Interface, ...)
	if __LxYIsWindow(Interface) then
		Interface.Visible = true
		Starlight.Minimized = false
		return
	end
	__LxYSlowUnhide(Interface, ...)
	pcall(function() Starlight.Minimized = not Starlight.Instance.MainWindow.Visible end)
end
Starlight.__LxYSetWindowShown = function(show)
	local ui = Starlight.Instance
	local drag = ui:FindFirstChild("Drag")
	if show then
		Unhide(ui.MainWindow)
		if drag ~= nil then Unhide(drag) end
	else
		Hide(ui.MainWindow)
		if drag ~= nil then Hide(drag) end
	end
end
]]

    -- most controls have no tooltip text, yet Starlight builds a tooltip frame, label, stroke, three theme bindings and
    -- three listeners for each. An empty tooltip is a stand-in that builds the real one only if text is set later
    -- (Starlight only ever writes and reads .Text on it).
    local LAZY_TIP = [[
local __LxYAddToolTipReal
local function AddToolTip(InfoStr, HoverInstance)
	if InfoStr ~= nil and InfoStr ~= "" then return __LxYAddToolTipReal(InfoStr, HoverInstance) end
	local real
	return setmetatable({}, {
		__index = function(_, k)
			if real ~= nil then return real[k] end
			if k == "Text" then return "" end
			return nil
		end,
		__newindex = function(_, k, v)
			if real ~= nil then real[k] = v return end
			if k == "Text" and v ~= nil and v ~= "" then real = __LxYAddToolTipReal(v, HoverInstance) end
		end,
	})
end
]]

    -- each patch is applied only when its anchor is found in the downloaded source; pieces that depend on each other
    -- are one patch (all or nothing)
    local PATCHES = {
        { "instant window hide", {
            { "\nlocal function Hide%(Interface,", function() return "\n" .. FAST_HIDE .. "__LxYSlowHide = function(Interface," end },
            { "\nlocal function Unhide%(Interface%)", "\n__LxYSlowUnhide = function(Interface)" },
        } },
        { "lazy tooltips + shared tooltip loop", {
            { "\nlocal function AddToolTip%(", function() return "\n" .. TIP_STEP .. LAZY_TIP .. "__LxYAddToolTipReal = function(" end },
            { "RunService%.RenderStepped:Connect%(function%(dt%)(%s*)if not IsHovering then", "__LxYTipStep(HoverInstance, function(dt)%1if not IsHovering then" },
        } },
        { "tooltip position listener", {
            { "(HoverInstance:GetPropertyChangedSignal%(\"AbsolutePosition\"%):Connect%(function%(%))", "%1 if not IsHovering then return end " },
        } },
        -- the interface model and the acrylic module come from the loaders above (downloaded / compiled once)
        { "cached interface model", {
            { "game:GetObjects%(\"rbxassetid://\" %.%. modelId%)%[1%]", "getgenv().__LxYStarlightUI(modelId, false)" },
            -- the second fetch is Starlight's retry when the build tag differs: that one downloads again
            { "game:GetObjects%(\"rbxassetid://\" %.%. modelId%)%[1%]", "getgenv().__LxYStarlightUI(modelId, true)" },
        } },
        -- the embedded acrylic module (no Maui getfenv / setfenv, no glass), and no acrylic glass in Starlight itself
        { "embedded acrylic module", {
            { "loadstring%(game:HttpGet%(\"https://raw%.\" %.%. website %.%. \"/AcrylicModule%.luau\"%)%)%(%)", "getgenv().__LxYAcrylic()" },
        } },
        -- every theme binding ran in its own new thread (thousands while the menu is built); the body never yields
        { "theme bindings in place", {
            { "pcall%(task%.spawn, function%(%)", "pcall(function()" },
        } },
        -- a dropdown's popup closed itself (two tweens) and moved itself on every AbsolutePosition change of its row,
        -- open or not: scrolling or dragging the window started hundreds of tweens a frame. Only an open popup follows
        -- now; opening one places it anyway.
        { "dropdown popups", {
            { "NestedElement%.Instances%[1%]:GetPropertyChangedSignal%(\"AbsolutePosition\"%):Connect%(close%)(%s*)NestedElement%.Instances%[1%]:GetPropertyChangedSignal%(\"AbsolutePosition\"%):Connect%(updPos%)",
                "NestedElement.Instances[1]:GetPropertyChangedSignal(\"AbsolutePosition\"):Connect(function() if NestedElement.Instances[2].Visible then close() updPos() end end)" },
        } },
        -- every colour picker (47 of them) had a RenderStepped of its own, called every frame to check whether one of
        -- its sliders is being dragged; a drag only happens while its popup is open, so the loop is connected only then
        { "colour picker drag loops", {
            { "RunService%.RenderStepped:Connect%(function%(%)(%s*)if mainDragging then", ";(__LxYOpenStep or function(_, fn) return RunService.RenderStepped:Connect(fn) end)(NestedElement.Instances[2], function()%1if mainDragging then" },
        } },
        -- the colour picker's close() places the popup first (opening relies on that) and then tweens it shut; an
        -- already closed picker stops after placing it
        { "colour picker popups", {
            { "\n(%s*)NestedElement%.Instances%[2%]%.Container%.Visible = false", "\n%1if not NestedElement.Instances[2].Visible then return end\n%1NestedElement.Instances[2].Container.Visible = false" },
        } },
    }

    local function patchSource(src)
        local report = {}
        for _, patch in ipairs(PATCHES) do
            local out, ok = src, true
            for _, step in ipairs(patch[2]) do
                local n
                out, n = string.gsub(out, step[1], step[2], 1)
                if n ~= 1 then ok = false break end
            end
            if ok then src = out end
            report[#report + 1] = patch[1] .. (ok and " on" or " OFF")
        end
        log("Starlight patches: " .. table.concat(report, ", "))
        return src
    end

    -- A Starlight build used to download and compile the library and its acrylic module and download its interface
    -- model every time (switching Classic -> Starlight froze the game while it ran). The library and the acrylic
    -- module are now embedded at the top of the script (K.StarlightFactory, K.StarlightAcrylic), so a build only runs
    -- them (each run gets the fresh state Starlight needs after Destroy). The interface model is an asset (Instances,
    -- not code): it is downloaded once and kept unparented as a template that every build clones.
    local uiTemplate
    function K.StarlightUI(modelId, fresh)
        if fresh or uiTemplate == nil then
            local t0 = os.clock()
            uiTemplate = game:GetObjects("rbxassetid://" .. modelId)[1]
            log(string.format("Starlight interface model downloaded in %.2f s", os.clock() - t0))
        end
        local ok, copy = pcall(function() return uiTemplate:Clone() end)
        if ok and copy ~= nil then return copy end
        return game:GetObjects("rbxassetid://" .. modelId)[1]
    end
    -- the downloaded fallback copy (SOURCES) is pointed at the same loaders by its patches
    getgenv().__LxYStarlightUI = K.StarlightUI
    getgenv().__LxYAcrylic = function() return K.StarlightAcrylic() end
    K.onUnload(function()
        pcall(function() getgenv().__LxYStarlightUI = nil end)
        pcall(function() getgenv().__LxYAcrylic = nil end)
        if uiTemplate ~= nil then pcall(function() uiTemplate:Destroy() end) end
    end)

    local libFn
    local function run(fn)
        local t0 = os.clock()
        local lb = fn()
        log(string.format("Starlight started in %.2f s", os.clock() - t0))
        return lb
    end

    -- Starlight cannot build a second window after Starlight:Destroy(), so every build runs a fresh copy of the source
    function StarUI.Load(fresh)
        if lib ~= nil and not fresh then return lib end
        lib = nil
        -- the embedded copy first: nothing to download or compile
        do
            local ok, res = pcall(run, K.StarlightFactory)
            if ok and type(res) == "table" and type(res.CreateWindow) == "function" then
                lib = res
                return lib
            end
            libErr = tostring(res)
            log("embedded Starlight failed to start, trying a download: " .. libErr)
        end
        if libFn ~= nil then
            local ok, res = pcall(run, libFn)
            if ok and type(res) == "table" and type(res.CreateWindow) == "function" then
                lib = res
                return lib
            end
            libErr = tostring(res)
            log("Starlight (cached source) failed to start: " .. libErr)
        end
        for _, url in ipairs(SOURCES) do
            local ok, res = pcall(function()
                local src = patchSource(game:HttpGet(url))
                local t0 = os.clock()
                local fn, err = loadstring(src)
                if not fn then error(err, 0) end
                log(string.format("Starlight compiled in %.2f s", os.clock() - t0))
                local lb = run(fn)
                libSource = src
                libFn = fn
                return lb
            end)
            if ok and type(res) == "table" and type(res.CreateWindow) == "function" then
                lib = res
                return lib
            end
            libErr = tostring(res)
            log("Starlight failed to load from " .. url .. ": " .. libErr)
        end
        return nil, libErr
    end

    --------------------------------------------------------------------------------------------------- stub
    -- anything the Starlight form does not implement: every member exists and does nothing
    local Stub = {}
    Stub.__index = function(self, key)
        if key == "Value" or key == "Options" then return nil end
        return function() return self end
    end
    Stub.__call = function(self) return self end
    local stub = setmetatable({}, Stub)
    StarUI.Stub = stub

    --------------------------------------------------------------------------------------------------- controls
    -- building a few hundred Starlight elements in one go freezes the game for seconds; a build yields a frame
    -- whenever it has used its slice (only where the caller can yield)
    local FRAME_BUDGET = 1 / 120
    local sliceStart = os.clock()
    local function yieldIfBusy()
        if os.clock() - sliceStart < FRAME_BUDGET then return end
        if coroutine.isyieldable() then task.wait() end
        sliceStart = os.clock()
    end

    -- Built the way the classic menu builds (its pages realize when first opened): a control is a plain object from
    -- the start (the page code holds it, the settings store is bound to it, Set keeps its Value), but its Starlight
    -- element is made only when the page is first opened, from the control's state at that moment. Until then Set
    -- only stores the value and SetVisible only records whether it is shown.
    local Control = {}
    Control.__index = Control

    local function newControl(sec, kind, class)
        local self = setmetatable({}, class or Control)
        self.Kind = kind
        self._sec = sec
        self._menu = sec._menu
        self._realized = false
        self._vis = true
        self._gv = {}
        self._followers = {}
        self._supUntil = 0
        -- Changed: the value changed by the user or by code that is not a refresh; ValueChanged: every change,
        -- including the silent ones that mirror the settings store (what a group follows)
        self.Changed = Signal.new()
        self.ValueChanged = Signal.new()
        self.Row = self
        local list = sec._menu._controls
        list[#list + 1] = self
        return self
    end

    function Control:OnChanged(fn)
        if fn ~= nil then return self.Changed:Connect(fn) end
    end

    function Control:Connect(sig, fn)
        local c = sig:Connect(fn)
        self._conns = self._conns or {}
        self._conns[#self._conns + 1] = c
        return c
    end

    function Control:_suppressed()
        return os.clock() < self._supUntil
    end

    function Control:_suppress(seconds)
        self._supUntil = os.clock() + (seconds or 0.3)
    end

    -- a silent write that arrives while the user is changing the control is the settings store echoing the menu's own
    -- write (debounced for sliders); pushing it back into Starlight would drag the knob or the text backwards
    function Control:_echo(silent)
        return silent and self._userAt ~= nil and os.clock() - self._userAt < 0.3
    end

    function Control:_emit(v)
        self._userAt = os.clock()
        self.Value = v
        self.ValueChanged:Fire(v)
        self.Changed:Fire(v)
    end

    function Control:_isReady()
        return true
    end

    -- the element is made by build(): now when the section is already on screen, otherwise when its page first opens
    function Control:_defer(build)
        self._build = build
        local sec = self._sec
        if sec._realized then
            self:_realizeNow()
        else
            sec._pending[#sec._pending + 1] = self
        end
    end

    function Control:_realizeNow()
        if self._realized or self._dead then return end
        self._realized = true
        local build = self._build
        self._build = nil
        if build ~= nil then
            yieldIfBusy()
            -- Starlight may call the callback while it makes the element: that is not the user
            self:_suppress()
            local ok, err = pcall(build)
            if not ok then log(tostring(self.Kind) .. " '" .. tostring(self._label) .. "' failed to build: " .. tostring(err)) end
        end
        if self._shown ~= nil then self:_applyVis() end
    end

    function Control:_whenReady(fn)
        -- not built yet: the build reads the current state, nothing to push
        if not self._realized then return end
        local function ready()
            local ok, r = pcall(self._isReady, self)
            return ok and r
        end
        if ready() then
            fn()
            return
        end
        task.spawn(function()
            for _ = 1, 120 do
                task.wait(0.05)
                if self._dead then return end
                if ready() then
                    fn()
                    return
                end
            end
        end)
    end

    function Control:_instance()
        return nil
    end

    function Control:_applyVis()
        local vis = self._vis
        for _, g in pairs(self._gv) do
            if not g then vis = false end
        end
        self._shown = vis
        -- not built yet: _realizeNow applies it; composites (range slider, ordered list) have no element of their own
        if self._realized and not self._noElement then
            self._visToken = (self._visToken or 0) + 1
            local token = self._visToken
            local function try()
                if self._visToken ~= token or self._dead then return true end
                local ok, inst = pcall(self._instance, self)
                if ok and typeof(inst) == "Instance" then
                    inst.Visible = vis
                    return true
                end
                return false
            end
            if not try() then
                task.spawn(function()
                    for _ = 1, 120 do
                        task.wait(0.05)
                        if try() then return end
                    end
                end)
            end
        end
        for _, f in ipairs(self._followers) do
            f._vis = vis
            f:_applyVis()
        end
    end

    function Control:SetVisible(v)
        self._vis = v ~= false
        self:_applyVis()
    end

    function Control:SetLabel() return self end
    function Control:SetTooltip() return self end
    function Control:SetEnabled() end
    function Control:SetFeatureEnabled() end

    function Control:Destroy()
        self._dead = true
        pcall(function()
            for _, c in ipairs(self._conns or {}) do c:Disconnect() end
        end)
        pcall(function() self._el:Destroy() end)
    end

    local function subclass()
        local c = setmetatable({}, { __index = Control })
        c.__index = c
        return c
    end

    -- a host is an element that can carry a colour picker or a keybind next to its label (Starlight: toggle or label)
    local LabelC = subclass()
    local ToggleC = subclass()
    local SliderC = subclass()
    local RangeC = subclass()
    local ButtonC = subclass()
    local DividerC = subclass()
    local TextBoxC = subclass()
    local DropdownC = subclass()
    local ColorC = subclass()
    local KeybindC = subclass()
    local OrderedC = subclass()

    local function elInstance(self)
        return self._el and self._el.Instance
    end

    local function elReady(self)
        return self._el ~= nil and self._el.Instance ~= nil
    end

    ----------------------------------------------------------------------------------------------- label
    function LabelC.new(sec, o)
        local self = newControl(sec, "Label", LabelC)
        self.Text = tostring(o.Label or o.Text or "")
        self._label = self.Text
        self._canNest = true
        local tooltip = o.Tooltip or ""
        self:_defer(function()
            self._el = sec._gb:CreateLabel({ Name = self.Text, Tooltip = tooltip }, uid("lbl"))
        end)
        return self
    end
    LabelC._instance = elInstance
    LabelC._isReady = elReady

    function LabelC:Set(text)
        self.Text = tostring(text or "")
        self:_whenReady(function() self._el:Set({ Name = self.Text }) end)
    end
    LabelC.SetLabel = function(self, text) self:Set(text) return self end
    LabelC.SetText = LabelC.SetLabel

    ----------------------------------------------------------------------------------------------- toggle
    function ToggleC.new(sec, o)
        local self = newControl(sec, "Toggle", ToggleC)
        self.Value = o.Default == true
        self._label = tostring(o.Label or "")
        self._canNest = true
        local style = o.Style
        self:_defer(function()
            self._el = sec._gb:CreateToggle({
                Name = tostring(o.Label or ""),
                CurrentValue = self.Value,
                Tooltip = o.Tooltip or "",
                IgnoreConfig = true,
                Style = style,
                Callback = function(v)
                    if self:_suppressed() then return end
                    self:_emit(v and true or false)
                end,
            }, uid("tg"))
        end)
        if o.OnChanged ~= nil then self:OnChanged(o.OnChanged) end
        return self
    end
    ToggleC._instance = elInstance
    ToggleC._isReady = elReady

    function ToggleC:Set(v, silent)
        v = v and true or false
        if silent and v == self.Value then return end
        self.Value = v
        self:_suppress()
        self:_whenReady(function()
            self:_suppress()
            pcall(self._el.Set, self._el, { CurrentValue = v })
        end)
        self.ValueChanged:Fire(v)
        if not silent then self.Changed:Fire(v) end
    end

    ----------------------------------------------------------------------------------------------- slider
    local function stepFor(o)
        if o.Step ~= nil and o.Step > 0 then return o.Step end
        return 1
    end

    function SliderC.new(sec, o)
        local self = newControl(sec, "Slider", SliderC)
        local min, max = o.Min or 0, o.Max or 100
        if max <= min then max = min + 1 end
        self._min, self._max = min, max
        local default = o.Default
        if type(default) ~= "number" then default = min end
        self.Value = default
        self:_defer(function()
            self._el = sec._gb:CreateSlider({
                Name = tostring(o.Label or ""),
                Range = { min, max },
                Increment = stepFor(o),
                CurrentValue = self.Value,
                Suffix = o.Suffix,
                Tooltip = o.Tooltip or "",
                IgnoreConfig = true,
                Callback = function(v)
                    if self:_suppressed() then return end
                    if type(v) == "number" then self:_emit(v) end
                end,
            }, uid("sl"))
        end)
        if o.OnChanged ~= nil then self:OnChanged(o.OnChanged) end
        return self
    end
    SliderC._instance = elInstance
    SliderC._isReady = elReady

    function SliderC:Set(v, silent)
        if type(v) ~= "number" then return end
        if v < self._min then v = self._min elseif v > self._max then v = self._max end
        if silent and (v == self.Value or self:_echo(silent)) then return end
        self.Value = v
        self:_suppress()
        self:_whenReady(function()
            self:_suppress()
            pcall(self._el.Set, self._el, { CurrentValue = v })
        end)
        self.ValueChanged:Fire(v)
        if not silent then self.Changed:Fire(v) end
    end

    ----------------------------------------------------------------------------------------------- range slider
    -- two sliders (lower and upper bound); Value = { Min = , Max = }
    function RangeC.new(sec, o)
        local self = newControl(sec, "RangeSlider", RangeC)
        -- no element of its own: its two sliders are built on their own
        self._realized, self._noElement = true, true
        local min, max = o.Min or 0, o.Max or 100
        local d = type(o.Default) == "table" and o.Default or {}
        self.Value = { Min = d.Min or min, Max = d.Max or max }
        local label = tostring(o.Label or "")
        local function make(which, text, init)
            return sec:_make("Slider", { Label = text, Min = min, Max = max, Step = o.Step, Default = init, Suffix = o.Suffix,
                OnChanged = function(v)
                    if self:_suppressed() then return end
                    local nv = { Min = self.Value.Min, Max = self.Value.Max }
                    nv[which] = v
                    if nv.Min > nv.Max then
                        if which == "Min" then nv.Max = nv.Min else nv.Min = nv.Max end
                    end
                    self:_emit(nv)
                end })
        end
        self._lo = make("Min", label .. " (min)", self.Value.Min)
        self._hi = make("Max", label .. " (max)", self.Value.Max)
        self._followers = { self._lo, self._hi }
        return self
    end

    function RangeC:Set(v, silent)
        if type(v) ~= "table" then return end
        local lo = v.Min or v[1] or self.Value.Min
        local hi = v.Max or v[2] or self.Value.Max
        if silent and ((lo == self.Value.Min and hi == self.Value.Max) or self:_echo(silent)) then return end
        self.Value = { Min = lo, Max = hi }
        self:_suppress()
        self._lo:Set(lo, true)
        self._hi:Set(hi, true)
        self.ValueChanged:Fire(self.Value)
        if not silent then self.Changed:Fire(self.Value) end
    end

    ----------------------------------------------------------------------------------------------- button
    function ButtonC.new(sec, o)
        local self = newControl(sec, "Button", ButtonC)
        self._label = tostring(o.Label or "")
        self._onClick = o.OnClick
        self._confirm = o.Confirm == true
        self._confirming = false
        self.Clicked = Signal.new()
        self:_defer(function()
            self._el = sec._gb:CreateButton({
                Name = self._confirming and K.T("Click again to confirm") or self._label,
                Tooltip = o.Tooltip or "",
                Callback = function() self:_click() end,
            }, uid("bt"))
            if self._disabled then pcall(self._el.Lock, self._el, "") end
        end)
        return self
    end
    ButtonC._instance = elInstance
    ButtonC._isReady = elReady

    function ButtonC:_click()
        if self._disabled then return end
        if self._confirm and not self._confirming then
            self._confirming = true
            self:_rename(K.T("Click again to confirm"))
            task.delay(3, function()
                if self._confirming then
                    self._confirming = false
                    self:_rename(self._label)
                end
            end)
            return
        end
        if self._confirming then
            self._confirming = false
            self:_rename(self._label)
        end
        if self._onClick ~= nil then
            local ok, err = pcall(self._onClick)
            if not ok then log("button '" .. self._label .. "' failed: " .. tostring(err)) end
        end
        self.Clicked:Fire()
    end

    function ButtonC:_rename(text)
        self:_whenReady(function() pcall(self._el.Set, self._el, { Name = text }) end)
    end

    function ButtonC:OnClick(fn)
        self._onClick = fn
        return self
    end

    function ButtonC:SetLabel(text)
        self._label = tostring(text or "")
        self:_rename(self._label)
        return self
    end

    function ButtonC:SetEnabled(enabled)
        self._disabled = enabled == false
        self:_whenReady(function()
            if self._disabled then
                pcall(self._el.Lock, self._el, "")
            else
                pcall(self._el.Unlock, self._el)
            end
        end)
    end
    ButtonC.SetActionEnabled = ButtonC.SetEnabled

    ----------------------------------------------------------------------------------------------- divider
    function DividerC.new(sec, o)
        local self = newControl(sec, "Divider", DividerC)
        local text = o and (o.Label or o.Title)
        if text ~= nil and tostring(text) ~= "" then
            self._labelCtl = LabelC.new(sec, { Label = tostring(text) })
            self._followers = { self._labelCtl }
        end
        self:_defer(function()
            self._el = sec._gb:CreateDivider()
        end)
        return self
    end
    DividerC._instance = elInstance
    DividerC._isReady = elReady

    ----------------------------------------------------------------------------------------------- text box
    function TextBoxC.new(sec, o)
        local self = newControl(sec, "TextBox", TextBoxC)
        self.Value = tostring(o.Default or "")
        self:_defer(function()
            self._el = sec._gb:CreateInput({
                Name = tostring(o.Label or ""),
                CurrentValue = self.Value,
                PlaceholderText = tostring(o.Placeholder or ""),
                RemoveTextAfterFocusLost = false,
                RemoveTextOnFocus = false,
                Tooltip = o.Tooltip or "",
                IgnoreConfig = true,
                Callback = function(text)
                    if self:_suppressed() then return end
                    self:_emit(tostring(text or ""))
                end,
            }, uid("in"))
        end)
        if o.OnChanged ~= nil then self:OnChanged(o.OnChanged) end
        return self
    end
    TextBoxC._instance = elInstance
    TextBoxC._isReady = elReady

    function TextBoxC:Set(v, silent)
        v = tostring(v or "")
        if silent and (v == self.Value or self:_echo(silent)) then return end
        self.Value = v
        self:_suppress()
        self:_whenReady(function()
            self:_suppress()
            pcall(self._el.Set, self._el, { CurrentValue = v })
        end)
        self.ValueChanged:Fire(v)
        if not silent then self.Changed:Fire(v) end
    end

    ----------------------------------------------------------------------------------------------- dropdown
    -- Value: single = option name or nil, multi = set { [option] = true }
    local function toSet(v, options)
        local set = {}
        if type(v) == "table" then
            for k, x in pairs(v) do
                if type(k) == "number" then
                    if table.find(options, x) then set[x] = true end
                elseif x == true and table.find(options, k) then
                    set[k] = true
                end
            end
        elseif type(v) == "string" and table.find(options, v) then
            set[v] = true
        end
        return set
    end

    local function sameSet(a, b)
        for k in pairs(a) do if not b[k] then return false end end
        for k in pairs(b) do if not a[k] then return false end end
        return true
    end

    function DropdownC:_display(value)
        return (self._labels and self._labels[value]) or tostring(value)
    end

    function DropdownC:_displayList()
        local out = {}
        for i, opt in ipairs(self.Options) do out[i] = self:_display(opt) end
        return out
    end

    function DropdownC:_current()
        if self.Multi then
            local out = {}
            for _, opt in ipairs(self.Options) do
                if self.Value[opt] then out[#out + 1] = self:_display(opt) end
            end
            return out
        end
        if self.Value ~= nil then return { self:_display(self.Value) } end
        return {}
    end

    function DropdownC:_fromDisplay(text)
        for _, opt in ipairs(self.Options) do
            if self:_display(opt) == text then return opt end
        end
        return nil
    end

    function DropdownC.new(sec, o, multi)
        local self = newControl(sec, multi and "MultiDropdown" or "Dropdown", DropdownC)
        self.Multi = multi == true
        self._labels = o.Labels
        local options = {}
        for i, opt in ipairs(o.Options or {}) do options[i] = tostring(opt) end
        self.Options = options
        if self.Multi then
            self.Value = toSet(o.Default, options)
        else
            local d = o.Default
            if not (type(d) == "string" and table.find(options, d)) then
                d = nil
                if o.SelectFirst ~= false then d = options[1] end
            end
            self.Value = d
        end
        -- a label row carries the dropdown (Starlight's own Dropdown element has no Set)
        self._label = tostring(o.Label or "")
        self._host = LabelC.new(sec, { Label = o.Label, Tooltip = o.Tooltip })
        self._followers = { self._host }
        -- the host row was queued first, so it is built before this
        self:_defer(function()
            self._nested = self._host._el:AddDropdown({
                Options = self:_displayList(),
                CurrentOption = self:_current(),
                MultipleOptions = self.Multi,
                IgnoreConfig = true,
                Callback = function(sel)
                    if self:_suppressed() then return end
                    self:_fromSelection(sel)
                end,
            }, uid("dd"))
        end)
        if o.OnChanged ~= nil then self:OnChanged(o.OnChanged) end
        return self
    end

    function DropdownC:_isReady()
        local n = self._nested
        return n ~= nil and n.Instances ~= nil and n.Instances[1] ~= nil
    end

    function DropdownC:_instance()
        return self._host and self._host._el and self._host._el.Instance
    end

    function DropdownC:_fromSelection(sel)
        sel = type(sel) == "table" and sel or { sel }
        if self.Multi then
            local set = {}
            for _, text in ipairs(sel) do
                local opt = self:_fromDisplay(text)
                if opt then set[opt] = true end
            end
            if sameSet(set, self.Value) then return end
            self:_emit(set)
        else
            local opt = self:_fromDisplay(sel[1])
            if opt == self.Value then return end
            self:_emit(opt)
        end
    end

    function DropdownC:_push()
        self:_suppress(0.5)
        self:_whenReady(function()
            self:_suppress(0.5)
            pcall(self._nested.Set, self._nested, { Options = self:_displayList(), CurrentOption = self:_current() })
        end)
    end

    function DropdownC:Set(v, silent)
        local nv
        if self.Multi then
            nv = toSet(v, self.Options)
            if silent and sameSet(nv, self.Value) then return end
        else
            if type(v) == "string" and table.find(self.Options, v) then nv = v end
            if silent and nv == self.Value then return end
        end
        self.Value = nv
        self:_push()
        self.ValueChanged:Fire(self.Value)
        if not silent then self.Changed:Fire(self.Value) end
    end

    function DropdownC:SetOptions(list)
        local options = {}
        for i, opt in ipairs(list or {}) do options[i] = tostring(opt) end
        local before = self.Value
        local sameOptions = #options == #self.Options
        if sameOptions then
            for i, opt in ipairs(options) do
                if self.Options[i] ~= opt then sameOptions = false break end
            end
        end
        -- rebuilding Starlight's option rows is the expensive part; an unchanged list is left alone
        if sameOptions then return end
        self.Options = options
        if self.Multi then
            self.Value = toSet(self.Value, options)
        elseif not (type(self.Value) == "string" and table.find(options, self.Value)) then
            self.Value = nil
        end
        self:_push()
        local changed
        if self.Multi then changed = not sameSet(before, self.Value) else changed = before ~= self.Value end
        self.ValueChanged:Fire(self.Value)
        if changed then self.Changed:Fire(self.Value) end
    end

    function DropdownC:Add(opt)
        if type(opt) ~= "string" or table.find(self.Options, opt) then return end
        local l = clone(self.Options)
        l[#l + 1] = opt
        self:SetOptions(l)
    end

    function DropdownC:Remove(opt)
        local i = table.find(self.Options, opt)
        if not i then return end
        local l = clone(self.Options)
        table.remove(l, i)
        self:SetOptions(l)
    end

    function DropdownC:SetLabel(text)
        self._host:Set(text)
        return self
    end

    function DropdownC:GetNames()
        return self.Options
    end

    ----------------------------------------------------------------------------------------------- color
    local function colorValue(v)
        if typeof(v) == "Color3" then return { Rgb = v, Alpha = 1, Stops = {} } end
        if type(v) == "table" then
            local rgb = v.Rgb
            if typeof(rgb) ~= "Color3" and type(v.Stops) == "table" and v.Stops[1] ~= nil then rgb = v.Stops[1].Value end
            if typeof(rgb) ~= "Color3" then rgb = Color3.new(1, 1, 1) end
            return { Rgb = rgb, Alpha = type(v.Alpha) == "number" and v.Alpha or 1, Stops = v.Stops or {} }
        end
        return { Rgb = Color3.new(1, 1, 1), Alpha = 1, Stops = {} }
    end

    local function hostFor(sec, o)
        local row = o.Row
        if row ~= nil and rawget(row, "_canNest") then return row, false end
        return LabelC.new(sec, { Label = o.Label }), true
    end

    function ColorC.new(sec, o)
        local self = newControl(sec, "Color", ColorC)
        local host, own = hostFor(sec, o)
        self._host = host
        if own then self._followers = { host } end
        self.Value = colorValue(o.Default)
        self:_defer(function()
            -- a row passed in as Row was made before this control, so it is queued (or built) ahead of it
            if not host._realized then host:_realizeNow() end
            self._nested = host._el:AddColorPicker({
                CurrentValue = self.Value.Rgb,
                Transparency = 1 - self.Value.Alpha,
                IgnoreConfig = true,
                Callback = function(color, transparency)
                    if self:_suppressed() then return end
                    if typeof(color) ~= "Color3" then return end
                    self:_emit({ Rgb = color, Alpha = 1 - (tonumber(transparency) or 0), Stops = {} })
                end,
            }, uid("cp"))
        end)
        if o.OnChanged ~= nil then self:OnChanged(o.OnChanged) end
        return self
    end

    function ColorC:_isReady()
        local n = self._nested
        return n ~= nil and n.Instances ~= nil and n.Instances[2] ~= nil
    end

    function ColorC:_instance()
        local n = self._nested
        if n ~= nil and n.LYRow ~= nil then return n.LYRow end
        return self._host and self._host._el and self._host._el.Instance
    end

    function ColorC:Set(v, silent)
        local nv = colorValue(v)
        if silent and ((nv.Rgb == self.Value.Rgb and nv.Alpha == self.Value.Alpha) or self:_echo(silent)) then return end
        self.Value = nv
        self:_suppress(0.4)
        self:_whenReady(function()
            self:_suppress(0.4)
            pcall(self._nested.Set, self._nested, { CurrentValue = self.Value.Rgb, Transparency = 1 - self.Value.Alpha }, nil, true)
        end)
        self.ValueChanged:Fire(self.Value)
        if not silent then self.Changed:Fire(self.Value) end
    end

    -- gradient and colour animation editing do not exist in Starlight's picker
    function ColorC:EnableAnimation() end
    function ColorC:SetAnimationMode() end
    function ColorC:SetAnimationSpeed() end
    function ColorC:SetAnimationBreathingRange() end
    ColorC.AnimationChanged = Signal.new()
    ColorC.AnimationSpeedChanged = Signal.new()
    ColorC.AnimationBreathingRangeChanged = Signal.new()

    ----------------------------------------------------------------------------------------------- keybind
    local function keyToText(key)
        if typeof(key) ~= "EnumItem" then return K.T("No Bind") end
        if key.EnumType == Enum.UserInputType then
            if key == Enum.UserInputType.MouseButton1 then return "MB1" end
            if key == Enum.UserInputType.MouseButton2 then return "MB2" end
            if key == Enum.UserInputType.MouseButton3 then return "MB3" end
            return "No Bind"
        end
        return key.Name
    end

    local function textToKey(text)
        if type(text) ~= "string" or text == "No Bind" or text == "" then return nil end
        if text == "MB1" then return Enum.UserInputType.MouseButton1 end
        if text == "MB2" then return Enum.UserInputType.MouseButton2 end
        if text == "MB3" then return Enum.UserInputType.MouseButton3 end
        local ok, key = pcall(function() return Enum.KeyCode[text] end)
        if ok and key ~= nil then return key end
        return nil
    end

    local function configKey(v)
        if typeof(v) == "EnumItem" then return v end
        if type(v) == "string" and v ~= "None" and v ~= "" then
            local ok, key = pcall(function() return tbl17.w().deserializeKey(v) end)
            if ok and typeof(key) == "EnumItem" then return key end
        end
        return nil
    end

    -- a keybind list entry per keybind control, lit while its feature is active: the LY form draws it with MD3
    -- (menu:_listAdd), the other forms with K.KeyHud
    function Control:_attachListEntry(sec, o, host)
        self.ShowInList = o.InKeybindList == true
        self.FeatureEnabled = false
        self.FeatureChanged = Signal.new()
        self.ListLabel = tostring(o.ListLabel or o.Label or host._label or "Keybind"):gsub("^Enable%s+", "")
        local menu = sec._menu
        local entry
        if menu._listAdd ~= nil then
            entry = menu:_listAdd(self.ListLabel)
        elseif K.KeyHud ~= nil then
            entry = K.KeyHud.add(self.ListLabel)
        end
        if entry == nil then return end
        local function sync()
            -- Always keys are not listed; Hold and Toggle look the same (the key, lit while active)
            entry.update(self.ShowInList and self.FeatureEnabled and self.Value.Mode ~= "Always", self.Value.Key, self.Active == true, false)
        end
        self._lySync = sync
        self.ActiveChanged:Connect(sync)
        self.ShowInListChanged:Connect(sync)
        self.FeatureChanged:Connect(sync)
        self.ValueChanged:Connect(sync)
    end

    function KeybindC.new(sec, o)
        local self = newControl(sec, "Keybind", KeybindC)
        local host, own = hostFor(sec, o)
        self._host = host
        local hostLabel = tostring(o.Label or host._label or "Keybind")
        if own then self._followers = { host } end
        local modes = {}
        for _, m in ipairs(o.Modes or {}) do modes[#modes + 1] = tostring(m) end
        self.Modes = modes
        self.Value = { Key = nil, Mode = modes[1] or "Toggle" }
        self.ShowInList = o.InKeybindList == true
        self.Invisible = false
        self.ShowInListChanged = Signal.new()
        self.InvisibleChanged = Signal.new()
        self.ActiveChanged = Signal.new()
        self:_attachListEntry(sec, o, host)
        self:_defer(function()
            if not host._realized then host:_realizeNow() end
            self._nested = host._el:AddBind({
                CurrentValue = keyToText(self.Value.Key),
                HoldToInteract = false,
                SyncToggleState = false,
                IgnoreConfig = true,
                Callback = function() end,
                OnChangedCallback = function(text)
                    if self:_suppressed() then return end
                    self:_emit({ Key = textToKey(text), Mode = self.Value.Mode })
                end,
            }, uid("bd"))
        end)
        if #modes > 1 then
            self._modeDropdown = sec:_make("Dropdown", {
                Label = hostLabel .. " Mode",
                Options = modes,
                Default = self.Value.Mode,
                OnChanged = function(m)
                    if self:_suppressed() or m == nil then return end
                    self:_emit({ Key = self.Value.Key, Mode = m })
                end,
            })
            self._followers[#self._followers + 1] = self._modeDropdown
        end
        return self
    end

    function KeybindC:_isReady()
        local n = self._nested
        return n ~= nil and n.Instance ~= nil
    end

    function KeybindC:_instance()
        local n = self._nested
        if n ~= nil and n.LYRow ~= nil then return n.LYRow end
        return self._host and self._host._el and self._host._el.Instance
    end

    function KeybindC:Set(v, silent)
        if type(v) ~= "table" then return end
        local key = v.Key
        if typeof(key) ~= "EnumItem" then key = nil end
        local mode = v.Mode
        if type(mode) ~= "string" or (#self.Modes > 0 and not table.find(self.Modes, mode)) then mode = self.Value.Mode end
        if silent and key == self.Value.Key and mode == self.Value.Mode then return end
        self.Value = { Key = key, Mode = mode }
        self:_suppress(0.4)
        self:_whenReady(function()
            self:_suppress(0.4)
            pcall(self._nested.Set, self._nested, { CurrentValue = keyToText(key) })
        end)
        -- the mode row is a control of its own: it keeps its value whether or not it is built yet
        if self._modeDropdown ~= nil then self._modeDropdown:Set(mode, true) end
        self.ValueChanged:Fire(self.Value)
        if not silent then self.Changed:Fire(self.Value) end
    end

    function KeybindC:SetKey(key)
        self:Set({ Key = key, Mode = self.Value.Mode }, false)
    end

    function KeybindC:SetMode(mode)
        self:Set({ Key = self.Value.Key, Mode = mode }, false)
    end

    function KeybindC:SetShowInList(v, silent)
        self.ShowInList = v == true
        if not silent then self.ShowInListChanged:Fire(self.ShowInList) end
    end

    function KeybindC:SetInvisible(v)
        self.Invisible = v == true
        self.InvisibleChanged:Fire(self.Invisible)
    end

    function KeybindC:SetFeatureEnabled(v)
        v = v == true
        if self.FeatureEnabled == v then return end
        self.FeatureEnabled = v
        self.FeatureChanged:Fire(v)
    end

    function KeybindC:SetActive(v)
        self.Active = v == true
        self.ActiveChanged:Fire(self.Active)
    end

    -- config map: Key / Mode are the path of the key and the mode in the settings store (State is written by the
    -- keybind controller of the script, not by the menu)
    function KeybindC:_BindConfigMap(config, map)
        local function pull()
            local key = map.Key and configKey(config:Get(map.Key)) or nil
            local mode = map.Mode and config:Get(map.Mode) or nil
            self:Set({ Key = key, Mode = type(mode) == "string" and mode or self.Value.Mode }, true)
        end
        pull()
        local writing = false
        if map.Key ~= nil then
            self:Connect(config:Changed(map.Key, true), function() if not writing then pull() end end)
        end
        if map.Mode ~= nil then
            self:Connect(config:Changed(map.Mode, true), function() if not writing then pull() end end)
        end
        self:Connect(self.Changed, function(v)
            writing = true
            if map.Key ~= nil then config:Set(map.Key, v.Key or "None") end
            if map.Mode ~= nil then config:Set(map.Mode, v.Mode) end
            writing = false
        end)
        if map.ShowInList ~= nil then
            local sv = config:Get(map.ShowInList)
            if type(sv) == "boolean" then self.ShowInList = sv end
        end
        if map.Invisible ~= nil then
            local iv = config:Get(map.Invisible)
            if type(iv) == "boolean" then self.Invisible = iv end
        end
        -- the state of the feature, written by the keybind controller (what a keybind list shows), and the
        -- list switches, which can change later
        if map.Active ~= nil then
            local av = config:Get(map.Active)
            if type(av) == "boolean" then self:SetActive(av) end
            self:Connect(config:Changed(map.Active, true), function(v) self:SetActive(v == true) end)
        end
        if map.ShowInList ~= nil then
            self:Connect(config:Changed(map.ShowInList, true), function(v)
                if type(v) == "boolean" then self:SetShowInList(v) end
            end)
        end
        if map.Invisible ~= nil then
            self:Connect(config:Changed(map.Invisible, true), function(v)
                if type(v) == "boolean" then self:SetInvisible(v) end
            end)
        end
        if self._lySync ~= nil then self._lySync() end
        -- on-screen key button (phones): only for the keys of the keybind list
        if map.Active ~= nil and self.ShowInList and K.MobileKeys ~= nil and not self._mobile then
            self._mobile = true
            K.MobileKeys.register(self.ListLabel or "Key", {
                Mode = function() return self.Value.Mode end,
                Visible = function() return self.ShowInList and self.FeatureEnabled == true end,
                Active = function() return self.Active == true end,
                Down = function(down)
                    local mode = self.Value.Mode
                    if mode == "Hold" then
                        config:Set(map.Active, down)
                    elseif down then
                        config:Set(map.Active, not (config:Get(map.Active) == true))
                    end
                end,
            })
        end
    end

    ----------------------------------------------------------------------------------------------- ordered list
    -- one dropdown per rank; picking an item that is already used swaps the two
    function OrderedC.new(sec, o)
        local self = newControl(sec, "OrderedList", OrderedC)
        -- no element of its own: one dropdown per rank, each built on its own
        self._realized, self._noElement = true, true
        local items = {}
        for i, it in ipairs(o.Items or {}) do items[i] = tostring(it) end
        self.Items = items
        local order = {}
        for _, it in ipairs(type(o.Default) == "table" and o.Default or items) do
            if table.find(items, it) and not table.find(order, it) then order[#order + 1] = it end
        end
        for _, it in ipairs(items) do
            if not table.find(order, it) then order[#order + 1] = it end
        end
        self.Value = order
        self._ranks = {}
        self._followers = {}
        local label = tostring(o.Label or "Order")
        for i = 1, #items do
            local dd = sec:_make("Dropdown", {
                Label = label .. " " .. i,
                Options = items,
                Default = order[i],
                OnChanged = function(choice)
                    if self:_suppressed() or choice == nil then return end
                    local nv = clone(self.Value)
                    local j = table.find(nv, choice)
                    if j ~= nil and j ~= i then nv[j], nv[i] = nv[i], nv[j] else nv[i] = choice end
                    self:_emit(nv)
                    self:_refresh(true)
                end,
            })
            self._ranks[i] = dd
            self._followers[i] = dd
        end
        return self
    end

    function OrderedC:_refresh()
        self:_suppress(0.6)
        for i, dd in ipairs(self._ranks) do dd:Set(self.Value[i], true) end
    end

    function OrderedC:Set(v, silent)
        if type(v) ~= "table" then return end
        local order = {}
        for _, it in ipairs(v) do
            if table.find(self.Items, it) and not table.find(order, it) then order[#order + 1] = it end
        end
        for _, it in ipairs(self.Items) do
            if not table.find(order, it) then order[#order + 1] = it end
        end
        if silent then
            local same = true
            for i, it in ipairs(order) do
                if self.Value[i] ~= it then same = false break end
            end
            if same then return end
        end
        self.Value = order
        self:_refresh()
        self.ValueChanged:Fire(order)
        if not silent then self.Changed:Fire(order) end
    end

    --------------------------------------------------------------------------------------------------- containers
    local Makers = {}

    Makers.Toggle = function(sec, o) return ToggleC.new(sec, o) end
    Makers.Slider = function(sec, o) return SliderC.new(sec, o) end
    Makers.RangeSlider = function(sec, o) return RangeC.new(sec, o) end
    Makers.Button = function(sec, o) return ButtonC.new(sec, o) end
    Makers.Label = function(sec, o) return LabelC.new(sec, o) end
    Makers.Divider = function(sec, o) return DividerC.new(sec, o) end
    Makers.TextBox = function(sec, o) return TextBoxC.new(sec, o) end
    Makers.Dropdown = function(sec, o) return DropdownC.new(sec, o, false) end
    Makers.MultiDropdown = function(sec, o) return DropdownC.new(sec, o, true) end
    Makers.List = function(sec, o) return DropdownC.new(sec, o, false) end
    Makers.MultiList = function(sec, o) return DropdownC.new(sec, o, true) end
    Makers.Color = function(sec, o) return ColorC.new(sec, o) end
    Makers.Keybind = function(sec, o) return KeybindC.new(sec, o) end
    Makers.OrderedList = function(sec, o) return OrderedC.new(sec, o) end
    Makers.SkinChanger = function(sec)
        if not sec._menu._skinNotice then
            sec._menu._skinNotice = true
            sec:_make("Label", { Label = K.T("The skin, wrap, charm and finisher picker is in the LY and Classic menus.") })
        end
        return stub
    end
    Makers.Stub = function() return stub end

    local Container = {}
    Container.__index = Container

    local function def(name, kind)
        Container[name] = function(self, o)
            local ok, res = pcall(self._make, self, kind, o or {})
            if ok then return res end
            log(name .. " failed: " .. tostring(res))
            return stub
        end
    end
    def("AddToggle", "Toggle")
    def("AddSlider", "Slider")
    def("AddRangeSlider", "RangeSlider")
    def("AddButton", "Button")
    def("AddLabel", "Label")
    def("AddDivider", "Divider")
    def("AddTextBox", "TextBox")
    def("AddDropdown", "Dropdown")
    def("AddMultiDropdown", "MultiDropdown")
    def("AddList", "List")
    def("AddMultiList", "MultiList")
    def("AddColor", "Color")
    def("AddKeybind", "Keybind")
    def("AddOrderedList", "OrderedList")
    def("AddSkinChanger", "SkinChanger")
    def("AddIconStrip", "Stub")
    def("AddViewport", "Stub")
    def("AddGear", "Stub")
    def("AddCustomRow", "Stub")

    -- groups: members follow the value of a source control (toggle: on, dropdown: option == Option)
    local Group = {}
    Group.__index = Group
    setmetatable(Group, { __index = Container })

    local function evalSource(src, opt)
        local v = src.Value
        if opt ~= nil then
            if type(v) == "table" then return v[opt] == true or table.find(v, opt) ~= nil end
            return v == opt
        end
        if type(v) == "table" then return next(v) ~= nil end
        return v ~= nil and v ~= false
    end

    function Group:_effective()
        local parent = self._parent
        local up = true
        if parent ~= nil and parent._effective ~= nil then up = parent:_effective() end
        return self._own and up
    end

    function Group:_refresh()
        local eff = self:_effective()
        for _, c in ipairs(self._members) do
            c._gv[self] = eff
            c:_applyVis()
        end
        for _, g in ipairs(self._children) do g:_refresh() end
    end

    function Group:_make(kind, o)
        local c = self._sec:_make(kind, o)
        if type(c) == "table" and getmetatable(c) ~= Stub then
            self._members[#self._members + 1] = c
            c._gv[self] = self:_effective()
            c:_applyVis()
        end
        return c
    end

    function Group:AddGroup(o)
        return Container.AddGroup(self, o)
    end

    function Group:SetVisible(v)
        self._manual = v ~= false
        self:_refresh()
    end

    function Container:AddGroup(o)
        o = o or {}
        local g = setmetatable({
            _sec = self._sec or self,
            _menu = self._menu,
            _parent = self,
            _src = o.Source,
            _opt = o.Option,
            _own = true,
            _members = {},
            _children = {},
        }, Group)
        if self._children ~= nil then self._children[#self._children + 1] = g end
        local src = o.Source
        if type(src) == "table" and rawget(src, "ValueChanged") ~= nil then
            g._own = evalSource(src, o.Option) and true or false
            local ok, conn = pcall(function()
                return src.ValueChanged:Connect(function()
                    g._own = evalSource(src, g._opt) and true or false
                    g:_refresh()
                end)
            end)
            if ok then
                self._menu._groupConns[#self._menu._groupConns + 1] = conn
            end
        end
        return g
    end

    -- sections (a Starlight groupbox)
    local Section = {}
    Section.__index = Section
    setmetatable(Section, { __index = Container })

    -- the link between a control and the settings store, by the same rules as the classic menu's _Bind / AddColor /
    -- AddKeybind: without it a control only moves on screen and the features never see the change
    local DEBOUNCED = { Slider = true, RangeSlider = true }
    local function bindToConfig(menu, kind, c, o)
        if type(c) ~= "table" or getmetatable(c) == Stub then return end
        local config = menu._config
        if config == nil then return end
        if kind == "Keybind" then
            if o.ConfigMap ~= nil then c:_BindConfigMap(config, o.ConfigMap) end
            return
        end
        if o.Config == nil then return end
        if kind == "Color" then
            tbl17.N().bindConfig(c, config, o)
            return
        end
        local bind = o.Bind
        if DEBOUNCED[kind] and (bind == nil or bind.Debounce == nil) then
            bind = { WriteBack = bind and bind.WriteBack, Debounce = true }
        end
        -- a feature switch also drives the keybind list: its changes must arrive while the menu is closed
        if kind == "Toggle" then
            bind = { WriteBack = bind and bind.WriteBack, Debounce = bind and bind.Debounce, Persistent = true }
        end
        -- the control is its own trove: Control:Connect keeps the connections and Destroy drops them
        tbl17.P().bind(c, config, c, o.Config, bind)
    end

    function Section:_make(kind, o)
        local maker = Makers[kind]
        if maker == nil then return stub end
        local c = maker(self, o)
        local ok, err = pcall(bindToConfig, self._menu, kind, c, o)
        if not ok then log(kind .. " '" .. tostring(o.Label) .. "' could not be linked to its setting: " .. tostring(err)) end
        return c
    end

    function Section:SetVisible(v)
        self._secVis = v ~= false
        -- not built yet: _realize applies it
        if not self._realized then return end
        local function try()
            local ok, inst = pcall(function() return self._gb.Instance end)
            if ok and typeof(inst) == "Instance" then
                inst.Visible = v ~= false
                return true
            end
            return false
        end
        if not try() then
            task.spawn(function()
                for _ = 1, 120 do
                    task.wait(0.05)
                    if try() then return end
                end
            end)
        end
    end


    local function newSection(page, o)
        o = o or {}
        local side = o.Side
        local columns = page._columns or 2
        local column = 1
        if columns >= 2 and side == "right" then column = 2 end
        if columns >= 3 and side == "right" then column = 3 end
        local title = o.Title
        if title == nil or tostring(title) == "" then title = " " end
        local sec = setmetatable({ _menu = page._menu, _page = page, _realized = false, _pending = {} }, Section)
        sec._sec = sec
        sec._gbSettings = { Name = tostring(title), Column = column, Icon = iconOf(o.Icon) }
        if page._realized then
            sec:_realize()
        else
            page._sections[#page._sections + 1] = sec
        end
        return sec
    end

    -- the groupbox, then every control queued on it, in the order the page code made them (a nested picker / bind /
    -- dropdown comes after the row it sits on)
    function Section:_realize()
        if self._realized then return end
        self._realized = true
        self._gb = self._page._tab:CreateGroupbox(self._gbSettings, uid("gb"))
        local pending = self._pending
        self._pending = {}
        for _, c in ipairs(pending) do
            c:_realizeNow()
        end
        if self._secVis == false then self:SetVisible(false) end
    end

    --------------------------------------------------------------------------------------------------- pages and tabs
    local Grid = {}
    Grid.__index = Grid
    function Grid:AddSection(o)
        if self._inert then return stub end
        local ok, res = pcall(newSection, self._page, o)
        if ok then return res end
        log("AddSection failed: " .. tostring(res))
        return stub
    end
    -- AddMultiSection({ Titles = { "A", "B" }, Side = ... }) returns one pane per title; here each pane is its own groupbox
    local function multiSection(page, o)
        o = o or {}
        local panes = {}
        for i, title in ipairs(o.Titles or {}) do
            local ok, res = pcall(newSection, page, { Title = title, Side = o.Side })
            panes[i] = ok and res or stub
            if not ok then log("AddMultiSection failed: " .. tostring(res)) end
        end
        return table.unpack(panes)
    end
    function Grid:AddMultiSection(o)
        if self._inert then return stub, stub end
        return multiSection(self._page, o)
    end
    function Section:AddMultiSection(o)
        return multiSection(self._page, o)
    end
    function Grid:SetVisible() end

    local Page = {}
    Page.__index = function(t, k)
        local v = rawget(Page, k)
        if v ~= nil then return v end
        if isMethodName(k) then return function() return nil end end
        return nil
    end

    -- The sidebar button and the empty page are made at once (the tab list is complete from the start); the page's
    -- groupboxes and controls wait until the button is first clicked, as the classic menu realizes a page on its first
    -- open. The tab Starlight opens by itself (the first one) is built at once.
    -- The page is only recorded here (its columns, its place in the sidebar); its Starlight tab is made by
    -- Page:_physical, when the window exists (Menu:_materialize), or at once when the window is already up.
    function Page:_ensure(columns)
        if self._ensured then return end
        self._ensured = true
        columns = math.max(1, math.min(3, columns or 2))
        self._columns = columns
        self._realized = false
        self._sections = {}
        local owner = self._owner
        owner._pagesOrder[#owner._pagesOrder + 1] = self
        if self._menu._materialized and owner._ts ~= nil then self:_physical() end
    end

    function Page:_physical()
        if self._tab ~= nil or self._menu._destroyed then return end
        local tab = self._owner._ts:CreateTab({ Name = self.Label, Columns = self._columns, Icon = iconOf(self.Icon) }, uid("tab"))
        self._tab = tab
        if self._theme then
            pcall(function() tab:BuildThemeGroupbox(1) end)
        end
        if tab.Active then
            -- the tab Starlight opens by itself: its sections (made before the window existed) are built now
            self:_realize()
        else
            local ok = pcall(function()
                local conn
                conn = tab.Instances.Button.Interact.MouseButton1Click:Connect(function()
                    conn:Disconnect()
                    self:_realize()
                end)
            end)
            -- no button to wait for: build it now rather than never
            if not ok then self:_realize() end
        end
    end

    function Page:_realize()
        if self._realized then return end
        self._realized = true
        local t0 = os.clock()
        local sections = self._sections
        self._sections = {}
        for _, sec in ipairs(sections) do
            local ok, err = pcall(sec._realize, sec)
            if not ok then log("a section of '" .. tostring(self.Label) .. "' failed to build: " .. tostring(err)) end
        end
        log(string.format("page '%s' built on first open in %.2f s", tostring(self.Label), os.clock() - t0))
    end

    function Page:Grid(o)
        o = o or {}
        local grid = setmetatable({ _page = self }, Grid)
        if self._theme then
            -- the theme groupbox is made with the tab (Page:_physical)
            self:_ensure(1)
            grid._inert = true
            return grid
        end
        self:_ensure(o.Columns)
        return grid
    end

    function Page:OnFirstOpen(fn)
        if type(fn) ~= "function" then return end
        task.defer(function()
            local ok, err = pcall(fn)
            if not ok then log("page '" .. tostring(self.Label) .. "' failed to build: " .. tostring(err)) end
        end)
    end

    function Page:Open() end
    function Page:SetVisible() end

    local Tab = {}
    Tab.__index = function(t, k)
        local v = rawget(Tab, k)
        if v ~= nil then return v end
        if isMethodName(k) then return function() return nil end end
        return nil
    end

    function Tab:AddTab(o)
        o = o or {}
        local page = setmetatable({
            _menu = self._menu,
            _owner = self,
            Label = tostring(o.Label or "Page"),
            Icon = o.Icon or false,
            Description = o.Description or false,
        }, Page)
        if self._isSettings and (o._enLabel or page.Label) == "Theme" then page._theme = true end
        self._pages[#self._pages + 1] = page
        return page
    end

    -- a top-level tab used without sub tabs behaves as one page
    function Tab:Grid(o)
        if self._single == nil then
            self._single = self:AddTab({ Label = self.Label, Icon = self.Icon })
        end
        return self._single:Grid(o)
    end

    --------------------------------------------------------------------------------------------------- dialogs
    -- A dialog becomes a tab in the "Manage" section of the sidebar; each page becomes a groupbox with an action button.
    local function buildDialog(menu, o, builder)
        local key = tostring(o.Title or "Dialog")
        local existing = menu._dialogs[key]
        if existing ~= nil then
            for _, p in ipairs(existing.pages) do
                if p.onOpen ~= nil then pcall(p.onOpen) end
            end
            return existing
        end
        if menu._manage == nil then
            -- a sidebar section like a tab; its Starlight section is made with the window
            menu._manage = { Label = K.T("Manage"), _menu = menu, _pagesOrder = {} }
            menu._owners[#menu._owners + 1] = menu._manage
            if menu._materialized then menu._manage._ts = menu._win:CreateTabSection("Manage") end
        end
        local page = setmetatable({ _menu = menu, _owner = menu._manage, Label = key }, Page)
        page:_ensure(2)
        local dialog = { pages = {}, title = key }
        menu._dialogs[key] = dialog
        function dialog:Close() end
        function dialog:AddPage(po, pbuilder)
            po = po or {}
            local sec = newSection(page, { Title = tostring(po.Title or "Page"), Side = (#dialog.pages % 2 == 0) and "left" or "right" })
            if po.Description then sec:_make("Label", { Label = tostring(po.Description) }) end
            local node = { onOpen = po.OnOpen }
            dialog.pages[#dialog.pages + 1] = node
            if pbuilder ~= nil then
                local ok, err = pcall(pbuilder, sec)
                if not ok then log("dialog page failed: " .. tostring(err)) end
            end
            local confirming = false
            local actionText = tostring(po.ActionText or "OK")
            local button
            button = sec:_make("Button", {
                Label = actionText,
                OnClick = function()
                    if po.Confirmation ~= nil and not confirming then
                        confirming = true
                        local desc = po.Confirmation.Description
                        if type(desc) == "function" then
                            local ok, text = pcall(desc)
                            desc = ok and text or ""
                        end
                        notify(K.T(tostring(desc or "Click again to confirm.")))
                        button:_rename("Confirm: " .. actionText)
                        task.delay(4, function()
                            if confirming then
                                confirming = false
                                button:_rename(actionText)
                            end
                        end)
                        return
                    end
                    if confirming then
                        confirming = false
                        button:_rename(actionText)
                    end
                    if po.OnAction ~= nil then
                        local ok, res = pcall(po.OnAction)
                        if not ok then
                            log("dialog action failed: " .. tostring(res))
                        elseif res then
                            if node.onOpen ~= nil then pcall(node.onOpen) end
                        end
                    end
                end,
            })
            if po.ActionEnabled == false then button:SetEnabled(false) end
            function node:SetActionEnabled(v) button:SetEnabled(v) end
            node.Close = function() end
            if node.onOpen ~= nil then pcall(node.onOpen) end
            return node
        end
        local ok, err = pcall(builder, dialog)
        if not ok then log("dialog '" .. key .. "' failed: " .. tostring(err)) end
        return dialog
    end

    --------------------------------------------------------------------------------------------------- menu
    local Menu = {}
    Menu.__index = function(t, k)
        local v = rawget(Menu, k)
        if v ~= nil then return v end
        -- members of the classic menu that have no meaning here
        if isMethodName(k) then return function() return nil end end
        return nil
    end
    StarUI.Menu = Menu

    function Menu.new(opts)
        local tNew = os.clock()
        local L, err = StarUI.Load(true)
        if L == nil then error("Starlight could not be loaded: " .. tostring(err), 0) end
        log(string.format("menu step: library loaded %.3f s", os.clock() - tNew))
        local self = setmetatable({}, Menu)
        self._lib = L
        self._opts = opts or {}
        self._trove = Trove.new("StarMenu")
        self._controls = {}
        self._groupConns = {}
        self._dialogs = {}
        self._config = opts.Config
        self._colorAnimation = opts.ColorAnimation
        self._persistence = opts.Persistence
        self._state = opts.State
        self._stateData = opts.StateData
        self._onUnload = opts.OnUnload
        self._themePath = opts.ThemePath or { "Theme" }
        self._notificationPath = opts.NotificationPath or { "Notifications" }
        self._autoExecuteEnabledPath = opts.AutoExecuteEnabledPath or { "AutoExecuteScript", "Enabled" }
        self.Title = opts.Title or "LxYHook"
        self.Icon = opts.Icon
        self.Directory = opts.Directory
        self.Visible = false
        self.Dragging = false
        self.Keybind = Enum.KeyCode.RightShift
        self.VisibilityChanged = Signal.new()
        self.AccentChanged = Signal.new()
        self._watermark = not (self._stateData ~= nil and self._stateData.ShowWatermark == false)
        self._keybindList = not (self._stateData ~= nil and self._stateData.ShowKeybinds == false)
        self._tabs = {}

        local saved
        pcall(function()
            saved = tbl17.w().deserializeKey(self._stateData and self._stateData.Keybind)
        end)
        if typeof(saved) == "EnumItem" then self.Keybind = saved end

        -- Like the classic menu, nothing of the window is built here: the tabs, pages and controls are plain objects
        -- (a control already is one until its page is first opened), and the Starlight window itself (its 18 000
        -- instance model, the sidebar, the tab buttons) is made by Menu:_materialize the first time the menu is
        -- shown. Building it all at load was a 1.5 s block of the main thread right as the game starts.
        self._materialized = false
        self._materializing = false
        self._owners = {}
        self._trove:Connect(UserInputService.InputBegan, function(input, processed)
            if processed or self._destroyed then return end
            local key = input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode or input.UserInputType
            if key == self.Keybind then self:SetVisible(not self.Visible) end
        end)
        pcall(function() self._cursor = tbl17.ag().new(self._trove) end)

        return self
    end

    -- Builds the window in the background while it is closed, a slice per frame (the same steps as the first show),
    -- so by the time the menu key is pressed it is already there. A key pressed meanwhile is honoured at the end.
    function Menu:_prewarm()
        if self._materialized or self._materializing or self._destroyed then return end
        self._prewarm = true
        self:_materialize()
        self._prewarm = false
        if self._destroyed or not self._materialized then return end
        if self._wantShow == true then
            self._wantShow = nil
            self:SetVisible(true, true)
        end
    end

    -- The Starlight window, its sidebar and every tab button, made the first time the menu is shown (see Menu.new).
    -- Runs in the thread that shows the menu and gives the frame back between tabs, so no single frame holds it all.
    function Menu:_materialize()
        if self._materialized or self._materializing or self._destroyed then return end
        self._materializing = true
        local L, opts = self._lib, self._opts
        local tM = os.clock()
        self._win = L:CreateWindow({
            Name = self.Title,
            Subtitle = opts.Subtitle or "Rivals",
            LoadingEnabled = false,
            NotifyOnCallbackError = false,
            BuildWarnings = false,
            InterfaceAdvertisingPrompts = false,
            FileSettings = { RootFolder = "LxYHook", ConfigFolder = "Interface" },
            KeySystem = { Enabled = false },
            Discord = { Enabled = false },
        }) or L.Window
        log(string.format("menu step: CreateWindow %.3f s", os.clock() - tM))
        -- built ahead of time (Menu:_prewarm): the window must not appear, so it is closed before the next frame
        if self._prewarm then pcall(function() L.__LxYSetWindowShown(false, true) end) end
        if coroutine.isyieldable() then task.wait() end
        -- Settings > Theme > "Autoload Theme" only writes themes/autoload.txt; Starlight reads it back when the script
        -- asks it to (LoadAutoloadTheme), which nothing did, so the chosen theme never came back on the next load.
        -- Done right after the window: every element made after this (all of them, pages are built lazily) gets it.
        local okTheme, themeResult, themeErr = pcall(L.LoadAutoloadTheme, L)
        if not okTheme then
            log("autoload theme failed: " .. tostring(themeResult))
        elseif themeResult == false or type(themeResult) == "string" then
            log("autoload theme: " .. tostring(themeErr or themeResult))
        end
        log(string.format("menu step: LoadAutoloadTheme %.3f s", os.clock() - tM))
        if coroutine.isyieldable() then task.wait() end
        -- The dashboard page exists in the interface model but had no sidebar button, so it only showed up by itself
        -- (page layout fallback). Give it a real "Welcome" category at the very top of the sidebar.
        -- (it waits on the network for the avatar and the server details for about a second, so it runs beside the
        -- tabs instead of in front of them)
        task.spawn(function()
            local okHome, home = pcall(function()
                return self._win:CreateHomeTab({ Backdrop = 0, IconStyle = 1, DiscordInvite = "" })
            end)
            if not okHome or type(home) ~= "table" then
                log("welcome tab failed: " .. tostring(home))
            else
                pcall(function()
                    local section = home.Instances.Button.Parent
                    section.Header.Text = K.T("Welcome")
                    section.Header.Visible = true
                    section.Name = "TAB_SECTION_Welcome"
                    section.LayoutOrder = -1
                    home.Instances.Button.Header.Text = K.T("Dashboard")
                    local discord = home.Instances.Page.Holder.Left.Discord
                    discord.Header.Text = "Lxyhook"
                    discord.Subheader.Text = "6767676767676767"
                end)
            end
            log(string.format("menu step: home tab %.3f s", os.clock() - tM))
        end)
        -- the menu key is handled in Menu.new (Starlight's own key is parked on a key nobody has)
        pcall(function() L.WindowKeybind = "F15" end)
        pcall(function()
            local logo = (K.LoadLogo and K.LoadLogo() or K.LithiumLogo)
            if logo ~= nil then
                L.Instance.MainWindow.Sidebar.Icon.Image = logo
                L.Instance.MobileToggle.Image = logo
                for _, target in ipairs({ L.Instance.MainWindow.Sidebar.Icon, L.Instance.MobileToggle }) do
                    K.AddLogoY(target, function(o)
                        local g = Instance.new("UIGradient")
                        g.Parent = o
                        if L.BindTheme then L.BindTheme(g, "Color", "Accents.Main")
                        else g.Color = L.CurrentTheme.Accents.Main end
                    end)
                end
            end
        end)
        log(string.format("menu step: window made %.3f s", os.clock() - tM))
        -- the sidebar, in the order the tabs and pages were made: a section per tab, then its pages' buttons
        local function owner(o)
            if o._ts == nil then o._ts = self._win:CreateTabSection(o.Label) end
            for _, page in ipairs(o._pagesOrder) do
                if self._destroyed then return end
                page:_physical()
            end
            if coroutine.isyieldable() then task.wait() end
        end
        for _, tab in ipairs(self._tabs) do owner(tab) end
        for _, o in ipairs(self._owners) do owner(o) end
        self._materialized = true
        self._materializing = false
        log(string.format("menu step: menu built on first show in %.3f s", os.clock() - tM))
        -- visibility and the menu key are Starlight's own; follow them
        task.spawn(function()
            local lastVis
            while not self._destroyed do
                task.wait(0.25)
                pcall(function()
                    local vis = L.Instance ~= nil and L.Instance.Enabled == true and not L.Minimized
                    if vis ~= lastVis then
                        lastVis = vis
                        self:_setVisibleState(vis)
                    end
                end)
            end
        end)
    end

    function Menu:_setVisibleState(vis)
        self.Visible = vis
        if self._cursor ~= nil then pcall(self._cursor.Set, self._cursor, vis) end
        local config = self._config
        if config ~= nil and config.SetActive ~= nil then pcall(config.SetActive, config, vis) end
        self.VisibilityChanged:Fire(vis)
    end

    function Menu:View() return self end
    function Menu:GetConfig() return self._config end
    function Menu:GetColorAnimation() return self._colorAnimation end
    function Menu:GetPersistence() return self._persistence end
    function Menu:GetStateData() return self._stateData end
    function Menu:GetOverlayLayer() return nil end

    function Menu:SaveState()
        local state, data = self._state, self._stateData
        if state ~= nil and data ~= nil then pcall(function() state:Save(data) end) end
    end

    function Menu:Connect(sig, fn)
        return self._trove:Connect(sig, fn)
    end

    function Menu:Add(item)
        return self._trove:Add(item)
    end

    function Menu:Notify(text, opts)
        notify(text)
    end

    function Menu:AddTab(o)
        o = o or {}
        local tab = setmetatable({
            _menu = self,
            Label = tostring(o.Label or "Tab"),
            Icon = o.Icon or false,
            _pages = {},
        }, Tab)
        -- the sidebar section is made with the window (Menu:_materialize); `_ts` stays nil until then
        tab._pagesOrder = {}
        if self._materialized then
            tab._ts = self._win:CreateTabSection(tab.Label)
        end
        self._tabs[#self._tabs + 1] = tab
        return tab
    end

    function Menu:AddSettingsTab()
        local tab = self:AddTab({
            Label = "Settings",
            Icon = "rbxassetid://106205298246017",
            Description = "Menu preferences, config management, and theme customization.",
        })
        tab._isSettings = true
        local menu = self
        local result
        local ok, err = pcall(function()
            result = tbl17.aC()(self:View(), tab, self._trove, {
                SetAccent = function(c) menu.AccentChanged:Fire(c) end,
                SetWatermarkEnabled = function(v) menu:SetWatermarkEnabled(v) end,
                IsWatermarkEnabled = function() return menu._watermark end,
                SetKeybindListEnabled = function(v) menu:SetKeybindListEnabled(v) end,
                IsKeybindListEnabled = function() return menu._keybindList end,
                SetMenuPillHidden = function() end,
                EnterMobileButtonDragMode = function() end,
                Unload = function() menu:Unload() end,
            }, self._themePath, self._notificationPath, self._autoExecuteEnabledPath)
        end)
        if not ok then log("settings tab failed: " .. tostring(err)) end
        return tab, result
    end

    function Menu:Dialog(o, builder)
        return buildDialog(self, o or {}, builder)
    end

    function Menu:SetWatermarkUsername(name)
        if K.KeyHud then K.KeyHud.ensure(name, self._watermark, self._keybindList) end
    end
    function Menu:_persistFlag(key, v)
        local data = self._stateData
        if data ~= nil and data[key] ~= (v ~= false) then
            data[key] = v ~= false
            self:SaveState()
        end
    end
    function Menu:SetWatermarkEnabled(v) self._watermark = v self:_persistFlag("ShowWatermark", v) if K.KeyHud then K.KeyHud.setWatermark(v) end end
    function Menu:IsWatermarkEnabled() return self._watermark end
    function Menu:SetKeybindListEnabled(v) self._keybindList = v self:_persistFlag("ShowKeybinds", v) if K.KeyHud then K.KeyHud.setList(v) end end
    function Menu:IsKeybindListEnabled() return self._keybindList end
    function Menu:SetAccent(c) self.AccentChanged:Fire(c) end

    -- Starlight's own minimize walks every descendant of the window (a GUID attribute and two or three tweens each),
    -- which with this many controls stalls the game on every open and close. The menu key only flips the window's
    -- Visible; the ScreenGui stays enabled so the mobile button is still there to reopen it.
    function Menu:SetVisible(visible, instant)
        if K.UIMark then K.UIMark(visible and "window shown" or "window hidden") end
        if not self._materialized then
            -- the window does not exist yet: hiding it is nothing to do, showing it builds it first (while that runs,
            -- a second call only changes what is wanted at the end)
            if self._destroyed then return true end
            if self._materializing then self._wantShow = visible return true end
            if not visible then
                self:_setVisibleState(false)
                return true
            end
            self._wantShow = true
            self:_materialize()
            if self._destroyed or not self._materialized then return true end
            visible, instant = self._wantShow, true
        end
        local L = self._lib
        pcall(function()
            local ui = L.Instance
            ui.Enabled = true
            -- the patched Starlight shows / hides its window at once; without that patch, the same done here
            if type(L.__LxYSetWindowShown) == "function" then
                L.__LxYSetWindowShown(visible, instant)
            else
                ui.MainWindow.Visible = visible
                local drag = ui:FindFirstChild("Drag")
                if drag ~= nil then drag.Visible = visible end
                L.Minimized = not visible
            end
        end)
        self:_setVisibleState(visible)
        return true
    end

    function Menu:Unload()
        if self._onUnload ~= nil then self._onUnload() else self:Destroy() end
    end

    function Menu:Destroy()
        if self._destroyed then return end
        if K.KeyHud then K.KeyHud.destroy() end
        self._destroyed = true
        self:SaveState()
        if self._cursor ~= nil then pcall(self._cursor.Set, self._cursor, false) end
        local config = self._config
        if config ~= nil and config.SetActive ~= nil then pcall(config.SetActive, config, false) end
        for _, c in ipairs(self._controls) do c._dead = true end
        pcall(function()
            for _, c in ipairs(self._groupConns) do c:Disconnect() end
        end)
        pcall(function() self._trove:Destroy() end)
        pcall(function() self._lib:Destroy() end)
    end

    --------------------------------------------------------------------------------------------------- Setsuna (Pop)
    -- Third form of the menu: a port of the Pop mode of Setsuna's ClickGUI. A ring of category bubbles around the logo;
    -- a bubble opens a list of its pages, a page opens its settings next to the list. It sits on the same Menu surface as
    -- the Starlight form (AddTab / Grid / AddSection / AddToggle ...) and reuses its control base, groups and config
    -- binding; only the widgets are its own.
    local SetsunaUI = {}
    K.SetsunaUI = SetsunaUI

    local TweenSvc = game:GetService("TweenService")
    local UIS = game:GetService("UserInputService")
    local GuiSvc = game:GetService("GuiService")

    local function mk(class, props, parent)
        local inst = Instance.new(class)
        for key, val in pairs(props) do inst[key] = val end
        if parent ~= nil then inst.Parent = parent end
        return inst
    end
    -- the KH V2 form has square corners everywhere (set per menu in newMenu)
    local sharpCorners = false
    local function corner(inst, px) return mk("UICorner", { CornerRadius = UDim.new(0, sharpCorners and 0 or px) }, inst) end
    local function circle(inst) return mk("UICorner", { CornerRadius = sharpCorners and UDim.new(0, 0) or UDim.new(0.5, 0) }, inst) end
    local function tween(inst, seconds, props, style, dir)
        local tw = TweenSvc:Create(inst, TweenInfo.new(seconds, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out), props)
        tw:Play()
        return tw
    end
    local function clamp(v, lo, hi) return math.max(lo, math.min(hi, v)) end

    local TEXT = Color3.fromRGB(243, 247, 248)
    local DIM = Color3.fromRGB(163, 175, 180)
    local FAINT = Color3.fromRGB(104, 118, 124)
    local DEFAULT_ACCENT = Color3.fromRGB(150, 80, 235)

    -- Setsuna's palette: dark greys pulled towards the accent
    -- Lite follows Starlight's theme data (Backgrounds / Foregrounds / Miscellaneous / Accents), the same one its
    -- library holds in Starlight.CurrentTheme, and uses each part the way Starlight's own window does: the window and
    -- its page area Backgrounds.Dark, the sidebar Backgrounds.Light, the top bar and the cards (groupboxes)
    -- Backgrounds.Medium, input rows Backgrounds.Dark, hovered / selected Backgrounds.Highlight, outlines
    -- Foregrounds.Dark, text Foregrounds.Light / Medium, dividers Miscellaneous.Divider, filled parts Accents.Main
    -- (a gradient: the `fill` role is white there and a UIGradient colours it).
    local function midOf(seq)
        local kps = seq.Keypoints
        return kps[math.ceil(#kps / 2)].Value
    end

    local function palette(acc, ov, lite, theme)
        if lite and theme ~= nil then
            local B, F, M, A = theme.Backgrounds, theme.Foregrounds, theme.Miscellaneous, theme.Accents
            return {
                acc = midOf(A.Main), fill = Color3.new(1, 1, 1),
                panel = B.Dark, side = B.Light, top = B.Medium, box = B.Medium, inner = B.Dark,
                track = M.Shadow, hover = B.Highlight, surf = B.Groupbox,
                text = F.Light, dim = F.Medium, faint = F.Dark, value = F.Active,
                outline = F.Dark, sel = B.Highlight, knob = F.Active, toggleoff = F.Dark, line = M.Divider,
            }
        end
        local function tone(base, amt)
            return Color3.new((base + (acc.R * 255 - base) * amt) / 255, (base + (acc.G * 255 - base) * amt) / 255, (base + (acc.B * 255 - base) * amt) / 255)
        end
        local p = { acc = acc, panel = tone(7, .22), inner = tone(9, .30), track = tone(13, .42), hover = tone(17, .52),
            surf = tone(7, .22), text = TEXT, dim = DIM, faint = FAINT, value = acc, outline = acc, sel = acc, knob = TEXT }
        p.fill, p.side, p.box, p.top, p.line = acc, p.inner, p.inner, p.inner, acc
        p.toggleoff = p.track
        -- colours the user picked on the Theme page (Background, Outline, Text ...) replace the derived ones
        for role, c in pairs(ov or {}) do p[role] = c end
        return p
    end

    -- GUI coordinates start below the top bar: input.Position already is in them, GetMouseLocation is not
    local function pointer(input)
        if input.UserInputType == Enum.UserInputType.Touch then
            return input.Position.X, input.Position.Y
        end
        local p = UIS:GetMouseLocation()
        local inset = GuiSvc:GetGuiInset()
        return p.X - inset.X, p.Y - inset.Y
    end

    -- cb(x, y) in screen pixels, on the press and on every move until the button is released
    local function dragArea(obj, cb)
        obj.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            local moveConn, endConn
            local function stop()
                if moveConn then moveConn:Disconnect() end
                if endConn then endConn:Disconnect() end
            end
            cb(pointer(input))
            moveConn = UIS.InputChanged:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch then
                    cb(pointer(i))
                end
            end)
            endConn = UIS.InputEnded:Connect(function(i)
                if i == input or i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                    stop()
                end
            end)
        end)
    end

    local SMenu = {}
    SMenu.__index = function(t, k)
        local v = rawget(SMenu, k)
        if v ~= nil then return v end
        if isMethodName(k) then return function() return nil end end
        return nil
    end
    SetsunaUI.Menu = SMenu

    -- the Drop form shares the Pop form's constructor, theme, popups, dialogs and settings tab
    local SDrop = {}
    SDrop.__index = function(t, k)
        local v = rawget(SDrop, k)
        if v ~= nil then return v end
        v = rawget(SMenu, k)
        if v ~= nil then return v end
        if isMethodName(k) then return function() return nil end end
        return nil
    end
    SetsunaUI.Drop = SDrop

    -- colours follow the accent: static roles are painted through here, state-dependent ones re-run their function
    function SMenu:_paint(inst, prop, role)
        inst[prop] = self._pal[role]
        local list = self._themed
        list[#list + 1] = { inst, prop, role }
        return inst
    end

    -- the Lite form's filled parts carry the accent as a gradient (nothing in the other forms)
    function SMenu:_grad(inst, kind)
        if not self._lite then return nil end
        kind = kind or "Main"
        local grad = mk("UIGradient", { Color = self._theme.Accents[kind] }, inst)
        self._grads = self._grads or {}
        self._grads[#self._grads + 1] = { grad, kind }
        return grad
    end

    function SMenu:_onTheme(owner, fn)
        local list = self._themeFns
        list[#list + 1] = { owner, fn }
        fn()
    end

    function SMenu:_setAccent(c)
        self._acc = c
        self:_applyPalette()
    end

    function SMenu:_applyPalette()
        self._pal = palette(self._acc, self._ov, self._lite, self._theme)
        if self._grads ~= nil and self._theme ~= nil then
            local live, g = {}, 0
            for _, e in ipairs(self._grads) do
                if e[1].Parent ~= nil then
                    e[1].Color = self._theme.Accents[e[2]]
                    g += 1
                    live[g] = e
                end
            end
            self._grads = live
        end
        local keep, n = {}, 0
        for _, e in ipairs(self._themed) do
            local inst = e[1]
            if inst.Parent ~= nil then
                pcall(function() inst[e[2]] = self._pal[e[3]] end)
                n += 1
                keep[n] = e
            end
        end
        self._themed = keep
        local keepFns, m = {}, 0
        for _, e in ipairs(self._themeFns) do
            if not (e[1] ~= nil and e[1]._dead) then
                pcall(e[2])
                m += 1
                keepFns[m] = e
            end
        end
        self._themeFns = keepFns
    end

    local function text(m, parent, str, size, role, bold)
        local t = mk("TextLabel", {
            BackgroundTransparency = 1, Text = tostring(str), TextSize = size, Font = bold and Enum.Font.GothamBold or Enum.Font.GothamMedium,
            TextXAlignment = Enum.TextXAlignment.Left, BorderSizePixel = 0,
        }, parent)
        m:_paint(t, "TextColor3", role)
        return t
    end

    local function imageOf(icon)
        local id = iconOf(icon)
        if id == "" then return "" end
        return "rbxassetid://" .. id
    end

    --------------------------------------------------------------------------------------------------- controls
    local SSection = {}
    SSection.__index = SSection
    setmetatable(SSection, { __index = Container })

    local function newRow(sec, h, solid)
        local m = sec._menu
        sec._n += 1
        local scroll = sec._card or sec._page:_ensureScroll()
        local row = mk("Frame", {
            Size = UDim2.new(1, -8, 0, h), BorderSizePixel = 0, LayoutOrder = sec._order * 1000 + sec._n, Active = true,
        }, scroll)
        corner(row, 8)
        if m._v2 and not solid then
            m:_paint(row, "BackgroundColor3", "hover")
            row.BackgroundTransparency = 1
        elseif m._lite and not solid then
            -- Starlight's rows sit flat on the card; only the pointer lights one (a button keeps its backdrop)
            m:_paint(row, "BackgroundColor3", "hover")
            row.BackgroundTransparency = 1
            row.MouseEnter:Connect(function() tween(row, .12, { BackgroundTransparency = .8 }) end)
            row.MouseLeave:Connect(function() tween(row, .12, { BackgroundTransparency = 1 }) end)
        elseif solid == "grad" then
            -- Starlight's primary button (Style 1): the accent gradient
            m:_paint(row, "BackgroundColor3", "fill")
            m:_grad(row, "Main")
        else
            m:_paint(row, "BackgroundColor3", "inner")
            row.MouseEnter:Connect(function() tween(row, .12, { BackgroundColor3 = m._pal.hover }) end)
            row.MouseLeave:Connect(function() tween(row, .12, { BackgroundColor3 = m._pal.inner }) end)
        end
        return row
    end

    local function rowReady(self) return self._row ~= nil end
    local function rowInstance(self) return self._row end

    -- the row's label; reserve = width kept free on the right for the row's own widget
    local function rowLabel(self, row, str, reserve)
        local t = text(self._menu, row, str, 14, "text", false)
        t.Position = UDim2.fromOffset(14, 0)
        t.Size = UDim2.new(1, -(reserve + 24), 1, 0)
        t.TextWrapped = true
        self._text, self._reserve, self._extrasW = t, reserve, 0
        return t
    end

    -- a label row's height from its text (AutomaticSize rows were laid out with no height and the rows below overlapped them)
    local TextSvc = game:GetService("TextService")
    local function fitLabel(self)
        local row, t = self._row, self._text
        if row == nil or t == nil then return end
        local g = self._menu._g
        local avail = (g and g.setW or 280) - 16 - 28 - self._extrasW
        local ok, size = pcall(TextSvc.GetTextSize, TextSvc, tostring(t.Text), 14, Enum.Font.GothamMedium, Vector2.new(math.max(60, avail), 10000))
        local h = ok and size.Y or 16
        row.Size = UDim2.new(1, -8, 0, self._menu._v2 and math.max(20, h + 6) or math.max(36, h + 20))
        t.Size = UDim2.new(1, -self._extrasW, 1, 0)
    end

    local function relabel(self)
        local t = self._text
        if t == nil then return end
        if self._auto then
            fitLabel(self)
        else
            t.Size = UDim2.new(1, -(self._reserve + self._extrasW + 24), 1, 0)
        end
    end

    -- a colour swatch or a key button sits on the right of the row it belongs to
    local function attach(host, widget, w)
        local ex = host._extras
        if ex == nil then
            ex = mk("Frame", {
                BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, .5), Position = UDim2.new(1, -(host._reserve + 10), .5, 0),
                Size = UDim2.fromOffset(0, 28), AutomaticSize = Enum.AutomaticSize.X, ZIndex = 3,
            }, host._row)
            mk("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, HorizontalAlignment = Enum.HorizontalAlignment.Right,
                VerticalAlignment = Enum.VerticalAlignment.Center, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, ex)
            host._extras = ex
        end
        widget.Parent = ex
        host._extrasW += w + 6
        relabel(host)
    end

    local function rowButton(row)
        return mk("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 1 }, row)
    end

    ----------------------------------------------------------------------------------------------- label
    local SLabel = subclass()
    function SLabel.new(sec, o)
        local self = newControl(sec, "Label", SLabel)
        self.Text = tostring(o.Label or o.Text or "")
        self._label = self.Text
        self._canNest = true
        self:_defer(function()
            local m = sec._menu
            local row = newRow(sec, m._v2 and 20 or 36)
            local pv, ph = m._v2 and 3 or 10, m._v2 and 4 or 14
            mk("UIPadding", { PaddingTop = UDim.new(0, pv), PaddingBottom = UDim.new(0, pv), PaddingLeft = UDim.new(0, ph), PaddingRight = UDim.new(0, ph) }, row)
            self._row, self._el, self._auto, self._reserve, self._extrasW = row, row, true, 0, 0
            local t = text(m, row, self.Text, 14, "dim", false)
            t.Size = UDim2.fromScale(1, 1)
            t.TextWrapped = true
            t.TextYAlignment = Enum.TextYAlignment.Center
            self._text = t
            fitLabel(self)
        end)
        return self
    end
    SLabel._instance = rowInstance
    SLabel._isReady = rowReady

    function SLabel:Set(str)
        self.Text = tostring(str or "")
        if self._text then
            self._text.Text = self.Text
            fitLabel(self)
        end
    end
    SLabel.SetLabel = function(self, str) self:Set(str) return self end
    SLabel.SetText = SLabel.SetLabel

    ----------------------------------------------------------------------------------------------- toggle
    local SToggle = subclass()
    function SToggle.new(sec, o)
        local self = newControl(sec, "Toggle", SToggle)
        self.Value = o.Default == true
        self._label = tostring(o.Label or "")
        self._canNest = true
        self:_defer(function()
            local m = sec._menu
            local v2 = m._v2
            local row = newRow(sec, v2 and 20 or 40)
            self._row, self._el = row, row
            rowLabel(self, row, self._label, v2 and 0 or 60)
            if v2 then self._text.Position = UDim2.fromOffset(22, 0) end
            rowButton(row).Activated:Connect(function()
                local nv = not self.Value
                self.Value = nv
                self:_render(true)
                self:_emit(nv)
            end)
            local track = mk("Frame", { AnchorPoint = v2 and Vector2.new(0, .5) or Vector2.new(1, .5), Position = v2 and UDim2.new(0, 4, .5, 0) or UDim2.new(1, -12, .5, 0),
                Size = v2 and UDim2.fromOffset(13, 13) or UDim2.fromOffset(44, 22), BorderSizePixel = 0, ZIndex = 2 }, row)
            circle(track)
            if v2 then mk("UIStroke", { Thickness = 1, Color = Color3.new(0, 0, 0) }, track) end
            local tg = m:_grad(track)
            local knob = mk("Frame", { AnchorPoint = Vector2.new(0, .5), Size = UDim2.fromOffset(16, 16), BorderSizePixel = 0, ZIndex = 3 }, track)
            circle(knob)
            m:_paint(knob, "BackgroundColor3", "knob")
            knob.Visible = not v2
            function self._render(_, animate)
                local on = self.Value
                local goal = on and m._pal.fill or (v2 and m._pal.track or m._pal.toggleoff)
                if tg then tg.Enabled = on end
                local pos = UDim2.new(0, on and 25 or 3, .5, 0)
                if animate and not v2 then
                    tween(track, .15, { BackgroundColor3 = goal })
                    tween(knob, .15, { Position = pos })
                else
                    track.BackgroundColor3 = goal
                    knob.Position = pos
                end
            end
            m:_onTheme(self, function() self:_render(false) end)
        end)
        if o.OnChanged ~= nil then self:OnChanged(o.OnChanged) end
        return self
    end
    SToggle._instance = rowInstance
    SToggle._isReady = rowReady

    function SToggle:Set(v, silent)
        v = v and true or false
        if silent and v == self.Value then return end
        self.Value = v
        if self._render ~= nil then self:_render(true) end
        self.ValueChanged:Fire(v)
        if not silent then self.Changed:Fire(v) end
    end

    ----------------------------------------------------------------------------------------------- slider
    local function decimals(step)
        if step >= 1 then return 0 end
        return math.min(4, math.ceil(-math.log10(step) - 1e-9))
    end

    local SSlider = subclass()
    function SSlider.new(sec, o)
        local self = newControl(sec, "Slider", SSlider)
        local min, max = o.Min or 0, o.Max or 100
        if max <= min then max = min + 1 end
        self._min, self._max = min, max
        self._step = stepFor(o)
        self._suffix = o.Suffix and tostring(o.Suffix) or ""
        local default = o.Default
        if type(default) ~= "number" then default = min end
        self.Value = default
        self._label = tostring(o.Label or "")
        self:_defer(function()
            local m = sec._menu
            local v2 = m._v2
            local row = newRow(sec, v2 and 32 or 56)
            self._row, self._el = row, row
            local t = text(m, row, self._label, 14, "text", false)
            t.Position = v2 and UDim2.fromOffset(4, 1) or UDim2.fromOffset(14, 8)
            t.Size = v2 and UDim2.new(1, -90, 0, 14) or UDim2.new(1, -110, 0, 18)
            self._text = t
            local val = text(m, row, "", 13, "value", true)
            val.AnchorPoint = Vector2.new(1, 0)
            val.Position = v2 and UDim2.new(1, -4, 0, 1) or UDim2.new(1, -14, 0, 8)
            val.Size = v2 and UDim2.fromOffset(90, 14) or UDim2.fromOffset(90, 18)
            if v2 then val.Font = Enum.Font.Ubuntu val.TextColor3 = m._pal.text end
            val.TextXAlignment = Enum.TextXAlignment.Right
            local track = mk("Frame", { Position = v2 and UDim2.new(0, 4, 0, 18) or UDim2.new(0, 14, 0, 38), Size = v2 and UDim2.new(1, -8, 0, 10) or UDim2.new(1, -28, 0, 5), BorderSizePixel = 0 }, row)
            circle(track)
            if v2 then mk("UIStroke", { Thickness = 1, Color = Color3.new(0, 0, 0) }, track) end
            m:_paint(track, "BackgroundColor3", "track")
            local fill = mk("Frame", { Size = UDim2.fromScale(0, 1), BorderSizePixel = 0 }, track)
            circle(fill)
            m:_paint(fill, "BackgroundColor3", "fill")
            m:_grad(fill)
            local thumb = mk("Frame", { AnchorPoint = Vector2.new(.5, .5), Position = UDim2.fromScale(0, .5), Size = UDim2.fromOffset(14, 14), BorderSizePixel = 0, ZIndex = 2 }, track)
            circle(thumb)
            m:_paint(thumb, "BackgroundColor3", m._lite and "knob" or "acc")
            thumb.Visible = not v2
            local dec = decimals(self._step)
            function self._render()
                local frac = (self.Value - self._min) / (self._max - self._min)
                frac = clamp(frac, 0, 1)
                fill.Size = UDim2.fromScale(frac, 1)
                thumb.Position = UDim2.fromScale(frac, .5)
                val.Text = string.format("%." .. dec .. "f", self.Value) .. self._suffix
            end
            self:_render()
            local hit = mk("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 5 }, row)
            dragArea(hit, function(x)
                local w = track.AbsoluteSize.X
                if w <= 0 then return end
                local frac = clamp((x - track.AbsolutePosition.X) / w, 0, 1)
                local v = self._min + frac * (self._max - self._min)
                v = self._min + math.floor((v - self._min) / self._step + .5) * self._step
                v = tonumber(string.format("%.6f", clamp(v, self._min, self._max)))
                if v ~= self.Value then
                    self.Value = v
                    self:_render()
                    self:_emit(v)
                end
            end)
        end)
        if o.OnChanged ~= nil then self:OnChanged(o.OnChanged) end
        return self
    end
    SSlider._instance = rowInstance
    SSlider._isReady = rowReady

    function SSlider:Set(v, silent)
        if type(v) ~= "number" then return end
        if v < self._min then v = self._min elseif v > self._max then v = self._max end
        if silent and (v == self.Value or self:_echo(silent)) then return end
        self.Value = v
        if self._render ~= nil then self:_render() end
        self.ValueChanged:Fire(v)
        if not silent then self.Changed:Fire(v) end
    end

    ----------------------------------------------------------------------------------------------- button
    local SButton = subclass()
    function SButton.new(sec, o)
        local self = newControl(sec, "Button", SButton)
        self._label = tostring(o.Label or "")
        self._onClick = o.OnClick
        self._confirm = o.Confirm == true
        self._confirming = false
        self.Clicked = Signal.new()
        self:_defer(function()
            local m = sec._menu
            local row = newRow(sec, m._v2 and 24 or 38, (o.Style == 1 and m._lite and not m._v2) and "grad" or true)
            self._row, self._el = row, row
            if m._v2 then
                local st = mk("UIStroke", { Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, row)
                m:_paint(st, "Color", "outline")
                row.MouseEnter:Connect(function() st.Color = m._pal.acc end)
                row.MouseLeave:Connect(function() st.Color = m._pal.outline end)
            end
            local t = text(m, row, self._confirming and K.T("Click again to confirm") or self._label, 14, "value", true)
            t.Size = UDim2.fromScale(1, 1)
            t.TextXAlignment = Enum.TextXAlignment.Center
            t.TextWrapped = true
            self._text = t
            rowButton(row).Activated:Connect(function() self:_click() end)
            if self._disabled then row.BackgroundTransparency = .5 end
        end)
        return self
    end
    SButton._instance = rowInstance
    SButton._isReady = rowReady
    SButton._click = ButtonC._click
    SButton.OnClick = ButtonC.OnClick

    function SButton:_rename(str)
