    ----------------------------------------------------------------------------------------------- text box
    local STextBox = subclass()
    function STextBox.new(sec, o)
        local self = newControl(sec, "TextBox", STextBox)
        self.Value = tostring(o.Default or "")
        self._label = tostring(o.Label or "")
