                Text = self.Value, PlaceholderText = tostring(o.Placeholder or ""), ClearTextOnFocus = false, TextSize = 13,
                Font = Enum.Font.GothamMedium, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 3,
