    ----------------------------------------------------------------------------------------------- popups
    function SMenu:_fontPass() end

    function SMenu:_closePopup()
        local p = self._popup
        if p == nil then return end
        self._popup = nil
        if p.wheel ~= nil then p.wheel:Disconnect() end
        pcall(function() p.catcher:Destroy() end)
        if p.onClose ~= nil then pcall(p.onClose) end
    end

    -- a floating panel next to anchor; build(frame) fills it
    function SMenu:_openPopup(anchor, w, h, build, onClose)
        self:_closePopup()
        local k, g, stage = self._k, self._g, self._stage
        local catcher = mk("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 60 }, stage)
        local ax = (anchor.AbsolutePosition.X - stage.AbsolutePosition.X) / k
        local ay = (anchor.AbsolutePosition.Y - stage.AbsolutePosition.Y) / k
        local aw, ah = anchor.AbsoluteSize.X / k, anchor.AbsoluteSize.Y / k
        local x = clamp(ax + aw - w, 8, math.max(8, g.sw - w - 8))
        local y = ay + ah + 4
        if y + h > g.sh - 8 then y = ay - h - 4 end
        y = clamp(y, 8, math.max(8, g.sh - h - 8))
        local frame = mk("Frame", { Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(w, h), BorderSizePixel = 0, ZIndex = 61, ClipsDescendants = true, Active = true }, catcher)
        corner(frame, 10)
        self:_paint(frame, "BackgroundColor3", self._v2 and "inner" or "panel")
        local st = mk("UIStroke", { Thickness = self._v2 and 1 or 1.5, Transparency = self._v2 and 0 or .3 }, frame)
        self:_paint(st, "Color", "outline")
        catcher.Activated:Connect(function() self:_closePopup() end)
        self._popup = { catcher = catcher, frame = frame, onClose = onClose }
        local ok, err = pcall(build, frame)
        if not ok then log("popup failed: " .. tostring(err)) end
        self:_fontPass(frame)
        -- the mouse wheel did not scroll a long list (a dropdown): it scrolls the list under the pointer by hand
        self._popup.wheel = UIS.InputChanged:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseWheel then return end
            local list = frame:FindFirstChildWhichIsA("ScrollingFrame", true)
            if list == nil then return end
            local at = UIS:GetMouseLocation()
            local pos, size = frame.AbsolutePosition, frame.AbsoluteSize
            if at.X < pos.X or at.X > pos.X + size.X or at.Y < pos.Y or at.Y > pos.Y + size.Y then return end
            local maxY = math.max(0, list.AbsoluteCanvasSize.Y - list.AbsoluteWindowSize.Y)
            list.CanvasPosition = Vector2.new(0, clamp(list.CanvasPosition.Y - input.Position.Z * 40, 0, maxY))
        end)
        return frame
    end

    ----------------------------------------------------------------------------------------------- dropdown
    local SDropdown = subclass()
    for _, name in ipairs({ "_display", "_displayList", "_current", "_fromDisplay", "_fromSelection", "SetOptions", "Add", "Remove", "GetNames", "Set" }) do
        SDropdown[name] = DropdownC[name]
    end

    function SDropdown.new(sec, o, multi)
        local self = newControl(sec, multi and "MultiDropdown" or "Dropdown", SDropdown)
        self.Multi = multi == true
        self._labels = o.Labels
        local options = {}
        for i, opt in ipairs(o.Options or {}) do options[i] = tostring(opt) end
        self.Options = options
        if self.Multi then
            self.Value = toSet(o.Default, options)
        else
            local d = o.Default
            if not (type(d) == "string" and table.find(options, d)) then
                d = nil
                if o.SelectFirst ~= false then d = options[1] end
            end
            self.Value = d
        end
        self._label = tostring(o.Label or "")
        self:_defer(function()
            local m = sec._menu
            local row = newRow(sec, m._v2 and 24 or 40)
            self._row, self._el = row, row
            rowLabel(self, row, self._label, m._ctlW.dd + 10)
            if m._v2 then self._text.Position = UDim2.fromOffset(4, 0) end
            local btn = mk("TextButton", {
                AnchorPoint = Vector2.new(1, .5), Position = UDim2.new(1, -10, .5, 0), Size = UDim2.fromOffset(m._ctlW.dd, m._v2 and 18 or 28), BorderSizePixel = 0,
                Text = "", AutoButtonColor = false, ZIndex = 3,
            }, row)
            corner(btn, 6)
            m:_paint(btn, "BackgroundColor3", m._v2 and "inner" or "track")
            if m._v2 then
                local cap = self._label ~= ""
                row.Size = UDim2.new(1, -8, 0, cap and 40 or 24)
                self._text.Visible = cap
                self._text.Size = UDim2.new(1, -8, 0, 16)
                self._text.Position = UDim2.fromOffset(4, 0)
                btn.AnchorPoint = Vector2.new(0, 0)
                btn.Position = UDim2.new(0, 4, 0, cap and 20 or 3)
                btn.Size = UDim2.new(1, -8, 0, 18)
            end
            if m._v2 then
                local st = mk("UIStroke", { Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, btn)
                m:_paint(st, "Color", "outline")
                btn.MouseEnter:Connect(function() st.Color = m._pal.acc end)
                btn.MouseLeave:Connect(function() st.Color = m._pal.outline end)
            end
            local val = text(m, btn, "", 13, m._v2 and "text" or "value", false)
            val.Position = UDim2.fromOffset(8, 0)
            val.Size = UDim2.new(1, -26, 1, 0)
            val.TextTruncate = Enum.TextTruncate.AtEnd
            local chev = text(m, btn, m._v2 and "+" or "v", m._v2 and 14 or 11, m._v2 and "text" or "faint", true)
            chev.AnchorPoint = Vector2.new(1, .5)
            chev.Position = UDim2.new(1, -8, .5, 0)
            chev.Size = UDim2.fromOffset(10, 14)
            self._btn, self._val = btn, val
            self:_push()
            btn.Activated:Connect(function() self:_openList(btn) end)
        end)
        if o.OnChanged ~= nil then self:OnChanged(o.OnChanged) end
        return self
    end
    SDropdown._instance = rowInstance
    SDropdown._isReady = rowReady

    function SDropdown:_push()
        if self._val == nil then return end
        local cur = self:_current()
        self._val.Text = #cur > 0 and table.concat(cur, ", ") or "None"
        if self._redraw ~= nil then self._redraw() end
    end

    function SDropdown:SetLabel(str)
        self._label = tostring(str or "")
        if self._text then self._text.Text = self._label end
        return self
    end

    function SDropdown:_openList(anchor)
        local m = self._menu
        local count = #self.Options
        local h = clamp(count * (m._v2 and 22 or 32) + 10, m._v2 and 34 or 52, 290)
        m:_openPopup(anchor, math.max(anchor.AbsoluteSize.X / m._k, 170), h, function(frame)
            local sc = mk("ScrollingFrame", {
                Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3,
                CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ZIndex = 62,
            }, frame)
            m:_paint(sc, "ScrollBarImageColor3", "acc")
            mk("UIListLayout", { Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder }, sc)
            mk("UIPadding", { PaddingTop = UDim.new(0, 5), PaddingBottom = UDim.new(0, 5), PaddingLeft = UDim.new(0, 5), PaddingRight = UDim.new(0, 5) }, sc)
            local items = {}
            local function redraw()
                for opt, item in pairs(items) do
                    local on
                    if self.Multi then on = self.Value[opt] == true else on = self.Value == opt end
                    item.dot.Visible = on
                    item.btn.BackgroundTransparency = on and .75 or 1
                    item.label.TextColor3 = on and m._pal.text or m._pal.dim
                end
            end
            self._redraw = redraw
            for i, opt in ipairs(self.Options) do
                local btn = mk("TextButton", { Size = UDim2.new(1, 0, 0, m._v2 and 20 or 30), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, LayoutOrder = i, ZIndex = 63 }, sc)
                corner(btn, 6)
                m:_paint(btn, "BackgroundColor3", "acc")
                local lbl = text(m, btn, self:_display(opt), 13, "dim", false)
                lbl.Position = UDim2.fromOffset(10, 0)
                lbl.Size = UDim2.new(1, -30, 1, 0)
                lbl.ZIndex = 64
                local dot = mk("Frame", { AnchorPoint = Vector2.new(1, .5), Position = UDim2.new(1, -10, .5, 0), Size = UDim2.fromOffset(8, 8), BorderSizePixel = 0, ZIndex = 64 }, btn)
                circle(dot)
                m:_paint(dot, "BackgroundColor3", "acc")
                items[opt] = { btn = btn, label = lbl, dot = dot }
                btn.Activated:Connect(function()
                    if self.Multi then
                        local set = {}
                        for k2, v2 in pairs(self.Value) do set[k2] = v2 end
                        if set[opt] then set[opt] = nil else set[opt] = true end
                        self:_emit(set)
                        self:_push()
                    else
                        if opt ~= self.Value then
                            self:_emit(opt)
                            self:_push()
                        end
                        m:_closePopup()
                    end
                end)
            end
            redraw()
        end, function() self._redraw = nil end)
    end

    ----------------------------------------------------------------------------------------------- colour
    local function hostFor2(sec, o)
        local row = o.Row
        if row ~= nil and rawget(row, "_canNest") then return row, false end
        return SLabel.new(sec, { Label = o.Label }), true
    end

    local SColor = subclass()
    function SColor.new(sec, o)
        local self = newControl(sec, "Color", SColor)
        local host, own = hostFor2(sec, o)
        self._host = host
        if own then self._followers = { host } end
        self.Value = colorValue(o.Default)
        self:_defer(function()
            if not host._realized then host:_realizeNow() end
            if host._row == nil then return end
            local v2 = sec._menu._v2
            local btn = mk("TextButton", { Size = v2 and UDim2.fromOffset(40, 13) or UDim2.fromOffset(34, 20), BorderSizePixel = 0, Text = "", AutoButtonColor = false, ZIndex = 4, BackgroundColor3 = self.Value.Rgb }, nil)
            corner(btn, 5)
            local st = mk("UIStroke", { Thickness = 1, Transparency = v2 and 0 or .5 }, btn)
            if v2 then st.Color = Color3.new(0, 0, 0) else sec._menu:_paint(st, "Color", "text") end
            attach(host, btn, v2 and 40 or 34)
            self._btn, self._el = btn, btn
            btn.Activated:Connect(function() self:_openPicker(btn) end)
        end)
        if o.OnChanged ~= nil then self:OnChanged(o.OnChanged) end
        return self
    end
    SColor._isReady = function(self) return self._btn ~= nil end
    SColor._instance = function(self) return self._btn end

    function SColor:_openPicker(anchor)
        local m = self._menu
        local h, s, v = Color3.toHSV(self.Value.Rgb)
        local alpha = self.Value.Alpha
        local function current() return Color3.fromHSV(h, s, v) end
        m:_openPopup(anchor, 232, 286, function(frame)
            local sv = mk("Frame", { Position = UDim2.fromOffset(12, 12), Size = UDim2.fromOffset(208, 130), BorderSizePixel = 0, ZIndex = 62 }, frame)
            corner(sv, 6)
            local white = mk("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 63 }, sv)
            corner(white, 6)
            mk("UIGradient", { Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) }) }, white)
            local black = mk("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BorderSizePixel = 0, ZIndex = 64 }, sv)
            corner(black, 6)
            mk("UIGradient", { Rotation = 90, Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) }) }, black)
            local svCursor = mk("Frame", { AnchorPoint = Vector2.new(.5, .5), Size = UDim2.fromOffset(12, 12), BackgroundTransparency = 1, ZIndex = 66 }, sv)
            circle(svCursor)
            mk("UIStroke", { Thickness = 2, Color = Color3.new(1, 1, 1) }, svCursor)

            local hue = mk("Frame", { Position = UDim2.fromOffset(12, 152), Size = UDim2.fromOffset(208, 14), BorderSizePixel = 0, BackgroundColor3 = Color3.new(1, 1, 1), ZIndex = 62 }, frame)
            corner(hue, 7)
            mk("UIGradient", { Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromHSV(0, 1, 1)), ColorSequenceKeypoint.new(1 / 6, Color3.fromHSV(1 / 6, 1, 1)),
                ColorSequenceKeypoint.new(2 / 6, Color3.fromHSV(2 / 6, 1, 1)), ColorSequenceKeypoint.new(3 / 6, Color3.fromHSV(3 / 6, 1, 1)),
                ColorSequenceKeypoint.new(4 / 6, Color3.fromHSV(4 / 6, 1, 1)), ColorSequenceKeypoint.new(5 / 6, Color3.fromHSV(5 / 6, 1, 1)),
                ColorSequenceKeypoint.new(1, Color3.fromHSV(1, 1, 1)) }) }, hue)
            local hueCursor = mk("Frame", { AnchorPoint = Vector2.new(.5, .5), Position = UDim2.fromScale(0, .5), Size = UDim2.fromOffset(8, 18), BorderSizePixel = 0, ZIndex = 64, BackgroundColor3 = Color3.new(1, 1, 1) }, hue)
            corner(hueCursor, 3)

            local alp = mk("Frame", { Position = UDim2.fromOffset(12, 176), Size = UDim2.fromOffset(208, 14), BorderSizePixel = 0, ZIndex = 62 }, frame)
            corner(alp, 7)
            m:_paint(alp, "BackgroundColor3", "track")
            local alpFill = mk("Frame", { Size = UDim2.fromScale(1, 1), BorderSizePixel = 0, ZIndex = 63 }, alp)
            corner(alpFill, 7)
            mk("UIGradient", { Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) }) }, alpFill)
            local alpCursor = mk("Frame", { AnchorPoint = Vector2.new(.5, .5), Position = UDim2.fromScale(0, .5), Size = UDim2.fromOffset(8, 18), BorderSizePixel = 0, ZIndex = 64, BackgroundColor3 = Color3.new(1, 1, 1) }, alp)
            corner(alpCursor, 3)

            local hex = mk("TextBox", { Position = UDim2.fromOffset(12, 202), Size = UDim2.fromOffset(120, 28), BorderSizePixel = 0, ClearTextOnFocus = false, TextSize = 13,
                Font = Enum.Font.GothamMedium, ZIndex = 62, Text = "" }, frame)
            corner(hex, 6)
            m:_paint(hex, "BackgroundColor3", "track")
            m:_paint(hex, "TextColor3", "text")
            local preview = mk("Frame", { Position = UDim2.fromOffset(142, 202), Size = UDim2.fromOffset(78, 28), BorderSizePixel = 0, ZIndex = 62 }, frame)
            corner(preview, 6)
            local ok = mk("TextButton", { Position = UDim2.fromOffset(12, 240), Size = UDim2.fromOffset(208, 34), BorderSizePixel = 0, Text = K.T("Done"), TextSize = 14,
                Font = Enum.Font.GothamBold, AutoButtonColor = false, ZIndex = 62 }, frame)
            corner(ok, 8)
            m:_paint(ok, "BackgroundColor3", "inner")
            m:_paint(ok, "TextColor3", "value")
            ok.Activated:Connect(function() m:_closePopup() end)

            local function refresh(emit)
                local c = current()
                sv.BackgroundColor3 = Color3.fromHSV(h, 1, 1)
                svCursor.Position = UDim2.fromScale(s, 1 - v)
                hueCursor.Position = UDim2.fromScale(h, .5)
                alpCursor.Position = UDim2.fromScale(alpha, .5)
                alpFill.BackgroundColor3 = c
                preview.BackgroundColor3 = c
                hex.Text = "#" .. c:ToHex():upper()
                if self._btn then self._btn.BackgroundColor3 = c end
                if emit then
                    self.Value = { Rgb = c, Alpha = alpha, Stops = {} }
                    self:_emit(self.Value)
                end
            end
            refresh(false)
            local function overlay(target)
                return mk("TextButton", { Size = UDim2.new(1, 0, 1, 12), Position = UDim2.fromOffset(0, -6), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 70 }, target)
            end
            dragArea(overlay(sv), function(x, y)
                s = clamp((x - sv.AbsolutePosition.X) / math.max(1, sv.AbsoluteSize.X), 0, 1)
                v = 1 - clamp((y - sv.AbsolutePosition.Y) / math.max(1, sv.AbsoluteSize.Y), 0, 1)
                refresh(true)
            end)
            dragArea(overlay(hue), function(x)
                h = clamp((x - hue.AbsolutePosition.X) / math.max(1, hue.AbsoluteSize.X), 0, .999)
                refresh(true)
            end)
            dragArea(overlay(alp), function(x)
                alpha = clamp((x - alp.AbsolutePosition.X) / math.max(1, alp.AbsoluteSize.X), 0, 1)
                refresh(true)
            end)
            hex.FocusLost:Connect(function()
                local okc, c = pcall(Color3.fromHex, hex.Text)
                if okc and typeof(c) == "Color3" then
                    h, s, v = Color3.toHSV(c)
                end
                refresh(true)
            end)
        end)
    end

    function SColor:Set(v, silent)
        local nv = colorValue(v)
        if silent and ((nv.Rgb == self.Value.Rgb and nv.Alpha == self.Value.Alpha) or self:_echo(silent)) then return end
        self.Value = nv
        if self._btn then self._btn.BackgroundColor3 = nv.Rgb end
        self.ValueChanged:Fire(self.Value)
        if not silent then self.Changed:Fire(self.Value) end
    end
    function SColor:EnableAnimation() end
    function SColor:SetAnimationMode() end
    function SColor:SetAnimationSpeed() end
    function SColor:SetAnimationBreathingRange() end
    SColor.AnimationChanged = ColorC.AnimationChanged
    SColor.AnimationSpeedChanged = ColorC.AnimationSpeedChanged
    SColor.AnimationBreathingRangeChanged = ColorC.AnimationBreathingRangeChanged

    ----------------------------------------------------------------------------------------------- keybind
    local SKeybind = subclass()
    for _, name in ipairs({ "SetKey", "SetMode", "SetShowInList", "SetInvisible", "SetActive", "SetFeatureEnabled", "_BindConfigMap" }) do
        SKeybind[name] = KeybindC[name]
    end

    function SKeybind.new(sec, o)
        local self = newControl(sec, "Keybind", SKeybind)
        local host, own = hostFor2(sec, o)
        self._host = host
        local hostLabel = tostring(o.Label or host._label or "Keybind")
        if own then self._followers = { host } end
        local modes = {}
        for _, mo in ipairs(o.Modes or {}) do modes[#modes + 1] = tostring(mo) end
        self.Modes = modes
        self.Value = { Key = nil, Mode = modes[1] or "Toggle" }
        self.ShowInList = true
        self.Invisible = false
        self.ShowInListChanged = Signal.new()
        self.InvisibleChanged = Signal.new()
        self.ActiveChanged = Signal.new()
        self:_attachListEntry(sec, o, host)
        self:_defer(function()
            if not host._realized then host:_realizeNow() end
            if host._row == nil then return end
            local m = sec._menu
            local v2 = m._v2
            local btn = mk("TextButton", { Size = UDim2.fromOffset(0, v2 and 14 or 22), AutomaticSize = Enum.AutomaticSize.X, BorderSizePixel = 0, Text = "", AutoButtonColor = false, ZIndex = 4 }, nil)
            corner(btn, 5)
            m:_paint(btn, "BackgroundColor3", v2 and "inner" or "track")
            if v2 then
                local st = mk("UIStroke", { Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, btn)
                m:_paint(st, "Color", "outline")
            end
            mk("UISizeConstraint", { MinSize = Vector2.new(v2 and 30 or 48, v2 and 14 or 22) }, btn)
            mk("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }, btn)
            local lbl = text(m, btn, "", 12, "value", true)
            lbl.Size = UDim2.fromScale(0, 1)
            lbl.AutomaticSize = Enum.AutomaticSize.X
            lbl.TextXAlignment = Enum.TextXAlignment.Center
            self._lbl = lbl
            attach(host, btn, 56)
            self._btn, self._el = btn, btn
            self:_showKey()
            btn.Activated:Connect(function() self:_capture() end)
        end)
        if #modes > 1 then
            self._modeDropdown = sec:_make("Dropdown", {
                Label = hostLabel .. " Mode",
                Options = modes,
                Default = self.Value.Mode,
                OnChanged = function(mode)
                    if self:_suppressed() or mode == nil then return end
                    self:_emit({ Key = self.Value.Key, Mode = mode })
                end,
            })
            self._followers[#self._followers + 1] = self._modeDropdown
        end
        return self
    end
    SKeybind._isReady = function(self) return self._btn ~= nil end
    SKeybind._instance = function(self) return self._btn end

    function SKeybind:_showKey()
        if self._lbl == nil then return end
        if self._capturing then self._lbl.Text = "..." return end
        local t = keyToText(self.Value.Key)
        self._lbl.Text = t == "No Bind" and "None" or t
    end

    function SKeybind:_capture()
        if self._capturing then return end
        self._capturing = true
        self:_showKey()
        local conn
        conn = UIS.InputBegan:Connect(function(input)
            local key
            if input.UserInputType == Enum.UserInputType.Keyboard then
                if input.KeyCode == Enum.KeyCode.Escape then
                    key = false -- cancel
                elseif input.KeyCode == Enum.KeyCode.Backspace or input.KeyCode == Enum.KeyCode.Delete then
                    key = nil -- clear
                else
                    key = input.KeyCode
                end
            elseif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.MouseButton2
                or input.UserInputType == Enum.UserInputType.MouseButton3 then
                key = input.UserInputType
            else
                return
            end
            conn:Disconnect()
            self._capturing = false
            if key ~= false then
                self.Value = { Key = key, Mode = self.Value.Mode }
                self:_emit(self.Value)
            end
            self:_showKey()
        end)
    end

    function SKeybind:Set(v, silent)
        if type(v) ~= "table" then return end
        local key = v.Key
        if typeof(key) ~= "EnumItem" then key = nil end
        local mode = v.Mode
        if type(mode) ~= "string" or (#self.Modes > 0 and not table.find(self.Modes, mode)) then mode = self.Value.Mode end
        if silent and key == self.Value.Key and mode == self.Value.Mode then return end
        self.Value = { Key = key, Mode = mode }
        self:_showKey()
        if self._modeDropdown ~= nil then self._modeDropdown:Set(mode, true) end
        self.ValueChanged:Fire(self.Value)
        if not silent then self.Changed:Fire(self.Value) end
    end

    ----------------------------------------------------------------------------------------------- makers and sections
    local SMakers = {}
    SMakers.Toggle = function(sec, o) return SToggle.new(sec, o) end
    SMakers.Slider = function(sec, o) return SSlider.new(sec, o) end
    SMakers.RangeSlider = function(sec, o) return RangeC.new(sec, o) end
    SMakers.Button = function(sec, o) return SButton.new(sec, o) end
    SMakers.Label = function(sec, o) return SLabel.new(sec, o) end
    SMakers.Divider = function(sec, o) return SDivider.new(sec, o) end
    SMakers.TextBox = function(sec, o) return STextBox.new(sec, o) end
    SMakers.Dropdown = function(sec, o) return SDropdown.new(sec, o, false) end
    SMakers.MultiDropdown = function(sec, o) return SDropdown.new(sec, o, true) end
    SMakers.List = SMakers.Dropdown
    SMakers.MultiList = SMakers.MultiDropdown
    SMakers.Color = function(sec, o) return SColor.new(sec, o) end
    SMakers.Keybind = function(sec, o) return SKeybind.new(sec, o) end
    SMakers.OrderedList = function(sec, o) return OrderedC.new(sec, o) end
    -- The picker of skins, wraps, charms and finishers for the Setsuna, Setsuna Drop and Lite forms: a card grid with
    -- the item pictures (and the 3D previews of wraps and charms), the same surface as the classic menu's widget
    -- (SetItems / SetState / SetFilter / SetClearFilterAction / Set / Value / OnChanged).
    do
        local SSkin = subclass()
        local STATE_TEXT = {
            Loading = { "Loading catalog", "The previews are being prepared." },
            Unavailable = { "Unavailable", "The catalog could not be loaded." },
            Empty = { "No items available", "This catalog does not have any items yet." },
            NoMatches = { "No matches", "Nothing matches the search." },
        }
        local function indexOf(items, name)
            for i, it in ipairs(items) do
                if it.Name == name then return i end
            end
            return nil
        end

        function SSkin.new(sec, o)
            local self = newControl(sec, "SkinChanger", SSkin)
            self.Items = o.Items or {}
            self._published = o.Items ~= nil
            self.State = o.State or "Ready"
            self._stateMsg = o.StateMessage
            self._onClear = o.OnClearFilter
            self._entries = {}
            self._token = 0
            self._label = "SkinChanger"
            if o.OnChanged ~= nil then self:OnChanged(o.OnChanged) end
            self:_defer(function() self:_build() end)
            return self
        end
        SSkin._instance = rowInstance
        SSkin._isReady = rowReady

        function SSkin:_paint(entry, selected)
            if entry == nil then return end
            entry.Selected = selected
            local pal = self._menu._pal
            entry.Button.BackgroundColor3 = selected and pal.hover or pal.panel
            entry.Title.TextColor3 = selected and pal.text or pal.dim
            entry.Stroke.Color = pal.sel
            entry.Stroke.Enabled = selected
        end

        function SSkin:_recolor()
            for _, e in ipairs(self._entries) do self:_paint(e, e.Selected == true) end
        end

        function SSkin:_applyFilter()
            local filter = self._filter
            for _, e in ipairs(self._entries) do
                local show = filter == nil or filter(e.Item, e.Key)
                if e.Button.Visible ~= show then e.Button.Visible = show end
            end
        end

        function SSkin:_applyState()
            if self._row == nil then return end
            local ready = self.State == "Ready"
            self._holder.Visible = ready
            self._overlay.Visible = not ready
            local info = STATE_TEXT[self.State] or { "", "" }
            self._stTitle.Text = K.T(info[1])
            self._stMsg.Text = K.T(self._stateMsg or info[2])
            self._clear.Visible = self.State == "NoMatches" and self._onClear ~= nil
        end

        function SSkin:_cards()
            self._token = self._token + 1
            local token = self._token
            for _, e in ipairs(self._entries) do pcall(function() e.Button:Destroy() end) end
            self._entries = {}
            self._sel = nil
            local items = self.Items
            task.spawn(function()
                for i, item in ipairs(items) do
                    if self._token ~= token or self._dead then return end
                    local button = mk("TextButton", {
                        Name = tostring(item.Name), Text = "", AutoButtonColor = false, BorderSizePixel = 0,
                        LayoutOrder = i, ClipsDescendants = true,
                    })
                    corner(button, 8)
                    local stroke = mk("UIStroke", { Thickness = 2, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Enabled = false }, button)
                    local preview = mk("Frame", {
                        BackgroundTransparency = 1, Size = UDim2.new(1, -10, 1, -32), Position = UDim2.fromOffset(5, 5),
                    }, button)
                    local image = mk("ImageLabel", {
                        BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ScaleType = Enum.ScaleType.Fit,
                        Image = item.Image or "rbxassetid://89204837120267",
                    }, preview)
                    local title = mk("TextLabel", {
                        BackgroundTransparency = 1, Size = UDim2.new(1, -8, 0, 24), Position = UDim2.new(0, 4, 1, -27),
                        Font = Enum.Font.GothamMedium, TextSize = 12, Text = tostring(item.Name),
                        TextTruncate = Enum.TextTruncate.AtEnd, TextWrapped = true,
                    }, button)
                    local entry = { Item = item, Button = button, Title = title, Stroke = stroke, Key = tostring(item.Name):lower() }
                    self._entries[#self._entries + 1] = entry
                    self:_paint(entry, item.Name == self.Value)
                    if item.Name == self.Value then self._sel = entry end
                    if item.Render ~= nil then
                        local content = mk("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1) }, preview)
                        local ok, err = pcall(item.Render, item, {
                            Content = content,
                            HideImage = function() image.Visible = false end,
                        })
                        if not ok then log("skin preview failed: " .. tostring(err)) end
                    end
                    button.Activated:Connect(function() self:Set(item.Name) end)
                    local filter = self._filter
                    if filter ~= nil and not filter(item, entry.Key) then button.Visible = false end
                    button.Parent = self._holder
                    if i % 8 == 0 then task.wait() end
                end
                -- Lite sets the font of a page when it opens: the cards came later
                local m = self._menu
                if m._fontPass ~= nil and self._row ~= nil then pcall(m._fontPass, m, self._row) end
            end)
        end

        function SSkin:_build()
            local sec = self._sec
            local m = sec._menu
            local row = newRow(sec, 340, true)
            self._row, self._el = row, row
            local holder = mk("ScrollingFrame", {
                Name = "Cards", BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, -10, 1, -10),
                Position = UDim2.fromOffset(5, 5), ScrollBarThickness = 3, CanvasSize = UDim2.new(),
                AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y,
            }, row)
            mk("UIGridLayout", {
                CellSize = UDim2.fromOffset(100, 118), CellPadding = UDim2.fromOffset(6, 6),
                SortOrder = Enum.SortOrder.LayoutOrder, HorizontalAlignment = Enum.HorizontalAlignment.Center,
            }, holder)
            local overlay = mk("Frame", { Name = "State", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Visible = false }, row)
            mk("UIListLayout", {
                HorizontalAlignment = Enum.HorizontalAlignment.Center, VerticalAlignment = Enum.VerticalAlignment.Center,
                Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder,
            }, overlay)
            local stTitle = text(m, overlay, "", 16, "text", true)
            stTitle.Size, stTitle.LayoutOrder, stTitle.TextXAlignment = UDim2.new(1, -20, 0, 22), 1, Enum.TextXAlignment.Center
            local stMsg = text(m, overlay, "", 13, "dim", false)
            stMsg.Size, stMsg.LayoutOrder, stMsg.TextXAlignment, stMsg.TextWrapped = UDim2.new(1, -20, 0, 36), 2, Enum.TextXAlignment.Center, true
            local clear = mk("TextButton", {
                Size = UDim2.fromOffset(120, 30), Text = K.T("Clear search"), Font = Enum.Font.GothamMedium, TextSize = 13,
                BorderSizePixel = 0, AutoButtonColor = true, Visible = false, LayoutOrder = 3,
            }, overlay)
            corner(clear, 8)
            m:_paint(clear, "BackgroundColor3", "hover")
            m:_paint(clear, "TextColor3", "text")
            clear.Activated:Connect(function()
                local fn = self._onClear
                if fn ~= nil then fn() end
            end)
            self._holder, self._overlay, self._stTitle, self._stMsg, self._clear = holder, overlay, stTitle, stMsg, clear
            if m._fontPass ~= nil then pcall(m._fontPass, m, row) end
            m:_onTheme(self, function() self:_recolor() end)
            self:_cards()
            self:_applyState()
        end

        function SSkin:Set(name, silent)
            local v = name
            if v ~= nil and self._published and indexOf(self.Items, v) == nil then v = nil end
            local entry
            for _, e in ipairs(self._entries) do
                if e.Item.Name == v then entry = e break end
            end
            if self.Value == v and (entry == nil or self._sel == entry) and not (name ~= nil and v == nil) then return end
            self.Value = v
            if self._sel ~= nil and self._sel ~= entry then self:_paint(self._sel, false) end
            self._sel = entry
            if entry ~= nil then self:_paint(entry, true) end
            self.ValueChanged:Fire(v)
            if not silent then self.Changed:Fire(v) end
        end

        function SSkin:SetItems(items, silent)
            self.Items = table.clone(items)
            self._published = true
            local value, emit = self.Value, false
            if value == nil or indexOf(self.Items, value) == nil then
                value = self.Items[1] and self.Items[1].Name or nil
                emit = self.Value ~= nil
            end
            self.Value = value
            if self._row ~= nil then self:_cards() end
            self.ValueChanged:Fire(value)
            if emit and not silent then self.Changed:Fire(value) end
        end

        function SSkin:SetFilter(filter)
            self._filter = filter
            if self._row ~= nil then self:_applyFilter() end
            return self
        end

        function SSkin:SetState(state, message)
            self.State = state
            self._stateMsg = message
            self:_applyState()
            return self
        end

        function SSkin:SetClearFilterAction(fn)
            self._onClear = fn
            self:_applyState()
            return self
        end

        function SSkin:Destroy()
            self._token = self._token + 1
            self._dead = true
            pcall(function() self._row:Destroy() end)
        end

        SMakers.SkinChanger = function(sec, o) return SSkin.new(sec, o or {}) end
    end
    SMakers.Stub = function() return stub end

    function SSection:_make(kind, o)
        local maker = SMakers[kind]
        if maker == nil then return stub end
        local c = maker(self, o)
        if type(c) == "table" and getmetatable(c) ~= Stub then
            self._ctls[#self._ctls + 1] = c
            if self._secVis == false then
                c._gv[self] = false
                c:_applyVis()
            end
        end
        local ok, err = pcall(bindToConfig, self._menu, kind, c, o)
        if not ok then log(kind .. " '" .. tostring(o.Label) .. "' could not be linked to its setting: " .. tostring(err)) end
        return c
    end

    function SSection:SetVisible(v)
        self._secVis = v ~= false
        if self._header ~= nil then self._header.Visible = self._secVis end
        -- the Lite card of a hidden section goes too (an empty card was left behind as a thin bar)
        if self._cardFrame ~= nil then self._cardFrame.Visible = self._secVis end
        for _, c in ipairs(self._ctls) do
            c._gv[self] = self._secVis
            c:_applyVis()
        end
    end

    function SSection:_realize()
        if self._realized then return end
        self._realized = true
        local m = self._menu
        local scroll = m:_sectionHost(self)
        self._card = scroll
        if m._lite then
            self._cardFrame = scroll
            if self._secVis == false then scroll.Visible = false end
        end
        if self._title ~= "" then
            local head = mk("Frame", { Size = UDim2.new(1, -8, 0, 28), BackgroundTransparency = 1, LayoutOrder = self._order * 1000 }, scroll)
            local t = text(m, head, m._lite and self._title or string.upper(self._title), m._lite and 13 or 12, m._lite and "text" or "value", true)
            t.Position = UDim2.fromOffset(6, 6)
            t.Size = UDim2.new(1, -12, 0, 18)
            local line = mk("Frame", { AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 6, 1, 0), Size = UDim2.new(1, -12, 0, 1), BorderSizePixel = 0, BackgroundTransparency = .55 }, head)
            m:_paint(line, "BackgroundColor3", "line")
            if m._lite then line.Visible = false end
            if m._v2 then
                local bar = mk("Frame", { Position = UDim2.fromOffset(0, 0), Size = UDim2.new(1, 0, 0, 2), BorderSizePixel = 0 }, head)
                m:_paint(bar, "BackgroundColor3", "acc")
                t.Position = UDim2.fromOffset(4, 4)
                t.Font = Enum.Font.Ubuntu
            end
            self._header = head
            if self._secVis == false then head.Visible = false end
        end
        local pending = self._pending
        self._pending = {}
        for _, c in ipairs(pending) do
            c:_realizeNow()
        end
    end

    local function newSSection(page, o)
        o = o or {}
        local title = o.Title
        if title == nil then title = "" end
        title = tostring(title)
        if string.match(title, "^%s*$") then title = "" end
        page._secCount += 1
        local sec = setmetatable({ _menu = page._menu, _page = page, _realized = false, _pending = {}, _order = page._secCount, _n = 0, _title = title, _ctls = {}, _side = o.Side }, SSection)
        sec._sec = sec
        if page._realized then
            sec:_realize()
        else
            page._sections[#page._sections + 1] = sec
        end
        return sec
    end

    local SGrid = {}
    SGrid.__index = SGrid
    function SGrid:AddSection(o)
        if self._inert then return stub end
        local ok, res = pcall(newSSection, self._page, o)
        if ok then return res end
        log("AddSection failed: " .. tostring(res))
        return stub
    end
    local function sMultiSection(page, o)
        o = o or {}
        local panes = {}
        for i, title in ipairs(o.Titles or {}) do
            local ok, res = pcall(newSSection, page, { Title = title, Side = o.Side })
            panes[i] = ok and res or stub
            if not ok then log("AddMultiSection failed: " .. tostring(res)) end
        end
        return table.unpack(panes)
    end
    function SGrid:AddMultiSection(o)
        if self._inert then return stub, stub end
        return sMultiSection(self._page, o)
    end
    function SSection:AddMultiSection(o) return sMultiSection(self._page, o) end
    function SGrid:SetVisible() end

    --------------------------------------------------------------------------------------------------- pages and tabs
    local SPage = {}
    SPage.__index = function(t, k)
        local v = rawget(SPage, k)
        if v ~= nil then return v end
        if isMethodName(k) then return function() return nil end end
        return nil
    end

    function SPage:_ensureScroll()
        if self._scroll ~= nil then return self._scroll end
        self._scroll = self._menu:_makeHost(self)
        return self._scroll
    end

    -- Pop: the page's settings are a scrolling list in the settings panel
    function SMenu:_makeHost(page)
        local sc = mk("ScrollingFrame", {
            Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3,
            CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y, Visible = false,
        }, self._setBody)
        self:_paint(sc, "ScrollBarImageColor3", "acc")
        mk("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder, HorizontalAlignment = Enum.HorizontalAlignment.Center }, sc)
        mk("UIPadding", { PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 12), PaddingLeft = UDim.new(0, 4), PaddingRight = UDim.new(0, 4) }, sc)
        return sc
    end

    function SPage:_realize()
        if self._realized then return end
        self._realized = true
        self:_ensureScroll()
        local t0 = os.clock()
        if K.UIMark then K.UIMark("building page '" .. tostring(self.Label) .. "'") end
        if self._liteTheme then
            local ok, err = pcall(self._menu._buildThemePage, self._menu, self)
            if not ok then log("theme page failed: " .. tostring(err)) end
        end
        local sections = self._sections
        self._sections = {}
        for _, sec in ipairs(sections) do
            local ok, err = pcall(sec._realize, sec)
            if not ok then log("a section of '" .. tostring(self.Label) .. "' failed to build: " .. tostring(err)) end
        end
        log(string.format("page '%s' built on first open in %.2f s", tostring(self.Label), os.clock() - t0))
        if K.UIMark then K.UIMark("built page '" .. tostring(self.Label) .. "'") end
    end

    function SPage:Grid(o)
        if not self._liteTheme then self._columns = (o and o.Columns) or self._columns or 2 end
        -- the Lite theme page ignores what the settings builder adds to it
        return setmetatable({ _page = self, _inert = self._liteTheme == true }, SGrid)
    end

    -- where a section's rows go: the page's own list (the Lite form puts them in a card in one of two columns)
    function SMenu:_sectionHost(sec)
        return sec._page:_ensureScroll()
    end

    function SPage:OnFirstOpen(fn)
        if type(fn) ~= "function" then return end
        task.defer(function()
            local ok, err = pcall(fn)
            if not ok then log("page '" .. tostring(self.Label) .. "' failed to build: " .. tostring(err)) end
        end)
    end

    function SPage:Open() end
    function SPage:SetVisible() end

    local STab = {}
    STab.__index = function(t, k)
        local v = rawget(STab, k)
        if v ~= nil then return v end
        if isMethodName(k) then return function() return nil end end
        return nil
    end

    function STab:AddTab(o)
        o = o or {}
        local page = setmetatable({
            _menu = self._menu, _tab = self,
            Label = tostring(o.Label or "Page"),
            Icon = o.Icon or false,
            Description = o.Description or false,
            _sections = {}, _realized = false, _secCount = 0,
        }, SPage)
        -- Lite builds Starlight's own Theme page (its theme, its colours, its theme files), not the script's token list
        if self._isSettings and (o._enLabel or page.Label) == "Theme" and self._menu._lite then
            page._liteTheme = true
            page._columns = 1
        end
        self._pages[#self._pages + 1] = page
        self._menu:_makePageRow(self, page)
        return page
    end

    -- a top-level tab used without sub tabs behaves as one page
    function STab:Grid(o)
        if self._single == nil then
            self._single = self:AddTab({ Label = self.Label, Icon = self.Icon })
        end
        return self._single:Grid(o)
    end

    --------------------------------------------------------------------------------------------------- dialogs
    local function sBuildDialog(menu, o, builder)
        local key = tostring(o.Title or "Dialog")
        local existing = menu._dialogs[key]
        if existing ~= nil then
            for _, p in ipairs(existing.pages) do
                if p.onOpen ~= nil then pcall(p.onOpen) end
            end
            return existing
        end
        if menu._manage == nil then
            menu._manage = menu:AddTab({ Label = "Manage" })
        end
        local page = menu._manage:AddTab({ Label = key })
        local grid = page:Grid({ Columns = 1 })
        local dialog = { pages = {}, title = key }
        menu._dialogs[key] = dialog
        function dialog:Close() end
        function dialog:AddPage(po, pbuilder)
            po = po or {}
            local sec = grid:AddSection({ Title = tostring(po.Title or "Page") })
            if po.Description then sec:_make("Label", { Label = tostring(po.Description) }) end
            local node = { onOpen = po.OnOpen }
            dialog.pages[#dialog.pages + 1] = node
            if pbuilder ~= nil then
                local ok, err = pcall(pbuilder, sec)
                if not ok then log("dialog page failed: " .. tostring(err)) end
            end
            local confirming = false
            local actionText = tostring(po.ActionText or "OK")
            local button
            button = sec:_make("Button", {
                Label = actionText,
                OnClick = function()
                    if po.Confirmation ~= nil and not confirming then
                        confirming = true
                        local desc = po.Confirmation.Description
                        if type(desc) == "function" then
                            local ok, t = pcall(desc)
                            desc = ok and t or ""
                        end
                        notify(K.T(tostring(desc or "Click again to confirm.")))
                        button:_rename("Confirm: " .. actionText)
                        task.delay(4, function()
                            if confirming then
                                confirming = false
                                button:_rename(actionText)
                            end
                        end)
                        return
                    end
                    if confirming then
                        confirming = false
                        button:_rename(actionText)
                    end
                    if po.OnAction ~= nil then
                        local ok, res = pcall(po.OnAction)
                        if not ok then
                            log("dialog action failed: " .. tostring(res))
                        elseif res then
                            if node.onOpen ~= nil then pcall(node.onOpen) end
                        end
                    end
                end,
            })
            if po.ActionEnabled == false then button:SetEnabled(false) end
            function node:SetActionEnabled(v) button:SetEnabled(v) end
            node.Close = function() end
            if node.onOpen ~= nil then pcall(node.onOpen) end
            return node
        end
        local ok, err = pcall(builder, dialog)
        if not ok then log("dialog '" .. key .. "' failed: " .. tostring(err)) end
        return dialog
    end

    --------------------------------------------------------------------------------------------------- menu
    local BUBBLE = 74

    local function newMenu(class, opts)
        opts = opts or {}
        local self = setmetatable({}, class)
        -- widths of the widgets on the right of a row (the Drop panels are narrower)
        self._ctlW = class == SDrop and { dd = 112, tb = 104 } or { dd = 160, tb = 150 }
        self._opts = opts
        self._trove = Trove.new("SetsunaMenu")
        self._controls = {}
        self._groupConns = {}
        self._dialogs = {}
        self._config = opts.Config
        self._colorAnimation = opts.ColorAnimation
        self._persistence = opts.Persistence
        self._state = opts.State
        self._stateData = opts.StateData
        self._onUnload = opts.OnUnload
        self._themePath = opts.ThemePath or { "Theme" }
        self._notificationPath = opts.NotificationPath or { "Notifications" }
        self._autoExecuteEnabledPath = opts.AutoExecuteEnabledPath or { "AutoExecuteScript", "Enabled" }
        self.Title = opts.Title or "LxYHook"
        self.Icon = opts.Icon
        self.Directory = opts.Directory
        self.Visible = false
        self.Dragging = false
        self.Keybind = Enum.KeyCode.RightShift
        self.VisibilityChanged = Signal.new()
        self.AccentChanged = Signal.new()
        self._watermark = not (self._stateData ~= nil and self._stateData.ShowWatermark == false)
        self._keybindList = not (self._stateData ~= nil and self._stateData.ShowKeybinds == false)
        self._tabs = {}
        self._acc, self._ov = DEFAULT_ACCENT, {}
        self._lite = class.__lite == true
        sharpCorners = rawget(class, "__sharp") == true
        self._v2 = sharpCorners
        if self._lite then self:_initTheme() end
        self._pal = palette(self._acc, self._ov, self._lite, self._theme)
        self._themed, self._themeFns = {}, {}

        local saved
        pcall(function()
            saved = tbl17.w().deserializeKey(self._stateData and self._stateData.Keybind)
        end)
        if typeof(saved) == "EnumItem" then self.Keybind = saved end

        self:_buildShell()
        self.AccentChanged:Connect(function(c)
            if typeof(c) == "Color3" then
                self:_setAccent(c)
            elseif type(c) == "table" and typeof(c.Rgb) == "Color3" then
                self:_setAccent(c.Rgb)
            end
        end)

        self._trove:Connect(UserInputService.InputBegan, function(input, processed)
            if processed or self._destroyed then return end
            local key = input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode or input.UserInputType
            if key == self.Keybind then self:SetVisible(not self.Visible) end
        end)
        pcall(function() self._cursor = tbl17.ag().new(self._trove) end)
        self:_hookTheme()
        return self
    end
    function SMenu.new(opts) return newMenu(SMenu, opts) end
    function SDrop.new(opts) return newMenu(SDrop, opts) end

    -- Settings > Theme edits the script's theme tokens; follow the ones that mean something here
    function SMenu:_hookTheme()
        local ok, err = pcall(function()
            local batch = tbl17.A().newBatch(self._trove)
            local map = {
                Background = { "panel", "surf" }, ElementBackground = { "inner" }, Outline = { "outline" }, TabButtonSelected = { "sel" },
                TextColor = { "text" }, Unselected = { "dim" }, ToggleCircleUnselected = { "knob" }, ToggleBackgroundUnselected = { "toggleoff" },
            }
            for token, roles in pairs(map) do
                batch:BindStateful(token, function(c)
                    if typeof(c) ~= "Color3" then return end
                    for _, role in ipairs(roles) do self._ov[role] = c end
                    self:_applyPalette()
                end)
            end
        end)
        if not ok then log("theme hook failed: " .. tostring(err)) end
    end

    function SMenu:_buildShell()
        local pal = self._pal
        local gui = mk("ScreenGui", { Name = "Setsuna Interface", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 100000,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling, Enabled = false })
        local placed = pcall(function() gui.Parent = gethui() end)
        if not placed or gui.Parent == nil then gui.Parent = game:GetService("CoreGui") end
        self._gui = gui

        -- Modal frees the mouse while the menu is open (first person locks it to the centre)
        local dim = mk("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, BorderSizePixel = 0, Modal = false }, gui)
        self._dim = dim
        local stage = mk("Frame", { BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 1 }, gui)
        self._stage = stage
        self._uiscale = mk("UIScale", {}, stage)

        local ring = mk("Frame", { AnchorPoint = Vector2.new(.5, .5), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 2 }, stage)
        circle(ring)
        local rst = mk("UIStroke", { Thickness = 1.2, Transparency = .6 }, ring)
        self:_paint(rst, "Color", "acc")
        self._ring = ring

        local logo = mk("ImageLabel", { AnchorPoint = Vector2.new(.5, .5), Size = UDim2.fromOffset(96, 96), BackgroundTransparency = 1, Image = tostring((K.LoadLogo and K.LoadLogo() or K.LithiumLogo) or ""), ZIndex = 3 }, stage)
        self._logo = logo
        pcall(function() K.AddLogoY(logo, function(o) self:_paint(o, "ImageColor3", "acc") end) end)

        self._bubbles = mk("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 4 }, stage)

        -- the list of pages of the open category
        local lp = mk("Frame", { BorderSizePixel = 0, ZIndex = 10, ClipsDescendants = true, Visible = false, Active = true }, stage)
        self:_paint(lp, "BackgroundColor3", "panel")
        self._lpCorner = corner(lp, 14)
        local lst = mk("UIStroke", { Thickness = 1.5, Transparency = .3 }, lp)
        self:_paint(lst, "Color", "outline")
        self._listPanel = lp
        local lc = mk("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Visible = false }, lp)
        self._listContent = lc
        self._listHead = self:_header(lc)
        self._listBody = mk("Frame", { Position = UDim2.fromOffset(0, 60), Size = UDim2.new(1, 0, 1, -60), BackgroundTransparency = 1, ClipsDescendants = true }, lc)

        -- the settings of the open page
        local sp = mk("Frame", { BorderSizePixel = 0, ZIndex = 10, ClipsDescendants = true, Visible = false, Active = true }, stage)
        self:_paint(sp, "BackgroundColor3", "panel")
        self._spCorner = corner(sp, 14)
        local sst = mk("UIStroke", { Thickness = 1.5, Transparency = .3 }, sp)
        self:_paint(sst, "Color", "outline")
        self._setPanel = sp
        local sc = mk("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Visible = false }, sp)
        self._setContent = sc
        self._setHead = self:_header(sc)
        self._setBody = mk("Frame", { Position = UDim2.fromOffset(0, 60), Size = UDim2.new(1, 0, 1, -60), BackgroundTransparency = 1, ClipsDescendants = true }, sc)

        dim.Activated:Connect(function()
            self:_closePopup()
            if self._page ~= nil then self:_closePage() elseif self._cat ~= nil then self:_closeCat() end
        end)
        gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() self:_relayout() end)
        self:_relayout()
    end

    -- a panel header: round button (back / icon) + title + separator
    function SMenu:_header(parent)
        local btn = mk("TextButton", { Position = UDim2.fromOffset(12, 11), Size = UDim2.fromOffset(36, 36), BorderSizePixel = 0, Text = "", AutoButtonColor = false }, parent)
        circle(btn)
        self:_paint(btn, "BackgroundColor3", "acc")
        local icon = mk("ImageLabel", { AnchorPoint = Vector2.new(.5, .5), Position = UDim2.fromScale(.5, .5), Size = UDim2.fromOffset(20, 20), BackgroundTransparency = 1, ImageColor3 = TEXT }, btn)
        local letter = mk("TextLabel", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", TextSize = 16, Font = Enum.Font.GothamBold, TextColor3 = TEXT }, btn)
        local title = text(self, parent, "", 17, "text", true)
        title.Position = UDim2.fromOffset(60, 0)
        title.Size = UDim2.new(1, -72, 0, 58)
        title.TextTruncate = Enum.TextTruncate.AtEnd
        local line = mk("Frame", { Position = UDim2.fromOffset(12, 58), Size = UDim2.new(1, -24, 0, 1), BorderSizePixel = 0, BackgroundTransparency = .55 }, parent)
        self:_paint(line, "BackgroundColor3", "acc")
        return { btn = btn, icon = icon, letter = letter, title = title }
    end

    local function setHeader(head, name, icon)
        head.title.Text = name
        local img = imageOf(icon)
        head.icon.Image = img
        head.icon.Visible = img ~= ""
        head.letter.Text = img == "" and string.upper(string.sub(name, 1, 1)) or ""
    end

    function SMenu:_relayout()
        local gui = self._gui
        local vw, vh = gui.AbsoluteSize.X, gui.AbsoluteSize.Y
        if vw <= 0 or vh <= 0 then
            local cam = workspace.CurrentCamera
            if cam == nil then return end
            vw, vh = cam.ViewportSize.X, cam.ViewportSize.Y
        end
        if vw <= 0 or vh <= 0 then return end
        local k = clamp(math.min(vw / 1280, vh / 720), .65, 1.6)
        self._k = k
        self._uiscale.Scale = k
        local sw, sh = vw / k, vh / k
        self._stage.Size = UDim2.fromOffset(sw, sh)
        self._g = {
            sw = sw, sh = sh, cx = sw / 2, cy = sh / 2,
            R = clamp(math.min(sw, sh) * .21, 112, 150),
            panelW = clamp(sw * .21, 240, 290), setW = clamp(sw * .27, 290, 360),
            listH = math.min(clamp(sh * .64, 300, 460), sh - 30), setH = math.min(clamp(sh * .80, 340, 600), sh - 30),
        }
        local g = self._g
        self._ring.Size = UDim2.fromOffset(g.R * 2, g.R * 2)
        self._ring.Position = UDim2.fromOffset(g.cx, g.cy)
        self._logo.Position = UDim2.fromOffset(g.cx, g.cy)
        self:_layoutRing(false)
        if self._cat ~= nil then self:_layoutPanels(false) end
        self:_closePopup()
    end

    function SMenu:_layoutRing(animate)
        local g = self._g
        if g == nil then return end
        local n = #self._tabs
        for i, tab in ipairs(self._tabs) do
            local ang = math.rad(-90 + (i - 1) * (360 / n))
            tab._bx, tab._by = g.cx + math.cos(ang) * g.R, g.cy + math.sin(ang) * g.R
            if self._cat == nil then
                local pos = UDim2.fromOffset(tab._bx, tab._by)
                if animate then tween(tab._bubble, .4, { Position = pos }) else tab._bubble.Position = pos end
            end
        end
    end

    function SMenu:_rects()
        local g = self._g
        local list = { w = g.panelW, h = g.listH, y = (g.sh - g.listH) / 2 }
        local set
        if self._page ~= nil then
            local pairW = g.panelW + 12 + g.setW
            list.x = (g.sw - pairW) / 2
            set = { x = list.x + g.panelW + 12, y = (g.sh - g.setH) / 2, w = g.setW, h = g.setH }
        else
            list.x = (g.sw - g.panelW) / 2
        end
        return list, set
    end

    local function rectProps(r)
        return { Position = UDim2.fromOffset(r.x, r.y), Size = UDim2.fromOffset(r.w, r.h) }
    end

    function SMenu:_layoutPanels(animate)
        local list, set = self:_rects()
        if animate then
            tween(self._listPanel, .3, rectProps(list))
        else
            self._listPanel.Position = UDim2.fromOffset(list.x, list.y)
            self._listPanel.Size = UDim2.fromOffset(list.w, list.h)
        end
        if set ~= nil then
            self._setPanel.Position = UDim2.fromOffset(set.x, set.y)
            self._setPanel.Size = UDim2.fromOffset(set.w, set.h)
        end
    end

    function SMenu:_showRing(animate, fromCenter)
        local g = self._g
        self._ring.Visible = true
        self._logo.Visible = true
        if animate then
            self._ring.Size = UDim2.fromOffset(0, 0)
            tween(self._ring, .45, { Size = UDim2.fromOffset(g.R * 2, g.R * 2) }, Enum.EasingStyle.Back)
            self._logo.Size = UDim2.fromOffset(0, 0)
            tween(self._logo, .4, { Size = UDim2.fromOffset(96, 96) }, Enum.EasingStyle.Back)
        else
            self._ring.Size = UDim2.fromOffset(g.R * 2, g.R * 2)
            self._logo.Size = UDim2.fromOffset(96, 96)
        end
        for i, tab in ipairs(self._tabs) do
            local b = tab._bubble
            b.Visible = true
            if fromCenter then
                b.Position = UDim2.fromOffset(g.cx, g.cy)
                b.Size = UDim2.fromOffset(0, 0)
                task.delay((i - 1) * .03, function()
                    if self._cat == nil then
                        tween(b, .45, { Position = UDim2.fromOffset(tab._bx, tab._by), Size = UDim2.fromOffset(BUBBLE, BUBBLE) }, Enum.EasingStyle.Back)
                    end
                end)
            else
                tween(b, .3, { Position = UDim2.fromOffset(tab._bx, tab._by), Size = UDim2.fromOffset(BUBBLE, BUBBLE) })
            end
        end
    end

    function SMenu:_hideRing()
        self._ring.Visible = false
        self._logo.Visible = false
        local g = self._g
        for _, tab in ipairs(self._tabs) do
            local b = tab._bubble
            tween(b, .25, { Position = UDim2.fromOffset(g.cx, g.cy), Size = UDim2.fromOffset(0, 0) })
            task.delay(.26, function() if self._cat ~= nil then b.Visible = false end end)
        end
    end

    function SMenu:_openCat(tab)
        if self._cat ~= nil or self._destroyed then return end
        self:_closePopup()
        self._cat, self._page = tab, nil
        local lp = self._listPanel
        for _, t in ipairs(self._tabs) do t._list.Visible = t == tab end
        setHeader(self._listHead, tab.Label, tab.Icon)
        self._listContent.Visible = false
        lp.Visible = true
        lp.Position = UDim2.fromOffset(tab._bx - BUBBLE / 2, tab._by - BUBBLE / 2)
        lp.Size = UDim2.fromOffset(BUBBLE, BUBBLE)
        self._lpCorner.CornerRadius = UDim.new(0, BUBBLE / 2)
        local list = self:_rects()
        tween(lp, .32, rectProps(list))
        tween(self._lpCorner, .32, { CornerRadius = UDim.new(0, 14) })
        task.delay(.16, function()
            if self._cat == tab then self._listContent.Visible = true end
        end)
        self:_hideRing()
    end

    function SMenu:_closeCat()
        local tab = self._cat
        if tab == nil then return end
        self:_closePopup()
        if self._page ~= nil then self:_closePage(true) end
        self._cat = nil
        self._listContent.Visible = false
        local lp = self._listPanel
        tween(lp, .28, { Position = UDim2.fromOffset(tab._bx - BUBBLE / 2, tab._by - BUBBLE / 2), Size = UDim2.fromOffset(BUBBLE, BUBBLE) })
        tween(self._lpCorner, .28, { CornerRadius = UDim.new(0, BUBBLE / 2) })
        task.delay(.28, function()
            if self._cat == nil then lp.Visible = false end
        end)
        self:_showRing(false, false)
    end

    function SMenu:_openPage(page)
        if self._cat ~= page._tab or self._destroyed then return end
        self:_closePopup()
        local first = self._page == nil
        local old = self._page
        self._page = page
        if old ~= nil and old._scroll ~= nil then old._scroll.Visible = false end
        for _, p in ipairs(page._tab._pages) do
            if p._row ~= nil then p._row.sel.Visible = p == page end
        end
        setHeader(self._setHead, page.Label, page.Icon)
        local sp = self._setPanel
        local list, set = self:_rects()
        if first then
            self._setContent.Visible = false
            sp.Visible = true
            sp.Position = UDim2.fromOffset(set.x - 40, set.y + 20)
            sp.Size = UDim2.fromOffset(set.w * .8, set.h * .9)
            self._spCorner.CornerRadius = UDim.new(0, 30)
            tween(sp, .3, rectProps(set))
            tween(self._spCorner, .3, { CornerRadius = UDim.new(0, 14) })
            tween(self._listPanel, .3, rectProps(list))
            task.delay(.14, function()
                if self._page ~= nil then self._setContent.Visible = true end
            end)
        end
        page:_realize()
        -- building a page can yield; if another page was opened meanwhile, this one stays hidden
        if self._page ~= page then return end
        for _, tab in ipairs(self._tabs) do
            for _, p in ipairs(tab._pages) do
                if p ~= page and p._scroll ~= nil then p._scroll.Visible = false end
            end
        end
        page._scroll.Visible = true
        page._scroll.CanvasPosition = Vector2.zero
    end

    function SMenu:_closePage(silent)
        local page = self._page
        if page == nil then return end
        self:_closePopup()
        self._page = nil
        if page._scroll ~= nil then page._scroll.Visible = false end
        for _, p in ipairs(page._tab._pages) do
            if p._row ~= nil then p._row.sel.Visible = false end
        end
        self._setContent.Visible = false
        self._setPanel.Visible = false
        if not silent then self:_layoutPanels(true) end
    end

    function SMenu:_makePageRow(tab, page)
        local m = self
        local n = #tab._pages
        local btn = mk("TextButton", { Size = UDim2.new(1, -8, 0, 44), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, LayoutOrder = n, BorderSizePixel = 0 }, tab._list)
        corner(btn, 8)
        local hover = mk("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 1 }, btn)
        corner(hover, 8)
        m:_paint(hover, "BackgroundColor3", "hover")
        local sel = mk("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = .75, BorderSizePixel = 0, Visible = false, ZIndex = 1 }, btn)
        corner(sel, 8)
        m:_paint(sel, "BackgroundColor3", "sel")
        local lbl = text(m, btn, page.Label, 14, "dim", false)
        lbl.Position = UDim2.fromOffset(14, 0)
        lbl.Size = UDim2.new(1, -50, 1, 0)
        lbl.ZIndex = 2
        lbl.TextTruncate = Enum.TextTruncate.AtEnd
        local dot = mk("Frame", { AnchorPoint = Vector2.new(1, .5), Position = UDim2.new(1, -16, .5, 0), Size = UDim2.fromOffset(7, 7), BorderSizePixel = 0, ZIndex = 2 }, btn)
        circle(dot)
        m:_paint(dot, "BackgroundColor3", "faint")
        btn.MouseEnter:Connect(function() tween(hover, .12, { BackgroundTransparency = .45 }) tween(lbl, .12, { TextColor3 = m._pal.text }) end)
        btn.MouseLeave:Connect(function() tween(hover, .12, { BackgroundTransparency = 1 }) tween(lbl, .12, { TextColor3 = m._pal.dim }) end)
        btn.Activated:Connect(function()
            if self._page == page then
                self:_closePage()
            else
                task.spawn(function() self:_openPage(page) end)
            end
        end)
        page._row = { btn = btn, sel = sel }
    end

    function SMenu:AddTab(o)
        o = o or {}
        local tab = setmetatable({ _menu = self, Label = tostring(o.Label or "Tab"), Icon = o.Icon or false, _pages = {} }, STab)
        local m = self
        local b = mk("TextButton", { AnchorPoint = Vector2.new(.5, .5), Size = UDim2.fromOffset(BUBBLE, BUBBLE), BorderSizePixel = 0, Text = "", AutoButtonColor = false, ZIndex = 5 }, self._bubbles)
        circle(b)
        self:_paint(b, "BackgroundColor3", "surf")
        local st = mk("UIStroke", { Thickness = 1.6, Transparency = .25 }, b)
        self:_paint(st, "Color", "acc")
        local img = imageOf(tab.Icon)
        local icon = mk("ImageLabel", { AnchorPoint = Vector2.new(.5, .5), Position = UDim2.new(.5, 0, 0, 27), Size = UDim2.fromOffset(26, 26), BackgroundTransparency = 1, Image = img, Visible = img ~= "", ZIndex = 6 }, b)
        self:_paint(icon, "ImageColor3", "acc")
        local name = text(self, b, tab.Label, 11, "text", true)
        name.AnchorPoint = Vector2.new(.5, .5)
        name.Position = UDim2.new(.5, 0, 0, img ~= "" and 54 or 37)
        name.Size = UDim2.new(1, -8, 0, 16)
        name.TextXAlignment = Enum.TextXAlignment.Center
        name.TextTruncate = Enum.TextTruncate.AtEnd
        name.ZIndex = 6
        b.MouseEnter:Connect(function()
            if self._cat == nil then tween(b, .15, { Size = UDim2.fromOffset(BUBBLE + 8, BUBBLE + 8) }) end
        end)
        b.MouseLeave:Connect(function()
            if self._cat == nil then tween(b, .15, { Size = UDim2.fromOffset(BUBBLE, BUBBLE) }) end
        end)
        b.Activated:Connect(function() self:_openCat(tab) end)
        tab._bubble = b

        local list = mk("ScrollingFrame", {
            Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3,
            CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y, Visible = false,
        }, self._listBody)
        self:_paint(list, "ScrollBarImageColor3", "acc")
        mk("UIListLayout", { Padding = UDim.new(0, 3), SortOrder = Enum.SortOrder.LayoutOrder, HorizontalAlignment = Enum.HorizontalAlignment.Center }, list)
        mk("UIPadding", { PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 10), PaddingLeft = UDim.new(0, 4), PaddingRight = UDim.new(0, 4) }, list)
        tab._list = list

        self._tabs[#self._tabs + 1] = tab
        self:_layoutRing(false)
        return tab
    end

    function SMenu:Dialog(o, builder)
        return sBuildDialog(self, o or {}, builder)
    end

    for _, name in ipairs({ "_setVisibleState", "View", "GetConfig", "GetColorAnimation", "GetPersistence", "GetStateData", "GetOverlayLayer",
        "SaveState", "Connect", "Add", "Notify", "AddSettingsTab", "SetWatermarkUsername", "SetWatermarkEnabled", "IsWatermarkEnabled",
        "SetKeybindListEnabled", "IsKeybindListEnabled", "SetAccent", "Unload", "_persistFlag" }) do
        SMenu[name] = Menu[name]
    end

    function SMenu:SetVisible(visible, instant)
        visible = visible and true or false
        local was = self.Visible
        self:_closePopup()
        if visible then
            self._gui.Enabled = true
            self._dim.Modal = true
            K.MenuOpen = true
            if self._cat ~= nil then
                self._cat, self._page = nil, nil
                self._listPanel.Visible, self._setPanel.Visible = false, false
                self._listContent.Visible, self._setContent.Visible = false, false
                for _, t in ipairs(self._tabs) do
                    if t._list then t._list.Visible = false end
                end
            end
            self:_relayout()
            if not was then
                self._dim.BackgroundTransparency = 1
                tween(self._dim, .3, { BackgroundTransparency = .45 })
                self:_showRing(not instant, not instant)
            else
                self:_showRing(false, false)
            end
        else
            -- a Modal button keeps the mouse free for as long as it is Modal, even in a disabled gui
            self._dim.Modal = false
            K.MenuOpen = false
            self._gui.Enabled = false
        end
        self:_setVisibleState(visible)
        return true
    end

    function SMenu:Destroy()
        pcall(function() self._dim.Modal = false end)
        K.MenuOpen = false
        if self._destroyed then return end
        if K.KeyHud then K.KeyHud.destroy() end
        self._destroyed = true
        self:SaveState()
        if self._cursor ~= nil then pcall(self._cursor.Set, self._cursor, false) end
        local config = self._config
        if config ~= nil and config.SetActive ~= nil then pcall(config.SetActive, config, false) end
        for _, c in ipairs(self._controls) do c._dead = true end
        pcall(function()
            for _, c in ipairs(self._groupConns) do c:Disconnect() end
        end)
        pcall(function() self._trove:Destroy() end)
        pcall(function() self._gui:Destroy() end)
    end

    --------------------------------------------------------------------------------------------------- Setsuna (Drop)
    -- Drop mode of Setsuna's ClickGUI: one draggable, collapsible panel per category; a page is a row of the panel
    -- and opens its settings right under itself. Same Menu surface and the same widgets as the Pop form.
    local DROP_W, DROP_HEAD, DROP_MAX = 262, 38, 430

    local function dropClamp(self, tab)
        local g, p = self._g, tab._panel
        if g == nil then return end
        local x, y = p.Position.X.Offset, p.Position.Y.Offset
        p.Position = UDim2.fromOffset(clamp(x, 0, math.max(0, g.sw - DROP_W)), clamp(y, 0, math.max(0, g.sh - DROP_HEAD)))
    end

    function SDrop:_buildShell()
        local gui = mk("ScreenGui", { Name = "Setsuna Interface", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 100000,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling, Enabled = false })
        local placed = pcall(function() gui.Parent = gethui() end)
        if not placed or gui.Parent == nil then gui.Parent = game:GetService("CoreGui") end
        self._gui = gui
        local dim = mk("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, BorderSizePixel = 0, Modal = false }, gui)
        self._dim = dim
        local stage = mk("Frame", { BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 1 }, gui)
        self._stage = stage
        self._uiscale = mk("UIScale", {}, stage)
        self._z = 10
        dim.Activated:Connect(function() self:_closePopup() end)
        gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() self:_relayout() end)
        self:_relayout()
    end

    function SDrop:_relayout()
        local gui = self._gui
        local vw, vh = gui.AbsoluteSize.X, gui.AbsoluteSize.Y
        if vw <= 0 or vh <= 0 then
            local cam = workspace.CurrentCamera
            if cam == nil then return end
            vw, vh = cam.ViewportSize.X, cam.ViewportSize.Y
        end
        if vw <= 0 or vh <= 0 then return end
        local k = clamp(math.min(vw / 1280, vh / 720), .65, 1.6)
        self._k = k
        self._uiscale.Scale = k
        local sw, sh = vw / k, vh / k
        self._stage.Size = UDim2.fromOffset(sw, sh)
        self._g = { sw = sw, sh = sh, cx = sw / 2, cy = sh / 2, setW = DROP_W, panelW = DROP_W }
        self:_arrange()
        for _, tab in ipairs(self._tabs) do
            dropClamp(self, tab)
            self:_fitPanel(tab, false)
        end
        self:_closePopup()
    end

    -- panels the user has not moved sit in rows of headers along the top; the others stay where they were put
    function SDrop:_arrange()
        local g = self._g
        if g == nil then return end
        local perRow = math.max(1, math.floor((g.sw - 24) / (DROP_W + 10)))
        for i, tab in ipairs(self._tabs) do
            if not tab._moved then
                local col, row = (i - 1) % perRow, math.floor((i - 1) / perRow)
                tab._panel.Position = UDim2.fromOffset(14 + col * (DROP_W + 10), 52 + row * (DROP_HEAD + 10))
            end
        end
    end

    function SDrop:_front(tab)
        self._z += 1
        if self._z > 48 then
            self._z = 10
            for _, t in ipairs(self._tabs) do t._panel.ZIndex = 10 end
            self._z = 11
        end
        tab._panel.ZIndex = self._z
    end

    -- height of a panel: its header, plus the list while open (at most DROP_MAX)
    function SDrop:_fitPanel(tab, animate)
        local p = tab._panel
        local body = tab._body
        local content = tab._layout.AbsoluteContentSize.Y
        local target = DROP_HEAD
        if tab._expanded then target = DROP_HEAD + math.min(content + 14, DROP_MAX) end
        body.Visible = tab._expanded
        local size = UDim2.fromOffset(DROP_W, target)
        if animate then
            tween(p, .22, { Size = size })
        else
            p.Size = size
        end
    end

    function SDrop:_toggleTab(tab, open)
        if open == nil then open = not tab._expanded end
        tab._expanded = open
        tab._chev.Text = open and "-" or "+"
        self:_closePopup()
        self:_fitPanel(tab, true)
        self:_front(tab)
    end

    function SDrop:AddTab(o)
        o = o or {}
        local m = self
        local tab = setmetatable({ _menu = self, Label = tostring(o.Label or "Tab"), Icon = o.Icon or false, _pages = {}, _expanded = false, _moved = false }, STab)
        local panel = mk("Frame", { Size = UDim2.fromOffset(DROP_W, DROP_HEAD), BorderSizePixel = 0, ClipsDescendants = true, Active = true, ZIndex = 10 }, self._stage)
        corner(panel, 10)
        self:_paint(panel, "BackgroundColor3", "panel")
        local st = mk("UIStroke", { Thickness = 1.4, Transparency = .3 }, panel)
        self:_paint(st, "Color", "outline")
        tab._panel = panel

        local head = mk("TextButton", { Size = UDim2.new(1, 0, 0, DROP_HEAD), BorderSizePixel = 0, Text = "", AutoButtonColor = false, ZIndex = 3 }, panel)
        self:_paint(head, "BackgroundColor3", "inner")
        local img = imageOf(tab.Icon)
        local icon = mk("ImageLabel", { Position = UDim2.fromOffset(12, 9), Size = UDim2.fromOffset(20, 20), BackgroundTransparency = 1, Image = img, Visible = img ~= "", ZIndex = 4 }, head)
        self:_paint(icon, "ImageColor3", "acc")
        local title = text(self, head, tab.Label, 15, "text", true)
        title.Position = UDim2.fromOffset(img ~= "" and 40 or 14, 0)
        title.Size = UDim2.new(1, -78, 1, 0)
        title.ZIndex = 4
        title.TextTruncate = Enum.TextTruncate.AtEnd
        local chev = text(self, head, "+", 18, "value", true)
        chev.AnchorPoint = Vector2.new(1, .5)
        chev.Position = UDim2.new(1, -14, .5, 0)
        chev.Size = UDim2.fromOffset(18, 22)
        chev.TextXAlignment = Enum.TextXAlignment.Center
        chev.ZIndex = 4
        tab._chev = chev
        local line = mk("Frame", { AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 0, 1, 0), Size = UDim2.new(1, 0, 0, 1), BorderSizePixel = 0, BackgroundTransparency = .5, ZIndex = 4 }, head)
        self:_paint(line, "BackgroundColor3", "acc")

        local body = mk("ScrollingFrame", {
            Position = UDim2.fromOffset(0, DROP_HEAD), Size = UDim2.new(1, 0, 1, -DROP_HEAD), BackgroundTransparency = 1, BorderSizePixel = 0,
            ScrollBarThickness = 3, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y,
            Visible = false, ZIndex = 2,
        }, panel)
        self:_paint(body, "ScrollBarImageColor3", "acc")
        local layout = mk("UIListLayout", { Padding = UDim.new(0, 3), SortOrder = Enum.SortOrder.LayoutOrder, HorizontalAlignment = Enum.HorizontalAlignment.Center }, body)
        mk("UIPadding", { PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 8), PaddingLeft = UDim.new(0, 4), PaddingRight = UDim.new(0, 4) }, body)
        tab._body, tab._layout = body, layout
        layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            if tab._expanded then self:_fitPanel(tab, false) end
        end)

        -- drag by the header; a press that does not move is a click (open / close)
        head.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            self:_front(tab)
            self:_closePopup()
            local sx, sy = pointer(input)
            local startPos = panel.Position
            local moved = false
            local moveConn, endConn
            moveConn = UIS.InputChanged:Connect(function(i)
                if i.UserInputType ~= Enum.UserInputType.MouseMovement and i.UserInputType ~= Enum.UserInputType.Touch then return end
                local x, y = pointer(i)
                local dx, dy = x - sx, y - sy
                if not moved and math.abs(dx) + math.abs(dy) < 5 then return end
                moved = true
                tab._moved = true
                local k = self._k
                panel.Position = UDim2.fromOffset(startPos.X.Offset + dx / k, startPos.Y.Offset + dy / k)
                dropClamp(self, tab)
            end)
            endConn = UIS.InputEnded:Connect(function(i)
                if i == input or i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                    moveConn:Disconnect()
                    endConn:Disconnect()
                    if not moved then self:_toggleTab(tab) end
                end
            end)
        end)

        self._tabs[#self._tabs + 1] = tab
        self:_arrange()
        return tab
    end

    -- the settings of a page are a block of rows right under its row
    function SDrop:_makeHost(page)
        local tab = page._tab
        local host = mk("Frame", { Size = UDim2.new(1, 0, 0, 0), BackgroundTransparency = 1, BorderSizePixel = 0, LayoutOrder = page._idx * 2 + 1, Visible = page._expanded == true }, tab._body)
        local layout = mk("UIListLayout", { Padding = UDim.new(0, 5), SortOrder = Enum.SortOrder.LayoutOrder, HorizontalAlignment = Enum.HorizontalAlignment.Center }, host)
        mk("UIPadding", { PaddingTop = UDim.new(0, 3), PaddingBottom = UDim.new(0, 8) }, host)
        local function size() host.Size = UDim2.new(1, 0, 0, layout.AbsoluteContentSize.Y + 11) end
        layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(size)
        size()
        return host
    end

    function SDrop:_makePageRow(tab, page)
        local m = self
        page._idx = #tab._pages
        local btn = mk("TextButton", { Size = UDim2.new(1, -8, 0, 36), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, LayoutOrder = page._idx * 2, BorderSizePixel = 0 }, tab._body)
        corner(btn, 8)
        local hover = mk("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0 }, btn)
        corner(hover, 8)
        m:_paint(hover, "BackgroundColor3", "hover")
        local sel = mk("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = .75, BorderSizePixel = 0, Visible = false }, btn)
        corner(sel, 8)
        m:_paint(sel, "BackgroundColor3", "sel")
        local lbl = text(m, btn, page.Label, 14, "dim", false)
        lbl.Position = UDim2.fromOffset(12, 0)
        lbl.Size = UDim2.new(1, -44, 1, 0)
        lbl.TextTruncate = Enum.TextTruncate.AtEnd
        lbl.ZIndex = 2
        local chev = text(m, btn, "+", 15, "faint", true)
        chev.AnchorPoint = Vector2.new(1, .5)
        chev.Position = UDim2.new(1, -12, .5, 0)
        chev.Size = UDim2.fromOffset(16, 20)
        chev.TextXAlignment = Enum.TextXAlignment.Center
        chev.ZIndex = 2
        btn.MouseEnter:Connect(function() tween(hover, .12, { BackgroundTransparency = .45 }) tween(lbl, .12, { TextColor3 = m._pal.text }) end)
        btn.MouseLeave:Connect(function() tween(hover, .12, { BackgroundTransparency = 1 }) tween(lbl, .12, { TextColor3 = m._pal.dim }) end)
        btn.Activated:Connect(function()
            m:_closePopup()
            page._expanded = not page._expanded
            sel.Visible = page._expanded
            chev.Text = page._expanded and "-" or "+"
            if page._expanded then
                task.spawn(function()
                    page:_realize()
                    if page._scroll ~= nil then page._scroll.Visible = page._expanded end
                end)
            elseif page._scroll ~= nil then
                page._scroll.Visible = false
            end
        end)
        page._row = { btn = btn, sel = sel }
    end

    function SDrop:SetVisible(visible, instant)
        visible = visible and true or false
        local was = self.Visible
        self:_closePopup()
        if visible then
            self._gui.Enabled = true
            self._dim.Modal = true
            K.MenuOpen = true
            self:_relayout()
            if not was then
                self._dim.BackgroundTransparency = 1
                tween(self._dim, .3, { BackgroundTransparency = .55 })
                if not self._opened and self._tabs[1] ~= nil then
                    self._opened = true
                    self:_toggleTab(self._tabs[1], true)
                end
                if not instant then
                    for i, tab in ipairs(self._tabs) do
                        local target = tab._panel.Position
                        tab._panel.Position = target - UDim2.fromOffset(0, 46)
                        task.delay((i - 1) * .04, function()
                            if self.Visible then tween(tab._panel, .38, { Position = target }, Enum.EasingStyle.Back) end
                        end)
                    end
                end
            end
        else
            self._dim.Modal = false
            K.MenuOpen = false
            self._gui.Enabled = false
        end
        self:_setVisibleState(visible)
        return true
    end

    --------------------------------------------------------------------------------------------------- Lite
    -- Fourth form of the menu: a Starlight-like window (a sidebar of categories and pages, a header, one page at a
    -- time) drawn with plain frames, built the way the classic menu is: the window is about a hundred instances and
    -- a button per page, and a page's rows are made when it is first opened. Starlight's own window is a model of
    -- thousands of instances that has to be cloned and laid out first. It sits on the same Menu surface and uses the
    -- same widgets as the Setsuna forms, and the window is one CanvasGroup, so opening and closing are a real fade.
    -- Starlight's window measured off its own screenshot: 930 x 560, a 212 wide sidebar, a 41 high top bar
    local LITE_W, LITE_H, LITE_SIDE, LITE_HEAD = 930, 560, 212, 41
    -- the font Starlight draws its text in (the same family as the classic menu's)
    local LITE_FONT = "rbxassetid://12187365364"
    local fonted = setmetatable({}, { __mode = "k" })
    local function liteFont(root)
        local function one(d)
            if fonted[d] then return end
            if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then
                fonted[d] = true
                local bold = d.Font == Enum.Font.GothamBold
                d.FontFace = Font.new(LITE_FONT, bold and Enum.FontWeight.SemiBold or Enum.FontWeight.Medium, Enum.FontStyle.Normal)
            end
        end
        one(root)
        for _, d in ipairs(root:GetDescendants()) do one(d) end
    end

    local SLite = {}
    SLite.__lite = true
    SLite.__index = function(t, k)
        local v = rawget(SLite, k)
        if v ~= nil then return v end
        v = rawget(SMenu, k)
        if v ~= nil then return v end
        if isMethodName(k) then return function() return nil end end
        return nil
    end
    SetsunaUI.Lite = SLite
    function SLite.new(opts) return newMenu(SLite, opts) end

    function SLite:_buildShell()
        local gui = mk("ScreenGui", { Name = "Lite Interface", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 100000,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling, Enabled = false })
        local placed = pcall(function() gui.Parent = gethui() end)
        if not placed or gui.Parent == nil then gui.Parent = game:GetService("CoreGui") end
        self._gui = gui
        -- Modal frees the mouse while the menu is open (first person locks it to the centre)
        local dim = mk("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, BorderSizePixel = 0, Modal = false }, gui)
        self._dim = dim
        local stage = mk("Frame", { BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 1 }, gui)
        self._stage = stage
        self._uiscale = mk("UIScale", {}, stage)

        local win = mk("CanvasGroup", { AnchorPoint = Vector2.new(.5, .5), Size = UDim2.fromOffset(LITE_W, LITE_H), BorderSizePixel = 0,
            ZIndex = 5, GroupTransparency = 1, Active = true }, stage)
        self:_paint(win, "BackgroundColor3", "panel")
        corner(win, 12)
        -- Starlight's window outline is the Accents.Brighter gradient (white, so the gradient is the colour)
        local wst = mk("UIStroke", { Thickness = 1.5, Transparency = .3 }, win)
        self:_paint(wst, "Color", "fill")
        self:_grad(wst, "Brighter")
        self._win = win
        self._winScale = mk("UIScale", { Scale = .965 }, win)

        -- sidebar: logo and title, then the categories with their pages
        self._ctlW = { dd = 128, tb = 118 }
        local side = mk("Frame", { Size = UDim2.new(0, LITE_SIDE, 1, 0), BorderSizePixel = 0 }, win)
        self:_paint(side, "BackgroundColor3", "side")
        self._side = side
        local logo = mk("ImageLabel", { Position = UDim2.fromOffset(6, 0), Size = UDim2.fromOffset(41, 41), BackgroundTransparency = 1, Image = tostring((K.LoadLogo and K.LoadLogo() or K.LithiumLogo) or "") }, side)
        pcall(function() K.AddLogoY(logo, function(o) self:_paint(o, "ImageColor3", "acc") end) end)
        local title = text(self, side, tostring(self.Title or "LxYHook"), 11, "text", false)
        title.Position = UDim2.fromOffset(52, 0)
        title.Size = UDim2.new(1, -56, 0, LITE_HEAD)
        title.TextTruncate = Enum.TextTruncate.AtEnd
        local sline = mk("Frame", { Position = UDim2.fromOffset(0, LITE_HEAD), Size = UDim2.new(1, 0, 0, 1), BorderSizePixel = 0, BackgroundTransparency = .6 }, side)
        self:_paint(sline, "BackgroundColor3", "outline")
        local list = mk("ScrollingFrame", {
            Position = UDim2.fromOffset(0, LITE_HEAD + 1), Size = UDim2.new(1, 0, 1, -(LITE_HEAD + 1 + 56)), BackgroundTransparency = 1, BorderSizePixel = 0,
            ScrollBarThickness = 2, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y,
        }, side)

        -- the player card at the foot of the sidebar: avatar, display name, user name
        local me = game:GetService("Players").LocalPlayer
        local card = mk("Frame", { AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1), Size = UDim2.new(1, 0, 0, 56), BackgroundTransparency = 1, BorderSizePixel = 0 }, side)
        local cline = mk("Frame", { Size = UDim2.new(1, -16, 0, 1), Position = UDim2.fromOffset(8, 0), BorderSizePixel = 0, BackgroundTransparency = .6 }, card)
        self:_paint(cline, "BackgroundColor3", "outline")
        local avatar = mk("ImageLabel", { Position = UDim2.fromOffset(14, 12), Size = UDim2.fromOffset(34, 34), BorderSizePixel = 0, BackgroundTransparency = 0 }, card)
        circle(avatar)
        self:_paint(avatar, "BackgroundColor3", "surf")
        local who = text(self, card, me and me.DisplayName or "Player", 14, "text", true)
        who.Position = UDim2.fromOffset(58, 10)
        who.Size = UDim2.new(1, -66, 0, 18)
        who.TextTruncate = Enum.TextTruncate.AtEnd
        local handle = text(self, card, me and me.Name or "", 11, "dim", false)
        handle.Position = UDim2.fromOffset(58, 28)
        handle.Size = UDim2.new(1, -66, 0, 16)
        handle.TextTruncate = Enum.TextTruncate.AtEnd
        task.spawn(function()
            local ok, img = pcall(function()
                return game:GetService("Players"):GetUserThumbnailAsync(me.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size48x48)
            end)
            if ok and avatar.Parent ~= nil then avatar.Image = img end
        end)
        self:_paint(list, "ScrollBarImageColor3", "acc")
        mk("UIListLayout", { Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder }, list)
        mk("UIPadding", { PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 12), PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }, list)
        self._sideList = list

        -- header (drag handle): the open page's name, and a close button
        local head = mk("Frame", { Position = UDim2.fromOffset(LITE_SIDE, 0), Size = UDim2.new(1, -LITE_SIDE, 0, LITE_HEAD), BorderSizePixel = 0, Active = true }, win)
        self:_paint(head, "BackgroundColor3", "top")
        self._head = head
        local hdr = text(self, head, "", 13, "dim", false)
        hdr.Position = UDim2.fromOffset(16, 0)
        hdr.Size = UDim2.new(1, -80, 1, 0)
        hdr.TextTruncate = Enum.TextTruncate.AtEnd
        self._hdrTitle = hdr
        -- the two window buttons are small round dots on the right of the top bar, like Starlight's
        local function dot(x, hoverColor)
            local b = mk("TextButton", { AnchorPoint = Vector2.new(1, .5), Position = UDim2.new(1, x, .5, 0), Size = UDim2.fromOffset(14, 14), BorderSizePixel = 0,
                Text = "", TextTransparency = 1, AutoButtonColor = false }, head)
            circle(b)
            self:_paint(b, "BackgroundColor3", "faint")
            b.MouseEnter:Connect(function() tween(b, .12, { BackgroundColor3 = hoverColor }) end)
            b.MouseLeave:Connect(function() tween(b, .12, { BackgroundColor3 = self._pal.faint }) end)
            return b
        end
        local close = dot(-14, Color3.fromRGB(235, 110, 110))
        close.Activated:Connect(function() self:SetVisible(false) end)
        -- minimise: the window folds up to its title bar
        local mini = dot(-36, Color3.fromRGB(230, 200, 120))
        mini.Activated:Connect(function() self:_setCollapsed(not self._collapsed) end)
        self._miniBtn = mini
        local hline = mk("Frame", { AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 0, 1, 0), Size = UDim2.new(1, 0, 0, 1), BorderSizePixel = 0, BackgroundTransparency = .6 }, head)
        self:_paint(hline, "BackgroundColor3", "outline")
        head.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            self:_closePopup()
            local sx, sy = pointer(input)
            local start = win.Position
            local moveConn, endConn
            moveConn = UIS.InputChanged:Connect(function(i)
                if i.UserInputType ~= Enum.UserInputType.MouseMovement and i.UserInputType ~= Enum.UserInputType.Touch then return end
                local x, y = pointer(i)
                local k = self._k
                self._moved = true
                win.Position = UDim2.fromOffset(start.X.Offset + (x - sx) / k, start.Y.Offset + (y - sy) / k)
                self:_clampWin()
            end)
            endConn = UIS.InputEnded:Connect(function(i)
                if i == input or i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                    moveConn:Disconnect()
                    endConn:Disconnect()
                end
            end)
        end)

        -- the open page
        self._body = mk("Frame", { Position = UDim2.fromOffset(LITE_SIDE, LITE_HEAD + 1), Size = UDim2.new(1, -LITE_SIDE, 1, -(LITE_HEAD + 1)), BackgroundTransparency = 1, ClipsDescendants = true }, win)

        -- the grip in the bottom right corner resizes the window (smaller or larger)
        self._w, self._h = LITE_W, LITE_H
        local grip = mk("TextButton", { AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -3, 1, -3), Size = UDim2.fromOffset(18, 18), BackgroundTransparency = 1,
            Text = "//", TextSize = 12, Font = Enum.Font.GothamBold, AutoButtonColor = false, ZIndex = 50 }, win)
        self:_paint(grip, "TextColor3", "faint")
        self._grip = grip
        grip.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            self:_closePopup()
            local sx, sy = pointer(input)
            local w0, h0, p0 = win.Size.X.Offset, win.Size.Y.Offset, win.Position
            local moveConn, endConn
            moveConn = UIS.InputChanged:Connect(function(i)
                if i.UserInputType ~= Enum.UserInputType.MouseMovement and i.UserInputType ~= Enum.UserInputType.Touch then return end
                local x, y = pointer(i)
                local k, g = self._k, self._g
                local nw = clamp(w0 + (x - sx) / k, 560, math.max(560, g.sw - 24))
                local nh = clamp(h0 + (y - sy) / k, 340, math.max(340, g.sh - 24))
                nw, nh = math.floor(nw / 2) * 2, math.floor(nh / 2) * 2
                self._w, self._h, self._moved = nw, nh, true
                win.Size = UDim2.fromOffset(nw, nh)
                -- the window is anchored at its centre: move the centre so the top left corner stays where it was
                win.Position = UDim2.fromOffset(p0.X.Offset + (nw - w0) / 2, p0.Y.Offset + (nh - h0) / 2)
                g.setW = (nw - LITE_SIDE - 52) / 2
            end)
            endConn = UIS.InputEnded:Connect(function(i)
                if i == input or i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                    moveConn:Disconnect()
                    endConn:Disconnect()
                end
            end)
        end)

        -- the glass is Starlight's own acrylic (its AcrylicPaint): a blurred glass part behind the window, the frosted
        -- frame on the window, and the see-through panels. getgenv().KiciaLiteAcrylic = false leaves it out.
        if getgenv().KiciaLiteAcrylic ~= false then self:_makeGlass() end
        self:_applyGlass(self._glass ~= nil)
        -- the glass part lives in the camera, outside the menu's gui: while the menu is closed it must be off, and a
        -- new camera (a new match) leaves the old part behind, so it is made again there
        task.spawn(function()
            while not self._destroyed do
                task.wait(.5)
                if self._destroyed then break end
                local glass = self._glass
                if glass ~= nil and not glass.Model:IsDescendantOf(workspace) then
                    pcall(function() glass.Frame:Destroy() end)
                    self._glass, self._glassShown = nil, nil
                    K._liteAcrylic = nil
                    self:_makeGlass()
                    self:_applyGlass(self._glassOn ~= false and self._glass ~= nil)
                end
                self:_setGlassShown(self._glassOn == true and gui.Enabled and win.GroupTransparency < 1)
            end
        end)

        liteFont(win)
        dim.Activated:Connect(function() self:_closePopup() end)
        gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() self:_relayout() end)
        self:_relayout()
    end

    -- one glass: Starlight's AcrylicPaint (its model sits in the camera's "Starlight Blur Elements" folder)
    function SLite:_makeGlass()
        pcall(function()
            local acr = K._liteAcrylic
            if acr == nil then
                acr = K.StarlightAcrylic()
                pcall(acr.Init)
                K._liteAcrylic = acr
            end
            -- Init clones the game's own DepthOfField, which can be switched off (as in Rivals) and then blurs
            -- nothing; the blur behind the glass part is near-field only, so far blur stays at 0
            local blur = game:GetService("Lighting"):FindFirstChild("starlightBlur")
            if blur ~= nil then
                blur.Enabled = true
                blur.FarIntensity = 0
                blur.NearIntensity = 1
            end
            local paint = acr.AcrylicPaint()
            if paint.Model == nil then
                paint.Frame:Destroy()
                return
            end
            paint.AddParent(self._win)
            paint.Frame.Parent = self._win
            paint.Model.Size = Vector3.new(1.0, 1.032, 0.001)
            local shadow = paint.Frame:FindFirstChild("shadow")
            if shadow ~= nil then shadow.Visible = false end
            self._glass, self._glassShown = paint, nil
            -- off until the menu is shown
            self:_setGlassShown(false)
        end)
    end

    -- the glass part draws (and blurs the game) only while the menu is on screen
    function SLite:_setGlassShown(on)
        local glass = self._glass
        if glass == nil or self._glassShown == on then return end
        self._glassShown = on
        pcall(glass.SetVisibility, on)
        if not on then pcall(function() glass.Model.Transparency = 1 end) end
    end

    -- Starlight's acrylic mode: the window 0.6, the sidebar 0.45 and the top bar 0.5 transparent, glass behind them
    function SLite:_applyGlass(on)
        local glass = self._glass
        on = on == true and glass ~= nil
        self._glassOn = on
        self._win.BackgroundTransparency = on and .6 or 0
        self._side.BackgroundTransparency = on and .45 or 0
        self._head.BackgroundTransparency = on and .5 or 0
        if glass ~= nil then
            glass.Frame.Visible = on
            self:_setGlassShown(on and self._gui.Enabled)
        end
    end

    -- fold the window up to its title bar (or open it again); the top edge stays where it is
    function SLite:_setCollapsed(on)
        local win, g = self._win, self._g
        if win == nil or g == nil then return end
        self:_closePopup()
        self._collapsed = on
        local w, oldH = win.Size.X.Offset, win.Size.Y.Offset
        local newH = on and (LITE_HEAD + 1) or math.min(self._h or LITE_H, g.sh - 24)
        local p = win.Position
        tween(win, .2, { Size = UDim2.fromOffset(w, newH), Position = UDim2.fromOffset(p.X.Offset, p.Y.Offset + (newH - oldH) / 2) }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
        self._grip.Visible = not on
        self._miniBtn.Text = on and "+" or "-"
    end

    function SLite:Destroy()
        -- the glass part lives in the camera, not in the menu's gui
        pcall(function() if self._glass ~= nil then self._glass.Model:Destroy() end end)
        SMenu.Destroy(self)
    end

    function SLite:_clampWin()
        local g, win = self._g, self._win
        if g == nil or win == nil then return end
        local p = win.Position
        win.Position = UDim2.fromOffset(math.floor(clamp(p.X.Offset, 90, math.max(90, g.sw - 90))), math.floor(clamp(p.Y.Offset, 40, math.max(40, g.sh - 40))))
    end

    function SLite:_relayout()
        local gui = self._gui
        local vw, vh = gui.AbsoluteSize.X, gui.AbsoluteSize.Y
        if vw <= 0 or vh <= 0 then
            local cam = workspace.CurrentCamera
            if cam == nil then return end
            vw, vh = cam.ViewportSize.X, cam.ViewportSize.Y
        end
        if vw <= 0 or vh <= 0 then return end
        -- no scaling unless the window does not fit: a fractional UIScale is what makes text blurry
        local k = clamp(math.min(1, (vw - 24) / LITE_W, (vh - 24) / LITE_H), .6, 1)
        k = math.floor(k * 20) / 20
        self._k = k
        self._uiscale.Scale = k
        local sw, sh = vw / k, vh / k
        self._stage.Size = UDim2.fromOffset(sw, sh)
        -- whole, even pixels (the window is centred on its anchor): half a pixel blurs every glyph
        local w = math.floor(math.min(self._w or LITE_W, sw - 24) / 2) * 2
        local h = math.floor(math.min(self._h or LITE_H, sh - 24) / 2) * 2
        if self._collapsed then h = LITE_HEAD + 1 end
        self._win.Size = UDim2.fromOffset(w, h)
        self._g = { sw = sw, sh = sh, cx = sw / 2, cy = sh / 2, setW = (w - LITE_SIDE - 56) / 2, panelW = LITE_SIDE }
        if self._moved then
            self:_clampWin()
        else
            self._win.Position = UDim2.fromOffset(math.floor(sw / 2), math.floor(sh / 2))
        end
        self:_closePopup()
    end

    function SLite:AddTab(o)
        o = o or {}
        local tab = setmetatable({ _menu = self, Label = tostring(o.Label or "Tab"), Icon = o.Icon or false, _pages = {} }, STab)
        local sec = mk("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, BorderSizePixel = 0, LayoutOrder = #self._tabs + 1 }, self._sideList)
        mk("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }, sec)
        local head = text(self, sec, tab.Label, 12, "dim", false)
        head.Size = UDim2.new(1, 0, 0, 28)
        head.LayoutOrder = 0
        mk("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingTop = UDim.new(0, 8) }, head)
        tab._sec = sec
        self._tabs[#self._tabs + 1] = tab
        return tab
    end

    -- the sidebar button of a page
    function SLite:_makePageRow(tab, page)
        local m = self
        local btn = mk("TextButton", { Size = UDim2.new(1, 0, 0, 34), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, LayoutOrder = #tab._pages, BorderSizePixel = 0 }, tab._sec)
        corner(btn, 7)
        local hover = mk("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0 }, btn)
        corner(hover, 7)
        m:_paint(hover, "BackgroundColor3", "hover")
        local sel = mk("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = .72, BorderSizePixel = 0, Visible = false }, btn)
        corner(sel, 7)
        m:_paint(sel, "BackgroundColor3", "sel")
        -- Starlight's selected tab: an Accents.Main gradient outline, the icon and the name in the Brighter gradient
        local selStroke = mk("UIStroke", { Thickness = 1, Transparency = .35 }, sel)
        m:_paint(selStroke, "Color", "fill")
        m:_grad(selStroke, "Main")
        local img = imageOf(page.Icon)
        local icon = mk("ImageLabel", { Position = UDim2.fromOffset(12, 6), Size = UDim2.fromOffset(22, 22), BackgroundTransparency = 1, Image = img, Visible = img ~= "", ZIndex = 2 }, btn)
        m:_paint(icon, "ImageColor3", "dim")
        local lbl = text(m, btn, page.Label, 14, "dim", false)
        lbl.Position = UDim2.fromOffset(img ~= "" and 44 or 14, 0)
        lbl.Size = UDim2.new(1, -44, 1, 0)
        lbl.TextTruncate = Enum.TextTruncate.AtEnd
        lbl.ZIndex = 2
        local row = { btn = btn, sel = sel, lbl = lbl }
        local lblGrad, iconGrad = m:_grad(lbl, "Brighter"), m:_grad(icon, "Brighter")
        local function tint()
            local on = m._page == page
            lbl.TextColor3 = on and m._pal.fill or m._pal.dim
            icon.ImageColor3 = on and m._pal.fill or m._pal.dim
            if lblGrad then lblGrad.Enabled = on end
            if iconGrad then iconGrad.Enabled = on end
        end
        tint()
        m:_onTheme(row, tint)
        btn.MouseEnter:Connect(function() tween(hover, .12, { BackgroundTransparency = .55 }) tween(lbl, .12, { TextColor3 = m._pal.text }) end)
        btn.MouseLeave:Connect(function() tween(hover, .12, { BackgroundTransparency = 1 }) tint() end)
        btn.Activated:Connect(function() task.spawn(function() m:_openPage(page) end) end)
        row.tint = tint
        page._row = row
    end

    -- a page is one or two columns of cards (a card is a section: its header and its rows), like Starlight's groupboxes
    function SLite:_makeHost(page)
        local sc = mk("ScrollingFrame", {
            Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3,
            CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y, Visible = false,
        }, self._body)
        self:_paint(sc, "ScrollBarImageColor3", "acc")
        mk("UIPadding", { PaddingTop = UDim.new(0, 11), PaddingBottom = UDim.new(0, 14), PaddingLeft = UDim.new(0, 11), PaddingRight = UDim.new(0, 11) }, sc)
        local wrap = mk("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, BorderSizePixel = 0 }, sc)
        mk("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 12), SortOrder = Enum.SortOrder.LayoutOrder, VerticalAlignment = Enum.VerticalAlignment.Top }, wrap)
        local n = (page._columns or 2) >= 2 and 2 or 1
        local cols = {}
        for i = 1, n do
            local c = mk("Frame", { Size = UDim2.new(1 / n, -12 * (n - 1) / n, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, BorderSizePixel = 0, LayoutOrder = i }, wrap)
            mk("UIListLayout", { Padding = UDim.new(0, 12), SortOrder = Enum.SortOrder.LayoutOrder }, c)
            cols[i] = c
        end
        page._cols = cols
        return sc
    end

    function SLite:_sectionHost(sec)
        local page = sec._page
        page:_ensureScroll()
        local cols = page._cols
        local idx = 1
        if #cols > 1 then
            if sec._side == "right" then
                idx = 2
            elseif sec._side ~= "left" then
                idx = (sec._order % 2 == 1) and 1 or 2
            end
        end
        local card = mk("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BorderSizePixel = 0, LayoutOrder = sec._order }, cols[idx])
        self:_paint(card, "BackgroundColor3", "box")
        corner(card, 10)
        local st = mk("UIStroke", { Thickness = 1, Transparency = .4 }, card)
        self:_paint(st, "Color", "outline")
        mk("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, HorizontalAlignment = Enum.HorizontalAlignment.Center }, card)
        mk("UIPadding", { PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 8), PaddingLeft = UDim.new(0, 4), PaddingRight = UDim.new(0, 4) }, card)
        return card
    end

    ----------------------------------------------------------------------------------------------- Lite theme
    -- A copy of Starlight's theme handling: the same theme tables (the library's own, Starlight.Themes), the same
    -- CurrentTheme shape, themes saved as files next to the library's other themes, "autoload.txt" naming the theme
    -- to load on the next start, and the same Theme page.
    local HttpSvc = game:GetService("HttpService")
    local THEME_ORDER = { "Starlight", "Hollywood Dark", "Hollywood Light", "Orca", "Glacier", "Pacific", "Neo", "Neo (Dark)", "Crimson", "Nebula",
        "Evergreen", "Luna", "OperaGX", "BBot", "Ubuntu", "Tokyo Night", "Hollywood Fluent", "Catppuccin Mocha", "Catppuccin Macchiato",
        "Catppuccin Frappe", "Catppuccin Latte" }

    local function copyTheme(v)
        if type(v) ~= "table" then return v end
        local out = {}
        for k, x in pairs(v) do out[k] = copyTheme(x) end
        return out
    end

    -- the same JSON as Starlight's encodeTheme / decodeTheme
    local function themeToJson(theme)
        local function ser(d)
            if typeof(d) == "Color3" then
                return { __type = "Color3", R = d.R * 255, G = d.G * 255, B = d.B * 255 }
            elseif typeof(d) == "ColorSequence" then
                local kps = {}
                for _, kp in ipairs(d.Keypoints) do
                    kps[#kps + 1] = { Time = kp.Time, Value = { R = kp.Value.R * 255, G = kp.Value.G * 255, B = kp.Value.B * 255 } }
                end
                return { __type = "ColorSequence", Keypoints = kps }
            elseif type(d) == "table" then
                local out = {}
                for k, x in pairs(d) do out[k] = ser(x) end
                return out
            end
            return d
        end
        local ok, enc = pcall(HttpSvc.JSONEncode, HttpSvc, ser(theme))
        if ok then return enc end
        return nil
    end

    local function themeFromJson(text)
        local function de(v)
            if type(v) == "table" then
                if v.__type == "Color3" then
                    return Color3.fromRGB(v.R, v.G, v.B)
                elseif v.__type == "ColorSequence" then
                    local kps = {}
                    for _, kp in ipairs(v.Keypoints) do
                        kps[#kps + 1] = ColorSequenceKeypoint.new(kp.Time, Color3.fromRGB(kp.Value.R, kp.Value.G, kp.Value.B))
                    end
                    return ColorSequence.new(kps)
                end
                local out = {}
                for k, x in pairs(v) do out[k] = de(x) end
                return out
            end
            return v
        end
        local ok, dec = pcall(HttpSvc.JSONDecode, HttpSvc, text)
        if not ok or type(dec) ~= "table" then return nil end
        local t = de(dec)
        if type(t.Backgrounds) ~= "table" or type(t.Foregrounds) ~= "table" or type(t.Miscellaneous) ~= "table" or type(t.Accents) ~= "table" then return nil end
        return t
    end

    -- used only when the library's own list cannot be reached
    local function fallbackTheme()
        local function seq(a, b, c) return ColorSequence.new({ ColorSequenceKeypoint.new(0, a), ColorSequenceKeypoint.new(.5, b), ColorSequenceKeypoint.new(1, c) }) end
        return {
            Backgrounds = { Dark = Color3.fromRGB(23, 25, 29), Medium = Color3.fromRGB(27, 29, 33), Light = Color3.fromRGB(33, 34, 38),
                Groupbox = Color3.fromRGB(33, 36, 42), Highlight = Color3.fromRGB(17, 19, 22) },
            Foregrounds = { Active = Color3.new(1, 1, 1), Light = Color3.new(1, 1, 1), Medium = Color3.fromRGB(165, 165, 165), Dark = Color3.fromRGB(65, 69, 77),
                MediumHover = Color3.fromRGB(185, 185, 185), DarkHover = Color3.fromRGB(85, 89, 97) },
            Miscellaneous = { Divider = Color3.fromRGB(117, 128, 149), Shadow = Color3.fromRGB(19, 21, 24), LighterShadow = Color3.fromRGB(24, 25, 30) },
            Accents = { Main = seq(Color3.fromRGB(230, 186, 251), Color3.fromRGB(161, 169, 225), Color3.fromRGB(138, 201, 242)),
                Brighter = seq(Color3.fromRGB(241, 212, 251), Color3.fromRGB(187, 192, 225), Color3.fromRGB(195, 227, 242)) },
        }
    end

    local function ensureFolder(path)
        local acc = ""
        for part in string.gmatch(path, "[^/]+") do
            acc = acc == "" and part or (acc .. "/" .. part)
            if not isfolder(acc) then makefolder(acc) end
        end
    end

    -- runs from newMenu, before the palette is made
    function SLite:_initTheme()
        local ok, L = pcall(function() return StarUI.Load(false) end)
        local lib = ok and type(L) == "table" and L or nil
        self._themes = lib ~= nil and type(lib.Themes) == "table" and lib.Themes or {}
        local fs = lib ~= nil and lib.FileSystem or nil
        self._themeExt = fs ~= nil and fs.FileExtension or ".starlight"
        self._themeDir = (fs ~= nil and fs.Folder or "Starlight Interface Suite") .. "/LxYHook/themes"
        self._themeName = "Starlight"
        local base = self._themes.Starlight
        self._theme = base ~= nil and copyTheme(base) or fallbackTheme()
        -- Starlight:LoadAutoloadTheme: autoload.txt names a built-in theme or a saved one
        pcall(function()
            if not isfile(self._themeDir .. "/autoload.txt") then return end
            local name = readfile(self._themeDir .. "/autoload.txt")
            local t = self._themes[name]
            if t == nil then t = themeFromJson(readfile(self._themeDir .. "/" .. name .. self._themeExt)) end
            if type(t) == "table" and type(t.Backgrounds) == "table" then
                self._theme = copyTheme(t)
                self._themeName = name
            end
        end)
    end

    function SLite:_setTheme(theme, name)
        self._theme = copyTheme(theme)
        if name ~= nil then self._themeName = name end
        self:_applyPalette()
        for _, e in ipairs(self._themeCtls or {}) do
            pcall(function() e.ctl:Set(e.get(), true) end)
        end
    end

    -- the built-in themes, then the saved ones (the library's RefreshConfigList)
    function SLite:_themeNames()
        local names = {}
        for _, n in ipairs(THEME_ORDER) do
            if self._themes[n] ~= nil then names[#names + 1] = n end
        end
        pcall(function()
            local ext = self._themeExt
            for _, f in ipairs(listfiles(self._themeDir)) do
                local file = string.match(f, "([^/\\]+)$")
                if file ~= nil and string.sub(file, -#ext) == ext then names[#names + 1] = string.sub(file, 1, #file - #ext) end
            end
        end)
        return names
    end

    -- Starlight's Theme page: its colours, then creating, applying, overwriting, autoloading and deleting themes
    function SLite:_buildThemePage(page)
        local m = self
        -- one groupbox, in the order of Starlight's own Theme page
        local colors = newSSection(page, { Title = K.T("Themes") })
        local manage = colors
        self._themeCtls = {}
        pcall(ensureFolder, self._themeDir)
        if self._glass ~= nil then
            manage:_make("Toggle", { Label = "Acrylic", Default = self._glassOn == true, OnChanged = function(v) m:_applyGlass(v) end })
        end
        manage:_make("Divider", {})

        local function color(host, group, key, idx)
            local function get()
                local v = m._theme[group][key]
                if idx ~= nil then return v.Keypoints[idx].Value end
                return v
            end
            local c = colors:_make("Color", { Row = host, Default = get() })
            if type(c) ~= "table" or c.OnChanged == nil then return end
            c:OnChanged(function(val)
                local rgb = val.Rgb
                if idx ~= nil then
                    local kps = {}
                    for i, kp in ipairs(m._theme[group][key].Keypoints) do
                        kps[i] = ColorSequenceKeypoint.new(kp.Time, i == idx and rgb or kp.Value)
                    end
                    m._theme[group][key] = ColorSequence.new(kps)
                else
                    m._theme[group][key] = rgb
                end
                m:_applyPalette()
            end)
            m._themeCtls[#m._themeCtls + 1] = { ctl = c, get = get }
        end
        -- one label with its swatches on the right, as Starlight lays the page out
        local function swatches(title, items)
            local host = colors:_make("Label", { Label = title })
            for _, it in ipairs(items) do color(host, it[1], it[2], it[3]) end
        end
        swatches("Backgrounds", { { "Backgrounds", "Dark" }, { "Backgrounds", "Medium" }, { "Backgrounds", "Light" }, { "Backgrounds", "Groupbox" }, { "Backgrounds", "Highlight" } })
        swatches("Foregrounds", { { "Foregrounds", "Dark" }, { "Foregrounds", "Medium" }, { "Foregrounds", "Light" }, { "Foregrounds", "Active" } })
        swatches("Foreground Hovers", { { "Foregrounds", "DarkHover" }, { "Foregrounds", "MediumHover" } })
        swatches("Divider", { { "Miscellaneous", "Divider" } })
        swatches("Shadows", { { "Miscellaneous", "Shadow" }, { "Miscellaneous", "LighterShadow" } })
        swatches("Accent", { { "Accents", "Main", 1 }, { "Accents", "Main", 2 }, { "Accents", "Main", 3 } })
        swatches("Accent Brighter", { { "Accents", "Brighter", 1 }, { "Accents", "Brighter", 2 }, { "Accents", "Brighter", 3 } })

        local path, ext = self._themeDir, self._themeExt
        local function say(text) notify(text) end
        local selected = self._themeName
        local function autoloadName()
            local ok, name = pcall(function()
                if isfile(path .. "/autoload.txt") then return readfile(path .. "/autoload.txt") end
            end)
            return ok and name or nil
        end

        manage:_make("Divider", {})
        local nameBox = manage:_make("TextBox", { Label = "New Theme Name", Placeholder = "Name" })
        local list
        local function refresh(keep)
            if list ~= nil then
                list:SetOptions(m:_themeNames())
                if keep ~= nil then list:Set(keep, true) end
            end
        end
        manage:_make("Button", { Label = "Create New Theme", OnClick = function()
            local name = tostring(nameBox.Value or "")
            name = string.gsub(string.gsub(name, "/", " "), "\\", " ")
            if string.match(name, "^%s*$") then say("Theme name cannot be empty.") return end
            if m._themes[name] ~= nil or isfile(path .. "/" .. name .. ext) then
                say("Theme with the provided name exists already. Overwrite it with Overwrite Theme below.")
                return
            end
            local json = themeToJson(m._theme)
            local ok = json ~= nil and pcall(writefile, path .. "/" .. name .. ext, json)
            if not ok then say("Unable to save the theme.") return end
            refresh()
            say(string.format("Created Theme %q", name))
        end })
        list = manage:_make("Dropdown", { Label = "Themes List", Options = self:_themeNames(), Default = selected, SelectFirst = false })
        if type(list) == "table" and list.OnChanged ~= nil then
            list:OnChanged(function(v) selected = v end)
        end
        local function apply(name)
            local t = m._themes[name]
            if t == nil then
                local ok, text = pcall(readfile, path .. "/" .. name .. ext)
                t = ok and themeFromJson(text) or nil
            end
            if t == nil then say("That theme could not be loaded.") return end
            m:_setTheme(t, name)
        end
        manage:_make("Button", { Label = "Apply Theme", Style = 1, OnClick = function()
            if selected == nil then say("Theme must be selected!") return end
            apply(selected)
        end })
        manage:_make("Button", { Label = "Overwrite Theme", OnClick = function()
            if selected == nil then say("Theme must be selected!") return end
            if m._themes[selected] ~= nil then say("Only a custom theme can be overwritten!") return end
            local json = themeToJson(m._theme)
            if json ~= nil and pcall(writefile, path .. "/" .. selected .. ext, json) then
                say(string.format("Overwrote theme %q", selected))
            else
                say("Unable to overwrite the theme.")
            end
        end })
        local loadLabel = manage:_make("Label", { Label = "Current Autoload Theme: " .. (autoloadName() or "None") })
        manage:_make("Button", { Label = "Autoload Theme", Style = 1, OnClick = function()
            if selected == nil then say("Theme must be selected!") return end
            pcall(writefile, path .. "/autoload.txt", selected)
            loadLabel:Set("Current Autoload Theme: " .. selected)
            say(string.format("Set %q to be automatically loaded on your future sessions.", selected))
        end })
        manage:_make("Button", { Label = "Reset Autoload", OnClick = function()
            pcall(function() if isfile(path .. "/autoload.txt") then delfile(path .. "/autoload.txt") end end)
            loadLabel:Set("Current Autoload Theme: None")
            say("Disabled current autoload.")
        end })
        manage:_make("Button", { Label = "Delete Theme", OnClick = function()
            if selected == nil then say("Theme must be selected!") return end
            if m._themes[selected] ~= nil then say("Only a custom theme can be deleted!") return end
            pcall(function() if isfile(path .. "/" .. selected .. ext) then delfile(path .. "/" .. selected .. ext) end end)
            if autoloadName() == selected then
                pcall(delfile, path .. "/autoload.txt")
                loadLabel:Set("Current Autoload Theme: None")
            end
            say(string.format("Deleted theme %q", selected))
            selected = nil
            refresh()
        end })
    end

    -- the script's own theme tokens and accent do not touch the Lite colours: they come from the Starlight theme
    function SLite:_hookTheme() end
    function SLite:_setAccent() end

    function SLite:_openPage(page)
        if self._destroyed then return end
        self:_closePopup()
        self._page = page
        for _, tab in ipairs(self._tabs) do
            for _, p in ipairs(tab._pages) do
                if p._row ~= nil then
                    p._row.sel.Visible = p == page
                    p._row.tint()
                end
                if p ~= page and p._scroll ~= nil then p._scroll.Visible = false end
            end
        end
        local tab = page._tab
        self._hdrTitle.Text = (tab ~= nil and tab.Label ~= page.Label) and (tab.Label .. "  /  " .. page.Label) or page.Label
        page:_realize()
        -- building a page can yield; if another page was opened meanwhile, this one stays hidden
        if self._page ~= page then return end
        liteFont(page._scroll)
        page._scroll.Visible = true
        page._scroll.CanvasPosition = Vector2.zero
    end

    -- the popups (a dropdown's list, a colour picker) are made later: their text gets the font too
    function SLite:_fontPass(root) liteFont(root) end

    function SLite:SetVisible(visible, instant)
        visible = visible and true or false
        if self._destroyed then return true end
        local was = self.Visible
        self:_closePopup()
        local win, scale = self._win, self._winScale
        self._fadeTok = (self._fadeTok or 0) + 1
        local tok = self._fadeTok
        if visible then
            self._gui.Enabled = true
            self._dim.Modal = true
            K.MenuOpen = true
            self:_relayout()
            if self._page == nil then
                local first = self._tabs[1] ~= nil and self._tabs[1]._pages[1] or nil
                if first ~= nil then task.spawn(function() self:_openPage(first) end) end
            end
            if instant then
                win.GroupTransparency = 0
                scale.Scale = 1
                self._dim.BackgroundTransparency = .6
            else
                if not was then
                    win.GroupTransparency = 1
                    scale.Scale = .965
                    self._dim.BackgroundTransparency = 1
                end
                tween(win, .24, { GroupTransparency = 0 }, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
                tween(scale, .28, { Scale = 1 }, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
                tween(self._dim, .24, { BackgroundTransparency = .6 }, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
            end
        else
            -- a Modal button keeps the mouse free for as long as it is Modal, even in a disabled gui
            self._dim.Modal = false
            K.MenuOpen = false
            if instant or not self._gui.Enabled then
                win.GroupTransparency = 1
                self._dim.BackgroundTransparency = 1
                self._gui.Enabled = false
            else
                tween(win, .16, { GroupTransparency = 1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.In)
                tween(scale, .16, { Scale = .965 }, Enum.EasingStyle.Sine, Enum.EasingDirection.In)
                tween(self._dim, .16, { BackgroundTransparency = 1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.In)
                task.delay(.18, function()
                    if self._fadeTok == tok and not self._destroyed then self._gui.Enabled = false end
                end)
            end
        end
        self:_setVisibleState(visible)
        return true
    end

    ----------------------------------------------------------------------------------------------- Matcha
    -- Fifth form of the menu: the flat "Matcha" look. A 600 x 650 window with a header (brand, style pill, user
    -- name), a row of tabs under it and, for a tab with several pages, a row of page pills; the open page is two
    -- columns of cards. It reuses the Lite form's widgets, cards, theme page and fade (it is a Lite with another
    -- shell), so every page builder works unchanged. Colours come from a flat theme (near-black greys, a muted
    -- matcha green accent); Options > Theme can still switch to any of the Starlight themes.
    local MATCHA_W, MATCHA_H, MATCHA_HEAD = 600, 650, 38

    local SMatcha = {}
    SMatcha.__lite = true
    SMatcha.__index = function(t, k)
        local v = rawget(SMatcha, k)
        if v ~= nil then return v end
        v = rawget(SLite, k)
        if v ~= nil then return v end
        v = rawget(SMenu, k)
        if v ~= nil then return v end
        if isMethodName(k) then return function() return nil end end
        return nil
    end
    SetsunaUI.Matcha = SMatcha
    function SMatcha.new(opts) return newMenu(SMatcha, opts) end

    local function matchaTheme()
        local function rgb(r, g, b) return Color3.fromRGB(r, g, b) end
        local function flat(c) return ColorSequence.new(c) end
        return {
            Backgrounds = { Dark = rgb(14, 14, 16), Medium = rgb(19, 19, 22), Light = rgb(14, 14, 16), Groupbox = rgb(26, 26, 30), Highlight = rgb(30, 30, 35) },
            Foregrounds = { Active = rgb(255, 255, 255), Light = rgb(228, 228, 232), Medium = rgb(125, 125, 132), Dark = rgb(48, 48, 54),
                MediumHover = rgb(160, 160, 166), DarkHover = rgb(66, 66, 73) },
            Miscellaneous = { Divider = rgb(38, 38, 43), Shadow = rgb(34, 34, 39), LighterShadow = rgb(26, 26, 30) },
            Accents = { Main = flat(rgb(160, 205, 140)), Brighter = flat(rgb(200, 232, 184)) },
        }
    end

    -- runs from newMenu, before the palette is made. No library download: the theme page works on this one theme
    -- plus the saved theme files.
    function SMatcha:_initTheme()
        self._theme = matchaTheme()
        self._themes = { Matcha = matchaTheme() }
        self._themeExt = ".starlight"
        self._themeDir = "Starlight Interface Suite/LxYHook/themes"
        self._themeName = "Matcha"
    end

    function SMatcha:_themeNames()
        local names = SLite._themeNames(self)
        table.insert(names, 1, "Matcha")
        return names
    end

    function SMatcha:_fontPass() end

    function SMatcha:_buildShell()
        local gui = mk("ScreenGui", { Name = "Matcha Interface", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 100000,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling, Enabled = false })
        local placed = pcall(function() gui.Parent = gethui() end)
        if not placed or gui.Parent == nil then gui.Parent = game:GetService("CoreGui") end
        self._gui = gui
        local dim = mk("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, BorderSizePixel = 0, Modal = false }, gui)
        self._dim = dim
        local stage = mk("Frame", { BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 1 }, gui)
        self._stage = stage
        self._uiscale = mk("UIScale", {}, stage)

        local win = mk("CanvasGroup", { AnchorPoint = Vector2.new(.5, .5), Size = UDim2.fromOffset(MATCHA_W, MATCHA_H), BorderSizePixel = 0,
            ZIndex = 5, GroupTransparency = 1, Active = true }, stage)
        self:_paint(win, "BackgroundColor3", "panel")
        corner(win, 10)
        local wst = mk("UIStroke", { Thickness = 1, Transparency = 0 }, win)
        self:_paint(wst, "Color", "outline")
        self._win = win
        self._winScale = mk("UIScale", { Scale = .965 }, win)
        self._ctlW = { dd = 112, tb = 104 }
        self._w, self._h = MATCHA_W, MATCHA_H

        -- header: brand, style pill, user name; also the drag handle
        local me = game:GetService("Players").LocalPlayer
        local head = mk("Frame", { Size = UDim2.new(1, 0, 0, MATCHA_HEAD), BackgroundTransparency = 1, BorderSizePixel = 0, Active = true }, win)
        self._head = head
        local brand = text(self, head, "Matcha", 12, "text", true)
        brand.Position, brand.Size = UDim2.fromOffset(16, 0), UDim2.fromOffset(50, MATCHA_HEAD)
        local sub = text(self, head, "Interface", 11, "dim", false)
        sub.Position, sub.Size = UDim2.fromOffset(70, 0), UDim2.fromOffset(60, MATCHA_HEAD)
        local pill = mk("Frame", { Position = UDim2.fromOffset(132, 9), Size = UDim2.fromOffset(62, 20), BorderSizePixel = 0 }, head)
        self:_paint(pill, "BackgroundColor3", "box")
        corner(pill, 10)
        local pst = mk("UIStroke", { Thickness = 1 }, pill)
        self:_paint(pst, "Color", "outline")
        local pt = text(self, pill, "Standard", 10, "text", false)
        pt.Size, pt.TextXAlignment = UDim2.fromScale(1, 1), Enum.TextXAlignment.Center
        local who = text(self, head, me and me.Name or "", 11, "text", false)
        who.Position, who.Size = UDim2.new(1, -176, 0, 0), UDim2.fromOffset(160, MATCHA_HEAD)
        who.TextXAlignment = Enum.TextXAlignment.Right
        who.TextTruncate = Enum.TextTruncate.AtEnd
        head.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            self:_closePopup()
            local sx, sy = pointer(input)
            local start = win.Position
            local moveConn, endConn
            moveConn = UIS.InputChanged:Connect(function(i)
                if i.UserInputType ~= Enum.UserInputType.MouseMovement and i.UserInputType ~= Enum.UserInputType.Touch then return end
                local x, y = pointer(i)
                local k = self._k
                self._moved = true
                win.Position = UDim2.fromOffset(start.X.Offset + (x - sx) / k, start.Y.Offset + (y - sy) / k)
                self:_clampWin()
            end)
            endConn = UIS.InputEnded:Connect(function(i)
                if i == input or i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                    moveConn:Disconnect()
                    endConn:Disconnect()
                end
            end)
        end)

        -- navigation: the tab row, then (for a tab with several pages) its page pills; both wrap onto more lines
        local nav = mk("Frame", { Position = UDim2.fromOffset(0, MATCHA_HEAD), Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1, BorderSizePixel = 0 }, win)
        mk("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, nav)
        mk("UIPadding", { PaddingLeft = UDim.new(0, 16), PaddingRight = UDim.new(0, 16), PaddingTop = UDim.new(0, 2), PaddingBottom = UDim.new(0, 4) }, nav)
        local tabBar = mk("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, BorderSizePixel = 0, LayoutOrder = 1 }, nav)
        mk("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Wraps = true, Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }, tabBar)
        self._nav, self._tabBar = nav, tabBar

        -- the open page: below the navigation, whose height changes with the tab
        local body = mk("Frame", { BackgroundTransparency = 1, ClipsDescendants = true, BorderSizePixel = 0 }, win)
        self._body = body
        local function place()
            local y = MATCHA_HEAD + math.floor(nav.AbsoluteSize.Y / (self._k or 1) + .5)
            body.Position = UDim2.fromOffset(0, y)
            body.Size = UDim2.new(1, 0, 1, -y)
        end
        nav:GetPropertyChangedSignal("AbsoluteSize"):Connect(place)
        self._placeBody = place
        place()

        dim.Activated:Connect(function() self:_closePopup() end)
        gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() self:_relayout() end)
        self:_relayout()
    end

    function SMatcha:_relayout()
        local gui = self._gui
        local vw, vh = gui.AbsoluteSize.X, gui.AbsoluteSize.Y
        if vw <= 0 or vh <= 0 then
            local cam = workspace.CurrentCamera
            if cam == nil then return end
            vw, vh = cam.ViewportSize.X, cam.ViewportSize.Y
        end
        if vw <= 0 or vh <= 0 then return end
        -- no scaling unless the window does not fit: a fractional UIScale is what makes text blurry
        local k = clamp(math.min(1, (vw - 24) / MATCHA_W, (vh - 24) / MATCHA_H), .5, 1)
        k = math.floor(k * 20) / 20
        self._k = k
        self._uiscale.Scale = k
        local sw, sh = vw / k, vh / k
        self._stage.Size = UDim2.fromOffset(sw, sh)
        local w = math.floor(math.min(self._w or MATCHA_W, sw - 24) / 2) * 2
        local h = math.floor(math.min(self._h or MATCHA_H, sh - 24) / 2) * 2
        self._win.Size = UDim2.fromOffset(w, h)
        self._g = { sw = sw, sh = sh, cx = sw / 2, cy = sh / 2, setW = (w - 56) / 2, panelW = 0 }
        if self._moved then
            self:_clampWin()
        else
            self._win.Position = UDim2.fromOffset(math.floor(sw / 2), math.floor(sh / 2))
        end
        if self._placeBody then self._placeBody() end
        self:_closePopup()
    end

    -- a tab is a button in the top row; its pages are pills in a row of their own
    function SMatcha:AddTab(o)
        o = o or {}
        local m = self
        local tab = setmetatable({ _menu = self, Label = tostring(o.Label or "Tab"), Icon = o.Icon or false, _pages = {} }, STab)
        local n = #self._tabs + 1
        local btn = mk("TextButton", { Size = UDim2.fromOffset(0, 26), AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 1,
            Text = "  " .. tab.Label .. "  ", TextSize = 11, Font = Enum.Font.Gotham, AutoButtonColor = false, BorderSizePixel = 0, LayoutOrder = n }, self._tabBar)
        corner(btn, 6)
        local function tint()
            local on = m._tab == tab
            btn.BackgroundColor3 = m._pal.sel
            btn.BackgroundTransparency = on and 0 or 1
            btn.TextColor3 = on and m._pal.text or m._pal.dim
        end
        tab._tint = tint
        tint()
        self:_onTheme(tab, tint)
        btn.MouseEnter:Connect(function() if m._tab ~= tab then btn.TextColor3 = m._pal.text end end)
        btn.MouseLeave:Connect(tint)
        btn.Activated:Connect(function()
            local target = tab._lastPage or tab._pages[1]
            if target ~= nil then
                task.spawn(function() m:_openPage(target) end)
            else
                m:_showTab(tab)
            end
        end)
        local pills = mk("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, BorderSizePixel = 0,
            Visible = false, LayoutOrder = 1 + n }, self._nav)
        mk("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Wraps = true, Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }, pills)
        tab._sub = pills
        self._tabs[n] = tab
        return tab
    end

    function SMatcha:_makePageRow(tab, page)
        local m = self
        local btn = mk("TextButton", { Size = UDim2.fromOffset(0, 22), AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 1,
            Text = "  " .. page.Label .. "  ", TextSize = 10, Font = Enum.Font.Gotham, AutoButtonColor = false, BorderSizePixel = 0, LayoutOrder = #tab._pages }, tab._sub)
        corner(btn, 11)
        local st = mk("UIStroke", { Thickness = 1 }, btn)
        self:_paint(st, "Color", "outline")
        local row = { btn = btn, sel = { Visible = false } }
        function row.tint()
            local on = m._page == page
            btn.BackgroundColor3 = m._pal.sel
            btn.BackgroundTransparency = on and 0 or 1
            btn.TextColor3 = on and m._pal.text or m._pal.dim
        end
        row.tint()
        self:_onTheme(row, row.tint)
        btn.MouseEnter:Connect(function() if m._page ~= page then btn.TextColor3 = m._pal.text end end)
        btn.MouseLeave:Connect(row.tint)
        btn.Activated:Connect(function() task.spawn(function() m:_openPage(page) end) end)
        page._row = row
        -- a second page makes the pill row appear
        if #tab._pages > 1 then self:_showTab(self._tab) end
    end

    function SMatcha:_showTab(tab)
        self._tab = tab
        for _, t in ipairs(self._tabs) do
            if t._tint then t._tint() end
            t._sub.Visible = t == tab and #t._pages > 1
        end
    end

    function SMatcha:_openPage(page)
        if self._destroyed then return end
        self:_closePopup()
        self._page = page
        local tab = page._tab
        if tab ~= nil then
            tab._lastPage = page
            self:_showTab(tab)
        end
        for _, t in ipairs(self._tabs) do
            for _, p in ipairs(t._pages) do
                if p._row ~= nil then p._row.tint() end
                if p ~= page and p._scroll ~= nil then p._scroll.Visible = false end
            end
        end
        page:_realize()
        -- building a page can yield; if another page was opened meanwhile, this one stays hidden
        if self._page ~= page then return end
        page._scroll.Visible = true
        page._scroll.CanvasPosition = Vector2.zero
    end

    ----------------------------------------------------------------------------------------------- KH V2
    -- Sixth form of the menu: the "Kiciahook V2" look. A small square-cornered window with a 1 px blue frame, a thin
    -- title bar ("Kiciahook V2 | Rivals"), a row of tabs and, for a tab with several pages, a row of page tabs under
    -- it. Everything is flat dark grey with the blue accent, drawn in the Ubuntu font. The window has one fixed size (the
    -- newer KHv2UI dropped the resize handles; it only scales down to fit a small screen) and a touch screen gets a
    -- static "Open" box at the top centre. It is a Matcha with another shell and theme (square corners come from
    -- sharpCorners, set in newMenu), so it reuses the Lite widgets and every page builder works unchanged.
    ;(function() -- own function (see the end of this block): V2 must not add locals to the saturated main chunk
    local V2_W, V2_H, V2_HEAD = 520, 360, 22
    local V2_TITLE = "Kiciahook V2 | Rivals"

    local SV2 = {}
    SV2.__lite = true
    SV2.__sharp = true
    SV2.__index = function(t, k)
        local v = rawget(SV2, k)
        if v ~= nil then return v end
        v = rawget(SMatcha, k)
        if v ~= nil then return v end
        v = rawget(SLite, k)
        if v ~= nil then return v end
        v = rawget(SMenu, k)
        if v ~= nil then return v end
        if isMethodName(k) then return function() return nil end end
        return nil
    end
    SetsunaUI.V2 = SV2
    function SV2.new(opts) return newMenu(SV2, opts) end

    local function v2Theme()
        local function rgb(r, g, b) return Color3.fromRGB(r, g, b) end
        local function flat(c) return ColorSequence.new(c) end
        return {
            Backgrounds = { Dark = rgb(26, 26, 26), Medium = rgb(31, 31, 31), Light = rgb(26, 26, 26), Groupbox = rgb(24, 24, 24), Highlight = rgb(42, 42, 42) },
            Foregrounds = { Active = rgb(255, 255, 255), Light = rgb(255, 255, 255), Medium = rgb(160, 160, 160), Dark = rgb(50, 50, 50),
                MediumHover = rgb(200, 200, 200), DarkHover = rgb(70, 70, 70) },
            Miscellaneous = { Divider = rgb(50, 50, 50), Shadow = rgb(32, 32, 32), LighterShadow = rgb(24, 24, 24) },
            Accents = { Main = flat(rgb(58, 164, 210)), Brighter = flat(rgb(88, 190, 232)) },
        }
    end

    function SV2:_initTheme()
        self._theme = v2Theme()
        self._themes = { ["KH V2"] = v2Theme() }
        self._themeExt = ".starlight"
        self._themeDir = "Starlight Interface Suite/LxYHook/themes"
        self._themeName = "KH V2"
    end

    function SV2:_themeNames()
        local names = SLite._themeNames(self)
        table.insert(names, 1, "KH V2")
        return names
    end

    -- the V2 menu is drawn in Ubuntu
    function SV2:_fontPass(root)
        if root == nil then return end
        local function one(d)
            if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then d.Font = Enum.Font.Ubuntu end
        end
        one(root)
        for _, d in ipairs(root:GetDescendants()) do one(d) end
    end

    function SV2:_buildShell()
        local gui = mk("ScreenGui", { Name = "Kiciahook V2 Interface", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 100000,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling, Enabled = false })
        local placed = pcall(function() gui.Parent = gethui() end)
        if not placed or gui.Parent == nil then gui.Parent = game:GetService("CoreGui") end
        self._gui = gui
        local dim = mk("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, BorderSizePixel = 0, Modal = false }, gui)
        self._dim = dim
        local stage = mk("Frame", { BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 1 }, gui)
        self._stage = stage
        self._uiscale = mk("UIScale", {}, stage)

        local win = mk("CanvasGroup", { AnchorPoint = Vector2.new(.5, .5), Size = UDim2.fromOffset(V2_W, V2_H), BorderSizePixel = 0,
            ZIndex = 5, GroupTransparency = 1, Active = true }, stage)
        self:_paint(win, "BackgroundColor3", "panel")
        -- the 1 px frame in the accent colour
        local wst = mk("UIStroke", { Thickness = 1, Transparency = 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, win)
        self:_paint(wst, "Color", "acc")
        self._win = win
        self._winScale = mk("UIScale", { Scale = .965 }, win)
        self._ctlW = { dd = 140, tb = 130 }
        self._w, self._h = V2_W, V2_H

        -- title bar: the title, the user name, and the drag handle
        local me = game:GetService("Players").LocalPlayer
        local head = mk("Frame", { Size = UDim2.new(1, 0, 0, V2_HEAD), BorderSizePixel = 0, Active = true }, win)
        self:_paint(head, "BackgroundColor3", "top")
        self._head = head
        local title = text(self, head, V2_TITLE, 13, "text", false)
        title.Position, title.Size = UDim2.fromOffset(8, 0), UDim2.new(0.6, 0, 1, 0)
        local who = text(self, head, me and me.Name or "", 12, "dim", false)
        who.Position, who.Size = UDim2.new(0.6, 0, 0, 0), UDim2.new(0.4, -8, 1, 0)
        who.TextXAlignment = Enum.TextXAlignment.Right
        who.TextTruncate = Enum.TextTruncate.AtEnd
        local rule = mk("Frame", { Position = UDim2.new(0, 0, 1, -1), Size = UDim2.new(1, 0, 0, 1), BorderSizePixel = 0 }, head)
        self:_paint(rule, "BackgroundColor3", "outline")
        head.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            self:_closePopup()
            local sx, sy = pointer(input)
            local start = win.Position
            local moveConn, endConn
            moveConn = UIS.InputChanged:Connect(function(i)
                if i.UserInputType ~= Enum.UserInputType.MouseMovement and i.UserInputType ~= Enum.UserInputType.Touch then return end
                local x, y = pointer(i)
                local k = self._k
                self._moved = true
                win.Position = UDim2.fromOffset(start.X.Offset + (x - sx) / k, start.Y.Offset + (y - sy) / k)
                self:_clampWin()
            end)
            endConn = UIS.InputEnded:Connect(function(i)
                if i == input or i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                    moveConn:Disconnect()
                    endConn:Disconnect()
                end
            end)
        end)

        -- navigation: the tab row, then (for a tab with several pages) its page tabs; both wrap onto more lines
        local nav = mk("Frame", { Position = UDim2.fromOffset(0, V2_HEAD), Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1, BorderSizePixel = 0 }, win)
        mk("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }, nav)
        mk("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6), PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 2) }, nav)
        local tabBar = mk("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, BorderSizePixel = 0, LayoutOrder = 1 }, nav)
        mk("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Wraps = true, Padding = UDim.new(0, 3), SortOrder = Enum.SortOrder.LayoutOrder }, tabBar)
        self._nav, self._tabBar = nav, tabBar

        -- the open page: below the navigation, whose height changes with the tab
        local body = mk("Frame", { BackgroundTransparency = 1, ClipsDescendants = true, BorderSizePixel = 0 }, win)
        self._body = body
        local bst = mk("UIStroke", { Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, body)
        self:_paint(bst, "Color", "outline")
        local function place()
            local y = V2_HEAD + math.floor(nav.AbsoluteSize.Y / (self._k or 1) + .5)
            body.Position = UDim2.fromOffset(6, y + 2)
            body.Size = UDim2.new(1, -12, 1, -y - 8)
        end
        nav:GetPropertyChangedSignal("AbsoluteSize"):Connect(place)
        self._placeBody = place
        place()

        -- open button for touch screens: a static 50 x 50 box at the top centre that opens and closes the menu. It lives in
        -- its own gui because the menu's gui is switched off while the menu is hidden. (open button by Neteless, don't steal)
        local openGui = mk("ScreenGui", { Name = "Kiciahook V2 Open", ResetOnSpawn = false, DisplayOrder = 100001, ZIndexBehavior = Enum.ZIndexBehavior.Sibling })
        local openPlaced = pcall(function() openGui.Parent = gethui() end)
        if not openPlaced or openGui.Parent == nil then openGui.Parent = game:GetService("CoreGui") end
        self._openGui = openGui
        local openBox = mk("Frame", { BackgroundColor3 = Color3.fromRGB(15, 15, 15), BackgroundTransparency = .6, BorderColor3 = Color3.new(0, 0, 0),
            BorderSizePixel = 1, Position = UDim2.new(.5, 0, 0, -30), AnchorPoint = Vector2.new(.5, 0), Size = UDim2.fromOffset(50, 50),
            Visible = UIS.TouchEnabled, ZIndex = 5 }, openGui)
        mk("UICorner", { CornerRadius = UDim.new(0, 10) }, openBox)
        local openInner = mk("Frame", { BackgroundColor3 = Color3.fromRGB(20, 20, 20), BackgroundTransparency = .6, BorderColor3 = Color3.fromRGB(50, 50, 50),
            BorderMode = Enum.BorderMode.Inset, BorderSizePixel = 1, Size = UDim2.fromScale(1, 1), ZIndex = 6 }, openBox)
        mk("UICorner", { CornerRadius = UDim.new(0, 9) }, openInner)
        local openBtn = mk("TextButton", { BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Text = K.T("Open"), Font = Enum.Font.Ubuntu,
            TextSize = 14, TextColor3 = Color3.new(1, 1, 1), TextStrokeTransparency = .5, TextYAlignment = Enum.TextYAlignment.Center,
            AutoButtonColor = false, ZIndex = 7 }, openInner)
        openBtn.Activated:Connect(function() self:SetVisible(not self.Visible) end)

        dim.Activated:Connect(function() self:_closePopup() end)
        gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() self:_relayout() end)
        self:_relayout()
    end

    function SV2:Destroy()
        pcall(function() if self._openGui ~= nil then self._openGui:Destroy() end end)
        SLite.Destroy(self)
    end

    function SV2:_relayout()
        local gui = self._gui
        local vw, vh = gui.AbsoluteSize.X, gui.AbsoluteSize.Y
        if vw <= 0 or vh <= 0 then
            local cam = workspace.CurrentCamera
            if cam == nil then return end
            vw, vh = cam.ViewportSize.X, cam.ViewportSize.Y
        end
        if vw <= 0 or vh <= 0 then return end
        local k = clamp(math.min(1, (vw - 24) / V2_W, (vh - 24) / V2_H), .5, 1)
        k = math.floor(k * 20) / 20
        self._k = k
        self._uiscale.Scale = k
        local sw, sh = vw / k, vh / k
        self._stage.Size = UDim2.fromOffset(sw, sh)
        local w = math.floor(math.min(self._w or V2_W, sw - 24) / 2) * 2
        local h = math.floor(math.min(self._h or V2_H, sh - 24) / 2) * 2
        self._win.Size = UDim2.fromOffset(w, h)
        self._g = { sw = sw, sh = sh, cx = sw / 2, cy = sh / 2, setW = (w - 56) / 2, panelW = 0 }
        if self._moved then
            self:_clampWin()
        else
            self._win.Position = UDim2.fromOffset(math.floor(sw / 2), math.floor(sh / 2))
        end
        if self._placeBody then self._placeBody() end
        self:_closePopup()
    end

    function SV2:_sectionHost(sec)
        local card = SLite._sectionHost(self, sec)
        self:_paint(card, "BackgroundColor3", "surf")
        local lay = card:FindFirstChildOfClass("UIListLayout")
        if lay ~= nil then lay.Padding = UDim.new(0, 1) end
        return card
    end

    -- every button of a row gets the same share of the width and a thin border
    function SV2:_fillRow(container, height)
        local btns = {}
        for _, c in ipairs(container:GetChildren()) do
            if c:IsA("TextButton") then btns[#btns + 1] = c end
        end
        local n = #btns
        if n == 0 then return end
        for _, b in ipairs(btns) do
            b.AutomaticSize = Enum.AutomaticSize.None
            b.Size = UDim2.new(1 / n, -math.ceil(3 * (n - 1) / n) - 1, 0, height)
            b.TextSize = 14
            if b:FindFirstChildOfClass("UIStroke") == nil then
                local st = mk("UIStroke", { Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, b)
                self:_paint(st, "Color", "outline")
            end
        end
    end

    function SV2:AddTab(o)
        local tab = SMatcha.AddTab(self, o)
        self:_fillRow(self._tabBar, 24)
        self:_fontPass(self._tabBar)
        return tab
    end

    function SV2:_makePageRow(tab, page)
        SMatcha._makePageRow(self, tab, page)
        self:_fillRow(tab._sub, 22)
        self:_fontPass(tab._sub)
    end

    function SV2:_openPage(page)
        SMatcha._openPage(self, page)
        if self._page == page and page._scroll ~= nil and not page._v2font then
            page._v2font = true
            self:_fontPass(page._scroll)
        end
    end
    end)() -- own function: the main chunk was at the 200 local register limit, so V2 gets its own registers
end
;(function()
K.Mark("shared hud")
--==========================================================================
--  Shared HUD for the Starlight / Lite / Setsuna forms: the watermark and the keybind list. Those forms only keep
--  the two on / off flags; this draws the HUD the same way for all of them (the LY form draws its own with MD3, the
--  classic menu has its own). Entries are made by the keybind controls (see attachListEntry).
--==========================================================================
do
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local UserInputService = game:GetService("UserInputService")
    local HttpService = game:GetService("HttpService")
    local KeyHud = { entries = {} }
    K.KeyHud = KeyHud

    local gui, wm, wmText, list, rows, wmStroke, listStroke, listTitle
    local wmOn, listOn = true, true
    local playerName = Players.LocalPlayer and Players.LocalPlayer.Name or "Player"
    local dirty, tickConn = true, nil
    local fps, fpsAt, frames = 60, os.clock(), 0

    local function mk(class, props, parent)
        local inst = Instance.new(class)
        for k, v in pairs(props) do inst[k] = v end
        if parent ~= nil then inst.Parent = parent end
        return inst
    end

    local function tokens()
        local ok, t = pcall(tbl17.z)
        return ok and type(t) == "table" and t or {}
    end

    local function color(t, name, fallback)
        local c = t[name]
        if typeof(c) == "Color3" then return c end
        return fallback
    end

    -- the pieces can be dragged; where they were left is kept in LxYHook/hud_positions.json (fractions of the screen)
    local POSITIONS = "LxYHook/hud_positions.json"
    local placed = {}
    pcall(function()
        local readFile, isFile = K.fn("readfile"), K.fn("isfile")
        if readFile and isFile and isFile(POSITIONS) then
            local decoded = HttpService:JSONDecode(readFile(POSITIONS))
            if type(decoded) == "table" then placed = decoded end
        end
    end)
    local function savePositions()
        pcall(function()
            local writeFile = K.fn("writefile")
            if writeFile then
                local makeFolder, isFolder = K.fn("makefolder"), K.fn("isfolder")
                if makeFolder and isFolder and not isFolder("LxYHook") then makeFolder("LxYHook") end
                writeFile(POSITIONS, HttpService:JSONEncode(placed))
            end
        end)
    end
    local function viewport()
        local cam = workspace.CurrentCamera
        local size = cam and cam.ViewportSize
        if typeof(size) == "Vector2" and type(size.X) == "number" and size.X > 0 then return size end
        return Vector2.new(1920, 1080)
    end
    local function place(frame, key, default)
        local saved = placed[key]
        if type(saved) == "table" and type(saved.x) == "number" and type(saved.y) == "number" then
            local v = viewport()
            frame.Position = UDim2.fromOffset(saved.x * v.X, saved.y * v.Y)
        else
            frame.Position = default
        end
    end
    local function draggable(frame, key)
        frame.Active = true
        frame.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            local start = input.Position
            local origin = Vector2.new(frame.Position.X.Offset, frame.Position.Y.Offset)
            local moveConn, endConn
            local function stop()
                if moveConn then moveConn:Disconnect() end
                if endConn then endConn:Disconnect() end
                savePositions()
            end
            moveConn = UserInputService.InputChanged:Connect(function(i)
                if i.UserInputType ~= Enum.UserInputType.MouseMovement and i ~= input then return end
                local v, own = viewport(), frame.AbsoluteSize
                local x = math.clamp(origin.X + (i.Position.X - start.X), 0, math.max(0, v.X - own.X))
                local y = math.clamp(origin.Y + (i.Position.Y - start.Y), 0, math.max(0, v.Y - own.Y))
                frame.Position = UDim2.fromOffset(x, y)
                placed[key] = { x = x / v.X, y = y / v.Y }
            end)
            endConn = UserInputService.InputEnded:Connect(function(i)
                if i == input or (i.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseButton1) then
                    stop()
                end
            end)
        end)
    end

    local function build()
        if gui ~= nil then return end
        gui = mk("ScreenGui", { Name = "LxYHud", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 99990,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling })
        local placed = pcall(function() gui.Parent = gethui() end)
        if not placed or gui.Parent == nil then gui.Parent = game:GetService("CoreGui") end

        wm = mk("Frame", { Name = "Watermark", Position = UDim2.fromOffset(14, 14), AutomaticSize = Enum.AutomaticSize.XY,
            BorderSizePixel = 0, Size = UDim2.fromOffset(0, 28) }, gui)
        mk("UICorner", { CornerRadius = UDim.new(0, 8) }, wm)
        wmStroke = mk("UIStroke", { Thickness = 1 }, wm)
        mk("UIPadding", { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }, wm)
        wmText = mk("TextLabel", { BackgroundTransparency = 1, AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.fromOffset(0, 28),
            Font = Enum.Font.GothamMedium, TextSize = 13, Text = "", TextXAlignment = Enum.TextXAlignment.Left }, wm)

        place(wm, "watermark", UDim2.fromOffset(14, 14))
        draggable(wm, "watermark")

        list = mk("Frame", { Name = "Keybinds", Position = UDim2.fromOffset(14, 56), Size = UDim2.fromOffset(200, 0),
            AutomaticSize = Enum.AutomaticSize.Y, BorderSizePixel = 0 }, gui)
        mk("UICorner", { CornerRadius = UDim.new(0, 8) }, list)
        listStroke = mk("UIStroke", { Thickness = 1 }, list)
        mk("UIPadding", { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12), PaddingTop = UDim.new(0, 8), PaddingBottom = UDim.new(0, 10) }, list)
        mk("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 6) }, list)
        listTitle = mk("TextLabel", { Name = "Title", LayoutOrder = 0, BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 18),
            Font = Enum.Font.GothamBold, TextSize = 13, Text = K.T("Keybinds"), TextXAlignment = Enum.TextXAlignment.Left }, list)
        rows = list
        place(list, "keybinds", UDim2.fromOffset(14, 56))
        draggable(list, "keybinds")
    end

    local function repaint()
        if gui == nil then return end
        local t = tokens()
        local bg = color(t, "ElementBackground", Color3.fromRGB(20, 20, 24))
        local outline = color(t, "Outline", Color3.fromRGB(60, 60, 70))
        local accent = color(t, "Accent", Color3.fromRGB(154, 213, 222))
        local text = color(t, "TextColor", Color3.fromRGB(220, 220, 220))
        local dim = color(t, "Unselected", Color3.fromRGB(130, 130, 130))

        wm.BackgroundColor3 = bg
        wmStroke.Color = outline
        wmText.TextColor3 = text
        local ping = 0
        pcall(function() ping = math.floor(Players.LocalPlayer:GetNetworkPing() * 1000 + 0.5) end)
        wmText.Text = string.format("LxYHook  |  %s  |  %d fps  |  %d ms", playerName, math.floor(fps + 0.5), ping)
        wm.Visible = wmOn

        list.BackgroundColor3 = bg
        listStroke.Color = outline
        listTitle.TextColor3 = accent
        local shown = {}
        for _, entry in ipairs(KeyHud.entries) do
            if entry.show then shown[#shown + 1] = entry end
        end
        table.sort(shown, function(a, b) return a.label < b.label end)
        -- the rows are rebuilt only when what they show changed (entries, keys, lit state, theme colours); the timer
        -- redraws twice a second for the watermark numbers and used to rebuild every row each time
        local parts = { tostring(bg), tostring(outline), tostring(accent), tostring(text), tostring(dim) }
        for _, entry in ipairs(shown) do
            parts[#parts + 1] = entry.label .. "\1" .. (entry.key and entry.key.Name or "")
                .. "\1" .. tostring(entry.active) .. tostring(entry.always)
        end
        local signature = table.concat(parts, "\2")
        if signature == KeyHud._rowsSignature and rows == KeyHud._rowsParent then
            list.Visible = listOn and not (UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled) and #shown > 0
            return
        end
        KeyHud._rowsSignature, KeyHud._rowsParent = signature, rows
        for _, child in ipairs(rows:GetChildren()) do
            if child.Name == "Row" then child:Destroy() end
        end
        for index, entry in ipairs(shown) do
            local active = entry.active or entry.always
            local row = mk("Frame", { Name = "Row", LayoutOrder = index, BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 20) }, rows)
            mk("TextLabel", { BackgroundTransparency = 1, Size = UDim2.new(1, -70, 1, 0), Font = Enum.Font.GothamMedium, TextSize = 13,
                Text = entry.label, TextColor3 = active and text or dim, TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd }, row)
            local chip = mk("TextLabel", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.fromScale(1, 0.5), Size = UDim2.fromOffset(0, 18),
                AutomaticSize = Enum.AutomaticSize.X, BorderSizePixel = 0, Font = Enum.Font.GothamBold, TextSize = 11,
                Text = entry.key and entry.key.Name or (entry.always and "Always" or "None"),
                BackgroundColor3 = active and accent or outline, TextColor3 = active and bg or text }, row)
            mk("UICorner", { CornerRadius = UDim.new(0, 5) }, chip)
            mk("UIPadding", { PaddingLeft = UDim.new(0, 7), PaddingRight = UDim.new(0, 7) }, chip)
        end
        -- a phone has the on-screen key buttons instead
        list.Visible = listOn and not (UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled) and #shown > 0
    end

    local function startTick()
        if tickConn ~= nil then return end
        local last = 0
        tickConn = RunService.Heartbeat:Connect(LPH_NO_VIRTUALIZE(function(dt)
            frames += 1
            local now = os.clock()
            if now - fpsAt >= 0.5 then
                fps, fpsAt, frames = frames / (now - fpsAt), now, 0
            end
            -- redraw on a change, and twice a second for the numbers and the theme
            if dirty or now - last >= 0.5 then
                dirty, last = false, now
                pcall(repaint)
            end
        end))
    end

    function KeyHud.ensure(name, watermark, keybinds)
        if type(name) == "string" and name ~= "" then playerName = name end
        wmOn, listOn = watermark ~= false, keybinds ~= false
        pcall(build)
        pcall(startTick)
        dirty = true
    end

    function KeyHud.setWatermark(v) wmOn = v ~= false dirty = true end
    function KeyHud.setList(v) listOn = v ~= false dirty = true end

    -- one entry per keybind control: update(show, key, active, always)
    function KeyHud.add(label)
        local entry = { label = tostring(label), show = false, key = nil, active = false, always = false }
        function entry.update(show, key, active, always)
            entry.show, entry.key, entry.active, entry.always = show == true, key, active == true, always == true
            dirty = true
        end
        table.insert(KeyHud.entries, entry)
        return entry
    end

    function KeyHud.destroy()
        if tickConn ~= nil then tickConn:Disconnect() tickConn = nil end
        if gui ~= nil then pcall(function() gui:Destroy() end) end
        gui, wm, wmText, list, rows, wmStroke, listStroke, listTitle = nil, nil, nil, nil, nil, nil, nil, nil
        table.clear(KeyHud.entries)
    end

    K.onUnload(KeyHud.destroy)
end
end)()

K.Mark("weapon visuals")
--==========================================================================
--  Weapon Visuals from LY.lua: the first-person weapon motion switch, the arm and gun chams
--  (material, colour, transparency, wireframe) and the muzzle flash switch run on the code of LY.lua; the options
--  of the Weapon Visuals page are what drives it (kh's own versions of these are switched off).
--  The LY code is used as it is: it makes its elements on a small stand-in section (no window), and each element
--  that has a counterpart in the script's settings is linked to that setting.
--==========================================================================
;(function()
local function setup()
    local cfg = tbl17.bG()
    local data = cfg.Data
    local RunService = game:GetService("RunService")
    local LocalPlayer = game:GetService("Players").LocalPlayer
    local PREFIX = "LxYWeapon_"
    local unloaders = {}
    local function track(item)
        unloaders[#unloaders + 1] = item
        return item
    end
    local owned = setmetatable({}, { __mode = "k" })
    local function camera()
        return workspace.CurrentCamera
    end
    -- where first-person viewmodels live: RIVALS keeps them in Workspace.ViewModels.FirstPerson
    local function viewmodelFolders()
        local folders = {}
        local root = workspace:FindFirstChild("ViewModels")
        local firstPerson = root and root:FindFirstChild("FirstPerson")
        if firstPerson then
            table.insert(folders, firstPerson)
        end
        if camera() then
            table.insert(folders, camera())
        end
        return folders
    end
    local function snapshot(instance, properties)
        local saved = {}
        for _, property in properties do
            local ok, value = pcall(function()
                return instance[property]
            end)
            if ok then
                saved[property] = value
            end
        end
        return function()
            for property, value in saved do
                pcall(function()
                    instance[property] = value
                end)
            end
        end
    end
    -- the elements LY makes: a value and the callback that applies it
    local virtual = {}
    local function element(options)
        local e = { Flag = options.Flag, Value = options.Default, Callback = options.Callback }
        function e:Set(value, silent)
            self.Value = value
            if not silent and self.Callback ~= nil then self.Callback(value) end
        end
        function e:SetVisible() end
        if options.Flag ~= nil then virtual[options.Flag] = e end
        return e
    end
    local Section = setmetatable({}, { __index = function() return function(_, options) return element(options or {}) end end })
    local CameraTab = { AddSection = function() return Section end }
    local Window = {
        Notify = function(_, options)
            pcall(function() tbl17.aB().get():Notify(tostring(options.Title) .. ": " .. tostring(options.Content)) end)
        end,
    }
    local function patchToggle(section, options)
        local toggle
        toggle = section:AddToggle({
            Title = options.Title,
            Default = false,
            Flag = options.Flag,
            Callback = function(on)
                if not options.Set(on) and on then
                    Window:Notify({ Title = options.Title, Content = options.Failure })
                    task.defer(function()
                        toggle:Set(false, true)
                    end)
                end
            end,
        })
        track(function()
            options.Set(false)
        end)
        return toggle
    end

	local function noop() end

	local function writeField(tbl, key, value)
		local frozen = type(isreadonly) == "function" and isreadonly(tbl)
		if frozen and type(setreadonly) == "function" then
			setreadonly(tbl, false)
		end
		local ok = pcall(rawset, tbl, key, value)
		if frozen and type(setreadonly) == "function" then
			setreadonly(tbl, true)
		end
		return ok
	end

	local function requireGameModule(name)
		local roots = { LocalPlayer:FindFirstChild("PlayerScripts"), cloneref(game:GetService("ReplicatedStorage")) }
		for _, root in roots do
			local module = root and root:FindFirstChild(name, true)
			if module and module:IsA("ModuleScript") then
				local ok, result = pcall(require, module)
				if ok then
					return result
				end
			end
		end
		return nil
	end

	-- The table that actually holds `method`: the module itself or its class
	-- (metatable / __index). Falls back to the Lua heap when the module isn't
	-- where we expect it.
	local function findClass(moduleName, method)
		local function holder(value)
			if type(value) ~= "table" then
				return nil
			end
			if type(rawget(value, method)) == "function" then
				return value
			end
			local meta = getmetatable(value)
			if type(meta) == "table" then
				if type(rawget(meta, method)) == "function" then
					return meta
				end
				local index = rawget(meta, "__index")
				if type(index) == "table" and type(rawget(index, method)) == "function" then
					return index
				end
			end
			return nil
		end
		local found = holder(requireGameModule(moduleName))
		if found or type(getgc) ~= "function" then
			return found
		end
		local ok, objects = pcall(getgc, true)
		if ok then
			for _, object in objects do
				if type(object) == "table" and type(rawget(object, method)) == "function" then
					return object
				end
			end
		end
		return nil
	end
	local WeaponSection = CameraTab:AddSection("Weapon")
	local MOTION_SPRINGS = {
		_sliding_spring = 0,
		_sprinting_spring = 0,
		_bobbing_speed_spring = 0,
		_bobbing_value_spring = Vector2.zero,
		_landing_spring = 0,
		_jump_spring = 0,
		_tilt_spring = Vector2.zero,
		_impulse_position_spring = Vector3.zero,
		_recoil_spring = Vector3.zero,
		_unrecoil_spring = Vector3.zero,
	}
	local motion = { Enabled = false, Connections = {} }
	local frozenSprings = setmetatable({}, { __mode = "k" })

	local function isLocalItem(viewModel)
		local ok, isLocal = pcall(function()
			return viewModel.ClientItem.ClientFighter.IsLocalPlayer
		end)
		return ok and isLocal == true
	end

	local function freezeViewModel(viewModel)
		for field, rest in MOTION_SPRINGS do
			local spring = rawget(viewModel, field)
			if type(spring) == "table" and writeField(spring, "Value", rest) then
				frozenSprings[spring] = true
			end
		end
	end

	local function freezeViewModels()
		if type(getgc) ~= "function" then
			return false
		end
		local ok, objects = pcall(getgc, true)
		if not ok then
			return false
		end
		local found = false
		for _, object in objects do
			-- CameraController has bobbing / sliding springs too; only viewmodels have
			-- a recoil spring and a ClientItem. Other players' items have viewmodels
			-- as well, so only your own are touched.
			if type(object) == "table" and type(rawget(object, "_recoil_spring")) == "table"
				and rawget(object, "ClientItem") ~= nil and isLocalItem(object)
			then
				freezeViewModel(object)
				found = true
			end
		end
		return found
	end

	local function restoreViewModels()
		for spring in frozenSprings do
			writeField(spring, "Value", nil)
			frozenSprings[spring] = nil
		end
	end

	local function watchViewModels()
		for _, connection in motion.Connections do
			connection:Disconnect()
		end
		table.clear(motion.Connections)
		if not motion.Enabled then
			return
		end
		for _, folder in viewmodelFolders() do
			table.insert(motion.Connections, folder.ChildAdded:Connect(function(child)
				if child:IsA("Model") and not owned[child] then
					task.defer(freezeViewModels)
				end
			end))
		end
	end
	track(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(watchViewModels))

	local function setNoMotion(on)
		motion.Enabled = on
		watchViewModels()
		if not on then
			restoreViewModels()
			return true
		end
		if type(getgc) ~= "function" then
			motion.Enabled = false
			watchViewModels()
			return false
		end
		freezeViewModels() -- nothing yet is fine: the next equip gets caught
		return true
	end

	patchToggle(WeaponSection, {
		Title = "No weapon motion",
		Description = "Removes gun bob, tilt, landing and recoil motion from your viewmodel",
		Flag = "NoMotion",
		Set = setNoMotion,
		Failure = "Your executor doesn't support getgc",
	})

	-- Viewmodel animations --------------------------------------------------------
	-- Shoot / sprint / equip / reload: like LY-broken, ViewModelAnimator:
	-- PlayAnimation(key, ...) is hooked (equip and sprint are played by the
	-- animator itself, so the ClientViewModel wrapper would miss them). For a
	-- suppressed key on your own viewmodel the track in _animation_tracks is
	-- swapped for one whose Play / Stop do nothing, the original still runs (so
	-- the game's state updates), then the real track goes back.
	-- Idle / crouch / aim, and the four above when the hook can't be installed,
	-- fall back to stopping matching tracks on the viewmodel's Animators each
	-- frame (matched by track / animation name and id).

	local animations = { Sprint = false, Shoot = false, Equip = false, Reload = false }
	local animationPatch = nil
	local silentTrack = { Play = noop, Stop = noop }

	local function shouldSuppress(animator, key)
		if type(key) ~= "string" then
			return false
		end
		return (animations.Sprint and key == rawget(animator, "_sprint_animation"))
			or (animations.Equip and key == rawget(animator, "_equip_animation"))
			or (animations.Shoot and (key:find("Shoot", 1, true) ~= nil or key == "QuickShot"))
			or (animations.Reload and key:find("Reload", 1, true) ~= nil)
	end

	local function isLocalAnimator(animator)
		local ok, isLocal = pcall(function()
			return animator.ClientViewModel.ClientItem.ClientFighter.IsLocalPlayer
		end)
		return ok and isLocal == true
	end

	local function installAnimationPatch()
		if animationPatch then
			return true
		end
		local class = findClass("ViewModelAnimator", "PlayAnimation")
		local original = class and rawget(class, "PlayAnimation")
		if type(original) ~= "function" then
			return false
		end
		local function playAnimation(animator, key, ...)
			local tracks = type(animator) == "table" and rawget(animator, "_animation_tracks")
			if type(tracks) ~= "table" or rawget(tracks, key) == nil
				or not shouldSuppress(animator, key) or not isLocalAnimator(animator)
			then
				return original(animator, key, ...)
			end
			local realTrack = rawget(tracks, key)
			rawset(tracks, key, silentTrack)
			local results = table.pack(pcall(original, animator, key, ...))
			rawset(tracks, key, realTrack)
			if not results[1] then
				error(results[2], 0)
			end
			return table.unpack(results, 2, results.n)
		end
		if not writeField(class, "PlayAnimation", playAnimation) then
			return false
		end
		animationPatch = { Class = class, Original = original }
		return true
	end

	local function removeAnimationPatch()
		if animationPatch then
			writeField(animationPatch.Class, "PlayAnimation", animationPatch.Original)
			animationPatch = nil
		end
	end

	local TRACK_PATTERNS = {
		Shoot = { "shoot", "fire", "shot" },
		Sprint = { "sprint" },
		Equip = { "equip" },
		Reload = { "reload" },
		Idle = { "idle" },
		Crouch = { "crouch" },
		Aim = { "aim", "ads", "scope" },
	}
	local stoppedKinds = {} -- kind -> true while handled by stopping tracks
	local trackStopper = nil

	local function trackLabel(animTrack)
		local label = animTrack.Name
		local anim = animTrack.Animation
		if anim then
			label ..= " " .. anim.Name .. " " .. anim.AnimationId
		end
		return label:lower()
	end

	-- a track keeps its animation, so its label is built once
	local trackLabels = setmetatable({}, { __mode = "k" })
	local function shouldStopTrack(animTrack)
		local label = trackLabels[animTrack]
		if label == nil then
			local ok, built = pcall(trackLabel, animTrack)
			if not ok then
				return false
			end
			label = built
			trackLabels[animTrack] = label
		end
		for kind in stoppedKinds do
			for _, pattern in TRACK_PATTERNS[kind] do
				if label:find(pattern, 1, true) then
					return true
				end
			end
		end
		return false
	end

	-- Event driven: every Animator under the viewmodel folders gets an AnimationPlayed listener that stops a
	-- matching track the moment it starts. It used to walk every descendant of the viewmodels and the camera
	-- and list each Animator's playing tracks on every frame. Animators are picked up through DescendantAdded
	-- (and swept once when found, since a deferred signal can arrive after the game already played a track);
	-- a light sweep of the known Animators twice a second covers the folders being replaced.
	local stopperAnimators = {} -- Animator -> AnimationPlayed connection
	local stopperFolders = {} -- folder -> DescendantAdded connection
	local function stopMatching(animator)
		local ok, playing = pcall(animator.GetPlayingAnimationTracks, animator)
		if not ok then return end
		for _, animTrack in playing do
			if shouldStopTrack(animTrack) then
				pcall(animTrack.Stop, animTrack, 0)
			end
		end
	end
	local function watchAnimator(animator)
		if stopperAnimators[animator] ~= nil or owned[animator] then return end
		stopperAnimators[animator] = animator.AnimationPlayed:Connect(function(animTrack)
			if next(stoppedKinds) ~= nil and shouldStopTrack(animTrack) then
				pcall(animTrack.Stop, animTrack, 0)
			end
		end)
		stopMatching(animator)
	end
	local function watchFolder(folder)
		if stopperFolders[folder] ~= nil then return end
		stopperFolders[folder] = folder.DescendantAdded:Connect(function(descendant)
			if descendant:IsA("Animator") then watchAnimator(descendant) end
		end)
		for _, descendant in folder:GetDescendants() do
			if descendant:IsA("Animator") then watchAnimator(descendant) end
		end
	end
	local function stopTrackStopper()
		if trackStopper then
			trackStopper:Disconnect()
			trackStopper = nil
		end
		for animator, connection in stopperAnimators do
			connection:Disconnect()
			stopperAnimators[animator] = nil
		end
		for folder, connection in stopperFolders do
			connection:Disconnect()
			stopperFolders[folder] = nil
		end
	end
	track(stopTrackStopper)

	local function updateTrackStopper()
		if next(stoppedKinds) == nil then
			stopTrackStopper()
			return
		end
		if trackStopper then
			-- the set of stopped kinds changed: apply it to what is already playing
			for animator in stopperAnimators do stopMatching(animator) end
			return
		end
		for _, folder in viewmodelFolders() do watchFolder(folder) end
		local sweepAt = os.clock()
		trackStopper = RunService.Heartbeat:Connect(LPH_NO_VIRTUALIZE(function()
			local now = os.clock()
			if now - sweepAt < 0.5 then return end
			sweepAt = now
			local current = viewmodelFolders()
			local live = {}
			for _, folder in current do
				live[folder] = true
				watchFolder(folder)
			end
			for folder, connection in stopperFolders do
				if not live[folder] then
					connection:Disconnect()
					stopperFolders[folder] = nil
				end
			end
			for animator, connection in stopperAnimators do
				if animator.Parent == nil then
					connection:Disconnect()
					stopperAnimators[animator] = nil
				else
					stopMatching(animator)
				end
			end
		end))
	end

	local function setAnimationDisabled(kind, on)
		stoppedKinds[kind] = nil
		if animations[kind] ~= nil then
			animations[kind] = on
			local any = animations.Sprint or animations.Shoot or animations.Equip or animations.Reload
			if not any then
				removeAnimationPatch()
			elseif not installAnimationPatch() then
				-- No hook available: stop the tracks instead.
				animations[kind] = false
				stoppedKinds[kind] = on or nil
			end
		else
			stoppedKinds[kind] = on or nil
		end
		updateTrackStopper()
		return true
	end

	for _, entry in {
		{ Kind = "Shoot", Title = "No shoot animation", Description = "Your gun doesn't play its firing animation" },
		{ Kind = "Sprint", Title = "No sprint animation", Description = "Your viewmodel doesn't play the sprint animation" },
		{ Kind = "Equip", Title = "No equip animation", Description = "Skip the draw animation when you switch weapons" },
		{ Kind = "Reload", Title = "No reload animation", Description = "Your viewmodel doesn't play the reload animation" },
		{ Kind = "Idle", Title = "No idle animation", Description = "Your viewmodel stays still while idle" },
		{ Kind = "Crouch", Title = "No crouch animation", Description = "Your viewmodel doesn't play the crouch animation" },
		{ Kind = "Aim", Title = "No aim animation", Description = "Your viewmodel doesn't play the aim-down-sights animation" },
	} do
		patchToggle(WeaponSection, {
			Title = entry.Title,
			Description = entry.Description,
			Flag = "No" .. entry.Kind .. "Animation",
			Set = function(on)
				return setAnimationDisabled(entry.Kind, on)
			end,
		})
	end
local viewmodel, muzzle
do
local ViewmodelSection = CameraTab:AddSection("Viewmodel")
local MATERIAL_NAMES = { "ForceField", "Neon", "Glass", "SmoothPlastic", "Plastic", "Metal", "Foil" }
viewmodel = {
	Offset = false, X = 0, Y = 0, Z = 0,
	-- Arms and gun are chammed separately.
	Arm = {
		Enabled = false, Material = "ForceField", Color = Color3.fromRGB(120, 170, 255), Transparency = 0,
		Wireframe = false, WireWidth = 0.02, WireAngle = 0, WireMaterial = "Neon",
	},
	Gun = {
		Enabled = false, Material = "Neon", Color = Color3.fromRGB(255, 255, 255), Transparency = 0,
		Wireframe = false, WireWidth = 0.02, WireAngle = 0, WireMaterial = "Neon",
	},
}
local chamRestores = setmetatable({}, { __mode = "k" }) -- part -> restore function
local chamKinds = setmetatable({}, { __mode = "k" }) -- part -> "Arm" | "Gun" | false

-- Arm / gun detection: arm models are named like "<Weapon> - Arms"; inside a
-- gun model, arm parts are found by name or by an arm-ish ancestor folder.
local CHAM_EXCLUDED_PARTS = {
	ChamOutlineShell = true, ChamOutlineGlow = true, ChamOutlineBloom = true,
	WeaponWireframeCore = true, WeaponWireframeGlow = true, WeaponWireframeBloom = true,
	GunChamNeonGlow = true,
	ChamMeshProxy = true,
}
local ARM_PART_SKIP = { "hitbox", "collision", "trigger", "proxy", "handguard", "handle", "foregrip", "charm", "armor" }
local ARM_PART_WORDS = {
	"leftarm", "rightarm", "left arm", "right arm", "forearm", "upperarm", "lowerarm",
	"glove", "sleeve", "finger", "wrist", "palm", "thumb", "hand",
}

local function isHelperPart(part)
	local name = part.Name:lower()
	return name:find("hitbox", 1, true) or name:find("collision", 1, true)
		or name:find("trigger", 1, true) or name:find("proxy", 1, true)
end

local function isArmViewModel(model)
	local segments = {}
	for segment in model.Name:gmatch("[^-]+") do
		table.insert(segments, segment:match("^%s*(.-)%s*$"):lower())
	end
	if #segments >= 2 then
		local tag = segments[2]
		if tag:find("glove", 1, true) then
			return true
		end
		return tag:find("arm", 1, true) ~= nil and not tag:find("charm", 1, true) and not tag:find("armor", 1, true)
	end
	local name = model.Name:lower()
	return name:find("arms", 1, true) ~= nil or name:find("glove", 1, true) ~= nil
end

local function isArmNamedPart(partName)
	local name = partName:lower()
	for _, skip in ARM_PART_SKIP do
		if name:find(skip, 1, true) then
			return false
		end
	end
	if name == "larm" or name == "rarm" then
		return true
	end
	for _, word in ARM_PART_WORDS do
		if name:find(word, 1, true) then
			return true
		end
	end
	return false
end

local function hasArmAncestor(part, model)
	local node = part.Parent
	while node and node ~= model do
		local name = node.Name:lower()
		if name == "hands" or name:find("glove", 1, true) or name:find("sleeve", 1, true) then
			return true
		end
		if name:find("arm", 1, true) and not name:find("armor", 1, true) and not name:find("charm", 1, true)
			and not name:find("handguard", 1, true) and not name:find("foregrip", 1, true) then
			return true
		end
		node = node.Parent
	end
	return false
end

-- "Arm", "Gun", or false for parts that are never chammed.
local function chamKind(part, model)
	local kind = chamKinds[part]
	if kind ~= nil then
		return kind
	end
	if CHAM_EXCLUDED_PARTS[part.Name] or part.Transparency >= 0.99 or isHelperPart(part) then
		kind = false
	elseif isArmViewModel(model) or hasArmAncestor(part, model) or isArmNamedPart(part.Name) then
		kind = "Arm"
	else
		kind = "Gun"
	end
	-- A hidden part may be shown later, so don't remember that answer.
	if part.Transparency < 0.99 then
		chamKinds[part] = kind
	end
	return kind
end

local function viewmodels()
	local list = {}
	for _, folder in viewmodelFolders() do
		for _, child in folder:GetChildren() do
			if child:IsA("Model") and not owned[child] then
				table.insert(list, child)
			end
		end
	end
	return list
end

-- Proxies: a MeshPart welded over a viewmodel part that shows the cham while
-- the original is hidden.
--  * Materials don't render on a Part shaped by a SpecialMesh (the arms), so
--    those get a MeshPart copy of their mesh; otherwise only the color showed.
--  * Wireframe: every edge of the mesh is rebuilt as a thin two-sided strip
--    (an EditableMesh), so the part's material and color land on the lines.
local chamMesh = {
	Proxies = setmetatable({}, { __mode = "k" }), -- part -> proxy MeshPart
	Keys = setmetatable({}, { __mode = "k" }), -- part -> template key of its proxy
	Templates = {}, -- key -> MeshPart, or false while loading / if it failed
	WireGeneration = 0, -- bumped when a line width changes; stale builds are dropped
}

-- MeshId, scale from mesh units to studs, and offset of what a part draws.
local function meshSource(part)
	if part:IsA("MeshPart") then
		local ok, size = pcall(function()
			return part.MeshSize
		end)
		if part.MeshId == "" or not ok or size.X <= 0 or size.Y <= 0 or size.Z <= 0 then
			return nil
		end
		return part.MeshId, part.Size / size, CFrame.new()
	end
	local mesh = part:FindFirstChildOfClass("SpecialMesh")
	if mesh and mesh.MeshType == Enum.MeshType.FileMesh and mesh.MeshId ~= "" then
		return mesh.MeshId, mesh.Scale, CFrame.new(mesh.Offset)
	end
	return nil
end

-- Reading a mesh's triangles needs the Roblox-only UGCValidationService calls.
local function asRobloxScript(fn)
	local get, set = getthreadidentity, setthreadidentity
	if type(get) ~= "function" or type(set) ~= "function" then
		return fn()
	end
	local previous = get()
	set(8)
	local ok, result = pcall(fn)
	set(previous)
	if not ok then
		error(result, 0)
	end
	return result
end

local function buildWireMesh(meshId, width, minAngle)
	local ugc = cloneref(game:GetService("UGCValidationService"))
	local mesh = ugc:CreateEditableMeshFromBinaryStringRobloxOnly(ugc:GetMeshDataBinaryString(meshId))
	local faces, original = {}, mesh:GetFaces()
	for _, face in original do
		local verts = mesh:GetFaceVertices(face)
		if #verts >= 3 then
			local points = {}
			for index, vertex in verts do
				points[index] = mesh:GetPosition(vertex)
			end
			local normal = (points[2] - points[1]):Cross(points[3] - points[1])
			if normal.Magnitude > 1e-6 then
				table.insert(faces, { Verts = verts, Points = points, Normal = normal.Unit })
			end
		end
	end
	for _, face in original do
		mesh:RemoveFace(face)
	end
	mesh:RemoveUnused()

	-- A mesh may not be wider than 2048 in any direction (some models are modelled huge and
	-- shown tiny, e.g. Blast X): shrink the lines to fit; the caller scales the part back up.
	local low, high = Vector3.one * math.huge, Vector3.one * -math.huge
	for _, face in faces do
		for _, point in face.Points do
			low, high = low:Min(point), high:Max(point)
		end
	end
	local span = math.max((high - low).X, (high - low).Y, (high - low).Z)
	local factor = if span > 1800 then 1800 / span else 1
	if factor ~= 1 then
		for _, face in faces do
			for index, point in face.Points do
				face.Points[index] = point * factor
			end
		end
		width *= factor
	end

	-- Edges keyed by position: meshes split vertices along UV / normal seams,
	-- which would draw a seam edge twice and hide its neighbouring face.
	local function pointKey(point)
		return string.format("%.4f,%.4f,%.4f", point.X, point.Y, point.Z)
	end
	local edges, order = {}, {}
	for _, face in faces do
		local count = #face.Points
		for i = 1, count do
			local p, q = face.Points[i], face.Points[i % count + 1]
			local kp, kq = pointKey(p), pointKey(q)
			local key = if kp < kq then kp .. "|" .. kq else kq .. "|" .. kp
			local edge = edges[key]
			if edge then
				table.insert(edge.Normals, face.Normal)
			elseif (q - p).Magnitude > 1e-6 then
				edge = { P = p, Q = q, Normals = { face.Normal } }
				edges[key] = edge
				table.insert(order, edge)
			end
		end
	end

	-- minAngle > 0 keeps only edges whose faces meet at least that sharply
	-- (open edges always stay), so flat surfaces lose their triangle lines.
	-- A mesh can't hold more than 20000 triangles and every line costs four, so a model with more
	-- edges than that keeps its sharpest ones (this is why the detailed guns had no wireframe).
	local MAX_LINES = 4900
	local kept = {}
	for _, edge in order do
		local sharp = 180 -- an open edge counts as the sharpest
		if #edge.Normals > 1 then
			sharp = 0
			for a = 1, #edge.Normals - 1 do
				for b = a + 1, #edge.Normals do
					sharp = math.max(sharp, math.deg(math.acos(math.clamp(edge.Normals[a]:Dot(edge.Normals[b]), -1, 1))))
				end
			end
		end
		edge.Sharp = sharp
		if minAngle <= 0 or sharp >= minAngle then
			table.insert(kept, edge)
		end
	end
	if #kept > MAX_LINES then
		table.sort(kept, function(left, right)
			return left.Sharp > right.Sharp
		end)
		kept = table.move(kept, 1, MAX_LINES, 1, {})
	end

	local white = mesh:AddColor(Color3.new(1, 1, 1), 1)
	local half = width / 2
	for _, edge in kept do
		local normal = edge.Normals[1]
		local side = normal:Cross(edge.Q - edge.P)
		if side.Magnitude > 1e-6 then
			local p, q = edge.P, edge.Q
			local lift = normal * 0.001 -- just off the surface
			side = side.Unit * half
			local v1 = mesh:AddVertex(p - side + lift)
			local v2 = mesh:AddVertex(p + side + lift)
			local v3 = mesh:AddVertex(q + side + lift)
			local v4 = mesh:AddVertex(q - side + lift)
			local up, down = mesh:AddNormal(normal), mesh:AddNormal(-normal)
			-- Both windings, so the lines show from either side.
			for _, tri in { { v1, v2, v3, up }, { v1, v3, v4, up }, { v3, v2, v1, down }, { v4, v3, v1, down } } do
				local triangle = mesh:AddTriangle(tri[1], tri[2], tri[3])
				mesh:SetFaceNormals(triangle, { tri[4], tri[4], tri[4] })
				mesh:SetFaceColors(triangle, { white, white, white })
			end
		end
	end
	return mesh, factor
end

-- Template MeshPart for a key, built in the background (it yields); nil until ready.
local function templateFor(key, create, generation)
	local template = chamMesh.Templates[key]
	if template ~= nil then
		return template or nil
	end
	chamMesh.Templates[key] = false
	task.spawn(function()
		local ok, created = pcall(create)
		if generation and generation ~= chamMesh.WireGeneration then
			if ok and created then
				created:Destroy()
			end
			chamMesh.Templates[key] = nil
			return
		end
		chamMesh.Templates[key] = ok and created or false
	end)
	return nil
end

local function dropProxy(part)
	local proxy = chamMesh.Proxies[part]
	if proxy then
		proxy:Destroy()
	end
	chamMesh.Proxies[part] = nil
	chamMesh.Keys[part] = nil
end

-- The part's proxy for `key`; keeps showing the previous one until it's built.
local function proxyFor(part, key, create, scale, offset, generation)
	local current = chamMesh.Proxies[part]
	if current and not current.Parent then
		current = nil
	end
	if current and chamMesh.Keys[part] == key then
		return current
	end
	local template = templateFor(key, create, generation)
	if not template then
		return current
	end
	local proxy = template:Clone()
	proxy.Name = "ChamMeshProxy"
	proxy.Anchored = false
	proxy.Massless = true
	proxy.CanCollide = false
	proxy.CanQuery = false
	proxy.CanTouch = false
	proxy.CastShadow = false
	proxy.Size = template.MeshSize * scale / (template:GetAttribute("WireFactor") or 1)
	local weld = Instance.new("Weld")
	weld.Part0 = part
	weld.Part1 = proxy
	weld.C0 = offset
	weld.Parent = proxy
	proxy.CFrame = part.CFrame * offset
	proxy.Parent = part
	dropProxy(part)
	chamMesh.Proxies[part] = proxy
	chamMesh.Keys[part] = key
	return proxy
end

local function applyCham(part, settings)
	if not chamRestores[part] then
		-- Viewmodel arms wear a ShirtTexture decal over the whole mesh, which
		-- hid most materials and the color; the decals are hidden while chammed.
		-- (The game resets a decal's Transparency every frame, not its
		-- LocalTransparencyModifier.)
		local restores = { snapshot(part, { "Material", "Color", "Transparency", "LocalTransparencyModifier" }) }
		for _, child in part:GetChildren() do
			if child:IsA("Decal") then -- Texture is a Decal too
				table.insert(restores, snapshot(child, { "LocalTransparencyModifier" }))
			end
		end
		chamRestores[part] = function()
			for _, restore in restores do
				restore()
			end
		end
	end
	for _, child in part:GetChildren() do
		if child:IsA("Decal") then
			child.LocalTransparencyModifier = 1
		end
	end

	local wire = settings.Wireframe
	local meshId, scale, offset = meshSource(part)
	local proxy = nil
	if wire and meshId then
		local width = settings.WireWidth / ((scale.X + scale.Y + scale.Z) / 3) -- studs -> mesh units
		local generation = chamMesh.WireGeneration
		local angle = settings.WireAngle
		proxy = proxyFor(part, string.format("wire|%s|%.5f|%d", meshId, width, angle), function()
			return asRobloxScript(function()
				local mesh, factor = buildWireMesh(meshId, width, angle)
				local template = game:GetService("AssetService"):CreateMeshPartAsync(Content.fromObject(mesh))
				template:SetAttribute("WireFactor", factor)
				return template
			end)
		end, scale, offset, generation)
	elseif not wire and meshId and not part:IsA("MeshPart") then
		proxy = proxyFor(part, "cham|" .. meshId, function()
			return game:GetService("AssetService"):CreateMeshPartAsync(meshId)
		end, scale, offset)
	else
		dropProxy(part)
	end

	local material = Enum.Material[if wire then settings.WireMaterial else settings.Material]
	local color = settings.Color -- the lines use the arm / gun color too
	local transparency = if wire then 0 else settings.Transparency
	if proxy then
		part.LocalTransparencyModifier = 1
		proxy.Material = material
		proxy.Color = color
		proxy.Transparency = transparency
	elseif not wire then
		part.LocalTransparencyModifier = 0
		part.Material = material
		part.Color = color
		part.Transparency = transparency
	end
end

local function restoreCham(part)
	dropProxy(part)
	local restore = chamRestores[part]
	if restore then
		restore()
		chamRestores[part] = nil
	end
end

local function clearChams()
	for part in chamRestores do
		restoreCham(part)
	end
end

local function chamsActive()
	return viewmodel.Arm.Enabled or viewmodel.Gun.Enabled or viewmodel.Arm.Wireframe or viewmodel.Gun.Wireframe
end

local function refreshChams()
	if not chamsActive() then
		clearChams()
		return
	end
	for _, model in viewmodels() do
		for _, descendant in model:GetDescendants() do
			if descendant:IsA("BasePart") then
				local kind = chamKind(descendant, model)
				local settings = kind and viewmodel[kind]
				if settings and (settings.Enabled or settings.Wireframe) then
					applyCham(descendant, settings)
				else
					restoreCham(descendant)
				end
			end
		end
	end
end

ViewmodelSection:AddToggle({
	Title = "Viewmodel offset",
	Description = "Move your first-person arms and gun",
	Default = false,
	Flag = "ViewmodelOffset",
