						if props[key] then
							table.insert(pending, { inst, field, props[key] })
						end
					end
				end
			end

			local function applyAttributes(inst, attributes)
				for key, value in attributes do
					inst:SetAttribute(key, value)
				end
			end

			-- a MeshPart's mesh can't be swapped in place: make a new one and move everything over
			local function swapMesh(old, meshId)
				local new = newMeshPart(meshId)
				new.Name = old.Name
				new.CFrame = old.CFrame
				for _, key in { "Anchored", "CanCollide", "CanQuery", "CanTouch", "Massless", "CastShadow", "Material", "Color", "Reflectance", "Transparency" } do
					new[key] = old[key]
				end
				for key, value in old:GetAttributes() do
					new:SetAttribute(key, value)
				end
				for _, child in old:GetChildren() do
					child.Parent = new
				end
				new.Parent = old.Parent
				old:Destroy()
				return new
			end

			local function createNode(node, parent, byPath, top, pending)
				local inst
				if node.c == "MeshPart" then
					inst = newMeshPart(node.p and node.p.MeshId)
				else
					inst = Instance.new(node.c)
				end
				inst.Name = node.n
				if node.p then
					applyProps(inst, node.p, byPath, top, pending)
				end
				if node.a then
					applyAttributes(inst, node.a)
				end
				inst.Parent = parent
				for _, child in node.k or {} do
					createNode(child, inst, byPath, top, pending)
				end
				return inst
			end

			local function findModel(root, name)
				return MD3.LYLookThrough(root, name)
			end

			-- Builds the skin's model from the stock one. Yields (mesh loading).
			function Builder.Build(name, data, root)
				local source = findModel(root, data.src)
				if not source then
					return nil, "source model missing: " .. tostring(data.src)
				end
				prefetch(data)
				local model = source:Clone()
				model.Name = name
				model:SetAttribute("__LYBuild", MD3.LYBuildVersion)
				expected = {}
				local byPath = mapTree(model)
				for _, path in data.del do
					local inst = byPath[path]
					if inst then
						inst:Destroy()
					end
				end
				for _, entry in data.set do
					local inst = byPath[entry.path]
					if inst then
						local p = entry.p
						if p and p.MeshId and p.MeshId ~= "" and inst:IsA("MeshPart") and inst.MeshId ~= p.MeshId then
							inst = swapMesh(inst, p.MeshId)
							byPath[entry.path] = inst
						end
						if p then
							applyProps(inst, p, byPath, model, nil)
						end
						if entry.a then
							applyAttributes(inst, entry.a)
						end
					end
				end
				local pending = {}
				for _, entry in data.add do
					local parent = entry.parent == "" and model or byPath[entry.parent]
					if parent then
						createNode(entry.node, parent, byPath, model, pending)
					end
				end
				local finalMap = mapTree(model)
				for _, item in pending do
					local target = finalMap[item[3]]
					if target then
						pcall(function()
							item[1][item[2]] = target
						end)
					end
				end
				-- every custom mesh must really be on its part: if the executor refused, give up
				-- before anything is hidden in the game
				-- A skin the game has no class of its own for is run by the weapon's default class,
				-- which waits for parts the stock skins it was written for have (and ours may lack).
				-- Waiting for a missing part never ends, so add tiny hidden stand-ins.
				local needs = MD3.LYClassNeeds[data.cos and data.cos.ItemName or ""]
				if needs then
					for _, need in needs do
						local holder = model:FindFirstChild(need[1])
						if holder and not holder:FindFirstChild(need[2]) then
							local stand = Instance.new("Part")
							stand.Name = need[2]
							stand.Size = Vector3.new(0.001, 0.001, 0.001)
							stand.Transparency = 1
							stand.CanCollide = false
							stand.CanQuery = false
							stand.CanTouch = false
							stand.Massless = true
							stand.CastShadow = false
							stand.Anchored = true
							local origin = holder:FindFirstChild("Primary")
							if origin and origin:IsA("BasePart") then
								stand.CFrame = origin.CFrame
							end
							stand:SetAttribute("IgnoreObject", true)
							stand:SetAttribute("IgnoreTransparency", true)
							stand.Parent = holder
						end
					end
				end
				local checks = expected
				expected = nil
				for _, check in checks do
					-- compare the asset numbers: the engine may print the same id in another form
					if string.match(check[1].MeshId, "%d+") ~= string.match(check[2], "%d+") then
						model:Destroy()
						return nil, "mesh " .. check[2] .. " could not be applied (MeshId stayed '" .. tostring(check[1].MeshId) .. "')"
					end
				end
				return model
			end

			Builder.MapTree = mapTree
			Builder.PathOf = pathOf
		end
		MD3.LYSkinBuilder = Builder
	end

	-- Assault Rifle skins, built here on the stock AK-47 viewmodel so they work without
	-- the loader. The game finds a skin's model with ItemLibrary.ViewModels[name] (data)
	-- and a model of that name anywhere under PlayerScripts.Assets.ViewModels.
	-- The numbers are the loader's own, decoded from its signatures and checked
	-- against its finished models: the AK-47's original meshes are hidden and the
	-- custom ones laid over them.
	--   anchor = first MeshPart of the Body model
	--   body = anchor * (A + K) * C       magazine = body * B
	--   reload magazine = body's position + W (in the anchor's axes), body's rotation
	-- Mesh size = the mesh's own size * scale. C is in degrees (XYZ).
	do
		local K = Vector3.new(-0.008, 0.0424, 0)
		local W = Vector3.new(-0.0016, -0.371, -0.538)
		local specs = {
			["Araxys"] = { body = { 133589602939606, 138578940980140 }, mag = { 74451574145397, 138578940980140 }, scale = 0.041, A = { -0.347, -0.256, 0.025 }, B = { -0.037, -0.219, 0.207 }, C = { -0.7, -90, -2.2 } },
			["Blast X"] = { body = { 136741358636207, 98325082951137 }, mag = { 88565897839187, 98325082951137 }, scale = 0.003, A = { -0.463, -0.38, 0.083 }, B = { 0.318, -0.07, -0.025 }, C = { 0, 0, 0 } },
			["Champions"] = { body = { 82974461105308, 92353937404179 }, scale = 4.162, A = { -0.017, -0.273, 0 }, C = { 0, 90, 0 } },
			["Prelude"] = { body = { 83623764990838, 140002013666794 }, mag = { 106237786919950, 109170034379159 }, scale = 4.02, A = { 0, -0.24, 0.01 }, B = { -0.135, -0.2, -0.03 }, C = { 0, 0, 0 } },
			["Vandal"] = { body = { 138100951261312, 84167100219585 }, mag = { 92935167277909, 84167100219585 }, scale = 0.4, A = { 0.1, -0.25, 0.04 }, B = { -0.135, -0.2, -0.03 }, C = { 0, 0, 0 } },
		}
		MD3.LYSkinSpecs = specs

		local building = {}

		local function assetsRoot()
			local scripts = Players.LocalPlayer and Players.LocalPlayer:FindFirstChild("PlayerScripts")
			local assets = scripts and scripts:FindFirstChild("Assets")
			return assets and assets:FindFirstChild("ViewModels")
		end

		local function findModel(root, name)
			return MD3.LYLookThrough(root, name)
		end

		local function hide(part)
			part.Transparency = 1
			part.CastShadow = false
			part:SetAttribute("IgnoreObject", true)
			part:SetAttribute("IgnoreTransparency", true)
		end

		local function customPart(entry, scale, name)
			local part = game:GetService("AssetService"):CreateMeshPartAsync("rbxassetid://" .. entry[1])
			part.Name = name
			part.TextureID = "rbxassetid://" .. entry[2]
			part.Size = part.MeshSize * scale
			part.Anchored = true
			part.CanCollide = false
			part.CanTouch = false
			part.Massless = false
			part.CastShadow = true
			part.Material = Enum.Material.SmoothPlastic
			part.Color = Color3.new(1, 1, 1)
			part:SetAttribute("IgnoreTransparency", true)
			part:SetAttribute("WrapGroup", 2)
			part:SetAttribute("__LYCustomMesh", true)
			return part
		end

		local function buildModel(name, spec, root)
			local source = findModel(root, "AK-47")
			if not source then
				return nil
			end
			local model = source:Clone()
			model.Name = name
			local body, bolt, magazine, reload = model.Body, model.Bolt, model.Magazine, model.ReloadMagazine
			local anchor = body:FindFirstChildWhichIsA("MeshPart")
			if not anchor then
				model:Destroy()
				return nil
			end
			local anchorCFrame = anchor.CFrame
			for _, folder in { body, bolt, magazine, reload } do
				for _, child in folder:GetChildren() do
					if child:IsA("MeshPart") then
						hide(child)
					end
				end
			end
			local A, C = spec.A, spec.C
			local bodyCFrame = anchorCFrame * CFrame.new(Vector3.new(A[1], A[2], A[3]) + K)
				* CFrame.Angles(math.rad(C[1]), math.rad(C[2]), math.rad(C[3]))
			local bodyPart = customPart(spec.body, spec.scale, "__LYCustomAssaultRifleBody")
			bodyPart.CFrame = bodyCFrame
			bodyPart.Parent = body
			if spec.mag then
				local B = spec.B
				local magazinePart = customPart(spec.mag, spec.scale, "__LYCustomAssaultRifleMagazine")
				magazinePart.CFrame = bodyCFrame * CFrame.new(B[1], B[2], B[3])
				magazinePart.Parent = magazine
				local reloadPart = magazinePart:Clone()
				reloadPart.Name = "__LYCustomAssaultRifleReloadMagazine"
				reloadPart.CFrame = CFrame.new(bodyCFrame.Position + anchorCFrame:VectorToWorldSpace(W))
					* bodyCFrame.Rotation
				reloadPart.Parent = reload
			end
			return model
		end

		-- true when the skin is already usable (nothing to build)
		-- Fire sounds the loader gives some skins (read from the running game): skin -> { sound id,
		-- volume }. The game plays sounds from a callback attached to the shoot animation's name, so a
		-- skin gets its own shoot animation entry (same animation, its own callback).
		-- Rifle skins: the game's rifle shot is played at volume 0.875; the loader multiplies it
		-- (its ShootSoundVolumeMult; Blast X has none).
		local RIFLE_VOLUME = 0.875
		MD3.LYFireSounds = {
			["Champions"] = { 87090279180730, RIFLE_VOLUME * 1.79 },
			["Vandal"] = { 87090279180730, RIFLE_VOLUME * 1.8 },
			["Prelude"] = { 108688689190270, RIFLE_VOLUME * 1.5 },
			["Araxys"] = { 113636085902025, RIFLE_VOLUME * 1.7 },
			["Blast X"] = { 92756525424950, RIFLE_VOLUME },
		}

		-- Sniper / shotgun / revolver skins: the loader keeps the stock shot and swaps its FIRST sound for its own
		-- (recorded while firing: Operator 121523370790516 replaces 13270206222 of sniper_shoot1,
		-- Chamber 108153762026790 replaces 115657023572170 of sniper_keyper_shoot1; the rest of the
		-- shot - bolt, shell - plays as usual). The stock callback is wrapped once per animation and
		-- only changes anything for these skins' viewmodels.
		-- { sound id, volume multiplier (the loader's ShootSoundVolumeMult, applied to the volume the
		-- stock call used) }
		local swapsByAnimation = {
			sniper_shoot1 = { Operator = { 121523370790516, 1 } },
			sniper_keyper_shoot1 = { Chamber = { 108153762026790, 1.3 } },
			shotgun_shoot1 = { ["Oni Shotgun"] = { 113174731622393, 1.3 } }, -- replaces 13479562219
			revolver_sheriff_shoot1 = { ["Arcane (Revolver)"] = { 105841267616589, 2.3 } }, -- replaces 137835445333923
		}
		local wrapped = {}
		local function applySoundSwaps()
			local infos = index(requireModule("AnimationLibrary"), "Info")
			if type(infos) ~= "table" then
				return
			end
			for animation, swaps in swapsByAnimation do
				local info = infos[animation]
				local original = type(info) == "table" and info.SoundCallback
				if type(original) == "function" and not wrapped[animation] then
					wrapped[animation] = true
					info.SoundCallback = function(viewModel, speed, hash)
						local swap = swaps[viewModel.Name]
						if not swap then
							return original(viewModel, speed, hash)
						end
						local first = true
						local proxy = setmetatable({
							CreateSound = function(_, id, volume, ...)
								if first then
									first = false
									return viewModel:CreateSound("rbxassetid://" .. swap[1], volume * swap[2], ...)
								end
								return viewModel:CreateSound(id, volume, ...)
							end,
						}, { __index = viewModel })
						return original(proxy, speed, hash)
					end
				end
			end
		end

		local function applyFireSound(name, info)
			local sound = MD3.LYFireSounds[name]
			local library = requireModule("AnimationLibrary")
			local infos = index(library, "Info")
			local animations = type(info) == "table" and info.Animations
			local baseName = type(animations) == "table" and animations.Shoot1
			local base = sound and type(infos) == "table" and baseName and infos[baseName]
			if not base then
				return
			end
			local newName = "ly_" .. string.lower(string.gsub(name, "%W", "")) .. "_shoot1"
			local entry = table.clone(base)
			local assetId = "rbxassetid://" .. sound[1]
			entry.SoundCallback = function(viewModel)
				viewModel:CreateSound(assetId, sound[2], 1 + 0.2 * math.random(), true, 5)
			end
			infos[newName] = entry
			local sounds = index(requireModule("SoundLibrary"), "AnimationSounds")
			if type(sounds) == "table" then
				sounds[newName] = { assetId }
			end
			info.Animations = table.clone(animations)
			info.Animations.Shoot1 = newName
		end

		-- The game runs a viewmodel with a Lua class found by the skin's name (ViewModels/<weapon>/<skin>),
		-- else the weapon's default class. Keyper, for one, has a class that turns its bullet trail on and
		-- draws its orange tracers; a skin built on it ("Chamber") needs the same class under its own name.
		MD3.LYCloneViewModelClass = function(name, sourceName)
			local scripts = LocalPlayer:FindFirstChild("PlayerScripts")
			local modules = scripts and scripts:FindFirstChild("Modules")
			local classes = modules and modules:FindFirstChild("ViewModels")
			local original = classes and classes:FindFirstChild(sourceName, true)
			if original and original:IsA("ModuleScript") and not original.Parent:FindFirstChild(name) then
				local copy = original:Clone()
				copy.Name = name
				copy.Parent = original.Parent
			end
		end

		MD3.LYSkinReady = function(name)
			local viewModels = index(requireModule("ItemLibrary"), "ViewModels")
			local root = assetsRoot()
			return type(viewModels) == "table" and root ~= nil and viewModels[name] ~= nil
				and MD3.FindSkinModel(root, name) ~= nil
		end

		-- true when the game has the skin's data and model (built here if need be)
		MD3.LYEnsureSkin = function(name)
			local viewModels = index(requireModule("ItemLibrary"), "ViewModels")
			local root = assetsRoot()
			if type(viewModels) ~= "table" or not root then
				return false
			end
			local existing = MD3.LYLookThrough(root, name)
			if existing and MD3.LYSkinData[name] then
				local built = existing:GetAttribute("__LYBuild")
				if built == nil then
					-- built by an older LY (before the version tag): its parts carry "__LY…" attributes
					for _, descendant in existing:GetDescendants() do
						for key in descendant:GetAttributes() do
							if string.sub(key, 1, 4) == "__LY" then
								built = 0
								break
							end
						end
						if built ~= nil then
							break
						end
					end
				end
				if built ~= nil and built ~= MD3.LYBuildVersion then
					existing:Destroy()
					existing = nil
				end
			end
			local hasData, hasModel = viewModels[name] ~= nil, existing ~= nil
			-- (before the early return: a skin built by an earlier run still needs its class)
			local sourceName = MD3.LYSkinData[name] and string.match(MD3.LYSkinData[name], "'src':'([^']+)'")
			if sourceName then
				pcall(MD3.LYCloneViewModelClass, name, sourceName)
			end
			if hasData and hasModel then
				return true
			end
			local spec, json = specs[name], MD3.LYSkinData[name]
			if not (spec or json) or building[name] then
				return false
			end
			building[name] = true
			local ok, result = pcall(function()
				local data = json and HttpService:JSONDecode((string.gsub(json, "'", '"')))
				if data then
					MD3.LYCloneViewModelClass(name, data.src)
				end
				if not hasModel then
					local model, reason
					if data then
						model, reason = MD3.LYSkinBuilder.Build(name, data, root)
					else
						model = buildModel(name, spec, root)
					end
					if not model then
						error(reason or "source model missing")
					end
					model.Parent = root
					MD3.ForgetSkinModel(name)
				end
				local entry = MD3.LYExtraSkins[name]
				if not hasData then
					local source = viewModels[data and data.src or "AK-47"]
					local info = type(source) == "table" and table.clone(source) or {}
					if data then
						for key, value in data.il do
							info[key] = key == "RootPartOffset" and CFrame.new(table.unpack(value)) or value
						end
					else
						info.Image = "rbxassetid://" .. entry[2]
						info.ImageHighResolution = "rbxassetid://" .. entry[3]
					end
					applyFireSound(name, info)
					applySoundSwaps()
					viewModels[name] = info
				end
				local library = requireModule("CosmeticLibrary")
				local cosmetics = index(library, "Cosmetics")
				if type(cosmetics) == "table" and cosmetics[name] == nil then
					local rarities = index(library, "Rarities")
					if data then
						local cosmetic = table.clone(data.cos)
						-- the loader adds its own "Contraband" rarity; use one the game has
						if type(rarities) ~= "table" or rarities[cosmetic.Rarity] == nil then
							cosmetic.Rarity = "Unobtainable"
						end
						cosmetics[name] = cosmetic
					else
						cosmetics[name] = {
							DisplayName = name,
							Image = "rbxassetid://" .. entry[2],
							ImageHighResolution = "rbxassetid://" .. entry[3],
							ImageScale = 3,
							ItemName = entry[1],
							Locked = false,
							Owned = true,
							Rarity = "Unobtainable",
							SourceViewModelName = "AK-47",
							Type = "Skin",
							Unlocked = true,
							ViewModelName = name,
							WorldViewModelName = "AK-47",
						}
					end
				end
			end)
			building[name] = nil
			if not ok then
				MD3.LYLastError = tostring(result)
				KQ("LY skin " .. name .. ": " .. tostring(result))
			end
			return ok
		end
	end

	-- Hooks for skins built by code instead of LY's JSON data (none at the moment).
	MD3.CustomClass = {}
	MD3.CustomCosmetics = {}
	MD3.CustomBuilders = {}
	local baseEnsure = MD3.LYEnsureSkin
	MD3.LYEnsureSkin = function(name)
		local custom = MD3.CustomBuilders[name]
		if custom then
			return custom(name)
		end
		return baseEnsure(name)
	end

	-- Adds every custom skin to CosmeticLibrary.Cosmetics (cheap: no models are built here).
	MD3.LYRequire = requireModule
	MD3.RegisterAll = function()
		local library = requireModule("CosmeticLibrary")
		local cosmetics = index(library, "Cosmetics")
		local rarities = index(library, "Rarities")
		if type(cosmetics) ~= "table" then
			return false
		end
		for name, entry in MD3.LYExtraSkins do
			if cosmetics[name] == nil then
				local cosmetic
				local json = MD3.LYSkinData[name]
				if MD3.CustomCosmetics[name] then
					cosmetic = table.clone(MD3.CustomCosmetics[name])
					-- Kicia's catalog only lists the rarities it knows (no "Contraband"), so every
					-- custom skin is filed under "Unobtainable" or it would be filtered out.
					cosmetic.Rarity = "Unobtainable"
				elseif json then
					local ok, data = pcall(function()
						return HttpService:JSONDecode((string.gsub(json, "'", '"')))
					end)
					if ok and type(data) == "table" and type(data.cos) == "table" then
						cosmetic = table.clone(data.cos)
						cosmetic.Rarity = "Unobtainable" -- see above: Kicia filters out "Contraband"
					end
				else
					cosmetic = {
						DisplayName = name,
						Image = "rbxassetid://" .. entry[2],
						ImageHighResolution = "rbxassetid://" .. entry[3],
						ImageScale = 3,
						ItemName = entry[1],
						Locked = false,
						Owned = true,
						Rarity = "Unobtainable",
						SourceViewModelName = "AK-47",
						Type = "Skin",
						Unlocked = true,
						ViewModelName = name,
						WorldViewModelName = "AK-47",
					}
				end
				if cosmetic and not writeField(cosmetics, name, cosmetic) then
					pcall(function() cosmetics[name] = cosmetic end)
				end
			end
		end
		return true
	end

	-- Called from Kicia's weapon-data hooks. Returns true when the skin can be used right now;
	-- otherwise starts building it in the background and returns false (caller falls back to stock).
	-- Makes the game's UI (hotbar icons, menus) read the weapon data again, the way LYHub does after
	-- an equip: PlayerDataController.CurrentData:GetDataChangedSignal(field) is fired by hand.
	local function fireDataChanged(field)
		local current = index(requireModule("PlayerDataController"), "CurrentData")
		if current == nil then
			return
		end
		local ok, signal = pcall(function()
			return current:GetDataChangedSignal(field)
		end)
		if not ok or signal == nil then
			return
		end
		local meta = getmetatable(signal)
		local methods = type(meta) == "table" and rawget(meta, "__index")
		local fire = type(methods) == "table" and rawget(methods, "Fire")
		if type(fire) == "function" then
			task.spawn(fire, signal)
		else
			task.spawn(pcall, function()
				signal:Fire()
			end)
		end
	end
	MD3.RefreshUI = function()
		fireDataChanged("WeaponInventory")
		fireDataChanged("WeaponData")
	end

	-- Builds a skin in the background; when it is done the UI is refreshed so it stops showing
	-- the stock look it was given while the model was still missing.
	local lastRefresh = {}
	-- LY's model builder keeps its working state in shared upvalues (`expected`), so two builds at the
	-- same time corrupt each other ("attempt to iterate over a nil value"). Build one skin at a time.
	local buildBusy = false
	-- Usable() asks for a build on every weapon-data read and every 0.25 s from the reload wait, so
	-- a skin is queued at most once, and a failed build waits before it is tried again (5 s, then
	-- doubling up to 60 s) instead of every queued request rebuilding it in turn.
	local buildQueued, buildFailures, buildRetryAt = {}, {}, {}
	MD3.Build = function(name)
		if buildQueued[name] or os.clock() < (buildRetryAt[name] or 0) then
			return
		end
		buildQueued[name] = true
		task.spawn(function()
			while buildBusy do
				task.wait(0.1)
			end
			buildBusy = true
			local okBuild, built = pcall(MD3.LYEnsureSkin, name)
			buildBusy = false
			buildQueued[name] = nil
			if not okBuild then
				KQ("[Kicia LY] build " .. tostring(name) .. " errored: " .. tostring(built))
				built = false
			end
			if built then
				buildFailures[name] = nil
				buildRetryAt[name] = nil
				if tick() - (lastRefresh[name] or 0) > 3 then
					lastRefresh[name] = tick()
					MD3.RefreshUI()
				end
			else
				local failures = (buildFailures[name] or 0) + 1
				local delay = math.min(60, 5 * 2 ^ (failures - 1))
				buildFailures[name] = failures
				buildRetryAt[name] = os.clock() + delay
				KQ(string.format("[Kicia LY] build %s not done (attempt %d), next try in %d s", tostring(name), failures, delay))
			end
		end)
	end

	-- Re-runs the hotbar slot's setup for a weapon so its icon follows the current skin.
	MD3.RefreshHotbar = function(weapon)
		pcall(function()
			local fighterController = requireModule("FighterController")
			local fighter = fighterController and fighterController:GetFighter(LocalPlayer)
			local hotbar = fighter and fighter.FighterInterface and fighter.FighterInterface.Hotbar
			for _, slot in pairs(hotbar and hotbar._hotbar_slots or {}) do
				local item = slot.ClientItem
				if item and item.Name == weapon then
					if slot._Setup then
						pcall(slot._Setup, slot)
					end
					if slot.UpdateVisuals then
						pcall(slot.UpdateVisuals, slot)
					end
					break
				end
			end
		end)
	end

	-- After any skin change: data-changed signals (menus, hotbar data) plus the hotbar slot itself.
	-- Runs deferred (yields). Changes made in the same frame (a config load reloads every weapon)
	-- share one batch: the data-changed signals fire once, then each weapon's hotbar slot is redone.
	-- A change that arrives after the signals already fired starts a new batch.
	local refreshBatch = nil
	MD3.RefreshWeaponUI = function(weapon)
		if refreshBatch ~= nil and not refreshBatch.Fired then
			if weapon ~= nil then
				refreshBatch.Weapons[weapon] = true
			end
			return
		end
		local batch = { Weapons = {}, Fired = false }
		if weapon ~= nil then
			batch.Weapons[weapon] = true
		end
		refreshBatch = batch
		task.wait()
		batch.Fired = true
		MD3.RefreshUI()
		task.wait(0.1)
		if refreshBatch == batch then
			refreshBatch = nil
		end
		for name in batch.Weapons do
			MD3.RefreshHotbar(name)
		end
	end

	-- Puts a custom skin on the gun in your hands without respawning, the way Harion does it:
	-- copy the old viewmodel's _serial, set Skin / Name, build the new viewmodel from the skin's
	-- own Lua class at identity 2, swap it into item.ViewModel, then refresh the hotbar slot.
	-- Returns true when the new viewmodel is in place, or false + a reason.
	local function normalizedName(name)
		return (string.lower((string.gsub(tostring(name or ""), "[%W_]+", ""))))
	end

	local function classFor(className, defaultClass)
		local scripts = LocalPlayer:FindFirstChild("PlayerScripts")
		local modules = scripts and scripts:FindFirstChild("Modules")
		local folder = modules and modules:FindFirstChild("ViewModels")
		if not folder then
			return defaultClass
		end
		local key = normalizedName(className)
		for _, module in folder:GetDescendants() do
			if module:IsA("ModuleScript") and normalizedName(module.Name) == key then
				local ok, class = pcall(require, module)
				if ok and type(class) == "table" and type(class.new) == "function" then
					return class
				end
				break
			end
		end
		return defaultClass
	end

	MD3.ApplyLive = function(weapon, skinName)
		local identity = type(getthreadidentity) == "function" and getthreadidentity() or nil
		local function setIdentity(level)
			if type(setthreadidentity) == "function" and level then
				pcall(setthreadidentity, level)
			end
		end
		local ok, applied, reason = pcall(function()
			setIdentity(2)
			local fighterController = requireModule("FighterController")
			local replicated = requireModule("ReplicatedClass")
			local viewModelClass = requireModule("ClientViewModel")
			if not (fighterController and replicated and viewModelClass) then
				return false, "game modules missing"
			end
			local fighter = fighterController:GetFighter(LocalPlayer)
			if not fighter or not fighter.Items then
				return false, "no fighter"
			end
			local item = nil
			for _, candidate in fighter.Items do
				if candidate.Name == weapon then
					item = candidate
					break
				end
			end
			if not item then
				return false, "no item named " .. tostring(weapon)
			end
			local oldViewModel = item.ViewModel
			if not (oldViewModel and oldViewModel._serial) then
				return false, "item has no viewmodel"
			end
			local wasEquipped = fighter.EquippedItem == item or item.IsEquipped == true

			local serial = table.clone(oldViewModel._serial)
			local dataKey = replicated:ToEnum("Data")
			local data = table.clone(serial.Data or serial[dataKey] or {})
			serial[dataKey] = data
			serial.Data = nil
			data[replicated:ToEnum("Skin")] = { Name = skinName }
			data[replicated:ToEnum("Name")] = skinName
			data.Skin = nil
			data.Name = nil

			local json = MD3.LYSkinData[skinName]
			local className = MD3.CustomClass[skinName] or json and string.match(json, "'src':'([^']+)'") or "AK-47"
			local targetClass = classFor(className, viewModelClass)
			local built, newViewModel = pcall(function()
				return targetClass.new(serial, item)
			end)
			local function valid(viewModel)
				return type(viewModel) == "table" and viewModel._destroyed ~= true
					and typeof(viewModel.Model) == "Instance" and typeof(viewModel.ItemModel) == "Instance"
			end
			if not (built and valid(newViewModel)) then
				if type(newViewModel) == "table" and newViewModel.Destroy then
					pcall(newViewModel.Destroy, newViewModel)
				end
				return false, "viewmodel build failed: " .. tostring(newViewModel)
			end

			if wasEquipped and oldViewModel.Unequip then
				pcall(oldViewModel.Unequip, oldViewModel)
			end
			item.ViewModel = newViewModel
			if wasEquipped and newViewModel.Equip then
				pcall(newViewModel.Equip, newViewModel, true)
			end
			if oldViewModel ~= newViewModel and oldViewModel.Destroy then
				pcall(oldViewModel.Destroy, oldViewModel)
			end

			MD3.RefreshHotbar(weapon)
			return true
		end)
		setIdentity(identity)
		if not ok then
			return false, tostring(applied)
		end
		return applied, reason
	end

	-- The game's weapon pickers get a gun's icon from ItemLibrary:GetViewModelImageFromWeaponData
	-- (Harion hooks it too). It does not know our skins, so answer for them from their cosmetic entry.
	MD3.InstallImageHook = function()
		local library = requireModule("ItemLibrary")
		if type(library) ~= "table" or MD3.ImageHook then
			return false
		end
		local original = library.GetViewModelImageFromWeaponData
		if type(original) ~= "function" then
			return false
		end
		local function wrapper(self, weaponData, highRes, ...)
			local skin = type(weaponData) == "table" and weaponData.Skin
			local name = type(skin) == "table" and skin.Name or (type(skin) == "string" and skin or nil)
			if name and MD3.LYExtraSkins[name] then
				local cosmetics = index(requireModule("CosmeticLibrary"), "Cosmetics")
				local cosmetic = cosmetics and index(cosmetics, name)
				local image = type(cosmetic) == "table" and (highRes and cosmetic.ImageHighResolution or cosmetic.Image)
				if type(image) == "string" and image ~= "" then
					return image
				end
			end
			return original(self, weaponData, highRes, ...)
		end
		if not writeField(library, "GetViewModelImageFromWeaponData", wrapper) then
			return false
		end
		MD3.ImageHook = { Library = library, Original = original }
		return true
	end

	MD3.Repaired = {}
	MD3.Usable = function(name)
		if type(name) ~= "string" or MD3.LYExtraSkins[name] == nil then
			return true
		end
		if MD3.LYSkinReady(name) then
			-- A model built earlier from a Camera-less source breaks the viewmodel: rebuild it once
			-- from a source that has a Camera.
			if not MD3.Repaired[name] then
				local scripts = LocalPlayer:FindFirstChild("PlayerScripts")
				local assets = scripts and scripts:FindFirstChild("Assets")
				local root = assets and assets:FindFirstChild("ViewModels")
				local model = root and MD3.FindSkinModel(root, name)
				if model and not model:FindFirstChild("Camera") then
					local json = MD3.LYSkinData[name]
					local sourceName = MD3.CustomClass[name] or json and string.match(json, "'src':'([^']+)'") or "AK-47"
					local source = MD3.LYLookThrough(root, sourceName)
					if source and source:FindFirstChild("Camera") then
						MD3.Repaired[name] = true
						model:Destroy()
						MD3.Build(name)
						return false
					end
				end
				MD3.Repaired[name] = true
			end
			return true
		end
		MD3.Build(name)
		return false
	end

	return MD3
end

do
	local ok, result = pcall(setupLYSkins)
	if not ok then
		KQ("[Kicia Rebuild] LY skins failed to set up: " .. tostring(result))
	else
		K.Skins = result
		local t0 = tick()
		local registered = false
		repeat
			local okReg, done = pcall(result.RegisterAll)
			if okReg and done then registered = true break end
			task.wait(0.25)
		until tick() - t0 > 30
		-- Summary in the console: proves which build is running and which skins did not register.
		local library = result.LYRequire and result.LYRequire("CosmeticLibrary")
		local cosmetics = library and library.Cosmetics
		local total, missing = 0, {}
		for name in result.LYExtraSkins do
			total += 1
			local entry = type(cosmetics) == "table" and cosmetics[name]
			if not (type(entry) == "table" and entry.Type == "Skin") then
				table.insert(missing, name)
			end
		end
		pcall(result.InstallImageHook)
		K.onUnload(function()
			local hook = result.ImageHook
			if hook then
				pcall(rawset, hook.Library, "GetViewModelImageFromWeaponData", hook.Original)
				result.ImageHook = nil
			end
		end)
		local sample = type(cosmetics) == "table" and cosmetics["Arcane (Revolver)"]
		KQ(string.format("[Kicia LY] custom skins registered: %d/%d (library ready: %s, Arcane: %s/%s)%s",
			total - #missing, total, tostring(registered),
			tostring(type(sample) == "table" and sample.ItemName), tostring(type(sample) == "table" and sample.Rarity),
			#missing > 0 and (" missing: " .. table.concat(missing, ", ")) or ""))
	end
end


--  Kicia's error reporter needs a sink; ours prints to the F9 console.
tbl17.b().use({ Report = function(_, e)
    local detail = type(e) == "table" and (e.Detail or e.Operation) or e
    KQ("[Kicia Rebuild] " .. tostring(detail))
end })

local boot = (function()
    local store = tbl17.bG()
    local profiles = GlobalTrove:Add(tbl17.bN().new(store))
    store:UseMiddleware(profiles)
    local fonts = tbl17.az()
    GlobalTrove:Add(tbl17.aB().use(store, { "Notifications" }, { "Theme" }, function(f) return fonts:Get(f) end,
        tbl17.bI().Notifications))

    local reporter = GlobalTrove:Add(tbl17.ad().new())
    local state = GlobalTrove:Add(tbl17.ae().new(K.AccountDir))
    local stateData = state:Load()
    local autoLoadFailed = false
    if stateData.AutoLoad and stateData.AutoLoadConfigName ~= nil then
        -- The file can be briefly unreadable right after injection (another client writing, a half-written
        -- file, a slow disk) and readfile can throw, which used to abort the whole boot. So a failed load is
        -- retried a few times before giving up; a config from a newer version never succeeds, so that one is not.
        local r
        for attempt = 1, 4 do
            local okLoad, res = pcall(store.LoadFromFile, store, stateData.AutoLoadConfigName)
            if not okLoad then
                res = { Ok = false, Error = { Detail = tostring(res) } }
            end
            local detail = res.Ok and "" or tostring(res.Error.Detail)
            if res.Ok or attempt == 4 or string.find(detail, "newer than current version", 1, true) ~= nil then
                if okLoad then
                    r = reporter:ReportResult(res)
                else
                    KQ("[Kicia Rebuild] auto-load failed: " .. detail)
                    r = res
                end
                break
            end
            task.wait(0.5)
        end
        autoLoadFailed = not r.Ok
        if not r.Ok then
            local text = "Failed to auto-load the selected config"
            if string.find(r.Error.Detail, "newer than current version", 1, true) ~= nil then
                text = "Your selected config was saved by a newer version - update or pick another config"
            end
            tbl17.aB().get():Notify(text)
        elseif #tbl17.bc().takeDroppedPaths() > 0 then
            tbl17.aB().get():Notify("Some saved settings could not be restored and were reset to defaults")
        end
    end

    -- Re-run After Teleport (LYHub style): the loader is queued once per server as soon as the
    -- toggle is on (the game moves you into matches without always firing OnTeleport). The
    -- queued loader waits for the game to finish loading and reads a flag file when it runs, so
    -- turning the toggle off afterwards still cancels the re-run.
    do
        -- UE style: persistence is the marker file LOAD_PERSISTENT (written while the toggle is on,
        -- deleted when it is off) and LOAD_SILENTLY marks a silent load. The queued loader checks
        -- isfile("LOAD_PERSISTENT") itself, so turning the toggle off still cancels the re-run.
        -- per-account marker files / loader file (11/21 fix, kept): the old shared names made every account follow whichever wrote last
        local PERSIST_FILE = K.AccountDir .. "/LOAD_PERSISTENT"
        local SILENT_FILE = K.AccountDir .. "/LOAD_SILENTLY"
        local LOADER_FILE = K.AccountDir .. "/rerun_loader.lua"
        -- What the queued loader runs. getgenv().KiciaRerunFile (a workspace file) wins if set;
        -- otherwise the script is downloaded from the public GitHub repo kkbisnyu-sys/ki-kh (branch main, kh.lua),
        -- so Re-run works without a local copy of the script. A raw.githubusercontent.com address is sent with
        -- a GitHub token when one exists (workspace file kiciarebuild/github_token.txt, or
        -- getgenv().KiciaGithubToken), which is only needed for a private repo; with no token it is a plain
        -- game:HttpGet. The token is never written into this script. getgenv().KiciaRerunUrl overrides the
        -- address (e.g. a private repo together with a token).
        local RERUN_URL = getgenv().KiciaRerunUrl
            or "https://raw.githubusercontent.com/kkbisnyu-sys/ki-kh/main/kh.lua"
        local RERUN_LOADER = [[
if not isfile("LOAD_PERSISTENT") then return end
local _env = (getgenv and getgenv()) or _G
local _job = tostring(game.JobId)
-- One loader per server. The script queues a loader and every loader re-queues itself, so one teleport can run
-- several (the log showed up to 4 in the same server, each starting the script). getgenv() is not one shared table
-- in Real and JobId is often still "" this early, so the claim is an Instance in the hidden UI container, which is
-- new for every server and seen by every chunk. Check and claim happen with no yield in between.
local _hui = nil
pcall(function() _hui = gethui and gethui() end)
if typeof(_hui) ~= "Instance" then _hui = game:GetService("CoreGui") end
local function _find(name)
    local found = nil
    pcall(function() found = _hui:FindFirstChild(name) end)
    if found == nil then pcall(function() found = game:GetService("CoreGui"):FindFirstChild(name) end) end
    return found
end
if _find("KiciaRerunClaim") ~= nil then return end
do
    local _claim = Instance.new("Folder")
    _claim.Name = "KiciaRerunClaim"
    _claim.Parent = _hui
end
_env.__KiciaRerunJob = _job
_env.SILENT = isfile("LOAD_SILENTLY")
-- trace of what the loader did, kept in kiciarebuild/logs/rerun_loader.log (survives crashes)
local function _log(m)
    pcall(function()
        appendfile("kiciarebuild/logs/rerun_loader.log", os.date("%%H:%%M:%%S") .. " job=" .. _job .. " " .. m .. "\n")
    end)
end
_log("loader started")
-- Queue the next hop right away. Waiting for the game and the script to load takes a while, and a
-- teleport inside that window would otherwise find nothing queued and end the chain. (The loader's
-- own source is kept in a file by the script, because a queued chunk cannot read its own text.)
do
    local _q = queue_on_teleport or queueonteleport
        or (syn and syn.queue_on_teleport) or (fluxus and fluxus.queue_on_teleport)
    local _self = "kiciarebuild/rerun_loader.lua"
    if _q and isfile(_self) then pcall(function() _q(readfile(_self)) end) end
end
local function waitFor(cond, timeout)
    local t0 = tick()
    while not cond() and tick() - t0 < timeout do task.wait(0.25) end
    return cond()
end
if not game:IsLoaded() then game.Loaded:Wait() end
local _lp = game:GetService("Players").LocalPlayer
if not _lp then repeat task.wait() _lp = game:GetService("Players").LocalPlayer until _lp end
waitFor(function()
    local c = _lp.Character
    return c and c:FindFirstChildOfClass("Humanoid") and c:FindFirstChild("HumanoidRootPart")
end, 60)
waitFor(function() return game:GetService("ReplicatedStorage"):FindFirstChild("Remotes") end, 30)
waitFor(function()
    local scripts = _lp:FindFirstChild("PlayerScripts")
    local controllers = scripts and scripts:FindFirstChild("Controllers")
    local gui = _lp:FindFirstChild("PlayerGui")
    return controllers and controllers:FindFirstChild("FighterController") and gui and gui:FindFirstChild("MainGui")
end, 45)
local _cp = game:GetService("ContentProvider")
local _quiet, _t0 = 0, tick()
while _quiet < 6 and tick() - _t0 < 40 do
    if _cp.RequestQueueSize == 0 then _quiet += 1 else _quiet = 0 end
    task.wait(0.25)
end
task.wait(2)
if not isfile("LOAD_PERSISTENT") then return end
local _file = %q
local _url = %q
-- the cached copy is kept per address, so a copy fetched from an old loader URL is never run for a new one
local _h = 0
for _i = 1, #_url do _h = (_h * 31 + string.byte(_url, _i)) %% 4294967296 end
local _cache = "kiciarebuild/rerun_cache_" .. _h .. ".lua"
local function _fetch()
    local ok, res
    if _file ~= "" then
        ok, res = pcall(readfile, _file)
    elseif string.find(_url, "raw.githubusercontent.com", 1, true) then
        -- GitHub raw address: with a token (kiciarebuild/github_token.txt) the request carries it, which a
        -- private repo needs; without one, or if that request fails, a plain HttpGet (public repos)
        local _tok = _env.KiciaGithubToken
        if (not _tok or _tok == "") and isfile("kiciarebuild/github_token.txt") then
            local okT, t = pcall(readfile, "kiciarebuild/github_token.txt")
            if okT and type(t) == "string" then _tok = string.gsub(t, "[\r\n\t ]", "") end
        end
        local _req = request or http_request or (syn and syn.request) or (fluxus and fluxus.request)
        if _req and _tok and _tok ~= "" then
            local okR, resp = pcall(_req, { Url = _url, Method = "GET", Headers = { Authorization = "token " .. _tok, ["User-Agent"] = "KiciaRerun" } })
            if okR and type(resp) == "table" and resp.StatusCode == 200 then
                ok, res = true, resp.Body
            else
                _log("github fetch with token failed: " .. tostring(okR and type(resp) == "table" and resp.StatusCode or resp))
            end
        end
        if not ok then
            ok, res = pcall(game.HttpGet, game, _url)
        end
    else
        ok, res = pcall(game.HttpGet, game, _url)
    end
    if ok and type(res) == "string" and res ~= "" then
        -- keep the last good copy, used below when the host cannot be reached
        if _file == "" then pcall(writefile, _cache, res) end
        return res
    end
    return nil
end
-- Up to 4 rounds. Each round: fetch (8 tries, growing waits), else the cached copy of the last good fetch;
-- then run it and wait for the script to report in (it sets getgenv().KiciaRebuild right at its top). If it
-- never does (request blocked, key check failed, compile error), the next round tries again. A script that
-- did start is never run a second time.
_job = tostring(game.JobId)
_env.__KiciaRerunJob = _job
-- the executor's auto-execute folder (or the user) may already have started the script while we waited for the game
local function _running()
    return _find("KiciaRebuildInstance") ~= nil
end
if _running() then _log("script already running, not starting a second copy") return end
local _before = _env.KiciaRebuild
for _round = 1, 4 do
    local _src
    for i = 1, 8 do
        _src = _fetch()
        if _src then break end
        task.wait(math.min(2 * i, 10))
    end
    if not _src and _file == "" and isfile(_cache) then
        local ok, res = pcall(readfile, _cache)
        if ok and type(res) == "string" and res ~= "" then _src = res _log("round " .. _round .. ": using cached copy") end
    end
    if _running() then _log("script started elsewhere, stopping") return end
    if _src then
        local fn = loadstring(_src)
        if fn then
            _log("round " .. _round .. ": running the script")
            task.spawn(fn)
            local t0 = tick()
            local function _reported() return _running() or (_env.KiciaRebuild ~= nil and _env.KiciaRebuild ~= _before) end
            while tick() - t0 < 120 and not _reported() do
                task.wait(0.5)
            end
            if _reported() then
                _log("script reported in after " .. math.floor(tick() - t0) .. " s")
                return
            end
            _log("round " .. _round .. ": script did not report in within 120 s")
        else
            _log("round " .. _round .. ": the downloaded source did not compile")
        end
    else
        _log("round " .. _round .. ": no source (download failed, no cache)")
    end
    task.wait(3)
    if not isfile("LOAD_PERSISTENT") then _log("marker gone, stopping") return end
end
_log("gave up after 4 rounds")
_env.__KiciaRerunJob = nil
pcall(function() _find("KiciaRerunClaim"):Destroy() end)
]]
        -- the loader text names the marker files and its own file literally; point them at this account's files
        RERUN_LOADER = RERUN_LOADER:gsub('"LOAD_PERSISTENT"', function() return string.format("%q", PERSIST_FILE) end):gsub('"LOAD_SILENTLY"', function() return string.format("%q", SILENT_FILE) end):gsub('"kiciarebuild/rerun_loader.lua"', function() return string.format("%q", LOADER_FILE) end)
        local queueFn = K.fn("queue_on_teleport") or K.fn("queueonteleport")
        if queueFn == nil then
            -- some executors only expose it under their own table
            pcall(function()
                local env = getgenv()
                local q = (env.syn and env.syn.queue_on_teleport) or (env.fluxus and env.fluxus.queue_on_teleport)
                if type(q) == "function" then queueFn = q end
            end)
        end
        local wrf, mkf, isf = K.fn("writefile"), K.fn("makefolder"), K.fn("isfolder")
        local queuedJob = nil

        local function rerunEnabled()
            local ok, enabled = pcall(function() return store.Data.AutoExecuteScript.Enabled end)
            return ok and enabled == true
        end

        -- Started by the queued loader (it stamps this server's JobId, and LOAD_PERSISTENT is still there, which
        -- means the toggle was on when the player left): carry the toggle over. The toggle lives in the config, so
        -- without this a config that was saved before the toggle was switched on (or no auto-load at all) reads
        -- "off" here, the first sync deletes LOAD_PERSISTENT and the chain ends after a single teleport.
        do
            local isfile_ = K.fn("isfile")
            local okEnv, jobMark = pcall(function() return getgenv().__KiciaRerunJob end)
            local job = tostring(game.JobId)
            -- getgenv() is not reliably shared in Real, so the loader's claim Instance counts too
            local claimed = okEnv and job ~= "" and jobMark == job
            if not claimed then
                pcall(function()
                    local hui = K.fn("gethui") and K.fn("gethui")()
                    claimed = (typeof(hui) == "Instance" and hui:FindFirstChild("KiciaRerunClaim") ~= nil)
                        or game:GetService("CoreGui"):FindFirstChild("KiciaRerunClaim") ~= nil
                end)
            end
            if claimed and isfile_ and isfile_(PERSIST_FILE) and not rerunEnabled() then
                pcall(store.Set, store, { "AutoExecuteScript", "Enabled" }, true)
                if not rerunEnabled() then
                    pcall(function() store.Data.AutoExecuteScript.Enabled = true end)
                end
            end
        end

        local function sync()
            local enabled = rerunEnabled()
            if not (wrf and queueFn) then
                if enabled then
                    warn("[Kicia Rebuild] Re-run After Teleport: executor has no queue_on_teleport / writefile")
                end
                return
            end
            local file = getgenv().KiciaRerunFile
            local isfile_ = K.fn("isfile")
            if enabled and file and isfile_ and not isfile_(file) then
                warn("[Kicia Rebuild] Re-run After Teleport: file `" .. file .. "` not found in the workspace")
                enabled = false
            end
            if enabled then
                pcall(wrf, PERSIST_FILE, "")
            else
                local dlf = K.fn("delfile")
                if dlf then pcall(dlf, PERSIST_FILE) end
            end
            local job = tostring(game.JobId)
            if enabled and queuedJob ~= job then
                local src = RERUN_LOADER:format(file or "", RERUN_URL)
                local key = getgenv().script_key
                if type(key) == "string" and key ~= "" then
                    src = string.format("script_key=%q; ", key) .. src
                end
                -- the loader re-queues itself from this file as soon as it starts (see RERUN_LOADER)
                pcall(wrf, LOADER_FILE, src)
                for attempt = 1, 3 do
                    if pcall(queueFn, src) then
                        queuedJob = job
                        K.Log("rerun", "loader queued for job " .. job .. " (attempt " .. attempt .. ")")
                        break
                    end
                    K.Log("rerun", "queue_on_teleport failed (attempt " .. attempt .. ")")
                    task.wait(0.25)
                end
            end
        end

        local conn = player.OnTeleport:Connect(function(state)
            if state ~= Enum.TeleportState.Failed then
                -- a queue only lasts one teleport: allow queueing again for the next one
                if state == Enum.TeleportState.Started then queuedJob = nil end
                sync()
            end
        end)
        K.onUnload(function() conn:Disconnect() end)

        task.spawn(function()
            local last = nil
            -- When the auto-load failed, the toggle only reads "off" because the saved config was not applied.
            -- The first sync must not treat that as the user turning it off (it deletes LOAD_PERSISTENT and
            -- silently cancels the re-run), so start from the current state; real changes still sync.
            if autoLoadFailed and not rerunEnabled() then
                last = false
            end
            -- Watchdog while the toggle is on: every 5 s make sure this server's loader really is queued
            -- (the queue call can fail) and that the marker file still exists (another client or a manual
            -- cleanup can delete it), and repair whichever is missing.
            local lastCheck = 0
            while not K.destroyed do
                local now = rerunEnabled()
                if now ~= last then
                    last = now
                    sync()
                elseif now and os.clock() - lastCheck >= 5 then
                    lastCheck = os.clock()
                    local isfile_ = K.fn("isfile")
                    if queuedJob ~= tostring(game.JobId) or (isfile_ and not isfile_(PERSIST_FILE)) then
                        sync()
                    end
                end
                task.wait(1)
            end
        end)
    end

    local Theme = tbl17.A()
    local theme = store.Data.Theme
    if theme ~= nil then
        for k, v in next, theme do
            if Theme.Tokens[k] ~= nil and typeof(v) == "Color3" then Theme.refresh(k, v) end
        end
    end

    local registry = GlobalTrove:Add(tbl17.bK().new())
    local identities = GlobalTrove:Add(tbl17.bL().new(registry))
    local tags = GlobalTrove:Add(tbl17.bM().new(registry))
    GlobalTrove:Add(tbl17.bR().new(tags, registry))
    GlobalTrove:Add(tbl17.bZ().new(identities))
    local avatar = GlobalTrove:Add(tbl17.b6().new(registry))

    return {
        StoreProfiles = profiles,
        PlayerRegistry = registry,
        PlayerIdentities = identities,
        PlayerTags = tags,
        DecoratorFactory = avatar ~= nil and avatar:GetDecoratorFactory() or nil,
        ArmAvatarSpoofer = function() avatar:Arm() end,
        GeneralState = state,
        GeneralStateData = stateData,
    }
end)()

function K.Unload()
    if K.destroyed then return end
    K.destroyed = true
    K.loading = false
    pcall(function() K.Marker:Destroy() end)
    for _, f in ipairs(K.cleanups) do pcall(f) end
    -- connections handed to K.track were never disconnected, so an unloaded copy kept running next to the new one
    for _, c in ipairs(K.connections) do pcall(function() c:Disconnect() end) end
    table.clear(K.connections)
    pcall(function() GlobalTrove:Destroy() end)
    if getgenv().KiciaRebuild == K then getgenv().KiciaRebuild = nil end
end

K.Mark("division hud")
--==========================================================================
--  Division HUD (DH): the self HUD of The Division, drawn around the crosshair. Ammo / reserve above the
--  crosshair, health and shield under it with a thin health line, the WASD keys (accent colour while held, white
--  colour while idle) and the horizontal speed. Everything is read from the LOCAL player only: the Humanoid
--  (health), FighterController.LocalFighter.EquippedItem (ammo), UserInputService (keys), the root part
--  velocity (speed). Shield is shown only when the game puts a numeric Shield / Armor attribute on the
--  character or the player (Rivals has none, so the shield cell stays hidden there).
--  3D Mode (default): drawn on a SurfaceGui in the world, tilted, with parallax; off: flat ScreenGui overlay.
--  Settings: config.Data.DivisionHud, menu: Visuals > Player ESP > Division HUD.
--==========================================================================
do -- DH
    local started = false
    K.StartDivisionHud = function()
        if started then return end
        started = true

        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local UserInputService = game:GetService("UserInputService")
        local HttpService = game:GetService("HttpService")
        local LocalPlayer = Players.LocalPlayer
        local config = tbl17.bG()

        local WHITE = Color3.new(1, 1, 1)
        local DARK = Color3.fromRGB(20, 20, 20)
        local DEFAULT_ACCENT = Color3.fromRGB(255, 150, 30)
        local FONT = Enum.Font.GothamMedium

        local function create(className, props)
            local instance = Instance.new(className)
            for k, v in props do
                if k ~= "Parent" then instance[k] = v end
            end
            instance.Parent = props.Parent
            return instance
        end

        --  a text label anchored by `align` ("L" / "R" / "C") at an offset from the crosshair
        local function label(parent, text, x, y, size, color, align)
            local ax = align == "R" and 1 or (align == "C" and 0.5 or 0)
            return create("TextLabel", {
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                AnchorPoint = Vector2.new(ax, 0.5),
                Position = UDim2.fromOffset(x, y),
                Size = UDim2.fromOffset(60, size + 4),
                Font = FONT,
                Text = text,
                TextSize = size,
                TextColor3 = color,
                TextStrokeTransparency = 0.3,
                TextStrokeColor3 = Color3.new(0, 0, 0),
                TextXAlignment = align == "R" and Enum.TextXAlignment.Right or (align == "C" and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left),
                TextYAlignment = Enum.TextYAlignment.Center,
                ZIndex = 2,
                Parent = parent,
            })
        end

        local function box(parent, x, y, w, h, color, radius)
            local f = create("Frame", {
                BackgroundColor3 = color,
                BorderSizePixel = 0,
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromOffset(x, y),
                Size = UDim2.fromOffset(w, h),
                ZIndex = 2,
                Parent = parent,
            })
            if radius then create("UICorner", { CornerRadius = UDim.new(0, radius), Parent = f }) end
            return f
        end

        local gui = create("ScreenGui", {
            Name = HttpService:GenerateGUID(false),
            ResetOnSpawn = false,
            IgnoreGuiInset = true,
            DisplayOrder = 84,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
            Parent = K.hudParent(),
        })
        local root = create("Frame", {
            Name = "DivisionHud",
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromOffset(0, 0),
            Visible = false,
            Parent = gui,
        })
        local scale = create("UIScale", { Parent = root })

        --  3D mode: the same root frame lives on a SurfaceGui (always on top, no lighting) that is adorned to an
        --  invisible part kept in front of the camera, along the ray through the muzzle. The part always faces the
        --  camera, then gets a fixed tilt; its direction is smoothed in world space, so turning the camera makes
        --  the panel lag a little and swing back (parallax) while moving the player does not drag it.
        local CANVAS = Vector2.new(640, 480)
        local DEPTH = 4
        local panel = create("Part", {
            Name = HttpService:GenerateGUID(false),
            Anchored = true,
            CanCollide = false,
            CanQuery = false,
            CanTouch = false,
            CastShadow = false,
            Transparency = 1,
            Size = Vector3.new(1, 1, 0.05),
        })
        local surface = create("SurfaceGui", {
            Name = HttpService:GenerateGUID(false),
            Adornee = panel,
            Face = Enum.NormalId.Front,
            SizingMode = Enum.SurfaceGuiSizingMode.FixedSize,
            CanvasSize = CANVAS,
            AlwaysOnTop = true,
            LightInfluence = 0,
            ResetOnSpawn = false,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
            Enabled = false,
            Parent = K.hudParent(),
        })
        local in3D = false
        local function setMode(want3D)
            in3D = want3D
            root.Parent = want3D and surface or gui
            surface.Enabled = want3D
            if want3D then
                root.Position = UDim2.fromScale(0.5, 0.5)
            else
                panel.Parent = nil
            end
        end
        local smoothDir

        local function group(name)
            return create("Frame", { Name = name, BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.fromOffset(0, 0), Parent = root })
        end

        --  ammo block, above-left / right of the crosshair
        local ammoGroup = group("Ammo")
        local ammoLabel = label(ammoGroup, "", -48, -2, 28, WHITE, "R")
        ammoLabel.Size = UDim2.fromOffset(80, 32)
        local reserveLabel = label(ammoGroup, "", 38, 6, 13, WHITE, "L")

        --  health: medkit icon, number, thin line under both cells
        local healthGroup = group("Health")
        local kit = box(healthGroup, -58, 28, 12, 12, WHITE, 2)
        box(kit, 6, 6, 8, 2, DARK)
        box(kit, 6, 6, 2, 8, DARK)
        kit.AnchorPoint = Vector2.new(0.5, 0.5)
        for _, c in kit:GetChildren() do
            if c:IsA("Frame") then c.Position = UDim2.fromScale(0.5, 0.5) end
        end
        local healthLabel = label(healthGroup, "", -43, 28, 15, WHITE, "L")
        local track = box(healthGroup, -9, 48, 68, 2, WHITE)
        track.BackgroundTransparency = 0.7
        local fill = create("Frame", {
            BackgroundColor3 = WHITE,
            BorderSizePixel = 0,
            Size = UDim2.fromScale(1, 1),
            ZIndex = 3,
            Parent = track,
        })

        --  shield: shield icon + number (only when the game has a value)
        local shieldGroup = group("Shield")
        local shield = box(shieldGroup, 45, 28, 11, 13, WHITE, 3)
        local shieldDot = box(shield, 5, 5, 3, 3, DARK, 2)
        shieldDot.Position = UDim2.fromScale(0.5, 0.45)
        local shieldLabel = label(shieldGroup, "", 60, 28, 15, WHITE, "L")

        --  WASD keys: W above, A S D below
        local keysGroup = group("Keys")
        local keyLabels = {
            W = label(keysGroup, "W", -27, 62, 11, WHITE, "C"),
            A = label(keysGroup, "A", -47, 78, 11, WHITE, "C"),
            S = label(keysGroup, "S", -27, 78, 11, WHITE, "C"),
            D = label(keysGroup, "D", -8, 78, 11, WHITE, "C"),
        }
        for _, l in keyLabels do l.Size = UDim2.fromOffset(16, 14) end
        local keyCodes = { W = Enum.KeyCode.W, A = Enum.KeyCode.A, S = Enum.KeyCode.S, D = Enum.KeyCode.D }

        --  speed
        local speedGroup = group("Speed")
        local speedLabel = label(speedGroup, "", 37, 70, 12, DEFAULT_ACCENT, "L")
        speedLabel.Size = UDim2.fromOffset(80, 16)

        --  write a property only when it changed (each write is a call into the engine)
        local written = setmetatable({}, { __mode = "k" })
        local function put(instance, property, value)
            local row = written[instance]
            if row == nil then
                row = {}
                written[instance] = row
            end
            if row[property] ~= value then
                row[property] = value
                instance[property] = value
            end
        end

        --  numeric Shield / Armor value from the character, humanoid or player (nil when the game has none)
        local SHIELD_NAMES = { "Shield", "Armor", "Armour", "Overshield" }
        local function readShield(character, humanoid)
            for _, holder in { character, humanoid, LocalPlayer } do
                for _, name in SHIELD_NAMES do
                    local v = holder:GetAttribute(name)
                    if type(v) == "number" then return v end
                end
            end
            return nil
        end

        local ammoNow, reserveNow, muzzleNow, aimingNow
        local function readAmmo()
            ammoNow, reserveNow, muzzleNow, aimingNow = nil, nil, nil, false
            local fc = K.Controller("FighterController")
            local lf = fc and fc.LocalFighter
            local item = lf and lf.EquippedItem
            if item and item.Get then
                ammoNow = item:Get("Ammo")
                reserveNow = item:Get("AmmoReserve")
                --  aiming down the sight / scope (the item's own IsAiming state, as read by the game's IsFullyAiming)
                aimingNow = item:Get("IsAiming") == true
            end
        end
        --  world position of the muzzle of the held weapon (nil for melee / no weapon); a separate pcall so a
        --  failure here never hides the ammo
        --  Same source as LY.lua: the "_muzzle" attachment inside the first-person viewmodel of the local player
        --  (workspace.ViewModels.FirstPerson.<UserName> ...). The game's own GetMuzzlePosition() does not return
        --  the barrel tip, it stays near the middle of the screen. The attachment is cached and searched again
        --  (4 times a second at most) when the weapon changes.
        local function readMuzzle()
            muzzleNow = K.MuzzleWorldPosition()
        end

        --  smoothed screen position of the HUD origin (px); starts at the first target
        local posX, posY

        local updateFrame = LPH_NO_VIRTUALIZE(function(dt)
            local s = config.Data and config.Data.DivisionHud
            if type(s) ~= "table" or not s.Enabled then
                put(root, "Visible", false)
                return
            end
            local character = LocalPlayer.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            if humanoid == nil or humanoid.Health <= 0 then
                put(root, "Visible", false)
                return
            end

            --  hidden in the lobby (no match environment, same test as the ragebot) and while aiming down the sight
            if LocalPlayer:GetAttribute("EnvironmentID") == nil then
                put(root, "Visible", false)
                return
            end
            local okAmmo = pcall(readAmmo)
            if okAmmo and aimingNow then
                put(root, "Visible", false)
                return
            end

            put(root, "Visible", true)
            put(scale, "Scale", (s.Scale or 100) / 100)

            --  origin: the muzzle on screen (smoothed like the FOV circle follower). With no muzzle (fists / melee,
            --  or the muzzle is behind the camera) or Follow Muzzle off, the origin is the crosshair (screen
            --  centre), the layout of the reference HUD: ammo left of it, health / keys / speed below it.
            --  The X / Y offset is added here and the result is kept inside the window (the whole cluster stays
            --  visible): a muzzle that leaves the screen pushes the HUD against the edge instead of throwing it
            --  back to the centre.
            local camera = workspace.CurrentCamera
            local size = camera.ViewportSize
            local targetX, targetY = size.X * 0.5, size.Y * 0.5
            if s.FollowMuzzle ~= false and pcall(readMuzzle) and typeof(muzzleNow) == "Vector3" then
                local vp = camera:WorldToViewportPoint(muzzleNow)
                if vp.Z > 0 then
                    targetX, targetY = vp.X, vp.Y
                end
            end
            local hudScale = (s.Scale or 100) / 100
            targetX = math.clamp(targetX + (s.PosX or 0), math.min(130 * hudScale, size.X * 0.5), math.max(size.X - 130 * hudScale, size.X * 0.5))
            targetY = math.clamp(targetY + (s.PosY or 0), math.min(24 * hudScale, size.Y * 0.5), math.max(size.Y - 90 * hudScale, size.Y * 0.5))
            local smoothing = math.clamp(s.Smoothing or 0, 0, 100)
            local alpha = smoothing <= 0 and 1 or (1 - math.exp(-(dt or 0.016) * (60 - smoothing * 0.55)))
            local want3D = s.Mode3D ~= false
            if want3D ~= in3D then setMode(want3D) end
            if want3D then
                --  direction through the muzzle (plus the X / Y offset in pixels), smoothed in world space
                local ray = camera:ViewportPointToRay(targetX, targetY)
                local cf = camera.CFrame
                if smoothDir == nil then
                    smoothDir = ray.Direction
                else
                    local blended = smoothDir:Lerp(ray.Direction, alpha)
                    if blended.Magnitude > 0.001 then smoothDir = blended.Unit end
                end
                --  the lag behind a fast camera turn is limited, so a flick never throws the panel out of the window
                local lagMax = 110 * hudScale
                local sp = camera:WorldToViewportPoint(cf.Position + smoothDir)
                if sp.Z <= 0 then
                    smoothDir = ray.Direction
                else
                    local dx, dy = sp.X - targetX, sp.Y - targetY
                    local dist = math.sqrt(dx * dx + dy * dy)
                    if dist > lagMax then
                        local k = lagMax / dist
                        smoothDir = camera:ViewportPointToRay(targetX + dx * k, targetY + dy * k).Direction
                    end
                end
                local planar = math.max(smoothDir:Dot(cf.LookVector), 0.2)
                local worldPos = cf.Position + smoothDir * (DEPTH / planar)
                --  1 canvas pixel = 1 screen pixel at DEPTH, so the 3D panel has the size of the flat one
                local pixelsPerStud = size.Y / (2 * DEPTH * math.tan(math.rad(camera.FieldOfView) * 0.5))
                put(panel, "Size", Vector3.new(CANVAS.X / pixelsPerStud, CANVAS.Y / pixelsPerStud, 0.05))
                panel.CFrame = CFrame.lookAt(worldPos, cf.Position)
                    * CFrame.Angles(math.rad(s.TiltPitch or 0), math.rad(s.TiltYaw or 0), 0)
                if panel.Parent ~= camera then panel.Parent = camera end
            else
                if posX == nil or smoothing <= 0 then
                    posX, posY = targetX, targetY
                else
                    posX = posX + (targetX - posX) * alpha
                    posY = posY + (targetY - posY) * alpha
                end
                root.Position = UDim2.fromOffset(math.floor(posX + 0.5), math.floor(posY + 0.5))
            end
            local accent = typeof(s.Color) == "Color3" and s.Color or DEFAULT_ACCENT

            --  ammo
            local showAmmo =s.ShowAmmo ~= false and okAmmo and type(ammoNow) == "number"
            put(ammoGroup, "Visible", showAmmo and true or false)
            if showAmmo then
                put(ammoLabel, "Text", tostring(math.floor(ammoNow)))
                put(ammoLabel, "TextColor3", ammoNow <= 0 and accent or WHITE)
                local hasReserve = type(reserveNow) == "number" and reserveNow < 1e6
                put(reserveLabel, "Text", hasReserve and ("/ " .. math.floor(reserveNow)) or "")
            end

            --  health
            local showHealth = s.ShowHealth ~= false
            put(healthGroup, "Visible", showHealth and true or false)
            if showHealth then
                local maxHealth = math.max(humanoid.MaxHealth, 1)
                local ratio = math.clamp(humanoid.Health / maxHealth, 0, 1)
                put(healthLabel, "Text", tostring(math.ceil(humanoid.Health)))
                local low = ratio < 0.3
                put(healthLabel, "TextColor3", low and accent or WHITE)
                put(fill, "BackgroundColor3", low and accent or WHITE)
                put(fill, "Size", UDim2.fromScale(ratio, 1))
            end

            --  shield
            local shieldValue = s.ShowShield ~= false and readShield(character, humanoid) or nil
            put(shieldGroup, "Visible", shieldValue ~= nil and true or false)
            if shieldValue ~= nil then
                put(shieldLabel, "Text", tostring(math.ceil(shieldValue)))
            end

            --  keys: accent colour while held, white while idle
            local showKeys = s.ShowKeys ~= false
            put(keysGroup, "Visible", showKeys and true or false)
            if showKeys then
                for key, l in keyLabels do
                    put(l, "TextColor3", UserInputService:IsKeyDown(keyCodes[key]) and accent or WHITE)
                end
            end

            --  speed (horizontal, studs per second)
            local showSpeed = s.ShowSpeed ~= false
            put(speedGroup, "Visible", showSpeed and true or false)
            if showSpeed then
                local hrp = character:FindFirstChild("HumanoidRootPart")
                local speed = 0
                if hrp then
                    local v = hrp.AssemblyLinearVelocity
                    speed = math.sqrt(v.X * v.X + v.Z * v.Z)
                end
                put(speedLabel, "Text", string.format("%d u/s", math.floor(speed + 0.5)))
                put(speedLabel, "TextColor3", accent)
            end
        end)

        local conn = K.track(RunService.RenderStepped:Connect(LPH_NO_VIRTUALIZE(function(dt)
            local ok, err = pcall(updateFrame, dt)
            if not ok and not K.__dhWarned then
                K.__dhWarned = true
                KQ("[Kicia DivisionHud] " .. tostring(err))
            end
        end)))
        K.onUnload(function()
            started = false
            pcall(function() conn:Disconnect() end)
            gui:Destroy()
            surface:Destroy()
            panel:Destroy()
        end)
    end
end
task.defer(function()
    local ok, err = pcall(K.StartDivisionHud)
    if not ok then KQ("[Kicia DivisionHud] could not start: " .. tostring(err)) end
end)

K.Mark("team hud")
--==========================================================================
--  Team HUD (TMH): the match panel. Title bar (name | main hud | fps | ping), the HP of your team against the
--  HP of the enemy team and by how much you are winning or losing, then one row per enemy in your match
--  (headshot, name, HP, held weapon, RAGE / LEGIT status) and the ragebot's current target at the bottom.
--  Teams: the TeamID player attribute, the match: the EnvironmentID attribute (the same tests as the ragebot).
--  Weapon: FighterController:GetFighter(player).EquippedItem. Target: K.HudAimTarget, set by the Target HUD's
--  Update (the ragebot calls it every frame with its target).
--  Status: KH's own Hacker Detector (the "Hacker" player tag, K.IsTaggedHacker): RAGE once the detector has
--  tagged the enemy, LEGIT otherwise. The detector runs while Hacker Detector, Prioritize Hackers, Evade When
--  Target Hacking or Knife Mode Auto is on; "Clear Hacker Tags" resets it.
--  Settings: config.Data.TeamHud, menu: Visuals > Player ESP > Team HUD.
--==========================================================================
do -- TMH
    local started = false
    K.StartTeamHud = function()
        if started then return end
        started = true

        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local UserInputService = game:GetService("UserInputService")
        local HttpService = game:GetService("HttpService")
        local Stats = game:GetService("Stats")
        local LocalPlayer = Players.LocalPlayer
        local config = tbl17.bG()

        local WIDTH = 300
        local HEADER_H, INFO_H, ROW_H, FOOTER_H = 22, 44, 52, 24
        local MAX_ROWS = 8
        local WHITE = Color3.fromRGB(235, 235, 240)
        local GREY = Color3.fromRGB(150, 150, 160)
        local BG = Color3.fromRGB(16, 16, 20)
        local LINE = Color3.fromRGB(48, 48, 56)
        local GREEN = Color3.fromRGB(80, 210, 110)
        local RED = Color3.fromRGB(235, 70, 70)
        local YELLOW = Color3.fromRGB(240, 200, 60)
        local FONT = Enum.Font.GothamMedium
        local FONT_BOLD = Enum.Font.GothamBold

        local function hex(c)
            return string.format("#%02x%02x%02x", math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
        end
        local function paint(text, c)
            return '<font color="' .. hex(c) .. '">' .. text .. "</font>"
        end

        local function create(className, props)
            local instance = Instance.new(className)
            for k, v in props do
                if k ~= "Parent" then instance[k] = v end
            end
            instance.Parent = props.Parent
            return instance
        end
        local function text(parent, x, y, w, h, size, font, color, align)
            return create("TextLabel", {
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                Position = UDim2.fromOffset(x, y),
                Size = UDim2.fromOffset(w, h),
                Font = font or FONT,
                Text = "",
                RichText = true,
                TextSize = size,
                TextColor3 = color or WHITE,
                TextStrokeTransparency = 0.6,
                TextXAlignment = align == "R" and Enum.TextXAlignment.Right or Enum.TextXAlignment.Left,
                TextYAlignment = Enum.TextYAlignment.Center,
                TextTruncate = Enum.TextTruncate.AtEnd,
                ZIndex = 3,
                Parent = parent,
            })
        end

        local gui = create("ScreenGui", {
            Name = HttpService:GenerateGUID(false),
            ResetOnSpawn = false,
            IgnoreGuiInset = true,
            DisplayOrder = 85,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
            Parent = K.hudParent(),
        })
        local root = create("Frame", {
            Name = "TeamHud",
            BackgroundColor3 = BG,
            BackgroundTransparency = 0.12,
            BorderSizePixel = 0,
            Active = true,
            Position = UDim2.fromScale(0.01, 0.3),
            Size = UDim2.fromOffset(WIDTH, 100),
            Visible = false,
            ClipsDescendants = true,
            Parent = gui,
        })
        create("UICorner", { CornerRadius = UDim.new(0, 4), Parent = root })
        local rootStroke = create("UIStroke", { Color = LINE, Thickness = 1, Parent = root })
        local scale = create("UIScale", { Parent = root })

        --  title bar + accent line under it
        local title = text(root, 8, 0, WIDTH - 16, HEADER_H, 13, FONT_BOLD, WHITE)
        local titleLine = create("Frame", { BackgroundColor3 = GREEN, BorderSizePixel = 0, Position = UDim2.fromOffset(0, HEADER_H), Size = UDim2.new(1, 0, 0, 1), ZIndex = 3, Parent = root })

        --  team / enemy HP and the lead
        local hpLine = text(root, 8, HEADER_H + 4, WIDTH - 16, 18, 13, FONT_BOLD, WHITE)
        local leadLine = text(root, 8, HEADER_H + 22, WIDTH - 16, 18, 13, FONT_BOLD, WHITE)

        --  enemy rows (a pool, shown as needed)
        local rows = {}
        for i = 1, MAX_ROWS do
            local y = HEADER_H + INFO_H + (i - 1) * ROW_H
            local frame = create("Frame", { BackgroundTransparency = 1, BorderSizePixel = 0, Position = UDim2.fromOffset(0, y), Size = UDim2.fromOffset(WIDTH, ROW_H), Visible = false, ZIndex = 2, Parent = root })
            local bar = create("Frame", { BackgroundColor3 = GREEN, BorderSizePixel = 0, Position = UDim2.fromOffset(8, 4), Size = UDim2.fromOffset(3, ROW_H - 8), ZIndex = 3, Parent = frame })
            create("UICorner", { CornerRadius = UDim.new(0, 2), Parent = bar })
            local avatar = create("ImageLabel", { BackgroundColor3 = Color3.fromRGB(32, 32, 40), BorderSizePixel = 0, Position = UDim2.fromOffset(16, 4), Size = UDim2.fromOffset(ROW_H - 8, ROW_H - 8), Image = "", ZIndex = 3, Parent = frame })
            create("UICorner", { CornerRadius = UDim.new(0, 3), Parent = avatar })
            local nx = 16 + ROW_H - 8 + 8
            rows[i] = {
                frame = frame,
                bar = bar,
                avatar = avatar,
                name = text(frame, nx, 4, 150, 16, 13, FONT_BOLD, WHITE),
                hp = text(frame, nx, 20, 150, 13, 11, FONT, GREY),
                weapon = text(frame, nx, 33, 150, 13, 11, FONT, GREY),
                status = text(frame, WIDTH - 108, 4, 100, 16, 12, FONT_BOLD, GREY, "R"),
            }
        end
        local footer = text(root, 8, 0, WIDTH - 16, FOOTER_H, 13, FONT_BOLD, WHITE)

        --  write a property only when it changed (each write is a call into the engine)
        local written = setmetatable({}, { __mode = "k" })
        local function put(instance, property, value)
            local row = written[instance]
            if row == nil then
                row = {}
                written[instance] = row
            end
            if row[property] ~= value then
                row[property] = value
                instance[property] = value
            end
        end

        --  drag (while the menu is open); the drop writes the position to the config
        local drag = K.MakeHudDraggable(root, function(px, py)
            config:Set({ "TeamHud", "PosX" }, px)
            config:Set({ "TeamHud", "PosY" }, py)
        end)

        --  match / team tests (same as the ragebot)
        local function inMyMatch(player)
            local mine = LocalPlayer:GetAttribute("EnvironmentID")
            return mine ~= nil and player:GetAttribute("EnvironmentID") == mine
        end
        local function isTeammate(player)
            if player == LocalPlayer then return true end
            local myId, theirId = LocalPlayer:GetAttribute("TeamID"), player:GetAttribute("TeamID")
            if myId ~= nil and theirId ~= nil then return myId == theirId end
            local a, b = LocalPlayer.Team, player.Team
            return a ~= nil and b ~= nil and a == b
        end
        local function humanoidOf(player)
            local character = player.Character
            return character and character:FindFirstChildOfClass("Humanoid")
        end
        local function weaponOf(player)
            local name
            pcall(function()
                local fighter = K.Controller("FighterController"):GetFighter(player)
                local item = fighter and fighter.EquippedItem
                if item == nil then return end
                local info
                pcall(function() info = item.Info end)
                name = (info and info.Name) or (item.Get and item:Get("Name")) or item.Name
            end)
            return type(name) == "string" and name or "-"
        end


        --  fps (smoothed) and ping
        local fps = 60
        local function pingMs()
            local ms
            pcall(function() ms = Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
            if type(ms) ~= "number" then
                pcall(function() ms = LocalPlayer:GetNetworkPing() * 1000 end)
            end
            return math.floor((ms or 0) + 0.5)
        end
        local lastPing, pingAt = 0, 0

        local function hpColor(ratio)
            if ratio > 0.6 then return GREEN elseif ratio > 0.3 then return YELLOW end
            return RED
        end

        local updateFrame = LPH_NO_VIRTUALIZE(function(dt)
            if dt and dt > 0 then fps = fps + (1 / dt - fps) * 0.05 end
            local s = config.Data and config.Data.TeamHud
            if type(s) ~= "table" or not s.Enabled or LocalPlayer:GetAttribute("EnvironmentID") == nil then
                put(root, "Visible", false)
                return
            end
            local now = os.clock()
            local accent = typeof(s.Color) == "Color3" and s.Color or GREEN
            put(scale, "Scale", (s.Scale or 100) / 100)
            if not drag.dragging then
                put(root, "Position", UDim2.fromScale((s.PosX or 1) / 100, (s.PosY or 30) / 100))
            end
            put(titleLine, "BackgroundColor3", accent)
            put(rootStroke, "Color", LINE)

            if now - pingAt > 0.5 then
                pingAt = now
                lastPing = pingMs()
            end
            put(title, "Text", string.format("Kicia | main hud | %d fps | %d ms", math.floor(fps + 0.5), lastPing))

            --  players of this match, split by team
            local teamHp, enemyHp = 0, 0
            local enemies = {}
            for _, player in Players:GetPlayers() do
                if player == LocalPlayer or inMyMatch(player) then
                    local humanoid = humanoidOf(player)
                    local hp = humanoid and math.max(humanoid.Health, 0) or 0
                    if isTeammate(player) then
                        teamHp = teamHp + hp
                    else
                        enemyHp = enemyHp + hp
                        table.insert(enemies, { player = player, humanoid = humanoid, hp = hp })
                    end
                end
            end
            table.sort(enemies, function(a, b)
                if (a.hp > 0) ~= (b.hp > 0) then return a.hp > 0 end
                return a.player.Name:lower() < b.player.Name:lower()
            end)

            teamHp, enemyHp = math.ceil(teamHp), math.ceil(enemyHp)
            put(hpLine, "Text", K.T("Team HP : ") .. paint(tostring(teamHp), accent) .. K.T("  |  Enemy team Hp : ") .. paint(tostring(enemyHp), RED))
            local diff = teamHp - enemyHp
            if diff > 0 then
                put(leadLine, "Text", K.T("You are winning by ") .. paint(tostring(diff), accent))
            elseif diff < 0 then
                put(leadLine, "Text", K.T("You are losing by ") .. paint(tostring(-diff), RED))
            else
                put(leadLine, "Text", K.T("You are ") .. paint(K.T("tied"), YELLOW))
            end

            --  enemy rows
            local shown = math.min(#enemies, MAX_ROWS)
            for i = 1, MAX_ROWS do
                local row = rows[i]
                local e = enemies[i]
                if e == nil then
                    put(row.frame, "Visible", false)
                else
                    put(row.frame, "Visible", true)
                    local player, humanoid = e.player, e.humanoid
                    local maxHp = humanoid and math.max(humanoid.MaxHealth, 1) or 100
                    local ratio = math.clamp(e.hp / maxHp, 0, 1)
                    local alive = e.hp > 0
                    put(row.avatar, "Image", "rbxthumb://type=AvatarHeadShot&id=" .. player.UserId .. "&w=48&h=48")
                    put(row.avatar, "ImageTransparency", alive and 0 or 0.6)
                    put(row.bar, "BackgroundColor3", alive and hpColor(ratio) or LINE)
                    put(row.bar, "Size", UDim2.fromOffset(3, math.max(math.floor((ROW_H - 8) * (alive and ratio or 1) + 0.5), 2)))
                    put(row.bar, "Position", UDim2.fromOffset(8, 4 + (ROW_H - 8) - math.max(math.floor((ROW_H - 8) * (alive and ratio or 1) + 0.5), 2)))
                    put(row.name, "Text", player.Name)
                    put(row.name, "TextColor3", alive and WHITE or GREY)
                    put(row.hp, "Text", alive and string.format("%d / %d", math.ceil(e.hp), math.ceil(maxHp)) or K.T("dead"))
                    put(row.weapon, "Text", K.T("weapon: ") .. (alive and weaponOf(player) or "-"))
                    if s.ShowStatus ~= false then
                        local rage = K.IsTaggedHacker(player)
                        put(row.status, "Text", K.T("status: ") .. (rage and paint(K.T("RAGE"), RED) or paint(K.T("LEGIT"), GREEN)))
                    else
                        put(row.status, "Text", "")
                    end
                end
            end

            --  target + height
            local footerY = HEADER_H + INFO_H + shown * ROW_H + 2
            local showTarget = s.ShowTarget ~= false
            put(footer, "Visible", showTarget)
            if showTarget then
                local target = K.HudAimTarget
                local fresh = target ~= nil and K.HudAimTargetAt ~= nil and now - K.HudAimTargetAt < 0.4
                put(footer, "Position", UDim2.fromOffset(8, footerY))
                put(footer, "Text", K.T("Target : ") .. (fresh and paint(target.Name, accent) or paint(K.T("none"), GREY)))
            end
            put(root, "Size", UDim2.fromOffset(WIDTH, footerY + (showTarget and FOOTER_H or 4)))
            put(root, "Visible", true)
        end)

        local conn = K.track(RunService.RenderStepped:Connect(LPH_NO_VIRTUALIZE(function(dt)
            local ok, err = pcall(updateFrame, dt)
            if not ok and not K.__tmhWarned then
                K.__tmhWarned = true
                KQ("[Kicia TeamHud] " .. tostring(err))
            end
        end)))
        K.onUnload(function()
            started = false
            pcall(function() conn:Disconnect() end)
            gui:Destroy()
        end)
    end
end
task.defer(function()
    local ok, err = pcall(K.StartTeamHud)
    if not ok then KQ("[Kicia TeamHud] could not start: " .. tostring(err)) end
end)

K.Mark("score hud")
--==========================================================================
--  Score HUD (SCH): the match score. Title bar (name | score hud | queue name), our team's score against the
--  enemy's in the middle with each side's player names, then the round number, the round state and the lead.
--  Source (read in game): DuelController.CurrentObject.Data -> Scores (a table keyed by TeamID, "\1" / "\2" ...),
--  RoundNum, Status (RoundStarting -> RoundStarted -> RoundFinished), QueueName, NumTeams. Time left in the round:
--  DuelController.CurrentObject.DuelInterface.Timer:GetTimeRemaining() (the game's own top-bar clock, in seconds,
--  shown rounded up like the game does; its Infinite icon is visible when the round has no time limit). Our team is the
--  TeamID player attribute; players of the match share the EnvironmentID attribute. The duel data carries no
--  "rounds to win" value, so none is shown. With more than two teams the enemy side is the best enemy score.
--  Settings: config.Data.ScoreHud, menu: Visuals > Player ESP > Score HUD.
--==========================================================================
do -- SCH
    local started = false
    K.StartScoreHud = function()
        if started then return end
        started = true

        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local UserInputService = game:GetService("UserInputService")
        local HttpService = game:GetService("HttpService")
        local ReplicatedStorage = game:GetService("ReplicatedStorage")
        local LocalPlayer = Players.LocalPlayer
        local config = tbl17.bG()

        local WIDTH, HEIGHT = 280, 114
        local HEADER_H = 22
        local WHITE = Color3.fromRGB(235, 235, 240)
        local GREY = Color3.fromRGB(150, 150, 160)
        local BG = Color3.fromRGB(16, 16, 20)
        local LINE = Color3.fromRGB(48, 48, 56)
        local GREEN = Color3.fromRGB(80, 210, 110)
        local RED = Color3.fromRGB(235, 70, 70)
        local YELLOW = Color3.fromRGB(240, 200, 60)
        local FONT = Enum.Font.GothamMedium
        local FONT_BOLD = Enum.Font.GothamBold
        local STATUS_TEXT = { RoundStarting = "Starting", RoundStarted = "In round", RoundFinished = "Round over" }

        local function hex(c)
            return string.format("#%02x%02x%02x", math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
        end
        local function paint(text, c)
            return '<font color="' .. hex(c) .. '">' .. text .. "</font>"
        end
        local function create(className, props)
            local instance = Instance.new(className)
            for k, v in props do
                if k ~= "Parent" then instance[k] = v end
            end
            instance.Parent = props.Parent
            return instance
        end
        local function text(parent, x, y, w, h, size, font, color, align)
            return create("TextLabel", {
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                Position = UDim2.fromOffset(x, y),
                Size = UDim2.fromOffset(w, h),
                Font = font or FONT,
                Text = "",
                RichText = true,
                TextSize = size,
                TextColor3 = color or WHITE,
                TextStrokeTransparency = 0.6,
                TextXAlignment = align == "R" and Enum.TextXAlignment.Right or (align == "C" and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left),
                TextYAlignment = Enum.TextYAlignment.Center,
                TextTruncate = Enum.TextTruncate.AtEnd,
                ZIndex = 3,
                Parent = parent,
            })
        end

        local gui = create("ScreenGui", {
            Name = HttpService:GenerateGUID(false),
            ResetOnSpawn = false,
            IgnoreGuiInset = true,
            DisplayOrder = 85,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
            Parent = K.hudParent(),
        })
        local root = create("Frame", {
            Name = "ScoreHud",
            BackgroundColor3 = BG,
            BackgroundTransparency = 0.12,
            BorderSizePixel = 0,
            Active = true,
            AnchorPoint = Vector2.new(0.5, 0),
            Position = UDim2.fromScale(0.5, 0.12),
            Size = UDim2.fromOffset(WIDTH, HEIGHT),
            Visible = false,
            ClipsDescendants = true,
            Parent = gui,
        })
        create("UICorner", { CornerRadius = UDim.new(0, 4), Parent = root })
        create("UIStroke", { Color = LINE, Thickness = 1, Parent = root })
        local scale = create("UIScale", { Parent = root })

        local title = text(root, 8, 0, WIDTH - 16, HEADER_H, 13, FONT_BOLD, WHITE)
        local titleLine = create("Frame", { BackgroundColor3 = GREEN, BorderSizePixel = 0, Position = UDim2.fromOffset(0, HEADER_H), Size = UDim2.new(1, 0, 0, 1), ZIndex = 3, Parent = root })

        --  middle: our names | score | their names
        local SIDE_W = 92
        local ourNames = text(root, 8, HEADER_H + 6, SIDE_W, 40, 12, FONT_BOLD, WHITE)
        local score = text(root, 8 + SIDE_W, HEADER_H + 4, WIDTH - 16 - SIDE_W * 2, 44, 30, FONT_BOLD, WHITE, "C")
        local theirNames = text(root, WIDTH - 8 - SIDE_W, HEADER_H + 6, SIDE_W, 40, 12, FONT_BOLD, WHITE, "R")
        --  time left in the round, under the score
        local timer = text(root, 8, HEADER_H + 48, WIDTH - 16, 18, 15, FONT_BOLD, WHITE, "C")

        --  bottom: round + state | lead
        local roundLine = text(root, 8, HEIGHT - 24, (WIDTH - 16) / 2, 20, 12, FONT, GREY)
        local leadLine = text(root, WIDTH / 2, HEIGHT - 24, (WIDTH - 16) / 2, 20, 12, FONT_BOLD, WHITE, "R")

        local written = setmetatable({}, { __mode = "k" })
        local function put(instance, property, value)
            local row = written[instance]
            if row == nil then
                row = {}
                written[instance] = row
            end
            if row[property] ~= value then
                row[property] = value
                instance[property] = value
            end
        end

        --  drag (while the menu is open); the drop writes the position (X is the centre) to the config
        local drag = K.MakeHudDraggable(root, function(px, py)
            config:Set({ "ScoreHud", "PosX" }, px)
            config:Set({ "ScoreHud", "PosY" }, py)
        end)

        --  queue display name ("Ranked 1v1"), looked up once per queue
        local queueNames = {}
        local function queueDisplayName(queueName)
            if type(queueName) ~= "string" then return nil end
            local cached = queueNames[queueName]
            if cached == nil then
                cached = queueName
                pcall(function()
                    local library = require(ReplicatedStorage.Modules.DuelLibrary)
                    local entry = (library.MatchmakingQueues and library.MatchmakingQueues[queueName])
                        or (library.PlaySources and library.PlaySources[queueName])
                    if type(entry) == "table" and type(entry.DisplayName) == "string" and entry.DisplayName ~= "" then
                        cached = entry.DisplayName
                    end
                end)
                queueNames[queueName] = cached
            end
            return cached
        end

        local currentDuel
        local function duelData()
            local data
            currentDuel = nil
            pcall(function()
                local current = K.Controller("DuelController").CurrentObject
                if type(current) == "table" then
                    currentDuel = current
                    data = current.Data
                end
            end)
            return type(data) == "table" and data or nil
        end

        --  seconds left on the game's round clock; "inf" when the round has no time limit, nil when unknown
        local function timeLeft()
            local left
            pcall(function()
                local clock = currentDuel.DuelInterface.Timer
                if clock.InfiniteIcon ~= nil and clock.InfiniteIcon.Visible then
                    left = "inf"
                    return
                end
                local v = clock:GetTimeRemaining()
                if type(v) == "number" and v == v then left = math.max(v, 0) end
            end)
            return left
        end
        local function clockText(seconds)
            local whole = math.ceil(seconds)
            return string.format("%d:%02d", math.floor(whole / 60), whole % 60)
        end

        --  names of the players of each side in our match ("A, B" or "A +2")
        local function joinNames(list)
            if #list == 0 then return "-" end
            if #list <= 2 then return table.concat(list, "\n") end
            return list[1] .. "\n+" .. (#list - 1)
        end

        local updateFrame = LPH_NO_VIRTUALIZE(function()
            local s = config.Data and config.Data.ScoreHud
            local data = duelData()
            local myTeam = LocalPlayer:GetAttribute("TeamID")
            local env = LocalPlayer:GetAttribute("EnvironmentID")
            if type(s) ~= "table" or not s.Enabled or data == nil or type(data.Scores) ~= "table" or myTeam == nil or env == nil then
                put(root, "Visible", false)
                return
            end
            local accent = typeof(s.Color) == "Color3" and s.Color or GREEN
            put(scale, "Scale", (s.Scale or 100) / 100)
            if not drag.dragging then
                put(root, "Position", UDim2.fromScale((s.PosX or 50) / 100, (s.PosY or 12) / 100))
            end
            put(titleLine, "BackgroundColor3", accent)

            local queue = queueDisplayName(data.QueueName)
            put(title, "Text", "Kicia | score hud" .. (queue and (" | " .. queue) or ""))

            --  scores: ours, and the best enemy team's
            local ours, theirs = 0, nil
            for teamId, value in data.Scores do
                local n = tonumber(value) or 0
                if teamId == myTeam then
                    ours = n
                elseif theirs == nil or n > theirs then
                    theirs = n
                end
            end
            theirs = theirs or 0
            local ourColor = ours > theirs and accent or (ours < theirs and RED or WHITE)
            local theirColor = theirs > ours and RED or WHITE
            put(score, "Text", paint(tostring(ours), ourColor) .. paint("  -  ", GREY) .. paint(tostring(theirs), theirColor))

            --  names per side
            local ourList, theirList = {}, {}
            for _, player in Players:GetPlayers() do
                if player:GetAttribute("EnvironmentID") == env then
                    local team = player:GetAttribute("TeamID")
                    if team == myTeam then
                        table.insert(ourList, player == LocalPlayer and paint(player.Name, accent) or player.Name)
                    elseif team ~= nil then
                        table.insert(theirList, player.Name)
                    end
                end
            end
            put(ourNames, "Text", joinNames(ourList))
            put(theirNames, "Text", paint(joinNames(theirList), RED))

            --  round, state, lead
            local roundNum = tonumber(data.RoundNum)
            local status = data.Status
            local stateText = K.T(STATUS_TEXT[status] or (status ~= nil and tostring(status) or "-"))
            put(roundLine, "Text", (roundNum and K.TF("Round %s", roundNum) or K.T("Round -")) .. "  |  " .. stateText)

            --  time left: the round clock while the round is on, the countdown while it is starting
            local left = timeLeft()
            if left == "inf" and status == "RoundStarted" then
                put(timer, "Text", paint(K.T("no time limit"), GREY))
            elseif type(left) == "number" and status == "RoundStarted" then
                put(timer, "Text", paint(clockText(left), left <= 10 and RED or (left <= 30 and YELLOW or WHITE)) .. paint(K.T("  left"), GREY))
            elseif type(left) == "number" and status == "RoundStarting" and left > 0 then
                put(timer, "Text", paint(K.T("starts in "), GREY) .. paint(tostring(math.ceil(left)), accent))
            else
                put(timer, "Text", paint("-", GREY))
            end
            local diff = ours - theirs
            if diff > 0 then
                put(leadLine, "Text", K.T("ahead by ") .. paint(tostring(diff), accent))
            elseif diff < 0 then
                put(leadLine, "Text", K.T("behind by ") .. paint(tostring(-diff), RED))
            else
                put(leadLine, "Text", paint(K.T("tied"), YELLOW))
            end
            put(root, "Visible", true)
        end)

        local conn = K.track(RunService.RenderStepped:Connect(LPH_NO_VIRTUALIZE(function()
            local ok, err = pcall(updateFrame)
            if not ok and not K.__schWarned then
                K.__schWarned = true
                KQ("[Kicia ScoreHud] " .. tostring(err))
            end
        end)))
        K.onUnload(function()
            started = false
            pcall(function() conn:Disconnect() end)
            gui:Destroy()
        end)
    end
end
task.defer(function()
    local ok, err = pcall(K.StartScoreHud)
    if not ok then KQ("[Kicia ScoreHud] could not start: " .. tostring(err)) end
end)

K.Mark("before main (j1)")
tbl17.j1()(boot)
K.loading = false
pcall(function() K.Log("load", string.format("script loaded in %.2f s (after the boot gate)", os.clock() - K.LoadT0)) end)
pcall(function() K.Marker:SetAttribute("Loading", false) end)
